[99] = {name = "Rugido desmoralizador", additional_info = "10 p. de ira\nHechizo instantáneo\nRequiere Forma de oso, Forma de oso temible\n[q]El druida ruge y disminuye 40 p. el poder de ataque cuerpo a cuerpo de los enemigos cercanos. Dura 30 s."},
[100] = {name = "Cargar", additional_info = "Alcance de 8 - 25 m\n{Instante} {15 seg de reutilización}\nRequiere Actitud de batalla\n[q]Carga contra un enemigo, genera 9 de ira y lo aturde durante 1 s. No se puede usar durante el combate."},
[101] = {name = "Tropiezo", additional_info = "{15 p. de energía} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {5 seg de reutilización}\n[q]Hace tropezar al enemigo humanoide infligiendo 10 p. de daño y derribándolo durante 3 s. Otorga 1 p. de combo."},
