[113] = {name = "Cadenas de hielo", additional_info = "{20 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Forma cadenas glaciales alrededor del enemigo que bloquean el objetivo durante 15 s."},
[116] = {name = "Descarga de Escarcha", additional_info = "{25 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Lanza una descarga de Escarcha al enemigo que le inflige de [18 * ( 1 ) ] a [20 * ( 1 ) ] p. de daño de Escarcha y ralentiza su velocidad de movimiento un 40% durante 5 s."},
[118] = {name = "Polimorfia", additional_info = "{60 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Transforma al enemigo en oveja y la obliga a deambular durante hasta 20 s. Mientras deambula, la oveja no puede atacar ni lanzar hechizos, pero se regenera muy rápidamente. Si recibe daño, volverá a su forma normal. Solo se puede aplicar polimorfia a un objetivo a la vez. Solo funciona en bestias, dragones y alimañas."},
[120] = {name = "Cono de frío", additional_info = "210 p. de maná\n{Instante} {10 seg de reutilización}\n[q]Los objetivos situados en un cono frente al taumaturgo reciben de [98 * ( 1 ) ] a [108 * ( 1 ) ] p. de daño de Escarcha y se ralentizan un 50% durante 8 s."},
[122] = {name = "Nova de Escarcha", additional_info = "55 p. de maná\n{Instante} {25 seg de reutilización}\n[q]Golpea a los enemigos situados cerca del taumaturgo, les inflige de [19 * ( 1 ) ] a [21 * ( 1 ) ] p. de daño de Escarcha y los congela durante un máximo de 8 s. Cualquier daño infligido interrumpirá su efecto."},
[126] = {name = "Ojo de Kilrogg", additional_info = "{100 p. de maná} {Rango ilimitado}\nHechizo de 5 seg\n[q]Invoca un Ojo de Kilrogg y vincula tu visión a él. El ojo se mueve con rapidez pero es muy frágil."},
[128] = {name = "Piedra de hechizo", additional_info = "Instante\n[q]Elimina todos los efectos mágicos del taumaturgo y absorbe 400 p. de daño mágico durante 1 min."},
[130] = {name = "Caída lenta", additional_info = "40 p. de maná\nInstante\nComponentes:\nPluma ligera\n[q]Reduce la velocidad de caída durante 30 s."},
