[585] = {name = "Punición", additional_info = "{20 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Golpea al enemigo y le inflige 15 to 20 p. de daño Sagrado."},
[586] = {name = "Desvanecerse", additional_info = "40 p. de maná\n{Instante} {30 seg de reutilización}\n[q]Te desvaneces y disuades a los enemigos de que te ataquen durante 10 s."},
[587] = {name = "Crear comida", additional_info = "60 p. de maná\nHechizo de 3 seg\n[q]Crea 20 magdalenas, y le provee al mago y a sus aliados algo para comer.\n\n Los objetos mágicos desaparecen si el jugador permanece desconectado durante más de 15 minutos."},
[588] = {name = "Fuego interno", additional_info = "30 p. de maná\nInstante\n[q]Una ráfaga de energía Sagrada que aumenta 315 p. la armadura del taumaturgo. Cada golpe de daño cuerpo a cuerpo o a distancia contra el sacerdote resta una carga. Dura 10 min o hasta que se hayan utilizado 20 cargas."},
[589] = {name = "Palabra de las Sombras: dolor", additional_info = "{25 p. de maná} {Alcance de 30 m}\nInstante\n[q]Una palabra de oscuridad que inflige 30 p. de daño de las Sombras durante 18 s."},
[591] = {name = "Punición", additional_info = "{30 p. de maná} {Alcance de 30 m}\nHechizo de 2 seg\n[q]Golpea al enemigo causándole 28 to 34 p. de daño Sagrado."},
[592] = {name = "Palabra de poder: escudo", additional_info = "{80 p. de maná} {Alcance de 40 m}\n{Instante} {4 seg de reutilización}\n[q]Refuerza con un escudo el alma de un miembro del grupo, amortiguando 94 p. de daño. Dura 30 s. Mientras dura el escudo, el lanzamiento de hechizos no se verá interrumpido por el daño. Una vez protegido, el objetivo no puede recibir protección de nuevo hasta pasados 15 s."},
[594] = {name = "Palabra de las Sombras: dolor", additional_info = "{50 p. de maná} {Alcance de 30 m}\nInstante\n[q]Una palabra de oscuridad que causa 66 p. de daño de las Sombras durante 18 s."},
[595] = {name = "Rezo de protección", additional_info = "15 p. de maná\n{Instante} {10 min de reutilización}\n[q]Aumenta la armadura del grupo hasta que se agote la duración o el sacerdote deje de rezar."},
[596] = {name = "Rezo de sanación", additional_info = "410 p. de maná\nHechizo de 3 seg\n[q]Un potente rezo que sana 312 to 333 p. a los miembros de tu grupo en un radio de 30 m."},
[597] = {name = "Crear comida", additional_info = "105 p. de maná\nHechizo de 3 seg\n[q]Crea 20 barras de pan, proporcionando al mago y a sus aliados algo para comer.\n\n Los objetos creados por arte de magia desaparecen si el jugador permanece desconectado durante más de 15 min."},
[598] = {name = "Punición", additional_info = "{60 p. de maná} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Golpea al enemigo causándole 58 to 67 p. de daño Sagrado."},
[600] = {name = "Palabra de poder: escudo", additional_info = "{130 p. de maná} {Alcance de 40 m}\n{Instante} {4 seg de reutilización}\n[q]Refuerza con un escudo el alma de un miembro del grupo, amortiguando 166 p. de daño. Dura 30 s. Mientras dura el escudo, el lanzamiento de hechizos no se verá interrumpido por el daño. Una vez protegido, el objetivo no puede recibir protección de nuevo hasta pasados 15 s."},
[601] = {name = "Maestría con espada", additional_info = "[q]Aumenta tu acierto en ataque con espadas de una mano 3 p."},
[602] = {name = "Fuego interno", additional_info = "105 p. de maná\nInstante\n[q]Una ráfaga de energía Sagrada, que aumenta la armadura del taumaturgo en 720 p. Cada golpe de daño cuerpo a cuerpo o a distancia contra el sacerdote restará una carga. Dura 10 min o hasta que se hayan usado 20 cargas."},
[603] = {name = "Maldición del Apocalipsis", additional_info = "{300 p. de maná} {Alcance de 30 m}\n{Instante} {1 min de reutilización}\n[q]Maldice al objetivo con una fatalidad inminente que inflige 3200 p. de daño de las Sombras después de 1 min. Si este daño mata al objetivo, existe la probabilidad de invocar a un guardia apocalíptico. No se puede lanzar sobre jugadores."},
[604] = {name = "Atenuar magia", additional_info = "{100 p. de maná} {Alcance de 30 m}\nInstante\n[q]Reprime la magia utilizada contra el miembro del grupo elegido, disminuyendo el daño recibido de los hechizos en hasta 10 p. y los hechizos de sanación en hasta 20 p. Dura 10 min."},
[605] = {name = "Control mental", additional_info = "{350 p. de maná} {Alcance de 20 m}\nHechizo de 3 seg\n[q]Controla una mente humanoide de un nivel máximo de 44, pero aumenta el tiempo entre ataques un 25%. Dura un máximo de 1 min."},
[606] = {name = "Putrefacción mental", additional_info = "{240 p. de maná} {Alcance de 30 m}\nHechizo de 2 seg\n[q]Drena 2160 p. de maná del objetivo durante 30 s."},
