[633] = {name = "Imposición de manos", additional_info = "Alcance de 40 m\nInstante 1 hora de reutilización\n[q]Sana a un objetivo aliado la misma cantidad de puntos que la salud máxima del paladín. Cuando se usa, absorbe todo el maná restante del paladín."},
[635] = {name = "Luz Sagrada", additional_info = "{35 p. de maná} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Sana a un objetivo amistoso 42 to 51 p."},
