[642] = {name = "Escudo divino", additional_info = "75 p. de maná\n{Instante} {5 min de reutilización}\n[q]Protege al paladín de todo el daño y los hechizos durante 10 s, pero [ S03 - Tuning and Overrides Passive - Paladin : reduce un 50% todo el daño que infliges / aumenta un 100% el daño entre tus ataques]. Una vez protegido, el objetivo no puede volverse invulnerable nuevamente con Escudo divino, Protección divina ni Bendición de protección durante 1 min."},
[643] = {name = "Aura de devoción", additional_info = "Instante\n[q]Da 275 p. de armadura extra a los miembros del grupo en un radio de 30 m. Los jugadores solo pueden tener un aura con ellos por paladín a la vez."},
