[674] = {name = "Doble empuñadura", additional_info = "[q]Permite que las armas de una mano y las armas de mano izquierda se equipen como armas de mano izquierda."},
[676] = {name = "Desarmar", additional_info = "{20 p. de ira} {Alcance de ataques cuerpo a cuerpo}\n{Hechizo instantáneo} {1 min de reutilización}\nRequiere Actitud defensiva\n[q]Desarma el arma del enemigo durante 10 s."},
