[686] = {name = "Descarga de las Sombras", additional_info = "{25 p. de maná} {Alcance de 30 m}\nHechizo de 1.7 seg\n[q]Lanza una descarga de las Sombras al enemigo, lo que le inflige 13 to 18 p. de daño de las Sombras."},
[687] = {name = "Piel de demonio", additional_info = "50 p. de maná\nInstante\n[q]Protege al taumaturgo, aumenta 40 p. su armadura y restaura 3 p. de Salud cada 5 s durante 30 min."},
[688] = {name = "Invocar diablillo", additional_info = "80% del maná base\nHechizo de 10 seg\n[q]Invoca un diablillo bajo las órdenes del brujo."},
[689] = {name = "Drenar vida", additional_info = "{55 p. de maná} {Alcance de 20 m}\nCanalizado (Hechizo de 5 seg)\n[q]Transfiere 10 p. de salud por segundo del objetivo al taumaturgo. Dura 5 s."},
[690] = {name = "Descarga de Fuego II", additional_info = "{18 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Golpea a un objetivo, causando 28 to 30 p. de daño de Fuego."},
[691] = {name = "Invocar manáfago", additional_info = "100% del maná base\nHechizo de 10 seg\nComponentes:\nFragmento de alma\n[q]Invoca un manáfago bajo las órdenes del brujo."},
[693] = {name = "Crear piedra de alma (menor)", additional_info = "85% del maná base\nHechizo de 3 seg\nComponentes:\nFragmento de alma\n[q]Crea una piedra de alma menor. La piedra de alma puede utilizarse para guardar el alma de un objetivo. Si el objetivo muere y su alma está guardada, tiene la posibilidad de resucitar con 400 p. de salud y 700 p. de maná.\n\n Los objetos mágicos desaparecen si el jugador permanece desconectado durante más de 15 min."},
[694] = {name = "Falsa arremetida", additional_info = "{10 p. de ira} {Alcance de ataques cuerpo a cuerpo}\n{Hechizo instantáneo} {2 min de reutilización}\nRequiere Arma cuerpo a cuerpo\nRequiere Actitud de batalla\n[q]Un ataque burlón que causa 22 p. de daño, una cantidad moderada de amenaza y obliga al objetivo a centrar sus ataques en ti durante 6 s."},
[695] = {name = "Descarga de las Sombras", additional_info = "{40 p. de maná} {Alcance de 30 m}\nHechizo de 2.2 seg\n[q]Lanza una descarga de Sombras al enemigo causándole 26 to 32 p. de daño de las Sombras."},
[696] = {name = "Piel de demonio", additional_info = "120 p. de maná\nInstante\n[q]Protege al taumaturgo aumentando su armadura en 120 p. y también restaura 5 p. de Salud cada 5 s. durante 30 min."},
[697] = {name = "Invocar abisario", additional_info = "100% del maná base\nHechizo de 10 seg\nComponentes:\nFragmento de alma\n[q]Invoca un abisario bajo las órdenes del brujo."},
[698] = {name = "Ritual de invocación", additional_info = "{300 p. de maná} {Alcance de 30 m}\nHechizo de 5 seg\nComponentes:\nFragmento de alma\n[q]Da comienzo a un ritual que invoca al miembro del grupo elegido. Requiere que el taumaturgo y 2 miembros más del grupo completen el ritual. Para poder participar, todos los jugadores deben estar fuera de combate, hacer clic derecho en el portal y no moverse hasta que el ritual se haya completado."},
[699] = {name = "Drenar vida", additional_info = "{85 p. de maná} {Alcance de 20 m}\nCanalizado (Hechizo de 5 seg)\n[q]Transfiere 17 p. de salud por segundo del objetivo al taumaturgo. Dura 5 s."},
[700] = {name = "Dormir", additional_info = "{60 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Duerme al enemigo objetivo durante un máximo de 20 s. Cualquier daño que se inflija lo despertará. Solo se puede dormir a un objetivo a la vez."},
[701] = {name = "Descarga de fuego", additional_info = "{10 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Golpea a un objetivo, inflige 19 p. de daño de Fuego."},
[702] = {name = "Maldición de debilidad", additional_info = "{20 p. de maná} {Alcance de 30 m}\nInstante\n[q]Reduce 3 p. el daño que inflige el objetivo durante 2 min. Un brujo solo puede tener una maldición activa sobre cada objetivo."},
[703] = {name = "Garrote", additional_info = "{50 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Sigilo\n[q]Le da un garrotazo al enemigo, lo que le inflige 144 p. de daño durante 18 s. Este monto aumenta según tu poder de ataque. Tienes que estar en modo sigilo y detrás del objetivo. Otorga 1 p. de combo."},
[704] = {name = "Maldición de temeridad", additional_info = "{35 p. de maná} {Alcance de 30 m}\nInstante\n[q]Lanza sobre el objetivo una Maldición de temeridad, aumentando su poder de ataque cuerpo a cuerpo en 20 p. pero disminuyendo su armadura en 140 p. durante 2 min. Los enemigos malditos no huirán e ignorarán los efectos del miedo y el horror. Un brujo solo puede tener una maldición activa a la vez sobre un mismo objetivo."},
[705] = {name = "Descarga de las Sombras", additional_info = "{70 p. de maná} {Alcance de 30 m}\nHechizo de 2.8 seg\n[q]Lanza una descarga de Sombras al enemigo causándole 52 to 61 p. de daño de las Sombras."},
[706] = {name = "Armadura demoníaca", additional_info = "275 p. de maná\nInstante\n[q]Protege al taumaturgo, lo que aumenta 210 p. la armadura y 3 p. la resistencia a las Sombras, y restaura 7 p. de salud cada 5 s durante 30 min."},
[707] = {name = "Inmolar", additional_info = "{45 p. de maná} {Alcance de 30 m}\nHechizo de 2 seg\n[q]Quema al enemigo, inflige [ 24 * ( ( ( 1 ) ) ) ] p. de daño de Fuego y 40 p. de daño de Fuego extra durante 15 s."},
[709] = {name = "Drenar vida", additional_info = "{135 p. de maná} {Alcance de 20 m}\nCanalizado (Hechizo de 5 seg)\n[q]Transfiere 29 p. de salud por segundo del objetivo al taumaturgo. Dura 5 s."},
[710] = {name = "Desterrar", additional_info = "{100 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Destierra al objetivo enemigo e impide que realice otras acciones pero lo vuelve invulnerable durante hasta 20 s. Solo se puede desterrar un objetivo por vez. Funciona únicamente con demonios y elementales."},
[711] = {name = "Llamas infernales", additional_info = "{25 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg 6 seg de reutilización\n[q]Golpea a todos los enemigos en un radio de 10 m., causando 69 to 78 p. de daño de llamas."},
[712] = {name = "Invocar súcubo", additional_info = "100% del maná base\nHechizo de 10 seg\nComponentes:\nFragmento de alma\n[q]Invoca un súcubo bajo las órdenes del brujo."},
[713] = {name = "Invocar íncubo", additional_info = "100% del maná base\nHechizo de 10 seg\nComponentes:\nFragmento de alma\n[q]Invoca un íncubo bajo las órdenes del brujo."},
