[758] = {name = "Piedra de fuego Pasivo", additional_info = "[q]Encanta el arma de la mano principal con fuego, proporcionando la posibilidad de infligir con cada ataque 25 to 35 p. de daño de Fuego extra."},
[759] = {name = "Crea Ágata de maná", additional_info = "530 p. de maná\nHechizo de 3 seg\n[q]Crea una ágata de maná que puede utilizarse para recuperar 375 to 425 p. de maná al instante.\n\n Los objetos mágicos desaparecen si el jugador permanece desconectado durante más de 15 minutos."},
[766] = {name = "Elemental de agua", additional_info = "Hechizo de 3 seg"},
[768] = {name = "Forma felina", additional_info = "55% del maná base\nInstante\n[q]Cambia a la forma felina, aumenta 40 p. más tu Agilidad el poder de ataque cuerpo a cuerpo. Además, protege al taumaturgo de los efectos de polimorfia y permite el uso de varias facultades felinas.\n\n El cambio de forma libera al taumaturgo de los efectos de polimorfia y de reducción de movimiento."},
[769] = {name = "Flagelo", additional_info = "{20 p. de ira} {Alcance de ataques cuerpo a cuerpo}\nHechizo instantáneo\nRequiere Forma de oso, Forma de oso temible\n[q]Flagela a 3 enemigos cercanos e inflige 36 p. de daño."},
[770] = {name = "Fuego feérico", additional_info = "{55 p. de maná} {Alcance de 30 m}\nInstante\n[q]Reduce la armadura del objetivo 175 p. durante 40 s. Mientras dura su efecto, el objetivo no puede utilizar el sigilo ni hacerse invisible."},
[772] = {name = "Desgarrar", additional_info = "{10 p. de ira} {Alcance de ataques cuerpo a cuerpo}\nHechizo instantáneo\nRequiere Arma cuerpo a cuerpo\nRequiere Actitud de batalla, Actitud defensiva\n[q]Hiere al objetivo y lo hace sangrar 15 p. de daño durante 9 s."},
[774] = {name = "Rejuvenecimiento", additional_info = "{25 p. de maná} {Alcance de 40 m}\nInstante\n[q]Sana 32 p. al objetivo durante 12 s."},
[775] = {name = "Forma de árbol", additional_info = "20% del maná base\n{Instante} {5 min de reutilización}\n[q]Transforma al druida en forma de árbol eliminado los efectos físicos nocivos y protege de todos los ataques físicos durante 8 s, pero no permite atacar, moverse ni lanzar hechizos. Protege al taumaturgo de los efectos de polimorfia.\n\n El cambio de forma libera al taumaturgo de los efectos de raíces, cepos y congelación."},
[776] = {name = "Suprimir magia", additional_info = "{24 p. de maná} {Alcance de 30 m}\n{Instante} {1 seg de reutilización}\n[q]Suprime toda la magia de un objetivo amistoso y evita que la magia le afecte durante 5 s."},
[778] = {name = "Fuego feérico", additional_info = "{75 p. de maná} {Alcance de 30 m}\nInstante\n[q]Disminuye la armadura del objetivo en 285 p. durante 40 s. Mientras dura su efecto, el objetivo no puede utilizar el sigilo ni hacerse invisible."},
[779] = {name = "Flagelo", additional_info = "{20 p. de ira} {Alcance de ataques cuerpo a cuerpo}\nHechizo instantáneo\nRequiere Forma de oso, Forma de oso temible\n[q]Flagela a 3 enemigos cercanos e inflige 18 p. de daño."},
[780] = {name = "Flagelo", additional_info = "{20 p. de ira} {Alcance de ataques cuerpo a cuerpo}\nHechizo instantáneo\nRequiere Forma de oso, Forma de oso temible\n[q]Flagela a 3 enemigos cercanos e inflige 25 p. de daño."},
[781] = {name = "Separación", additional_info = "{50 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {5 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Intenta separarse del objetivo, lo que reduce la amenaza. El personaje sale del modo de combate."},
[782] = {name = "Espinas", additional_info = "{60 p. de maná} {Alcance de 30 m}\nInstante\n[q]Hace que salgan espinas del objetivo amistoso que infligen 6 p. de daño de Naturaleza cuando los atacantes te golpean. Dura 10 min."},
[783] = {name = "Forma de viaje", additional_info = "20% del maná base\nInstante\n[q]Transforma al druida en una forma de viaje, lo que aumenta un 40% la velocidad de movimiento. También protege al taumaturgo de los efectos de polimorfia. Solo se puede usar en el exterior.\n\n El cambio de forma libera al taumaturgo de los efectos de polimorfia y reducción de movimiento."},
