[943] = {name = "Descarga de relámpagos", additional_info = "{105 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Lanza una Descarga de relámpagos sobre un objetivo, causando 131 to 149 p. de daño de Naturaleza."},
[944] = {name = "Descarga de relámpagos", additional_info = "Hechizo de 3 seg"},
[945] = {name = "Escudo de relámpagos", additional_info = "180 p. de maná\nInstante\n[q]El taumaturgo queda rodeado de 3 bolas de relámpagos. Cuando un hechizo o un ataque cuerpo a cuerpo o a distancia golpean al taumaturgo, el atacante recibe 80 p. de daño de Naturaleza y se consume una bola de relámpagos. Solo puede dispararse una bola cada cierta cantidad de segundos. Dura 10 min.\n(3.5s de reutilización)"},
[946] = {name = "Escudo de relámpagos", additional_info = "Hechizo de 3 seg"},
[950] = {name = "Bomba mental", additional_info = "Hechizo de 3 seg\n[q]Enseña Bomba mental."},
[952] = {name = "Explosión de arrabio", additional_info = "Hechizo de 3 seg"},
[956] = {name = "Maldición de las lenguas", additional_info = "Hechizo de 3 seg"},
