[960] = {name = "Ola de sanación superior", additional_info = "Hechizo de 3 seg"},
[962] = {name = "Fuego lunar", additional_info = "Hechizo de 3 seg"},
[964] = {name = "Sanar", additional_info = "Hechizo de 3 seg"},
[967] = {name = "Regreso astral en grupo", additional_info = "Hechizo de 3 seg\n[q]Enseña Regreso astral en grupo."},
[968] = {name = "Espíritu feral II", additional_info = "33 p. de maná\nHechizo de 3 seg"},
[970] = {name = "Palabra de las Sombras: dolor", additional_info = "{95 p. de maná} {Alcance de 30 m}\nInstante\n[q]Una palabra de oscuridad que causa 132 p. de daño de las Sombras durante 18 s."},
[971] = {name = "Palabra de las Sombras: dolor", additional_info = "Hechizo de 3 seg"},
[973] = {name = "Protección contra lo Sagrado", additional_info = "Hechizo de 3 seg\n[q]Enseña Protección contra lo Sagrado."},
[974] = {name = "Escudo de tierra", additional_info = "{15% del maná base} {Alcance de 40 m}\nInstante\n[q]Protege al objetivo con un escudo de tierra que reduce el tiempo perdido de lanzamiento o canalización cuando recibe un 30% de daño y provoca que los ataques sanen p. al objetivo escudado. Este efecto solo puede ocurrir una vez cada pocos segundos. 6 cargas. Dura 10 min. Escudo de tierra solo puede utilizarse en un objetivo a la vez y solo puede haber un escudo elemental activo a la vez sobre un objetivo.\n(3.5s de reutilización)"},
[976] = {name = "Protección contra las Sombras", additional_info = "{250 p. de maná} {Alcance de 30 m}\nInstante\n[q]Aumenta la resistencia del objetivo a hechizos de las Sombras en 30 p. durante 10 min."},
[977] = {name = "Protección contra las Sombras", additional_info = "Hechizo de 3 seg\n[q]Enseña Protección contra las sombras."},
[979] = {name = "Corrupción", additional_info = "Hechizo de 3 seg"},
[980] = {name = "Maldición de agonía", additional_info = "{25 p. de maná} {Alcance de 30 m}\nInstante\n[q]Lanza una Maldición de agonía contra el objetivo e inflige 84 p. de daño de las Sombras durante 24 s. El daño provocado aumenta progresivamente a medida que el hechizo surte efecto. Un brujo solo puede tener una maldición activa a la vez sobre un mismo objetivo."},
[981] = {name = "Maldición de agonía", additional_info = "Hechizo de 3 seg"},
[982] = {name = "Revivir mascota", additional_info = "100% del maná base\nHechizo de 10 seg\n[q]Revive a tu mascota, que vuelve a la vida con un 15% de su salud."},
[983] = {name = "Sanar", additional_info = "Hechizo de 3 seg"},
[984] = {name = "Punición", additional_info = "{95 p. de maná} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Golpea al enemigo causándole 97 to 112 p. de daño Sagrado."},
[985] = {name = "Punición Sagrada", additional_info = "Hechizo de 3 seg"},
[988] = {name = "Disipar magia", additional_info = "{18% del maná base} {Alcance de 30 m}\nInstante\n[q]Elimina la magia del objetivo, suprimiendo 2 efectos dañinos de un amigo o 2 hechizos beneficiosos de un enemigo."},
[989] = {name = "Disipar magia", additional_info = "Hechizo de 3 seg"},
[990] = {name = "Crear comida", additional_info = "180 p. de maná\nHechizo de 3 seg\n[q]Crea 20 panes de centeno, proporcionando al mago y a sus aliados algo para comer.\n\n Los objetos creados por arte de magia desaparecen si el jugador permanece desconectado durante más de 15 min."},
[991] = {name = "Crear comida", additional_info = "Hechizo de 3 seg"},
