[993] = {name = "Palabra de las Sombras: dolor", additional_info = "Hechizo de 3 seg"},
[994] = {name = "Rezo de protección II", additional_info = "20 p. de maná\n{Instante} {10 min de reutilización}\n[q]Aumenta la armadura del grupo hasta que se agote la duración o el sacerdote deje de rezar."},
[996] = {name = "Rezo de sanación", additional_info = "560 p. de maná\nHechizo de 3 seg\n[q]Un potente rezo que sana en 458 to 487 p. a los miembros de tu grupo en un radio de 30 m."},
[997] = {name = "Rezo de sanación", additional_info = "Hechizo de 3 seg"},
[999] = {name = "Palabra de las Sombras: fracaso", additional_info = "Hechizo de 3 seg"},
[1002] = {name = "Ojos de la bestia", additional_info = "{20 p. de maná} {Rango ilimitado}\nHechizo de 2 seg\n[q]Controla a tu mascota y mira con sus ojos durante 1 min."},
