[1004] = {name = "Punición", additional_info = "{140 p. de maná} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Golpea al enemigo causándole 158 to 178 p. de daño Sagrado."},
[1005] = {name = "Punición Sagrada", additional_info = "Hechizo de 3 seg"},
[1006] = {name = "Fuego interno", additional_info = "165 p. de maná\nInstante\n[q]Una ráfaga de energía Sagrada, que aumenta la armadura del taumaturgo en 945 p. Cada golpe de daño cuerpo a cuerpo o a distancia contra el sacerdote restará una carga. Dura 10 min o hasta que se hayan usado 20 cargas."},
[1007] = {name = "Fuego interno", additional_info = "Hechizo de 3 seg"},
[1008] = {name = "Amplificar magia", additional_info = "{150 p. de maná} {Alcance de 30 m}\nInstante\n[q]Amplifica la magia utilizada contra el miembro del grupo elegido, aumentando el daño recibido de los hechizos en hasta 15 p. y los hechizos de sanación en hasta 30 p. Dura 10 min."},
[1009] = {name = "Paliza cruel", additional_info = "{45 p. de enfoque} {Alcance de ataques cuerpo a cuerpo}\nCanalizado (Hechizo de 5 seg) 25 seg de reutilización\n[q]Zurra a un enemigo."},
[1010] = {name = "Maldición de imbecilidad", additional_info = "{110 p. de maná} {Alcance de 30 m}\nInstante\n[q]Lanza sobre el enemigo una Maldición de imbecilidad, disminuyendo su intelecto y su espíritu en 6 p. cada 3 s hasta un total de 90 p. cada una. Un brujo solo puede tener una maldición activa a la vez sobre un mismo objetivo."},
[1011] = {name = "Ahuyentar no-muertos", additional_info = "Hechizo de 3 seg"},
[1012] = {name = "Maestría con espada", additional_info = "Alcance de 100 m\nInstante\n[q]Aumenta tu acierto en ataque con espadas en 3 p."},
[1013] = {name = "Fuerza heroica", additional_info = nil},
[1014] = {name = "Maldición de agonía", additional_info = "{50 p. de maná} {Alcance de 30 m}\nInstante\n[q]Lanza sobre el objetivo una maldición de agonía, causando 180 p. de daño de las Sombras durante 24 s. El daño provocado aumenta progresivamente a medida que el hechizo surte efecto. Un brujo solo puede tener una maldición activa a la vez sobre un mismo objetivo."},
[1015] = {name = "Maldición de agonía", additional_info = "Hechizo de 3 seg"},
[1017] = {name = "Captar demonios", additional_info = "Hechizo de 3 seg\n[q]Enseña Captar demonios."},
[1020] = {name = "Escudo divino", additional_info = "110 p. de maná\n{Instante} {5 min de reutilización}\n[q]Protege al paladín de todo el daño y los hechizos durante 12 s, pero [ S03 - Tuning and Overrides Passive - Paladin : reduce un 50% todo el daño que infliges / aumenta un 100% el daño entre tus ataques]. Una vez protegido, el objetivo no puede volverse invulnerable nuevamente con Escudo divino, Protección divina ni Bendición de protección durante 1 min."},
[1021] = {name = "Escudo divino", additional_info = "Hechizo de 3 seg"},
[1022] = {name = "Bendición de protección", additional_info = "{25 p. de maná} {Alcance de 30 m}\n{Instante} {5 min de reutilización}\n[q]Protege al miembro del grupo elegido como objetivo de los ataques físicos durante 6 s. Durante ese período, no puede atacar ni utilizar facultades físicas. Los jugadores solo pueden tener una Bendición activa a la vez por cada paladín. Una vez protegido, no puede utilizar Escudo divino, Protección divina ni Bendición de protección para hacerse invulnerable durante 1 min."},
[1023] = {name = "Sello de protección", additional_info = "Hechizo de 3 seg"},
[1025] = {name = "Corrupción", additional_info = "Hechizo de 3 seg"},
[1026] = {name = "Luz Sagrada", additional_info = "{190 p. de maná} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Sana un objetivo amistoso en 322 to 368 p."},
[1027] = {name = "Luz Sagrada", additional_info = "Hechizo de 3 seg"},
[1029] = {name = "Maldición de agonía", additional_info = "Hechizo de 3 seg"},
[1031] = {name = "Maldición de debilidad", additional_info = "Hechizo de 3 seg"},
[1032] = {name = "Aura de devoción", additional_info = "Instante\n[q]Da 505 p. de armadura extra a los miembros del grupo en un radio de 30 m. Los jugadores solo pueden tener un aura con ellos por paladín a la vez."},
[1033] = {name = "Disparo de Fuego", additional_info = nil},
[1035] = {name = "Resguardo contra el Fuego", additional_info = nil},
[1037] = {name = "Sello de furia", additional_info = "Hechizo de 3 seg"},
[1038] = {name = "Bendición de salvación", additional_info = "{8% del maná base} {Alcance de 30 m}\nInstante\n[q]Coloca una bendición sobre el miembro del grupo que reduce la amenaza total generada un 30% durante 5 min. Los jugadores solo pueden tener una bendición activa por Paladín a la vez."},
[1039] = {name = "Sello de salvación", additional_info = "Hechizo de 3 seg"},
[1042] = {name = "Luz Sagrada", additional_info = "{275 p. de maná} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Sana un objetivo amistoso en 506 to 569 p."},
[1043] = {name = "Luz Sagrada", additional_info = "Hechizo de 3 seg"},
[1044] = {name = "Bendición de libertad", additional_info = "{10% del maná base} {Alcance de 30 m}\n{Instante} {20 seg de reutilización}\n[q]Coloca una Bendición sobre un objetivo aliado y le otorga inmunidad a los efectos de reducción de movimiento durante 10 s. Los jugadores solo pueden tener una Bendición activa por paladín a la vez."},
