[1059] = {name = "Rejuvenecimiento", additional_info = "Hechizo de 3 seg"},
[1062] = {name = "Raíces enredadoras", additional_info = "{65 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Enraíza al enemigo y causa 50 p. de daño de Naturaleza durante 15 s. El daño causado puede interrumpir el efecto. Solo se puede usar en el exterior."},
[1063] = {name = "Raíces enredadoras", additional_info = "Hechizo de 3 seg"},
[1064] = {name = "Sanación en cadena", additional_info = "{260 p. de maná} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Restablece 332 to 381 p. de salud al objetivo aliado y salta para sanar objetivos adicionales cercanos. Si se lanza sobre un miembro del grupo, la sanación solo saltará hacia otros miembros del grupo. Cada sanación conserva un 50% de la efectividad con cada salto. Sana a un total de 3 objetivos."},
[1065] = {name = "Grito desmoralizador", additional_info = nil},
[1066] = {name = "Forma acuática", additional_info = "20% del maná base\nInstante\n[q]Cambia a la forma acuática, aumenta la velocidad de nado un 50% y le permite al druida respirar debajo del agua. Además, protege al taumaturgo de los efectos de polimorfia.\n\n El cambio de forma libera al taumaturgo de los efectos de polimorfia y de reducción de movimiento."},
[1070] = {name = "Fuego feérico", additional_info = "Hechizo de 3 seg"},
[1075] = {name = "Espinas", additional_info = "{105 p. de maná} {Alcance de 30 m}\nInstante\n[q]Hace que salgan espinas del objetivo amistoso que infligen 9 p. de daño de Naturaleza cuando los atacantes te golpean. Dura 10 min."},
[1076] = {name = "Espinas", additional_info = "Hechizo de 3 seg"},
[1079] = {name = "Destripar", additional_info = "{30 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Forma felina\n[q]Remate que inflige daño con el tiempo. El daño aumenta por cada punto de combo y con tu poder de ataque:\n 1 p.: [ 6 * 1 * (7)] p. de daño durante 12 s.\n 2 p.: [ 6 * 1 * (11)] p. de daño durante 12 s.\n 3 p.: [ 6 * 1 * (15)] p. de daño durante 12 s.\n 4 p.: [ 6 * 1 * (19)] p. de daño durante 12 s.\n 5 p.: [ 6 * 1 * (23)] p. de daño durante 12 s."},
[1082] = {name = "Zarpa", additional_info = "{45 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Forma felina\n[q]Da un zarpazo al enemigo y le inflige 27 p. de daño extra. Otorga 1 p. de combo."},
[1084] = {name = "Descarga de Fuego III", additional_info = "{26 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Golpea a un objetivo, causando 35 to 40 p. de daño de Fuego."},
[1086] = {name = "Armadura demoníaca", additional_info = "520 p. de maná\nInstante\n[q]Protege al taumaturgo, lo que aumenta 300 p. la armadura y 6 p. la resistencia a las Sombras y restaura 9 p. de salud cada 5 s durante 30 min."},
[1087] = {name = "Armadura demoníaca", additional_info = "Hechizo de 3 seg"},
[1088] = {name = "Descarga de las Sombras", additional_info = "{110 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Lanza una descarga de Sombras al enemigo causándole 92 to 104 p. de daño de las Sombras."},
[1089] = {name = "Descarga de las Sombras", additional_info = "Hechizo de 3 seg"},
[1090] = {name = "Dormir", additional_info = "{90 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Duerme al enemigo objetivo durante un máximo de 30 s. Cualquier daño que se inflija lo despertará. Solo se puede dormir a un objetivo a la vez."},
[1091] = {name = "Dormir", additional_info = "Hechizo de 3 seg"},
[1094] = {name = "Inmolar", additional_info = "{90 p. de maná} {Alcance de 30 m}\nHechizo de 2 seg\n[q]Quema al enemigo, inflige [ 53 * ( ( ( 1 ) ) ) ] p. de daño de Fuego y 90 p. de daño de Fuego extra durante 15 s."},
[1095] = {name = "Inmolar", additional_info = "Hechizo de 3 seg"},
[1096] = {name = "Descarga de Fuego IV", additional_info = "{34 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Golpea a un objetivo, causando 42 to 49 p. de daño de Fuego."},
[1098] = {name = "Subyugar demonio", additional_info = "{300 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\nComponentes:\nFragmento de alma\n[q]Subyuga al demonio objetivo, de nivel 45 como máximo, y lo obliga a seguir tus órdenes. Mientras está subyugado, el tiempo entre los ataques del demonio aumenta un 40% y su velocidad de lanzamiento de hechizos se reduce un 30%. Dura un máximo de 5 min. Si subyugas reiteradamente al mismo demonio, cada vez será más difícil de controlar."},
[1101] = {name = "Cauce de maná", additional_info = "Hechizo de 3 seg\n[q]Enseña Cauce de maná."},
[1105] = {name = "Sello de sabiduría", additional_info = "Hechizo de 3 seg"},
[1106] = {name = "Descarga de las Sombras", additional_info = "{160 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Lanza una descarga de Sombras al enemigo causándole 150 to 170 p. de daño de las Sombras."},
[1107] = {name = "Corrupción", additional_info = "Hechizo de 3 seg"},
[1108] = {name = "Maldición de debilidad", additional_info = "{35 p. de maná} {Alcance de 30 m}\nInstante\n[q]Reduce 6 p. el daño que inflige el objetivo durante 2 min. Un brujo solo puede tener una maldición activa sobre cada objetivo."},
[1109] = {name = "Maldición de debilidad", additional_info = "Hechizo de 3 seg"},
[1112] = {name = "Nova de las Sombras II", additional_info = "Hechizo de 3 seg"},
[1114] = {name = "Maestría en esquivar", additional_info = "[q]Aumenta la probabilidad de esquivar en un 1%."},
[1116] = {name = "Escudo de caos", additional_info = "25 p. de maná, más 4 por segundo"},
[1117] = {name = "Aliviar mascota", additional_info = nil},
[1120] = {name = "Drenar alma", additional_info = "{55 p. de maná} {Alcance de 30 m}\nCanalizado (Hechizo de 15 seg)\n[q]Drena el alma del objetivo e inflige 55 p. de daño de las Sombras durante 15 s. Si el objetivo muere mientras está siendo drenado y otorga experiencia u honor, el taumaturgo obtiene un fragmento de alma. Los fragmentos de alma son necesarios para otros hechizos."},
[1121] = {name = "Enredar", additional_info = nil},
[1122] = {name = "Inferno", additional_info = "{100% del maná base} {Alcance de 30 m}\nHechizo de 2 seg 1 hora de reutilización\nComponentes:\nPiedra infernal\n[q]Invoca un meteoro del Vacío Abisal, que inflige 200 p. de daño de fuego y aturde a todos los objetivos enemigos en el área durante 2 s. Del cráter surge un infernal bajo las órdenes del taumaturgo durante 5 min. Cuando pierdes el control sobre el infernal, debes subyugarlo para controlarlo. Solo puede usarse en exteriores."},
[1123] = {name = "Ritual de condena", additional_info = "Hechizo de 3 seg\n[q]Enseña Ritual de condena."},
[1124] = {name = "Llamas infernales II", additional_info = "{27 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg 6 seg de reutilización\n[q]Golpea a todos los enemigos en un radio de 10 m., causando 80 to 91 p. de daño de llamas."},
[1126] = {name = "Marca de lo Salvaje", additional_info = "{20 p. de maná} {Alcance de 30 m}\nInstante\n[q]Aumenta 25 p. la armadura de un objetivo aliado durante 30 min."},
[1127] = {name = "Comida", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 874.8 p. de salud durante 27 s. Debes permanecer sentado mientras comes."},
[1129] = {name = "Comida", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 1392 p. de salud durante 30 s. Debes permanecer sentado mientras comes."},
[1130] = {name = "Marca del cazador", additional_info = "{15 p. de maná} {Alcance de 100 m}\nInstante\n[q]Deja la Marca del cazador en el objetivo, lo que aumenta 20 p. el poder de ataque a distancia de todos los que ataquen al objetivo. Además, el cazador siempre podrá ver al objetivo, aunque use sigilo o invisibilidad. El objetivo también aparecerá en el minimapa. Dura 2 min."},
[1131] = {name = "Comida", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 2148 p. de salud durante 30 s. Debes permanecer sentado mientras comes."},
[1132] = {name = "Golpe crítico", additional_info = nil},
[1133] = {name = "Beber", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 1344.6 p. de maná durante 27 s. Debes permanecer sentado mientras bebes."},
[1135] = {name = "Beber", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 1992 p. de maná durante 30 s. Debes permanecer sentado mientras bebes."},
[1137] = {name = "Beber", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 2934 p. de maná durante 30 s. Debes permanecer sentado mientras bebes."},
