[1499] = {name = "Trampa congelante", additional_info = "50 p. de maná\n{Instante} {15 seg de reutilización}\n[q]Coloca una trampa de escarcha que congela al primer enemigo que se acerque y le impide actuar durante hasta 10 s. Cualquier daño infligido romperá el hielo. La trampa dura 1 min. Las trampas solo pueden colocarse cuando estás fuera de combate y solo puede haber una trampa activa a la vez."},
[1509] = {name = "Solo MJ desact.", additional_info = nil},
[1510] = {name = "Salva", additional_info = "{350 p. de maná} {Alcance de 8 - 35 m}\nCanalizado (Hechizo de 6 seg) 1 min de reutilización\nRequiere Arma a distancia\n[q]Dispara continuamente una salva de munición al área objetivo e inflige 50 p. de daño Arcano a todos los objetivos enemigos en un radio de 8 m cada segundo durante 6 s."},
[1513] = {name = "Asustar bestia", additional_info = "{35 p. de maná} {Alcance de 10 m}\nHechizo de 1.5 seg 30 seg de reutilización\n[q]Asusta a una bestia haciendo que huya durante un máximo de 10 s. El daño infligido puede interrumpir el efecto. Solo se puede asustar a una bestia cada vez."},
[1515] = {name = "Domesticar bestia", additional_info = "{60% del maná base} {Alcance de 30 m}\nCanalizado (Hechizo de 20 seg)\n[q]Comienza a domesticar una bestia para que se convierta en tu compañera. Tu armadura se reduce un 100% durante 20 s mientras te concentras en la domesticación de la bestia. Si pierdes la atención de la bestia por cualquier motivo, el proceso de domesticación fracasará. Cuando la domestiques, la bestia estará triste y no será leal. Intenta alimentar a la mascota de inmediato para hacerla feliz."},
[1516] = {name = "Disparo presuroso", additional_info = "Alcance de 5 - 30 m\n1 min de reutilización\nRequiere Arma a distancia\n[q]Dispara instantáneamente tu arma, inflige 5 p. de daño extra."},
[1528] = {name = "Liberar al maestro", additional_info = "Alcance de 5 m\nInstante\n[q]Libera a tu maestro de cualquier vínculo."},
[1535] = {name = "Tótem Nova de Fuego", additional_info = "95 p. de maná\n{Instante} {15 seg de reutilización}\nHerramientas: Tótem de fuego\n[q]Invoca un Tótem Nova de Fuego que tiene 5 p. de salud y dura 5 s. Si no lo destruyen en un plazo de 4 s, inflige 53 to 62 p. de daño de Fuego a los enemigos en un radio de 10 m."},
