[3491] = {name = "[q2]Cuchillo de bronce grande", additional_info = "Hechizo de 25 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de bronce (6), Flujo débil (4), Piedra de pulir férrea (2), Ojo de tigre , Cuero medio\n[q2]Cuchillo de bronce grande\nSe liga al equiparlo\nUna mano Daga\n13 - 25 p. de daño Velocidad 1.90\n(10.00 p. de daño por segundo)\n+3 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 15"},
[3492] = {name = "[q2]Espada corta de hierro endurecido", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de hierro (6), Flujo concentrado (2), Piedra de pulir pesada , Piedra lunar inferior (2), Cuero pesado (3)\n[q2]Espada corta de hierro endurecido\nSe liga al equiparlo\nMano derecha Espada\n21 - 39 p. de daño Velocidad 1.80\n(16.67 p. de daño por segundo)\n+5 aguante\nDurabilidad 75 / 75\nNecesitas ser de nivel 27"},
[3493] = {name = "[q2]Hoja serpentina de jade", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de hierro (8), Flujo concentrado (2), Piedra de pulir pesada (2), Jade (2), Cuero pesado (3)\n[q2]Hoja serpentina de jade\nSe liga al equiparlo\nUna mano Espada\n33 - 62 p. de daño Velocidad 2.60\n(18.27 p. de daño por segundo)\n+4 fuerza\n+4 agilidad\nDurabilidad 75 / 75\nNecesitas ser de nivel 30"},
