[3932] = {name = "Muñeco-diana", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nModulador de cobre , Puñado de tornillos de cobre (2), Barra de bronce , Paño de lana\nRequiereIngeniería\n(85)\n[q2]Uso: Coloca un muñeco-diana en el suelo que atrae los ataques de los monstruos cercanos. Dura 15 s o hasta que lo matan. (2 Min Reutilización)"},
[3933] = {name = "Carga de seforio pequeña", additional_info = "Hechizo de 8 seg\nComponentes:\nPólvora burda (2), Modulador de cobre , Cuero ligero , Agua de manantial refrescante\n[q]Una carga de seforio pequeña suficiente para abrir algunas puertas con una explosión.\nRequiereIngeniería\n(100)\n[q2]Uso: Hace explotar las cerraduras de puertas simples."},
[3934] = {name = "[q2]Gafas de tigre volador", additional_info = "Hechizo de 12.5 seg\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nCuero ligero (6), Ojo de tigre (2)\n[q2]Gafas de tigre volador\nSe liga al equiparlo\nCabeza Tela\n27 armadura\n+4 aguante\n+4 espíritu\nDurabilidad 35 / 35\nRequiereIngeniería\n(100)"},
[3936] = {name = "[q2]Trabuco mortal", additional_info = "Hechizo de 25 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTubo de cobre (2), Puñado de tornillos de cobre (4), Pila de madera , Cuero medio (2)\n[q2]Trabuco mortal\nSe liga al equiparlo\nA distancia Arma de fuego\n15 - 28 p. de daño Velocidad 2.60\n(8.27 p. de daño por segundo)\nDurabilidad 50 / 50\nNecesitas ser de nivel 16"},
[3937] = {name = "Bomba grande de cobre", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de cobre (3), Pólvora burda (4), Contacto de plata\n(2)\nRequiereIngeniería\n(105)\n[q2]Uso: Inflige 43 to 57 p. de daño de Fuego y aturde a los objetivos durante 1 s en un radio de 5 m. Cualquier daño anulará el efecto. (1 Min Reutilización)"},
