[3949] = {name = "[q2]Escopeta de chapa de plata", additional_info = "Hechizo de 25 seg\nComponentes:\nTubo de bronce (2), Cacharros zumbones de bronce (2), Surtido pesado , Barra de plata (3)\n[q2]Escopeta de chapa de plata\nSe liga al equiparlo\nA distancia Arma de fuego\n19 - 37 p. de daño Velocidad 2.70\n(10.37 p. de daño por segundo)\nDurabilidad 60 / 60\nNecesitas ser de nivel 21"},
[3950] = {name = "Bomba de bronce grande", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nPólvora potente (2), Barra de bronce (3), Contacto de plata\n(2)\nRequiereIngeniería\n(140)\n[q2]Uso: Inflige 85 to 115 p. de daño de Fuego y aturde a los objetivos durante 2 s en un radio de 5 m. Cualquier daño anulará el efecto. (1 Min Reutilización)"},
[3952] = {name = "[q2]Recombobulador menor", additional_info = "Hechizo de 12.5 seg\nComponentes:\nTubo de bronce , Cacharros zumbones de bronce (2), Cuero medio (2), Ágata musgosa\n[q2]Recombobulador menor\nAbalorio\nRequiereIngeniería\n(140)\n[q2]Uso: Elimina los efectos de polimorfia de un objetivo aliado. También restaura 150 to 250 p. de salud y maná. (5 Min Reutilización)\n10 cargas"},
[3953] = {name = "Marco de bronce", additional_info = "Hechizo de 5.125 seg\nComponentes:\nBarra de bronce (2), Cuero medio , Paño de lana"},
[3954] = {name = "[q2]Rifle de vista lunar", additional_info = "Hechizo de 25 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTubo de bronce (3), Cacharros zumbones de bronce (3), Surtido pesado , Piedra lunar inferior (2)\n[q2]Rifle de vista lunar\nSe liga al equiparlo\nA distancia Arma de fuego\n14 - 26 p. de daño Velocidad 1.70\n(11.76 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 24"},
[3955] = {name = "Oveja explosiva", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nMarco de bronce , Cacharros zumbones de bronce , Pólvora potente (2), Paño de lana (2)\nRequiereIngeniería\n(150)\n[q2]Uso: Invoca una oveja explosiva que carga contra un enemigo cercano y estalla infligiendo 135 to 165 p. de daño. Dura 3 minutos o hasta que estalla. (1 Min Reutilización)"},
[3956] = {name = "[q2]Gafas tintadas de verde", additional_info = "Hechizo de 12.5 seg\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nCuero medio (4), Ágata musgosa (2), Gafas de tigre volador\n[q2]Gafas tintadas de verde\nSe liga al equiparlo\nCabeza Tela\n35 armadura\n+8 aguante\n+7 espíritu\nDurabilidad 45 / 45\nRequiereIngeniería\n(150)"},
