[3958] = {name = "Tornapunta de hierro", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de hierro (2)"},
[3959] = {name = "Rayo descombobulador", additional_info = "Hechizo de 12.5 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nCacharros zumbones de bronce (3), Paño de seda (2), Jade , Tubo de bronce\n[q2]Uso: Transforma al objetivo en un Gnomo paria, reduce 40 p. su daño cuerpo a cuerpo y con hechizos, y reduce un 20% su índice de movimiento durante 12 s. (1 Min Reutilización)\n5 cargas"},
[3960] = {name = "Mortero de bronce portátil", additional_info = "Hechizo de 12.5 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTubo de bronce (4), Tornapunta de hierro , Pólvora potente (4), Cuero medio (4)\nRequiereIngeniería\n(165)\n[q2]Uso: Inflige 85 to 115 p. de daño de Fuego y aturde a los objetivos durante 2 s en un radio de 5 m. Cualquier daño anulará el efecto. (1 Min Reutilización)\n8 cargas"},
[3961] = {name = "Girocronátomo", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de hierro , Núcleo de poder de oro"},
[3962] = {name = "Granada de hierro", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de hierro , Pólvora potente , Paño de seda\n(2)\nRequiereIngeniería\n(175)\n[q2]Uso: Inflicts 132 to 218 Fire damage and stuns targets for 3 s in a 3 yard radius. Any damage will break the effect. (1 Min Reutilización)"},
[3963] = {name = "Juego de segador de la cosecha compacto", additional_info = "Hechizo de 25 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTornapunta de hierro (2), Marco de bronce , Girocronátomo (2), Cuero pesado (4)\nNecesitas ser de nivel 30\nRequiereIngeniería\n(175)\n[q2]Uso: Crea un segador de la cosecha compacto que luchará por ti durante 10 min o hasta que lo destruyan. (10 Min Reutilización)"},
