[3966] = {name = "[q2]Monóculo de artesano", additional_info = "Hechizo de 25 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nCuero pesado (6), Citrino (2)\n[q2]Monóculo de artesano\nSe liga al equiparlo\nCabeza Tela\n40 armadura\n+15 intelecto\nDurabilidad 45 / 45\nNecesitas ser de nivel 32\nRequiereIngeniería\n(185)"},
[3967] = {name = "Bomba de hierro grande", additional_info = "Hechizo de 12.5 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de hierro (3), Pólvora potente (3), Contacto de plata\n(2)\nRequiereIngeniería\n(190)\n[q2]Uso: Inflige 149 to 201 p. de daño de Fuego y aturde a los objetivos durante 3 s en un radio de 5 m. Cualquier daño anulará el efecto. (1 Min Reutilización)"},
[3968] = {name = "Mina terrestre goblin", additional_info = "Hechizo de 12.5 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nPólvora potente (3), Barra de hierro (2), Girocronátomo\n[q]Crea una mina terrestre goblin.\nRequiereIngeniería\n(195)\n[q2]Uso: Deja la mina terrestre goblin en el suelo. Cuando una criatura hostil pase cerca de ella, la mina explotará y causará 394 to 506 p. de daño de Fuego. La mina dura 1 min. (1 Min Reutilización)"},
[3969] = {name = "Dragonizo mecánico", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nMarco de bronce , Tornapunta de hierro (4), Girocronátomo (4), Citrino (2), Cableado de fusibles\nSe liga al equiparlo\nÚnicoAbalorio\nNecesitas ser de nivel 30\nRequiereIngeniería\n(200)\n[q2]Uso: Activa tu dragonizo mecánico para que luche por ti durante 1 min. El tiempo de reutilización es de una hora. (1 Hora Reutilización)"},
[3971] = {name = "Aparato de invisibilidad gnómico", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nGirocronátomo (4), Jade (2), Piedra lunar inferior (2), Citrino (2), Cableado de fusibles\nSe liga al equiparlo\nAbalorio\nRequiereIngeniería\n(200)\n[q2]Uso: Otorga invisibilidad durante 10 s. Solo se puede usar cada 60 minutos. (1 Hora Reutilización)"},
