[7121] = {name = "Escudo antimagia", additional_info = "{75 p. de maná} {Alcance de 10 m}\nHechizo de 2 seg\n[q]Crea un escudo antimagia que rodea al taumaturgo y le da inmunidad a la magia durante 10 s."},
[7122] = {name = "Transfusión de sangre", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Drena 20 p. de salud de un enemigo, sanando al taumaturgo hasta el doble de esta cantidad."},
[7124] = {name = "Ofrenda de Arugal", additional_info = "Alcance de 20 m\nHechizo de 2.5 seg\n[q]Inflige 175 to 225 p. de daño de las Sombras a un enemigo cada 60 s durante 5 min."},
[7125] = {name = "Saliva tóxica", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 0.5 seg 1 min de reutilización\n[q]Inflige 17 p. de daño de Naturaleza a un enemigo cada 6 s. También drena 20 p. de maná cada 6 s y se los transfiere al taumaturgo. Dura 2 min."},
[7126] = {name = "Jubón de cuero cosido a mano", additional_info = "Hechizo de 5.125 seg\nComponentes:\nCuero ligero (3), Hilo burdo\nPecho Cuero\n45 armadura\nDurabilidad 50 / 50\nNecesitas ser de nivel 3"},
[7127] = {name = "Voluntad vacilante", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {1 min de reutilización}\n[q]Aumenta el tiempo entre los ataques de un enemigo un 25%, reduce su velocidad de lanzamiento de hechizos un 20% y reduce su movimiento un 20%. Dura 1 min."},
[7128] = {name = "Fuego interno", additional_info = "65 p. de maná\nInstante\n[q]Una ráfaga de energía Sagrada, que aumenta la armadura del taumaturgo en 495 p. Cada golpe de daño cuerpo a cuerpo o a distancia contra el sacerdote restará una carga. Dura 10 min o hasta que se hayan usado 20 cargas."},
