[7131] = {name = "Ilusión Pasivo", additional_info = nil},
[7132] = {name = "Invocar delusiones lupinas", additional_info = "Hechizo de 1 seg 3.333 min de reutilización\n[q]Invoca a 2 delusiones lupinas para ayudar en combate durante 4 min."},
[7133] = {name = "[q2]Pantalones de cuero refinado", additional_info = "Hechizo de 25 seg\nComponentes:\nCuero medio (8), Madeja de paño de lana , Hilo refinado\n[q2]Pantalones de cuero refinado\nSe liga al equiparlo\nPiernas Cuero\n69 armadura\n+5 intelecto\n+4 espíritu\nDurabilidad 55 / 55\nNecesitas ser de nivel 16"},
