[7135] = {name = "[q2]Pantalones de cuero oscuro", additional_info = "Hechizo de 25 seg\nComponentes:\nCuero medio (12), Tinte gris , Hilo refinado\n[q2]Pantalones de cuero oscuro\nSe liga al equiparlo\nPiernas Cuero\n72 armadura\n+8 agilidad\nDurabilidad 55 / 55\nNecesitas ser de nivel 18"},
[7136] = {name = "Puerto de las Sombras", additional_info = nil},
[7137] = {name = "Carga de las Sombras", additional_info = "Instante\n[q]Carga contra un enemigo, aumenta la velocidad e inflige 60 p. de daño extra en el primer ataque."},
[7139] = {name = "Pisotón vil", additional_info = "{Instante} {20 seg de reutilización}\n[q]Inflige daño normal más 20 p. a los enemigos cercanos, lo que los aturde durante 3 s y aumenta 10 p. el daño físico que reciben."},
[7140] = {name = "Exponer debilidad", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Siguiente cuerpo a cuerpo} {25 seg de reutilización}\n[q]Aumenta 5 p. el daño físico que recibe un enemigo durante 5 s."},
