[7144] = {name = "Somnolencia pétrea", additional_info = "Instante\n[q]Convoca el poder de la piedra durante 15 s. Protege a quien lo lanza de cualquier ataque físico, pero le vuelve incapaz de actuar. También le sana 30 p. de daño cada 3 s durante ese tiempo."},
[7145] = {name = "Barrido profundo", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Siguiente cuerpo a cuerpo} {10 seg de reutilización}\n[q]Inflige el daño normal más 30 p. a un enemigo y a sus aliados cercanos. Afecta hasta a 3 objetivos."},
