[7295] = {name = "Drenaje de alma", additional_info = "Alcance de 40 m\nHechizo de 2 seg\n[q]Inmoviliza un enemigo durante 10 s y absorbe 35 p. de salud del enemigo para transferirlos al taumaturgo."},
