[7300] = {name = "Armadura de Escarcha", additional_info = "110 p. de maná\nInstante\n[q]Aumenta 110 p. la armadura. Si un enemigo golpea al taumaturgo, su movimiento puede verse ralentizado un 30% y el tiempo entre sus ataques puede aumentar un 25% durante 5 s. Un mago solo puede tener un tipo de hechizo de armadura activo a la vez. Dura 30 min."},
[7301] = {name = "Armadura de Escarcha", additional_info = "170 p. de maná\nInstante\n[q]Aumenta 200 p. la armadura. Si un enemigo golpea al taumaturgo, su movimiento puede verse ralentizado un 30% y el tiempo entre sus ataques puede aumentar un 25% durante 5 s. Un mago solo puede tener un tipo de hechizo de armadura activo a la vez. Dura 30 min."},
[7302] = {name = "Armadura de hielo", additional_info = "240 p. de maná\nInstante\n[q]Aumenta 290 p. la armadura y 6 p. la resistencia a la Escarcha. Si un enemigo golpea al taumaturgo, su movimiento puede verse ralentizado un 30% y el tiempo entre sus ataques puede aumentar un 25% durante 5 s. Un mago solo puede tener un tipo de hechizo de armadura activo a la vez. Dura 30 min."},
[7320] = {name = "Armadura de hielo", additional_info = "320 p. de maná\nInstante\n[q]Aumenta 380 p. la armadura y 9 p. la resistencia a la Escarcha. Si un enemigo golpea al taumaturgo, su movimiento puede verse ralentizado un 30% y el tiempo entre sus ataques puede aumentar un 25% durante 5 s. Un mago solo puede tener un tipo de hechizo de armadura activo a la vez. Dura 30 min."},
