[7620] = {name = "Pesca", additional_info = "Alcance de 10 - 20 m\nCanalizado (Hechizo de 30 seg)\n[q]Equipa una caña de pescar y encuentra una extensión de agua donde pescar. Haz clic derecho sobre el cebo cuando veas que se mueve para atrapar al pez. Cuanto mayor sea la habilidad, mayor será tu probabilidad de pescar con éxito en zonas de niveles más altos."},
[7621] = {name = "Maldición de Arugal", additional_info = "{75 p. de maná} {Alcance de 30 m}\nInstante\n[q]Transforma al enemigo en glotón Colmillo Oscuro encadenándolo a la voluntad del taumaturgo durante 10 s."},
[7623] = {name = "[q2]Toga de lino marrón", additional_info = "Hechizo de 8 seg\nComponentes:\nMadeja de paño de lino (3), Hilo burdo\n[q2]Toga de lino marrón\nSe liga al equiparlo\nPecho Tela\n19 armadura\n+1 espíritu\nDurabilidad 45 / 45\nNecesitas ser de nivel 5"},
