[11082] = {name = "Megavoltio", additional_info = "Alcance de 30 m\nHechizo de 2 seg\n[q]Inflige 5 p. de daño de Naturaleza a los enemigos en un cono frente al taumaturgo."},
[11083] = {name = "Alma ardiente", additional_info = "[q0]Talento\n[q]Otorga a tus hechizos de Fuego un 35% de probabilidad de no perder tiempo de lanzamiento cuando recibes daño, y reduce la amenaza que generan un 15%."},
[11084] = {name = "Choque", additional_info = "Alcance de 20 m\n{Instante} {6 seg de reutilización}\n[q]Lanza instantáneamente una descarga de relámpago a un enemigo y le inflige 269 to 286 p. de daño de Naturaleza."},
[11085] = {name = "Descarga en cadena", additional_info = "Alcance de 30 m\nHechizo de 2.5 seg\n[q]Golpea al enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 3 objetivos y les inflige 162 to 181 p. de daño de Naturaleza a cada uno."},
[11086] = {name = "Guarda de Zum'rah", additional_info = "Instante\n[q]Lanza un Tótem de guarda de Zum'rah que dura 20 s e invoca periódicamente un esqueleto de Zum'rah. Cada esqueleto dura 20 s."},
