[11108] = {name = "Fogonazo mejorado", additional_info = "[q0]Talento\n[q]Aumenta un 5% la probabilidad de golpe crítico de tu hechizo Fogonazo."},
[11113] = {name = "Ola explosiva", additional_info = "[q0]Talento\n215 p. de maná\n{Instante} {45 seg de reutilización}\n[q]El taumaturgo irradia una ola de llamas que inflige 160 to 192 p. de daño de fuego a todos los enemigos que quedan atrapados en la explosión y los atonta durante 6 s."},
[11115] = {name = "Masa crítica", additional_info = "[q0]Talento\n[q]Aumenta un 2% la probabilidad de golpe crítico de tus hechizos de Fuego."},
[11119] = {name = "Ignición", additional_info = "[q0]Talento\n[q]Tus golpes críticos de hechizos de daño de Fuego hacen que el objetivo arda un 8% extra del daño del hechizo durante 4 s."},
