[13578] = {name = "Fuego de jade", additional_info = "Instante\n[q]Rodea al taumaturgo con magia abrasadora durante 8 s. Las llamas aumentan la armadura un 50% e infligen 50 p. de daño a los atacantes cuerpo a cuerpo."},
[13579] = {name = "Gubia", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Inflige 20 p. de daño a un enemigo y lo aturde durante un máximo de 4 s. Dejarás de atacar automáticamente. El objetivo debe estar de cara a ti. Cualquier daño que reciba el objetivo aturdido lo revivirá."},
[13582] = {name = "Veneno mortal", additional_info = "Alcance de 10 m\nHechizo de 2 seg\n[q]Inflige 2 p. de daño de Naturaleza a los enemigos cercanos cada 10 s durante 2 min."},
[13583] = {name = "Maldición de los Muertobosque", additional_info = "Alcance de 10 m\nHechizo de 2 seg\n[q]Reduce un 50% los efectos de sanación en un enemigo durante 2 min."},
[13584] = {name = "Golpear", additional_info = "Alcance de ataques cuerpo a cuerpo\nSiguiente cuerpo a cuerpo\n[q]Golpea a un enemigo e inflige daño normal más 5 p."},
[13585] = {name = "Escudo de relámpagos", additional_info = "{5 p. de maná} {Alcance de 30 m}\n{Instante} {10 seg de reutilización}\n[q]Rodea a un aliado con 3 bolas de relámpagos con un 50% de probabilidad de infligir 2 p. de daño a los atacantes cuerpo a cuerpo o a distancia. Cada vez que el escudo de relámpagos golpea, se disipa una bola de relámpagos. El escudo expira tras 10 min o cuando ha golpeado 3 veces.\n(Probabilidad de que accione: 50%)"},
[13586] = {name = "Aspersión", additional_info = "Instante\n[q]Lanza agua en todas direcciones, lo que inflige daño de Escarcha a los enemigos cercanos y los repele."},
[13587] = {name = "Velocidad de montura", additional_info = "5 seg de reutilización\n[q]Aumenta la velocidad de la montura un 3%."},
