[14293] = {name = "[q2]Varita mágica inferior", additional_info = "Hechizo de 10 seg\nHerramientas: Vara rúnica de cobre\nComponentes:\nMadera simple , Esencia mágica inferior\n[q]Crea una varita mágica inferior.\n[q2]Varita mágica inferior\nSe liga al equiparlo\nA distancia Varita\n12 - 22 p. de daño de Arcano Velocidad 1.50\n(11.33 p. de daño por segundo)\nDurabilidad 35 / 35\nNecesitas ser de nivel 5"},
[14294] = {name = "Salva", additional_info = "{420 p. de maná} {Alcance de 8 - 35 m}\nCanalizado (Hechizo de 6 seg) 1 min de reutilización\nRequiere Arma a distancia\n[q]Dispara continuamente una salva de munición al área objetivo e inflige 65 p. de daño Arcano a todos los objetivos enemigos en un radio de 8 m cada segundo durante 6 s."},
[14295] = {name = "Salva", additional_info = "{490 p. de maná} {Alcance de 8 - 35 m}\nCanalizado (Hechizo de 6 seg) 1 min de reutilización\nRequiere Arma a distancia\n[q]Dispara continuamente una salva de munición al área objetivo e inflige 80 p. de daño Arcano a todos los objetivos enemigos en un radio de 8 m cada segundo durante 6 s."},
[14296] = {name = "Flecha negra", additional_info = "Alcance de 8 - 35 m\nInstante\nRequiere Arma a distancia\n[q]Dispara una flecha negra al objetivo que frena su movimiento en 70%, causa un daño de Sombras de 150 p. y absorbe más de 150 p. de su maná durante 30 s."},
[14297] = {name = "Tormenta de las Sombras", additional_info = "Alcance de 45 m\nInstante\n[q]Lanza Descargas de las Sombras a los enemigos que se encuentren entre 7 y 14 m."},
