[14315] = {name = "Efecto de Trampa explosiva", additional_info = nil},
[14316] = {name = "Trampa explosiva", additional_info = "395 p. de maná\n{Instante} {15 seg de reutilización}\n[q]Coloca una trampa de fuego que explota cuando se acerca un enemigo e inflige 145 to 193 p. de daño de Fuego y 240 p. de daño de Fuego extra durante 20 s a todos los enemigos en un radio de 10 m. La trampa dura 1 min. Las trampas solo pueden colocarse cuando estás fuera de combate y solo puede haber una trampa activa a la vez."},
[14317] = {name = "Trampa explosiva", additional_info = "520 p. de maná\n{Instante} {15 seg de reutilización}\n[q]Coloca una trampa de fuego que explota cuando se acerca un enemigo e inflige 208 to 265 p. de daño de Fuego y 330 p. de daño de Fuego extra durante 20 s a todos los enemigos en un radio de 10 m. La trampa dura 1 min. Las trampas solo pueden colocarse cuando estás fuera de combate y solo puede haber una trampa activa a la vez."},
[14318] = {name = "Aspecto del halcón", additional_info = "35 p. de maná\nInstante\n[q]El cazador asume los aspectos de un halcón y aumenta 35 p. el poder de ataque a distancia. Solo puede haber un aspecto activo a la vez."},
