[14514] = {name = "Traslación", additional_info = "75 p. de maná\nInstante\n[q]Teletransporta al taumaturgo 20 m hacia delante salvo si hay algún obstáculo y lo libera de sus ataduras."},
[14515] = {name = "Dominar mente", additional_info = "{30 p. de maná} {Alcance de 20 m}\nHechizo de 2 seg\n[q]Controla a un enemigo humanoide hasta el nivel 25 durante 15 s."},
[14516] = {name = "Golpear", additional_info = "Alcance de ataques cuerpo a cuerpo\nSiguiente cuerpo a cuerpo\nRequiere Arma cuerpo a cuerpo\n[q]Golpea a un enemigo e inflige daño cuerpo a cuerpo aumentado."},
[14517] = {name = "Golpe de cruzado", additional_info = "{40 p. de maná} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Inflige 27 p. de daño a un enemigo y aumenta el daño Sagrado que recibe 10 p. por cada Golpe de cruzado. Puede aplicarse hasta 5 veces. Dura 30 s."},
[14518] = {name = "Golpe de cruzado", additional_info = "{40 p. de maná} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Inflige 50 p. de daño a un enemigo y aumenta el daño Sagrado que recibe 20 p. por cada Golpe de cruzado. Puede aplicarse hasta 5 veces. Dura 30 s."},
[14520] = {name = "Agilidad mental", additional_info = "[q0]Talento\n[q]Reduce el coste de maná de tus hechizos instantáneos un 2%."},
[14521] = {name = "Meditación", additional_info = "[q0]Talento\n[q]Permite que continúe un 5% de la regeneración de maná mientras lanzas hechizos."},
[14522] = {name = "Voluntad inquebrantable", additional_info = "[q0]Talento\n[q]Aumenta tu probabilidad de resistir los efectos de Aturdir, Miedo y Silencio un 3% extra."},
[14523] = {name = "Resolución silenciosa", additional_info = "[q0]Talento\n[q]Reduce un 4% la amenaza generada por tus hechizos."},
[14524] = {name = "Especialización en varitas", additional_info = "[q0]Talento\n[q]Aumenta el daño con varitas un 5%."},
[14525] = {name = "Especialización en varitas", additional_info = "[q0]Talento\n[q]Aumenta el daño con varitas un 10%."},
[14526] = {name = "Especialización en varitas", additional_info = "[q0]Talento\n[q]Aumenta el daño con varitas un 15%."},
[14527] = {name = "Especialización en varitas", additional_info = "[q0]Talento\n[q]Aumenta el daño con varitas un 20%."},
[14528] = {name = "Especialización en varitas", additional_info = "[q0]Talento\n[q]Aumenta el daño con varitas un 25%."},
[14530] = {name = "Velocidad", additional_info = "Instante\n[q]Aumenta la velocidad de carrera un 40% durante 10 s."},
[14531] = {name = "Martirio", additional_info = "[q0]Talento\n[q]Te otorga un 50% de probabilidad de obtener el efecto de Lanzamiento enfocado, que dura 6 s después de ser víctima de un golpe crítico de un ataque cuerpo a cuerpo o a distancia. El efecto Lanzamiento enfocado impide que pierdas tiempo de lanzamiento cuando recibes daño y aumenta la resistencia a los efectos de Interrumpir un 10%.\n(Probabilidad de que accione: 50%)"},
[14532] = {name = "Veneno de trepador", additional_info = "Hechizo de 2 seg\n[q]Aumenta un 30% el daño físico infligido a los enemigos cercanos durante 5 min."},
[14533] = {name = "Disyunción", additional_info = "Instante\n[q]Aumenta un 50% el daño de Fuego, de Escarcha y Arcanos infligido a los enemigos cercanos durante 5 min."},
[14534] = {name = "Aguijón con púas", additional_info = "Instante\n[q]Aumenta el tiempo entre los ataques de los enemigos cercanos un 54% durante 5 min."},
[14535] = {name = "Dolencia dragante", additional_info = "Instante\n[q]Reduce todos los atributos de los enemigos cercanos un 25% durante 5 min."},
[14537] = {name = "Bolsa de seis demonios", additional_info = "Alcance de 30 m\nInstante\n[q]Golpea a los enemigos situados frente a ti con el poder del viento, fuego... ¡y todo eso!"},
[14538] = {name = "Choque de aura", additional_info = "Instante\n[q]Reduce la velocidad de lanzamiento de los enemigos cercanos un 35% durante 5 min."},
[14539] = {name = "Enzima pútrido", additional_info = "Instante\n[q]Aumenta un 50% el daño de Naturaleza sufridos por los enemigos cercanos y aumenta un 50% el daño de las Sombras que reciben. Dura 5 min."},
