[14875] = {name = "Maldición de agonía", additional_info = "{75 p. de maná} {Alcance de 30 m}\nInstante\n[q]Lanza sobre un enemigo una Maldición de agonía, inflige daño de las Sombras cada 3 s durante 30 s. Un brujo solo puede tener una maldición activa a la vez sobre un mismo objetivo."},
[14887] = {name = "Salva de descarga de las Sombras", additional_info = "{160 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Lanza misiles de magia oscura a los enemigos cercanos y les inflige daño de las Sombras."},
