[14895] = {name = "Abrumar", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {5 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Abruma instantáneamente a un enemigo y le inflige daño con arma más 15 p. Solo puede utilizarse después de que el objetivo esquive. El Abrumar no se puede bloquear, ni esquivar ni parar."},
[14897] = {name = "Veneno ralentizante", additional_info = "Alcance de 30 m\nInstante\n[q]Aumenta el tiempo entre los ataques de un enemigo un 25% y ralentiza su velocidad de movimiento un 30% durante 25 s."},
[14898] = {name = "Sanación espiritual", additional_info = "[q0]Talento\n[q]Aumenta la efectividad de tus hechizos de sanación un 2%."},
[14900] = {name = "Sanación en cadena", additional_info = "{150 p. de maná} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Imbuye a un aliado herido con energía de sanación que se extiende a otro aliado cercano. El hechizo afecta hasta a 3 objetivos, pero la energía de sanación disminuye un 50% en cada objetivo sucesivo."},
[14901] = {name = "Guía espiritual", additional_info = "[q0]Talento\n[q]Aumenta el daño y la sanación con hechizos hasta un 5% de tu espíritu total."},
[14902] = {name = "Golpe bajo", additional_info = "{60 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\nRequiere Sigilo\n[q]Aturde a un enemigo durante 4 s. Tienes que estar en sigilo. Otorga 2 p. de combo."},
[14903] = {name = "Ruptura", additional_info = "{25 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Inflige daño físico a un enemigo cada 2 s. Los puntos de combo extra aumentan el daño periódico infligido y la duración total."},
