[14907] = {name = "Nova de Escarcha", additional_info = "Instante\n[q]Inflige daño de Escarcha a los enemigos cercanos y los inmoviliza durante un máximo de 8 s."},
[14908] = {name = "Renovar mejorado", additional_info = "[q0]Talento\n[q]Aumenta la cantidad sanada por tu hechizo Renovar un 5%."},
