[16724] = {name = "[q3]Yelmo almablanca", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de torio (20), Barra de torio encantado (4), Barra de veraplata (6), Barra de oro (6), Diamante de Azeroth (2)\n[q3]Yelmo almablanca\nSe liga al equiparlo\nCabeza Placas\n[q2]629 armadura\n+15 intelecto\n+15 espíritu\nDurabilidad 80 / 80\nNecesitas ser de nivel 55\n[q2]Equipar: Aumenta hasta 35 p. la sanación de los hechizos y efectos."},
[16725] = {name = "[q2]Leotardos radiantes", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de torio (20), Corazón de fuego (4)\n[q2]Leotardos radiantes\nSe liga al equiparlo\nPiernas Malla\n286 armadura\n+18 resistencia a Escarcha\n+18 resistencia a Sombras\nDurabilidad 75 / 75\nNecesitas ser de nivel 56"},
