[17615] = {name = "Quemadura de maná", additional_info = "{95 p. de maná} {Alcance de 30 m}\nInstante\n[q]Alcanza al enemigo con una descarga antimaná. Por cada punto de maná que la descarga consume, el objetivo sufre 0.5 p. de daño."},
[17616] = {name = "Deflagración de cadáver", additional_info = "Alcance de 30 m\nInstante\n[q]Hace que un cadáver explote, e inflige 1500 p. de daño de las Sombras a los enemigos cercanos."},
