[17618] = {name = "Invocar lacayo resucitado", additional_info = "{100 p. de maná} {Alcance de 30 m}\nHechizo de 2 seg\n[q]Invoca a 1 lacayo resucitado para ayudar en combate durante 1 min."},
[17619] = {name = "Piedra de alquimista", additional_info = "Instante\n[q]Aumenta un 33% los efectos de las pociones de salud y maná en el portador."},
[17620] = {name = "Drenar vida", additional_info = "{75 p. de maná} {Alcance de 20 m}\nCanalizado (Hechizo de 5 seg)\n[q]Drena 240 p. de salud de un enemigo durante 5 s y se la transfiere al taumaturgo."},
