[17624] = {name = "Petrificación", additional_info = "Instante\n[q]Te conviertes en piedra y obtienes protección contra todos los ataques físicos y hechizos durante 1 min, pero no puedes atacar, moverte ni lanzar hechizos durante ese período. Solo puedes disfrutar del efecto de un frasco a la vez."},
[17625] = {name = "Aura profana", additional_info = "[q]Aumenta tu velocidad de regeneración de vida y la velocidad de movimiento."},
[17626] = {name = "Frasco de los titanes", additional_info = "Instante\n[q]Aumenta 1200 p. la salud máxima del jugador durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte."},
[17627] = {name = "Sabiduría destilada", additional_info = "Instante\n[q]Aumenta el maná máximo del jugador 2000 p. durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte."},
[17628] = {name = "Poder supremo", additional_info = "{Instante} {1 seg de reutilización}\n[q]Aumenta el daño que infligen los hechizos y efectos mágicos hasta 150 p. durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte."},
[17629] = {name = "Resistencia cromática", additional_info = "Instante\n[q]Aumenta 25 p. tu resistencia a todas las escuelas de magia durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte y se acumula con todos los demás objetos y hechizos de resistencia."},
[17630] = {name = "Quemadura de maná", additional_info = "{95 p. de maná} {Alcance de 30 m}\nInstante\n[q]Alcanza al enemigo con una descarga antimaná. Por cada punto de maná que la descarga consume, el objetivo sufre 0.5 p. de daño."},
[17631] = {name = "Lamento de almas", additional_info = "Alcance de 100 m\nInstante\n[q]Inflige daño de las Sombras a los enemigos cercanos, los golpea con descargas antimaná y los derriba."},
[17632] = {name = "[q4]Piedra de alquimista", additional_info = "Hechizo de 1 min\nComponentes:\nEsencia de Fuego (8), Esencia de tierra (8), Esencia de aire (8), Esencia de agua (8), Esencia viva (8), Vitriolo negro (2), Loto negro (4)\n[q4]Piedra de alquimista\nSe liga al recogerlo\nÚnicoAbalorio\n+8 espíritu\nRequiereAlquimia\n(300)\n[q2]Equipar: Aumenta un 33% los efectos de las pociones de salud y maná en el portador."},
