[18457] = {name = "[q4]Toga del archimago", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de paño rúnico (12), Esencia de Fuego (10), Esencia de aire (10), Esencia de tierra (10), Esencia de agua (10), Hilo rúnico (2)\n[q4]Toga del archimago\nSe liga al recogerlo\nPecho Tela\n96 armadura\n+12 intelecto\nDurabilidad 100 / 100\nClases: Mago\nNecesitas ser de nivel 57\n[q2]Equipar: Aumenta hasta 40 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Mejora tu probabilidad de asestar un golpe crítico con hechizos un 1%.\n[q2]Uso: Restaura 375 to 625 p. de maná. (5 Min Reutilización)"},
[18458] = {name = "[q4]Toga del Vacío", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de paño rúnico (12), Runa demoníaca (20), Tela vil (40), Esencia de Fuego (12), Esencia de no-muerto (12), Hilo rúnico (2)\n[q4]Toga del Vacío\nSe liga al recogerlo\nPecho Tela\n96 armadura\n+14 aguante\nDurabilidad 100 / 100\nClases: Brujo\nNecesitas ser de nivel 57\n[q2]Equipar: Aumenta hasta 46 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Sana a tu mascota 450 to 750 p. (10 Min Reutilización)"},
[18459] = {name = "Incinerar", additional_info = "[q0]Talento\n[q]Aumenta un 2% la probabilidad de golpe crítico de tus hechizos Explosión de Fuego y Agostar."},
