[18545] = {name = "Picadura de escórpido", additional_info = "{10 p. de maná} {Alcance de 5 - 30 m}\nRequiere Arma a distancia\n[q]Pica al enemigo y reduce su fuerza y agilidad 1 p. durante 20 s."},
[18546] = {name = "Ultravelocidad", additional_info = "Instante\n[q]Inmoviliza al taumaturgo pero aumenta la velocidad de sus ataques un 100% durante 6 s."},
[18547] = {name = "Fuerza de voluntad", additional_info = "[q0]Talento\n[q]Aumenta el daño de hechizos en un 2% y la probabilidad de conseguir un golpe crítico con tus hechizos ofensivos en un 2%."},
