[19128] = {name = "Derribo", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {5 seg de reutilización}\n[q]Inflige 60 to 80 p. de daño a un enemigo y a sus aliados más cercanos, y los aturde durante 2 s. Afecta hasta a 5 objetivos."},
[19129] = {name = "Temblor monumental", additional_info = "Instante\n[q]Provoca un temblor de tierra monumental que inflige 900 to 1100 p. de daño a los enemigos cercanos e interrumpe el lanzamiento de hechizos durante 2 s."},
[19130] = {name = "Revancha", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Contraataque instantáneo que inflige 31 to 41 p. de daño a un enemigo. La Revancha tiene que seguir a bloquear, esquivar o parar."},
[19131] = {name = "Carga con escudo", additional_info = "Alcance de 8 - 25 m\nInstante\n[q]Carga contra el enemigo, lo derriba y le inflige el daño normal más 75 p."},
[19132] = {name = "Arremetida poderosa", additional_info = "Alcance de 10 m\nInstante\n[q]Inflige el daño normal más 25 p. a un enemigo y lo derriba."},
[19133] = {name = "Choque de Escarcha", additional_info = "Alcance de 20 m\nInstante\n[q]Inflige daño de Escarcha a un enemigo y reduce su velocidad de movimiento durante 8 s."},
[19134] = {name = "Grito intimidador", additional_info = "Alcance de 10 m\nInstante\n[q]Grita a un enemigo, lo que lo paraliza con terror durante 8 s y hace que todos los demás enemigos cercanos huyan despavoridos."},
[19135] = {name = "Avatar", additional_info = "Instante\n[q]Aumenta un 50% el daño físico infligido por el taumaturgo y mejora un 50% su armadura durante 15 s."},
[19136] = {name = "Descarga tormentosa", additional_info = "Alcance de 30 m\nInstante\n[q]Inflige 165 p. de daño a un enemigo y lo aturde durante 5 s."},
[19137] = {name = "Ralentizar", additional_info = "{140 p. de maná} {Alcance de 30 m}\nInstante\n[q]Aumenta el tiempo entre los ataques de los enemigos cercanos un 54% y ralentiza su velocidad de movimiento un 60% durante 20 s."},
[19138] = {name = "Invocar a Garraluna", additional_info = "Alcance de 10 m\nHechizo de 3 seg\n[q]Utilízalo cerca de una piedra de lechúcico lunar para invocar al defensor de la piedra, Garraluna."},
