[19792] = {name = "[q2]Rifle de torio", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTubo de mitril (2), Envoltura de mitril (2), Trasto de torio (2), Barra de torio (4), Mira mortal\n[q2]Rifle de torio\nSe liga al equiparlo\nA distancia Arma de fuego\n42 - 79 p. de daño Velocidad 2.50\n(24.20 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 47\n[q2]Equipar: Aumenta 17 p. el poder de ataque a distancia."},
[19793] = {name = "Sapo mecánico casi vivo", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nEsencia viva , Trasto de torio (4), Núcleo de poder de oro , Cuero basto\nSe liga al usarlo\n[q2]Uso: Haz clic con el botón derecho del ratón para invocar y retirar a tu sapo mecánico casi vivo."},
[19794] = {name = "[q2]Gafas de poder con hechizos Xtremo Plus", additional_info = "Hechizo de 45 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nGafas de poder con hechizos Xtremo , Rubí estrella (4), Cuero encantado (2), Paño rúnico (8)\n[q2]Gafas de poder con hechizos Xtremo Plus\nSe liga al equiparlo\nCabeza Tela\n57 armadura\nDurabilidad 45 / 45\nRequiereIngeniería\n(270)\n[q2]Equipar: Aumenta hasta 27 p. el daño y la sanación de los hechizos y efectos mágicos."},
[19795] = {name = "Tubo de torio", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de torio (6)"},
[19796] = {name = "[q3]Rifle Hierro Negro", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTubo de torio (2), Barra de hierro negro (6), Mira mortal (2), Zafiro azul (2), Ópalo grande (2), Cuero basto (4)\n[q3]Rifle Hierro Negro\nSe liga al equiparlo\nA distancia Arma de fuego\n53 - 100 p. de daño Velocidad 2.70\n(28.33 p. de daño por segundo)\nDurabilidad 75 / 75\nNecesitas ser de nivel 50\n[q2]Equipar: Probabilidad de golpear a tu objetivo a distancia con un Disparo de las Sombras, inflige 18 to 26 de daño de las Sombras."},
