[20697] = {name = "Palabra de poder: escudo", additional_info = "{200 p. de maná} {Alcance de 40 m}\nInstante\n[q]Envuelve al taumaturgo en un escudo que dura hasta 30 s y absorbe un máximo de 5000 p. de daño físico o mágico. Los ataques físicos no interrumpen los hechizos."},
[20698] = {name = "Cólera", additional_info = "{200 p. de maná} {Alcance de 40 m}\nHechizo de 1 seg\n[q]Lanza una descarga de relámpago a un enemigo y le inflige 1020 to 1380 p. de daño de Naturaleza."},
[20699] = {name = "Raíces enredadoras", additional_info = "Alcance de 30 m\nInstante\n[q]Enreda a los enemigos cercanos en raíces, lo que inflige 333 to 367 p. de daño de Naturaleza cada 3 s y los inmoviliza durante un máximo de 15 s."},
[20700] = {name = "Ritual de fatalidad", additional_info = nil},
[20701] = {name = "Rejuvenecimiento", additional_info = "{200 p. de maná} {Alcance de 40 m}\nInstante\n[q]Sana a un aliado cada 3 s durante 12 s."},
[20702] = {name = "Invocar aliados Antárbol", additional_info = "Hechizo de 1.5 seg\n[q]Invoca a 2 antárboles aliados para acompañar al taumaturgo."},
[20703] = {name = "Ejecutar", additional_info = nil},
[20704] = {name = "Ejecutar", additional_info = nil},
[20705] = {name = "Escudo de poder 500", additional_info = "[q]Al recibir un golpe crítico en combate hay un 1% de probabilidad de tener protección de un escudo mágico que absorbe los siguientes 515 p. de daño.\n(Probabilidad de que accione: 5%)"},
[20706] = {name = "Palabra de poder: escudo 500", additional_info = "Alcance de 40 m\nInstante\n[q]Refuerza con un escudo a los objetivos, amortiguando 515 p. de daño. Dura 30 s. Mientras dura el escudo, el lanzamiento de hechizos no se verá interrumpido por el daño. Una vez protegido, el objetivo no puede recibir protección de nuevo hasta pasados 15 s."},
[20707] = {name = "Resurrección con piedra de alma", additional_info = "Alcance de 30 m\nHechizo de 3 seg\n[q]Guarda el alma del objetivo aliado de forma que si muere mientras su alma está almacenada, resucitará con 400 p. de salud y 700 p. de maná."},
[20708] = {name = "Estado de emotexto listo", additional_info = nil},
[20709] = {name = "Llave esqueleto de arcanita", additional_info = "Alcance de 5 m\nHechizo de 5 seg\n[q]Permite abrir cerraduras complicadas. La llave esqueleto se consume durante el proceso."},
[20710] = {name = "Coraje interno 20", additional_info = "[q]+10% de probabilidad de resistir los hechizos de Miedo y sus efectos."},
[20711] = {name = "Espíritu redentor", additional_info = "[q0]Talento\n[q]Al morir, el sacerdote se transforma en Espíritu redentor durante 10 s. El Espíritu redentor no puede moverse, atacar, ser atacado o ser objetivo de ningún hechizo o efecto. Mientras está en esta forma, el sacerdote puede lanzar cualquier hechizo de sanación sin coste. Cuando el efecto acaba, el sacerdote muere."},
[20712] = {name = "Aliento de llamas", additional_info = "Instante\n[q]Inflige 833 to 967 p. de daño de Fuego a los enemigos en un cono frente al taumaturgo."},
[20714] = {name = "Bola de Fuego", additional_info = "Alcance de 40 m\nHechizo de 2 seg\n[q]Inflige daño de Fuego a un enemigo."},
[20715] = {name = "Emotexto: OmniLanzaHechizos", additional_info = nil},
[20716] = {name = "Aliento de arena", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 2 seg\n[q]Inflige daño Arcano a los enemigos situados en un cono frente al taumaturgo, ralentizando su movimiento y aumentando el tiempo entre sus ataques durante 10 s."},
[20717] = {name = "Aliento de arena", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 2 seg\n[q]Inflige daño Arcano a los enemigos situados en un cono frente al taumaturgo, ralentizando su movimiento y aumentando el tiempo entre sus ataques durante 10 s."},
[20718] = {name = "Emotexto: DirecciónLanzaHechizos", additional_info = nil},
[20719] = {name = "Gracia felina", additional_info = "Requiere Forma felina\n[q]Reduce el daño de las caídas."},
[20720] = {name = "Descarga Arcana", additional_info = "Alcance de 40 m\nHechizo de 1 seg\n[q]Lanza una descarga mágica a un enemigo y le inflige daño Arcano."},
