[20732] = {name = "Poder de ataque 15", additional_info = "[q]Aumenta 15 p. el poder de ataque."},
[20733] = {name = "Flecha negra", additional_info = "Hechizo de 2 seg\n[q]Maldice a un enemigo y le inflige periódicamente daño de las Sombras durante 1 min. Si el objetivo muere mientras el efecto de Flecha negra sigue activo, se invocará 2 esqueletos desde su cadáver."},
