[20735] = {name = "Multidisparo", additional_info = "Alcance de 30 m\nInstante\nRequiere Arma a distancia\n[q]Dispara una descarga de misiles contra el enemigo y sus aliados cercanos que alcanza a un máximo de 10 objetivos y aumenta 225 p el daño normal."},
[20736] = {name = "Disparo de distracción", additional_info = "{20 p. de maná} {Alcance de 8 - 35 m}\n8 seg de reutilización\nRequiere Arma a distancia\n[q]Distrae al objetivo y genera amenaza."},
