[20909] = {name = "Contraataque", additional_info = "[q0]Talento\n{65 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {5 seg de reutilización}\n[q]Un golpe que se activa tras parar el ataque de un oponente. Este ataque causa 70 p. de daño e inmoviliza al objetivo durante 5 s. El contraataque no se puede bloquear, esquivar ni parar."},
[20910] = {name = "Contraataque", additional_info = "[q0]Talento\n{85 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {5 seg de reutilización}\n[q]Un golpe que se activa tras parar el ataque de un oponente. Este ataque causa 110 p. de daño e inmoviliza al objetivo durante 5 s. El contraataque no se puede bloquear, esquivar ni parar."},
[20911] = {name = "Bendición de salvaguardia", additional_info = "[q0]Talento\n{60 p. de maná} {Alcance de 30 m}\nInstante\n[q]Coloca una bendición sobre el objetivo aliado que reduce el daño recibido de todas las fuentes 10 p. durante 5 min. Además, cuando el objetivo bloquea un ataque cuerpo a cuerpo, el atacante recibe 14 p. de daño Sagrado. Los jugadores solo pueden tener una bendición activa por Paladín a la vez."},
[20912] = {name = "Bendición de salvaguardia", additional_info = "[q0]Talento\n{85 p. de maná} {Alcance de 30 m}\nInstante\n[q]Coloca una bendición sobre el objetivo aliado que reduce el daño recibido de todas las fuentes 14 p. durante 5 min. Además, cuando el objetivo bloquea un ataque cuerpo a cuerpo, el atacante recibe 21 p. de daño Sagrado. Los jugadores solo pueden tener una bendición activa por Paladín a la vez."},
[20913] = {name = "Bendición de salvaguardia", additional_info = "[q0]Talento\n{110 p. de maná} {Alcance de 30 m}\nInstante\n[q]Da a un objetivo amistoso una Bendición que reduce los daños sufridos en 19 p. durante 5 min. Además, cuando el objetivo bloquea un ataque cuerpo a cuerpo, el atacante recibirá 28 p. de daño Sagrado. Los jugadores solo pueden tener una Bendición con ellos por paladín a la vez."},
[20914] = {name = "Bendición de salvaguardia", additional_info = "[q0]Talento\n{135 p. de maná} {Alcance de 30 m}\nInstante\n[q]Da a un objetivo amistoso una Bendición que reduce los daños sufridos en 24 p. durante 5 min. Además, cuando el objetivo bloquea un ataque cuerpo a cuerpo, el atacante recibirá 35 p. de daño Sagrado. Los jugadores solo pueden tener una Bendición con ellos por paladín a la vez."},
[20915] = {name = "Sello de orden", additional_info = "[q0]Talento\n110 p. de maná\nInstante\n[q]Le da al paladín la oportunidad de infligir daño Sagrado extra igual al 70% del daño de arma normal. El paladín solo puede tener un sello activado al mismo tiempo. Dura 30 s.\n\n Al liberar la energía de este sello, se juzgará a un enemigo, infligiendo instantáneamente 97 to 105 p. de daño Sagrado y 194 to 209 p. si el objetivo está aturdido o incapacitado.\n(1s de reutilización)"},
[20916] = {name = "Trucha cabeza de mitril", additional_info = "Hechizo de 3 seg\nComponentes:\nTrucha cabeza de mitril cruda\nNecesitas ser de nivel 25\n[q2]Uso: Restaura 874.8 p. de salud durante 27 s. Debes permanecer sentado mientras comes."},
