[23077] = {name = "[q3]Reflector de hielo girohielo", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTrasto de torio (6), Transformador de veraplata (2), Zafiro azul (2), Esencia de Fuego (4), Aceite de Escarcha (2), Setelo (4)\n[q3]Reflector de hielo girohielo\nSe liga al equiparlo\nAbalorio\n+15 resistencia a Escarcha\nNecesitas ser de nivel 47\nRequiereIngeniería\n(260)\n[q2]Uso: Devuelve los hechizos de Escarcha al taumaturgo durante 5 s. (5 Min Reutilización)"},
[23078] = {name = "Desfibriladores goblin XL", additional_info = "Hechizo de 12.5 seg\nComponentes:\nTrasto de torio (2), Transformador de veraplata (2), Cableado de fusibles (2), Seda de araña Tejehierro (2), Rubí estrella (2)\nAbalorio\nRequiereIngeniería\n(265)\n[q2]Uso: A veces los desfibriladores podrán devolver a un jugador muerto a la vida. No se pueden usar en combate. (30 Min Reutilización)"},
[23079] = {name = "[q2]Recombobulador sublime", additional_info = "Hechizo de 25 seg\nComponentes:\nTubo de torio (2), Transformador de veraplata , Paño rúnico (2)\n[q2]Recombobulador sublime\nAbalorio\nRequiereIngeniería\n(275)\n[q2]Uso: Elimina los efectos de polimorfia de un objetivo aliado. También restaura 375 to 625 p. de salud y maná. (5 Min Reutilización)\n10 cargas"},
[23080] = {name = "Carga de seforio potente", additional_info = "Hechizo de 12.5 seg\nComponentes:\nTrasto de torio (2), Pólvora densa (3), Cuero basto (2), Agua de manantial refrescante\nRequiereIngeniería\n(275)\n[q2]Uso: Hace explotar la cerradura de casi cualquier puerta cerrada."},
[23081] = {name = "[q3]Reflector de llamas hiperradiante", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de hierro negro (4), Transformador de veraplata (3), Esencia de agua (6), Rubí estrella (4), Diamante de Azeroth (2)\n[q3]Reflector de llamas hiperradiante\nSe liga al equiparlo\nAbalorio\n+18 resistencia a Fuego\nNecesitas ser de nivel 53\nRequiereIngeniería\n(290)\n[q2]Uso: Devuelve los hechizos de Fuego al taumaturgo durante 5 s. (5 Min Reutilización)"},
[23082] = {name = "[q3]Reflector de las Sombras ultradeslumbrante", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de hierro negro (8), Transformador de veraplata (4), Esencia viva (6), Esencia de no-muerto (4), Diamante de Azeroth (2), Ópalo grande (2)\n[q3]Reflector de las Sombras ultradeslumbrante\nSe liga al equiparlo\nAbalorio\n+20 resistencia a Sombras\nNecesitas ser de nivel 55\nRequiereIngeniería\n(300)\n[q2]Uso: Devuelve los hechizos de las Sombras al taumaturgo durante 5 s. (5 Min Reutilización)"},
