[23720] = {name = "Bendición del Libro Negro", additional_info = "Alcance de 100 m\nInstante\n[q]Potencia tu mascota, lo que aumenta el daño de mascota un 100% y la armadura de mascota un 100% durante 30 s. Este hechizo solo afectará a un diablillo, súcubo, íncubo, abisario o manáfago."},
[23721] = {name = "Infundir Arcano", additional_info = "Instante\n[q]Te infunde energía Arcana, haciendo que el siguiente Disparo Arcano que efectúes en 10 s explosione en el objetivo. La Detonación Arcana causará daño de 185 to 215 p. a los enemigos que estén cerca del objetivo."},
