[24091] = {name = "[q3]Jubón vid de sangre", additional_info = "Hechizo de 1 min\nComponentes:\nTela lunar (3), Vid de sangre (5), Mojo potente (4), Madeja de paño rúnico (4), Seda de araña Tejehierro (2)\n[q3]Jubón vid de sangre\nSe liga al equiparlo\nPecho Tela\n92 armadura\n+13 intelecto\nDurabilidad 80 / 80\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 2% tu probabilidad de golpear con hechizos.\n[q2]Equipar: Aumenta hasta 27 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Atuendo de vid de sangre (0/3)\nRequiereSastrería\n(300)[q0]Jubón vid de sangre\nLeotardos vid de sangre\nBotas vid de sangre"},
[24092] = {name = "[q3]Leotardos vid de sangre", additional_info = "Hechizo de 1 min\nComponentes:\nTela lunar (4), Vid de sangre (4), Mojo potente (4), Madeja de paño rúnico (4), Seda de araña Tejehierro (2)\n[q3]Leotardos vid de sangre\nSe liga al equiparlo\nPiernas Tela\n80 armadura\n+6 intelecto\nDurabilidad 65 / 65\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con hechizos.\n[q2]Equipar: Aumenta hasta 37 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Atuendo de vid de sangre (0/3)\nRequiereSastrería\n(300)[q0]Jubón vid de sangre\nLeotardos vid de sangre\nBotas vid de sangre"},
[24093] = {name = "[q0]Botas vid de sangre", additional_info = "Hechizo de 1 min\nComponentes:\nTela lunar (3), Vid de sangre (3), Cuero encantado (4), Madeja de paño rúnico (4), Seda de araña Tejehierro (4)\n[q3]Botas vid de sangre\nSe liga al equiparlo\nPies Tela\n63 armadura\n+16 intelecto\nDurabilidad 40 / 40\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con hechizos.\n[q2]Equipar: Aumenta hasta 19 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Atuendo de vid de sangre (0/3)\nRequiereSastrería\n(300)[q0]Jubón vid de sangre\nLeotardos vid de sangre\nBotas vid de sangre"},
