[24160] = {name = "Sigilo de Sincretista", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 10 p. de aguante y 7 p. de defensa, y le aumenta hasta 24 p. la sanación a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[24161] = {name = "Abrazo de la Muerte", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 28 p. de poder de ataque y un 1% de posibilidad de esquivar a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[24162] = {name = "Llamada del falcón", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 24 p. de poder de ataque a distancia, 10 p. de aguante y un 1% de probabilidad de golpear a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[24163] = {name = "Abrazo del vigilante de Vodouisant", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 15 p. de intelecto y le aumenta hasta 13 p. la sanación y el daño con hechizos a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[24164] = {name = "Presencia de Vista", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 18 p. a todos los hechizos de sanación y daño y un 1% de probabilidad de golpear con hechizos a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[24165] = {name = "Maleficio hudú", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 10 p. de aguante y le aumenta hasta 18 p. el daño y la sanación con hechizos a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[24167] = {name = "Aura profética", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 10 p. de aguante y 4 p. de maná cada 5 s, y le aumenta hasta 24 p. la sanación a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[24168] = {name = "Caricia del animista", additional_info = "Hechizo de 4 seg\nRequiere Pantalones, Yelmos\n[q]Añade de forma permanente 10 p. de aguante y 10 p. de intelecto, y le aumenta hasta 24 p. la sanación a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
