[24399] = {name = "[q4]Botas Hierro Negro", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nNúcleo de lava (3), Núcleo ígneo (3), Cuero del Núcleo (4), Barra de hierro negro (6)\n[q4]Botas Hierro Negro\nSe liga al equiparlo\nPies Placas\n[q2]664 armadura\n[q2]<Encantamiento aleatorio>\n+28 resistencia a Fuego\nDurabilidad 75 / 75\nNecesitas ser de nivel 60"},
[24400] = {name = "Diseño: botas Hierro Negro", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer botas Hierro Negro."},
