[24406] = {name = "Aliviar mascota mejorado", additional_info = nil},
[24407] = {name = "Abrumar", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Abruma instantáneamente a un enemigo y le inflige daño con arma más 750 p. Solo puede utilizarse después de que el objetivo esquive. El Abrumar no se puede bloquear, ni esquivar ni parar."},
[24408] = {name = "Cargar", additional_info = "Alcance de 40 m\nInstante\n[q]Carga contra un enemigo, inflige el daño normal más 0 p. y aturde al oponente durante 2 s."},
[24409] = {name = "Ración de campo de la Cuenca de Arathi", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 1074 p. de salud y 2202 de maná durante 30 s. Debes permanecer sentado mientras comes. Solo se puede usar en la Cuenca de Arathi."},
[24410] = {name = "Ración de hierro de la Cuenca de Arathi", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 1608 p. de salud y 3306 p. de maná durante 30 s. Debes permanecer sentado mientras comes. Solo se puede usar en la Cuenca de Arathi."},
[24411] = {name = "Ración enriquecida de la Cuenca de Arathi", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 2148 p. de salud y 4410 de maná durante 30 s. Debes permanecer sentado mientras comes. Solo se puede usar en la Cuenca de Arathi."},
[24412] = {name = "Primeros auxilios", additional_info = "Alcance de 15 m\nCanalizado (Hechizo de 8 seg)\n[q]Sana 640 p. de daño durante 8 s. Solo se puede usar en la Cuenca de Arathi."},
[24413] = {name = "Primeros auxilios", additional_info = "Alcance de 15 m\nCanalizado (Hechizo de 8 seg)\n[q]Sana 1104 p. de daño durante 8 s. Solo se puede usar en la Cuenca de Arathi."},
[24414] = {name = "Primeros auxilios", additional_info = "Alcance de 15 m\nCanalizado (Hechizo de 8 seg)\n[q]Sana 2000 p. de daño durante 8 s. Solo se puede usar en la Cuenca de Arathi."},
[24415] = {name = "Ralentizar", additional_info = "{140 p. de maná} {Alcance de 100 m}\nInstante\n[q]Aumenta el tiempo entre los ataques de los enemigos cercanos un 100%, ralentiza su velocidad de movimiento un 50% y su velocidad de lanzamiento de hechizos un 50% durante 20 s."},
[24416] = {name = "Aspectos excelentes", additional_info = "[q]Permite compartir con el grupo del cazador el hechizo Aspecto de la bestia y un 1% del efecto de Aspecto del mono."},
[24417] = {name = "Brillo de Zanza", additional_info = "Instante\n[q]Aumenta un 3% la probabilidad de que el jugador rechace hechizos hostiles durante 2 h. Rechazará automáticamente el primer hechizo ofensivo lanzado contra el usuario. Solo puede haber 1 poción de Zanza activa a la vez."},
[24418] = {name = "Estofado de crocolisco pesado", additional_info = "Hechizo de 3 seg\nComponentes:\nCarne de crocolisco tierna (2), Especias calmantes\nNecesitas ser de nivel 20\n[q2]Uso: Restaura 874.8 p. de salud durante 27 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 8 p. de aguante y espíritu durante 15 min."},
[24419] = {name = "Receta: estofado de crocolisco pesado", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer estofado de crocolisco pesado."},
[24420] = {name = "Sello Zandalar de serenidad", additional_info = "Hechizo de 5 seg\nRequiere Sobrehombros\n[q]Añade de forma permanente hasta 33 p. de sanación de hechizos y efectos a un objeto de la casilla de hombros."},
[24421] = {name = "Sello Zandalar de mojo", additional_info = "Hechizo de 5 seg\nRequiere Sobrehombros\n[q]Añade de forma permanente daño y hasta 18 p. de daño y sanación de hechizos y efectos mágicos a un objeto de la casilla de hombros."},
[24422] = {name = "Sello Zandalar de poderío", additional_info = "Hechizo de 5 seg\nRequiere Sobrehombros\n[q]Añade de forma permanente 30 p. de poder de ataque a un objeto de la casilla de hombros."},
[24423] = {name = "Chirrido", additional_info = "{20 p. de enfoque} {Alcance de ataques cuerpo a cuerpo}\nHechizo instantáneo\n[q]Golpea a un único enemigo con 7 to 9 p. de daño y disminuye el poder de ataque cuerpo a cuerpo de todos los enemigos cercanos en 25 p. El efecto dura 4 s."},
[24424] = {name = "Chirrido", additional_info = "Alcance de 100 m\nInstante\n[q]Golpea a un único enemigo infligiendo 7 to 9 p. de daño y disminuye el poder de ataque de todos los enemigos en rango cuerpo a cuerpo 25 p. El efecto dura 4 s."},
[24425] = {name = "Espíritu de Zandalar", additional_info = "Rango ilimitado\nInstante\n[q]Aumenta un 10% la velocidad de movimiento y un 15% todas las estadísticas durante 2 horas."},
[24426] = {name = "Golpe crítico con hechizos Sagrados aumentado", additional_info = "[q]Aumenta un 1% la probabilidad de efecto crítico de tus hechizos Sagrados."},
[24427] = {name = "Frasco de diamante", additional_info = "Instante\n[q]Restaura 9 p. de salud cada 5 s. y aumenta tu fuerza 75 p. Dura 1 min."},
