[24668] = {name = "Descarga de las Sombras", additional_info = "{250 p. de maná} {Alcance de 40 m}\nHechizo de 2 seg\n[q]Lanza una descarga de magia oscura a un enemigo y le inflige daño de las Sombras."},
[24669] = {name = "Lluvia de Fuego", additional_info = "{250 p. de maná} {Alcance de 30 m}\nCanalizado (Hechizo de 10 seg)\n[q]Invoca una lluvia de arrabio que quema a todos los enemigos del área seleccionada y les inflige 500 p. de daño de Fuego cada 2 s durante 10 s."},
[24670] = {name = "Inferno", additional_info = "{350 p. de maná} {Alcance de 100 m}\nHechizo de 3 seg\nComponentes:\nPiedra infernal\n[q]Invoca un meteoro del Vacío Abisal, que inflige 200 p. de daño de fuego y aturde a todos los objetivos enemigos en el área durante 2 s. Del cráter surge un infernal bajo las órdenes del taumaturgo durante 5 min. Cuando pierdes el control sobre el infernal, debes subyugarlo para controlarlo. Solo puede usarse en exteriores."},
[24671] = {name = "Patada mordedora", additional_info = "Alcance de ataques cuerpo a cuerpo\nSiguiente cuerpo a cuerpo\n[q]Inflige 875 to 1125 p. de daño a un enemigo y lo aturde durante 2 s."},
[24672] = {name = "Frenesí profano", additional_info = "{200 p. de maná} {Alcance de 30 m}\nInstante\n[q]Aumenta la velocidad de ataque de un aliado un 50% durante 20 s pero también le inflige 200 p. de daño de Naturaleza cada 2 s."},
