[24683] = {name = "Nube de relámpagos", additional_info = "{60 p. de maná} {Alcance de 30 m}\nInstante\n[q]Crea una nube de relámpagos que dura 15 s y que carga contra todos los enemigos de un área seleccionada infligiendo 463 to 537 p. de daño de Naturaleza y 875 to 1125 p. de daño extra cada 5 s."},
[24684] = {name = "Quemadura en cadena", additional_info = "Alcance de 100 m\nInstante\n[q]Alcanza a un enemigo con una descarga antimaná y afecta a otro enemigo próximo. Por cada punto de maná que la descarga consume, el objetivo sufre 0.5 p. de daño. El hechizo afecta a un máximo de 3 objetivos."},
[24685] = {name = "Choque de tierra", additional_info = "Alcance de 20 m\nInstante\n[q]Golpea a un enemigo con fuerza de conmoción, lo que inflige daño de Naturaleza e interrumpe el hechizo que se esté lanzando durante 4 s."},
