[25019] = {name = "Ventisca", additional_info = "Alcance de 30 m\nCanalizado (Hechizo de 10 seg)\n[q]Invoca una ventisca que dura 10 s, lo que inflige 12 p. de daño de Escarcha cada 2 s a todos los enemigos de un área seleccionada."},
[25020] = {name = "Escudo de relámpagos", additional_info = "Alcance de 30 m\n{Instante} {10 seg de reutilización}\n[q]Rodea al taumaturgo con 3 bolas de relámpagos que tienen un 50% de probabilidad de infligir 4 p. de daño a los atacantes cuerpo a cuerpo o a distancia. Cada vez que el escudo de relámpagos golpea, se disipa una bola de relámpagos. El escudo se disipa tras 10 min o cuando haya golpeado 3 veces.\n(Probabilidad de que accione: 50%)"},
[25021] = {name = "Cadena de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Golpea al enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 5 objetivos e inflige más daño de naturaleza a cada objetivo sucesivo."},
[25022] = {name = "Miedo de Halloween", additional_info = nil},
[25023] = {name = "Miedo de Halloween", additional_info = "(Probabilidad de que accione: 5%)"},
[25024] = {name = "Emplazar mina", additional_info = "{30 p. de maná} {Alcance de 50 m}\n{Instante} {10 seg de reutilización}\n[q]Coloca una mina terrestre. Las minas tardan 3 s en explotar e infligen 35 to 45 p. de daño a todos los tonques situados en un radio de 2 m una vez activadas."},
[25025] = {name = "Choque de tierra", additional_info = "Alcance de 20 m\nInstante\n[q]Golpea a un enemigo con fuerza de conmoción, lo que inflige daño de Naturaleza e interrumpe el hechizo que se esté lanzando durante 2 s."},
[25026] = {name = "Activar torreta MJ", additional_info = "{Instante} {10 seg de reutilización}\n[q]10 p. de maná por segundo.\n Dispara automáticamente al tonque enemigo más próximo en un radio de 10 m cada 1 s e inflige 2 to 4 p. de daño con cada disparo."},
[25027] = {name = "Lanzallamas", additional_info = "Alcance de 15 m\n{Instante} {2 seg de reutilización}\n[q]10 p. de maná por segundo.\n Inflige 18 to 22 p. de daño cada 1 s a todos los tonques situados en un radio de 5 m. También ralentiza el movimiento un 20% e inflige 5 p. de daño por segundo durante 2 s."},
[25028] = {name = "Explosión de Fuego", additional_info = "Alcance de 20 m\nInstante\n[q]Inflige daño de Fuego a un enemigo."},
