[25128] = {name = "Aceite de zahorí", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de veraplata\nComponentes:\nPolvo de ilusión (3), Flor de fuego (2), Vial de cristal\n[q]Crea aceite de zahorí.\nNecesitas ser de nivel 40\n[q2]Uso: Cuando se aplica al arma objetivo, aumenta hasta 24 p. el daño con hechizos. Dura 30 minutos.\n5 cargas"},
[25129] = {name = "Aceite de zahorí luminoso", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nFragmento luminoso grande (2), Flor de fuego (3), Vial imbuido\n[q]Crea aceite de zahorí luminoso.\nNecesitas ser de nivel 45\n[q2]Uso: Cuando se aplica al arma objetivo, aumenta hasta 36 p. el daño con hechizos y aumenta un 1% la probabilidad de golpe crítico con hechizos. Dura 30 minutos.\n5 cargas"},
[25130] = {name = "Aceite de maná luminoso", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nFragmento luminoso grande (2), Loto cárdeno (3), Vial imbuido\n[q]Crea aceite de maná luminoso.\nNecesitas ser de nivel 45\n[q2]Uso: Cuando se aplica al arma objetivo, restaura 12 p. de maná al taumaturgo cada 5 s y aumenta hasta 25 p. el efecto de los hechizos de sanación. Dura 30 minutos.\n5 cargas"},
