[25286] = {name = "Golpe heroico", additional_info = "{15 p. de ira} {Alcance de ataques cuerpo a cuerpo}\nSiguiente cuerpo a cuerpo\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 157 p. el daño cuerpo a cuerpo y genera una gran amenaza."},
[25288] = {name = "Revancha", additional_info = "{5 p. de ira} {Alcance de ataques cuerpo a cuerpo}\n{Hechizo instantáneo} {5 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\nRequiere Actitud defensiva\n[q]Contraataque instantáneo que causa 81 to 99 p. de daño a un enemigo y una gran cantidad de amenaza. La Revancha tiene que seguir a bloquear, esquivar o parar."},
[25289] = {name = "Grito de batalla", additional_info = "10 p. de ira\nHechizo instantáneo\n[q]El guerrero grita aumentando en 232 p. el poder de ataque cuerpo a cuerpo de los miembros del grupo en un radio de 20 m. Dura 2 min."},
[25290] = {name = "Bendición de sabiduría", additional_info = "{125 p. de maná} {Alcance de 30 m}\nInstante\n[q]Coloca una bendición sobre el objetivo aliado que restaura 33 p. de maná cada 5 s durante 5 min. Los jugadores solo pueden tener una bendición activa por Paladín a la vez."},
[25291] = {name = "Bendición de poderío", additional_info = "{130 p. de maná} {Alcance de 30 m}\nInstante\n[q]Coloca una bendición sobre el objetivo aliado que aumenta 185 p. el poder de ataque cuerpo a cuerpo durante 5 min. Los jugadores solo pueden tener una bendición activa por Paladín a la vez."},
[25292] = {name = "Luz Sagrada", additional_info = "{660 p. de maná} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Sana un objetivo amistoso en 1590 to 1770 p."},
[25294] = {name = "Multidisparo", additional_info = "{230 p. de maná} {Alcance de 8 - 35 m}\n{Instante} {10 seg de reutilización}\nRequiere Arma a distancia\n[q]Dispara varios misiles que alcanzan 3 objetivos con 150 p. de daño extra."},
[25295] = {name = "Picadura de serpiente", additional_info = "{250 p. de maná} {Alcance de 8 - 35 m}\nRequiere Arma a distancia\n[q]Pica al objetivo e inflige 555 p. de daño de Naturaleza durante 15 s. Solo puede haber una picadura activa por cazador sobre un mismo objetivo."},
[25296] = {name = "Aspecto del halcón", additional_info = "120 p. de maná\nInstante\n[q]El cazador asume los aspectos de un halcón y aumenta 120 p. el poder de ataque a distancia. Solo puede haber un aspecto activo a la vez."},
[25297] = {name = "Toque de sanación", additional_info = "{800 p. de maná} {Alcance de 40 m}\nHechizo de 3.5 seg\n[q]Sana un objetivo amistoso en 2267 to 2677 p."},
[25298] = {name = "Fuego estelar", additional_info = "{340 p. de maná} {Alcance de 30 m}\nHechizo de 3.5 seg\n[q]Causa 496 to 584 p. de daño Arcano al objetivo."},
[25299] = {name = "Rejuvenecimiento", additional_info = "{360 p. de maná} {Alcance de 40 m}\nInstante\n[q]Sana al objetivo en 888 p. durante 12 s."},
[25300] = {name = "Puñalada", additional_info = "{60 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Asesta una puñalada al objetivo, causando un 150% de daño de arma más 225 p. de daño al objetivo. Tienes que estar detrás del objetivo. Requiere una daga en la mano principal. Otorga 1 p. de combo."},
[25302] = {name = "Amago", additional_info = "{20 p. de energía} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {10 seg de reutilización}\n[q]Hace un amago que no causa daño pero reduce tu amenaza en gran cantidad, reduciendo la probabilidad de que el enemigo te ataque."},
[25304] = {name = "Descarga de Escarcha", additional_info = "{290 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Lanza una descarga de Escarcha al enemigo que le inflige de [515 * ( 1 ) ] a [555 * ( 1 ) ] p. de daño de Escarcha y ralentiza su velocidad de movimiento un 40% durante 9 s."},
[25306] = {name = "Bola de Fuego", additional_info = "{410 p. de maná} {Alcance de 35 m}\nHechizo de 3.5 seg\n[q]Lanza una bola ígnea que causa 596 to 760 p. de daño de Fuego y 76 p. de daño extra durante 8 s."},
[25307] = {name = "Descarga de las Sombras", additional_info = "{380 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Lanza una descarga de magia oscura a un enemigo y le causa 482 to 538 p. de daño de las Sombras."},
