[25890] = {name = "Bendición de Luz superior", additional_info = "{260 p. de maná} {Alcance de 40 m}\nInstante\nComponentes:\nSímbolo de Reyes\n[q]Da la Bendición de Luz superior a todos los miembros de la banda o grupo que pertenecen a la misma clase que el objetivo, lo que aumenta hasta 400 p. los efectos de los hechizos de Luz sagrada que se usan sobre el objetivo y hasta 115 p. el efecto de los hechizos Destello de luz que se usan sobre el objetivo. Dura 15 min. Los jugadores solo pueden tener una bendición a la vez por cada paladín."},
[25891] = {name = "Golpe de tierra", additional_info = "Instante\n[q]Aumenta tu poder de ataque a distancia y cuerpo a cuerpo 280 p. El efecto dura 20 s."},
