[27582] = {name = "Veneno de la memoria de Dirk", additional_info = nil},
[27583] = {name = "Dirk's Rememberin' Poison Effect DND", additional_info = nil},
[27584] = {name = "Seccionar", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Mutila al enemigo y le inflige 45 p. de daño y reduce su movimiento un 50% durante 15 s."},
[27585] = {name = "[q3]Cinturón de obsidiana pesado", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana pequeño (14), Barra de torio encantado (4), Esencia de tierra (2)\n[q3]Cinturón de obsidiana pesado\nSe liga al equiparlo\nCintura Placas\n397 armadura\n+25 fuerza\nDurabilidad 45 / 45\nNecesitas ser de nivel 60\n[q2]Equipar: +5 p. todas las resistencias."},
[27586] = {name = "[q4]Escudo dentado de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Barra de torio encantado (8), Esencia de tierra (4)\n[q4]Escudo dentado de obsidiana\nSe liga al equiparlo\nMano izquierda Escudo\n2645 armadura\n48 bloqueo\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: +5 p. todas las resistencias.\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 5% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 5%, 20s de reutilización)"},
[27587] = {name = "[q4]Coraza gruesa de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (18), Fragmento de obsidiana pequeño (40), Barra de torio encantado (12), Esencia de tierra (10), Esmeralda enorme (4)\n[q4]Coraza gruesa de obsidiana\nSe liga al equiparlo\nPecho Placas\n814 armadura\n+38 fuerza\n+16 aguante\nDurabilidad 165 / 165\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando te golpea un hechizo de daño tienes un 30% de probabilidad de obtener un escudo contra hechizos 6 s que absorbe 300 to 500 p. de daño de esa escuela. (Probabilidad de que accione: 30%, 10s de reutilización)"},
[27588] = {name = "[q3]Cinturón de obsidiana ligero", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana pequeño (14), Cuero encantado (4)\n[q3]Cinturón de obsidiana ligero\nSe liga al equiparlo\nCintura Malla\n224 armadura\nDurabilidad 40 / 40\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 32 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: +5 p. todas las resistencias."},
[27589] = {name = "[q4]Garra negra del Destructor", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Cuero encantado (8), Frasco de poder supremo\n[q4]Garra negra del Destructor\nSe liga al equiparlo\nManos Malla\n279 armadura\nDurabilidad 50 / 50\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 28 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: En ataques cuerpo a cuerpo o a distancia que alcancen al objetivo, obtienes 8 p. de maná y, si es posible, absorbes 8 p. de maná del objetivo."},
[27590] = {name = "[q4]Guerrera de malla de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (15), Fragmento de obsidiana pequeño (36), Cuero encantado (12), Piedra guardián (10), Diamante de Azeroth (4)\n[q4]Guerrera de malla de obsidiana\nSe liga al equiparlo\nPecho Malla\n458 armadura\nDurabilidad 140 / 140\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 76 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: Se reduce el daño con hechizos recibido 10 p."},
[27591] = {name = "Diseño: cinturón de obsidiana pesado", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un cinturón de obsidiana pesado."},
