[27603] = {name = "Escopeta dragón goblin", additional_info = "Canalizado (Hechizo de 8 seg)\n[q]Inflige 158 to 192 p. de daño de Fuego durante 8 s a todos los objetivos situados en un cono frente al ingeniero al utilizar el arma. Eso siempre y cuando no explote..."},
[27604] = {name = "Escopeta dragón goblin", additional_info = nil},
[27605] = {name = "Palabra de las Sombras: dolor", additional_info = "{470 p. de maná} {Alcance de 30 m}\nInstante\n[q]Una palabra de oscuridad que inflige 852 p. de daño de las Sombras durante 18 s."},
[27606] = {name = "Renovar", additional_info = "{365 p. de maná} {Alcance de 40 m}\nInstante\n[q]Sana al objetivo 810 p. de daño durante 15 s."},
[27607] = {name = "Palabra de poder: escudo", additional_info = "{500 p. de maná} {Alcance de 40 m}\n{Instante} {4 seg de reutilización}\n[q]Refuerza con un escudo el alma de un miembro del grupo, amortiguando 942 p. de daño. Dura 30 s. Mientras dura el escudo, el lanzamiento de hechizos no se verá interrumpido por el daño. Una vez protegido, el objetivo no puede recibir protección de nuevo hasta pasados 15 s."},
[27608] = {name = "Sanación relámpago", additional_info = "{380 p. de maná} {Alcance de 40 m}\nHechizo de 1.5 seg\n[q]Sana a un objetivo amistoso 828 to 975 p."},
[27609] = {name = "Disipar magia", additional_info = "{18% del maná base} {Alcance de 30 m}\nInstante\n[q]Elimina la magia del objetivo, suprimiendo 2 efectos dañinos de un amigo o 2 hechizos beneficiosos de un enemigo."},
[27610] = {name = "Alarido psíquico", additional_info = "210 p. de maná\n{Instante} {30 seg de reutilización}\n[q]El taumaturgo lanza un alarido psíquico que hace que 5 enemigos en un radio de 8 m huyan despavoridos durante 8 s. El daño infligido puede interrumpir el efecto."},
[27611] = {name = "Eviscerar", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo"},
[27613] = {name = "Patada", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Da una patada a un enemigo infligiendo 2 p. de daño e interrumpiendo el hechizo que esté lanzando durante 6 s."},
[27614] = {name = "Conjunto de mazmorra 2.0 Fantasmas", additional_info = nil},
[27615] = {name = "Golpe en los riñones", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {20 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Remate que aturde al objetivo."},
[27616] = {name = "Detector de fantasmas extradimensional", additional_info = "Instante\n[q]Permite al portador ver los fantasmas de los que murieron recientemente."},
[27617] = {name = "Esfumarse", additional_info = "{Instante} {5 min de reutilización}\nComponentes:\nPólvora cegadora"},
[27618] = {name = "Ventisca", additional_info = "{1400 p. de maná} {Alcance de 30 m}\nCanalizado (Hechizo de 8 seg)\n[q]Fragmentos de hielo que acribillan el área objetivo e infligen 1192 p. de daño de Escarcha durante 8 s."},
[27619] = {name = "Bloque de hielo", additional_info = "15 p. de maná\n{Instante} {5 min de reutilización}\n[q]Te envuelve en un bloque de hielo que te protege de todos los ataques físicos y hechizos durante 10 s, pero durante ese tiempo no puedes moverte, atacar ni lanzar hechizos."},
[27620] = {name = "Patada mordedora", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Da una patada a un enemigo infligiendo 2 p. de daño e interrumpiendo el hechizo que esté lanzando durante 4 s."},
[27621] = {name = "Tótem Viento Furioso", additional_info = "250 p. de maná\nInstante\n[q]Invoca un Tótem Viento Furioso con 5 p. de salud a los pies del taumaturgo que encanta con viento las armas de mano principales de los miembros del grupo en un radio de 20 m cada golpe tiene un 20% de posibilidades de otorgar 1 ataque extra con 315 p. extra de poder de ataque. Dura 1.50 min."},
[27623] = {name = "Tótem Nova de Fuego", additional_info = "640 p. de maná\n{Instante} {15 seg de reutilización}\n[q]Invoca un Tótem Nova de Fuego con 5 p. de salud que dura 5 s. Si no es destruido antes de 4 s, inflige 413 to 459 p. de daño de Fuego en un radio de 10 m."},
[27624] = {name = "Ola de sanación inferior", additional_info = "{380 p. de maná} {Alcance de 40 m}\nHechizo de 1.5 seg\n[q]Sana a un objetivo amistoso 832 to 928 p."},
[27626] = {name = "Purgar", additional_info = "{5% del maná base} {Alcance de 30 m}\nInstante\n[q]Purga al objetivo enemigo eliminando 2 efectos mágicos beneficiosos."},
