[27633] = {name = "Cortar alas", additional_info = "{80 p. de maná} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Inflige 50 p. de daño y reduce la velocidad de movimiento del objetivo un 60% durante 10 s."},
[27634] = {name = "Disparo de conmoción", additional_info = "Alcance de 8 - 35 m\nRequiere Arma a distancia\n[q]Deja atontado a un enemigo, lo que reduce su velocidad de movimiento un 50% durante 3 s.\n(Probabilidad de que accione: 40%)"},
[27635] = {name = "Escudo de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo que le inflige 50 p. de daño de Naturaleza."},
[27636] = {name = "Fragmentos estelares", additional_info = "{500 p. de maná} {Alcance de 100 m}\nCanalizado (Hechizo de 6 seg)\n[q]Lanza una lluvia de Fragmentos estelares sobre la cabeza del enemigo objetivo infligiendo 3000 p. de daño Arcano durante 6 s."},
[27637] = {name = "Recrecimiento", additional_info = "{250 p. de maná} {Alcance de 40 m}\nHechizo de 2 seg\n[q]Sana a un aliado una cantidad fija y luego le sana daño extra cada 3 s durante 21 s."},
