[27658] = {name = "[q2]Faltriquera de tejido mágico encantada", additional_info = "Hechizo de 45 seg\nComponentes:\nMadeja de tejido mágico (4), Polvo de visión (4), Hilo de seda grueso (2)\n[q2]Faltriquera de tejido mágico encantada\nSe liga al equiparlo\nBolsa de encantamiento de 16 casillas"},
[27659] = {name = "[q2]Bolsa de paño rúnico encantada", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de paño rúnico (5), Esencia eterna superior (2), Hilo rúnico (2)\n[q2]Bolsa de paño rúnico encantada\nSe liga al equiparlo\nBolsa de encantamiento de 20 casillas"},
[27660] = {name = "[q2]Bolsa de encantamiento grande", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de paño rúnico (6), Fragmento luminoso grande (4), Cuero encantado (4), Seda de araña Tejehierro (4)\n[q2]Bolsa de encantamiento grande\nSe liga al equiparlo\nBolsa de encantamiento de 24 casillas"},
[27661] = {name = "Loco de amor", additional_info = "Alcance de 10 m\nInstante\n[q]¡Coloca un muñeco-diana enamorado en el suelo que enfurece de envidia a los monstruos cercanos! Dura 15 s."},
[27662] = {name = "Lanzar flecha de cupido", additional_info = "Alcance de 30 m\nHechizo de 1 seg\n[q]¡Dispara a un jugador y Kwee Q. Pies Rápidos lo encontrará! (Funciona únicamente con jugadores que no tienen mascotas alimañas)."},
