[27664] = {name = "Ofrenda de amistad de Ventormenta", additional_info = "Instante\nComponentes:\nFardo de tarjetas , Saco de pan casero , Colección de juramentos de Ventormenta\n[q]Combina un fardo de tarjetas, un saco de pan casero y una colección de juramentos de Ventormenta para formar una colección de regalos de Ventormenta."},
[27665] = {name = "Ofrenda de amistad de Forjaz", additional_info = "Instante\nComponentes:\nCaja de cerveza casera , Colección de juramentos de Forjaz , Caja de tarjetas\n[q]Combina una caja de cerveza casera, una colección de juramentos de Forjaz y una caja de tarjetas para formar una colección de regalos de Forjaz."},
[27666] = {name = "Ofrenda de amistad de Darnassus", additional_info = "Instante\nComponentes:\nCaja de talla de madera , Colección de juramentos de Darnassus , Montón de tarjetas\n[q]Combina una caja de talla de madera, una colección de juramentos de Darnassus y un montón de tarjetas para formar una colección de regalos de Darnassus."},
[27667] = {name = "Crear colección de ofrendas de la Alianza", additional_info = "Instante\nComponentes:\nColección de obsequios de Darnassus , Colección de obsequios de Forjaz , Colección de obsequios de Ventormenta\n[q]Combina una colección de regalos de Darnassus, una colección de regalos de Forjaz y una colección de regalos de Ventormenta para formar una colección de regalos de la Alianza."},
[27668] = {name = "Crear colección de ofrendas de la Horda", additional_info = "Instante\nComponentes:\nColección de obsequios de Orgrimmar , Colección de obsequios de Cima del Trueno , Colección de obsequios de Entrañas\n[q]Combina una colección de regalos de Orgrimmar, una colección de regalos de Cima del Trueno y una colección de regalos de Entrañas para formar una colección de regalos de la Horda."},
[27669] = {name = "Ofrenda de amistad de Orgrimmar", additional_info = "Instante\nComponentes:\nCaja de tartas recientes , Colección de juramentos de Orgrimmar , Paquete de tarjetas\n[q]Combina una caja de tartas recientes, una colección de juramentos de Orgrimmar y un paquete de tarjetas para formar una colección de regalos de Orgrimmar."},
[27670] = {name = "Ofrenda de amistad de Cima del Trueno", additional_info = "Instante\nComponentes:\nCesta de flores , Cartera de tarjetas , Colección de juramentos de Cima del Trueno\n[q]Combina una cesta de flores, una cartera de tarjetas y una colección de juramentos de Cima del Trueno para formar una colección de regalos de Cima del Trueno."},
