[27829] = {name = "[q4]Leotardos titánicos", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (12), Barra de torio encantado (20), Esencia de tierra (10), Frasco de los titanes (2)\n[q4]Leotardos titánicos\nSe liga al equiparlo\nPiernas Placas\n598 armadura\n+30 fuerza\nDurabilidad 120 / 120\nNecesitas ser de nivel 55\n[q2]Equipar: Mejora tu probabilidad de golpear un 2%.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico."},
[27830] = {name = "[q4]Persuasor", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (15), Barra de hierro negro (10), Esencia de no-muerto (20), Runa oscura (20), Cuero de demosaurio (10), Piel de Sombra (2)\n[q4]Persuasor\nSe liga al equiparlo\nMano derecha Maza\n86 - 161 p. de daño Velocidad 2.70\n(45.74 p. de daño por segundo)\nDurabilidad 105 / 105\nNecesitas ser de nivel 58\n[q2]Equipar: Mejora tu probabilidad de golpear un 1%.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico."},
[27831] = {name = "Salva de descarga de las Sombras", additional_info = "Alcance de 30 m\nHechizo de 1.5 seg\n[q]Lanza misiles de magia oscura a los enemigos cercanos y les inflige daño de las Sombras."},
[27832] = {name = "[q4]Hoja sabia", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (12), Cristal nexo (2), Frasco de poder supremo (2), Cuero encantado (4)\n[q4]Hoja sabia\nSe liga al equiparlo\nMano derecha Espada\n49 - 100 p. de daño Velocidad 1.80\n(41.39 p. de daño por segundo)\n+14 aguante\n+6 intelecto\nDurabilidad 105 / 105\nNecesitas ser de nivel 59\n[q2]Equipar: Aumenta hasta 20 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Las resistencias mágicas de los objetivos de tus hechizos se reducen 10 p."},
