[28270] = {name = "Polimorfia: vaca", additional_info = "{150 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Transforma al enemigo en vaca obligándole a merodear durante 50 s. Mientras merodea, la vaca no puede atacar ni lanzar hechizos, pero se regenera muy rápidamente. Si recibe daño volverá a su forma normal. Solo se puede aplicar polimorfia a 1 objetivo cada vez. Solo funciona con bestias, humanoides y alimañas."},
[28271] = {name = "Polimorfia", additional_info = "{150 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Transforma al enemigo en tortuga obligándole a merodear durante 50 s. Mientras merodea, la tortuga no puede atacar ni lanzar hechizos, pero se regenera muy rápidamente. Si recibe daño volverá a su forma normal. Solo se puede aplicar polimorfia a 1 objetivo cada vez. Solo funciona con bestias, humanoides y alimañas."},
[28272] = {name = "Polimorfia", additional_info = "{150 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Transforma al enemigo en cerdo obligándole a merodear durante 50 s. Mientras merodea, el cerdo no puede atacar ni lanzar hechizos, pero se regenera muy rápidamente. Si recibe daño volverá a su forma normal. Solo se puede aplicar polimorfia a 1 objetivo cada vez. Solo funciona con bestias, humanoides y alimañas."},
