[48108] = {name = "Una buena racha", additional_info = "Instante\n[q]Cada vez que asestes 2 golpes críticos con hechizos seguidos con Bola de Fuego, Explosión de Fuego, Agostar, Bomba viva o Descarga de Pirofrío, tienes la probabilidad de que el próximo Piroexplosión que lances en 10 s sea un lanzamiento instantáneo."},
[53489] = {name = "El arte de la guerra", additional_info = "Instante\n[q]Aumenta el daño de golpe crítico de tus habilidades Sentencia, Golpe de cruzado y Tormenta divina un 750% y, cuando esas habilidades asestan un golpe crítico, el tiempo de lanzamiento de tu siguiente Destello de luz o Exorcismo se reduce 0.75 s."},
[53601] = {name = "Escudo sacro", additional_info = "{12% del maná base} {Alcance de 40 m}\nInstante\n[q]Cada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe 500 p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de luz durante un máximo de 6 s. No puede obtener este efecto más de una vez cada 6 s. Dura 30 s. Solo un objetivo puede tener este efecto a la vez."},
[53672] = {name = "Infusión de Luz", additional_info = "Instante\n[q]Tus golpes críticos con Choque Sagrado reducen el tiempo de lanzamiento de tu siguiente hechizo Destello de Luz 0.75 s o aumentan la probabilidad de crítico de tu próxima Luz Sagrada un 10%."},
[58597] = {name = "Escudo sacro", additional_info = "Rango ilimitado\nInstante\n[q]Cada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe 500 p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante 6 s. No puede obtener este efecto más de una vez cada 6 s. Dura 6 s."},
