[384135] = {name = "Runa de fortuna", additional_info = "Instante\n[q]Otorga a todos los miembros de la banda la oportunidad de obtener recompensas adicionales de Kel'Thuzad y sus tenientes.\n\n Este efecto se acumula y dura una semana entera."},
[398061] = {name = "Brazales de reorientación", additional_info = "[q]Obtienes 1 punto de combo cada vez que evitas un ataque o hechizo de un objetivo enemigo que no sea tu objetivo actual.\n(1s de reutilización)"},
[398115] = {name = "Cinturón de inoculación", additional_info = "Instante\n[q]Recibe un 1% de daño para quitarte un efecto de enfermedad o veneno."},
[398117] = {name = "Bolsillos con bocadillos", additional_info = "Alcance de 20 m\nInstante\n[q]Abres la bolsa de bocadillos y la colocas en el bolsillo de tu objetivo, lo que aumenta el daño de las bestias contra el objetivo en 20 p."},
[398196] = {name = "Desenfunde rápido", additional_info = "{25 p. de energía} {Alcance de 20 m}\n{Instante} {10 seg de reutilización}\nRequiere Arma a distancia\n[q]Saca tu arma a distancia, haz un disparo rápido contra un enemigo e inflige daño de arma a distancia normal y reduce la velocidad de movimiento del objetivo un 50% durante 6 s. Otorga 1 p. de combo.\n\n Desenfunde rápido se beneficia de todos los talentos y efectos que se activan por Golpe siniestro o lo modifican."},
[398197] = {name = "Desenfunde rápido", additional_info = "[q]Obtienes la habilidad Desenfunde rápido:\n\n\nSaca tu arma a distancia, haz un disparo rápido contra un enemigo e inflige daño de arma a distancia normal y reduce la velocidad de movimiento del objetivo un 50% durante 6 s. Otorga 1 p. de combo.\n\n Desenfunde rápido se beneficia de todos los talentos y efectos que se activan por Golpe siniestro o lo modifican."},
[398198] = {name = "Huracán de espadas", additional_info = "{20 p. de energía} {Alcance de 100 m}\nInstante\n[q]Remate que aumenta la probabilidad de parar. Dura más y aumenta la probabilidad de parar por cada punto de combo:\n 1 p. : 10 segundos, 12% de parar\n 2 p.: 15 segundos, 14% de parar\n 3 p.: 20 segundos, 16% de parar\n 4 p.: 25 segundos, 18% de parar\n 5 p.: 30 segundos, 20% de parar"},
[398199] = {name = "Túnica de soberbia", additional_info = nil},
[398538] = {name = "Brazal de tallado rúnico - Desvío menor", additional_info = "Hechizo de 5 seg\nRequiere [Bracers]Herramientas: Vara rúnica de cobre\nComponentes:\nEsencia mágica inferior , Polvo extraño\n[q]Encanta de forma permanente unos brazales para que aumente 1 p. la habilidad de defensa del portador."},
[398603] = {name = "Tallado rúnico", additional_info = "Instante\n[q]Incrusta runas poderosas en tu armadura."},
[398604] = {name = "Tallado rúnico", additional_info = nil},
[399954] = {name = "Habilidad de runa de torso", additional_info = "Instante\n[q]Equipa un objeto de casilla de pecho con una runa grabada para activar una habilidad en esta casilla."},
[399956] = {name = "Mutilar", additional_info = "{40 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Atacas instantáneamente con ambas armas e infliges 95% de daño con arma más [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] p. adicionales con cada arma. El daño aumenta un 20% frente a objetivos envenenados. Otorga 2 p. de combo.\n\n Mutilar se beneficia de todos los talentos y efectos que se activan con Puñalada o que la modifican a menos que se explicite lo contrario."},
[399960] = {name = "Mutilar", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Ataque instantáneo con ambas armas que inflige 100% de daño con arma más [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60)] p. adicionales con cada arma. El daño aumenta un 20% frente a objetivos envenenados. Da 2 p. de combo."},
[399961] = {name = "Mutilar", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Ataque instantáneo con ambas armas que inflige 100% de daño con arma más $[100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60)] p. adicionales con cada arma. El daño aumenta un 20% frente a objetivos envenenados. Da 2 p. de combo."},
[399962] = {name = "Mutilar", additional_info = "[q]Obtienes la habilidad Mutilar:\n\n\nAtacas instantáneamente con ambas armas e infliges 95% de daño con arma más [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] p. adicionales con cada arma. El daño aumenta un 20% frente a objetivos envenenados. Otorga 2 p. de combo.\n\n Mutilar se beneficia de todos los talentos y efectos que se activan con Puñalada o que la modifican a menos que se explicite lo contrario."},
[399963] = {name = "Envenenar", additional_info = "{35 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Remate que inflige daño de veneno de forma instantánea según las dosis de Veneno mortal sobre el objetivo. Tras el ataque de Envenenar, aumenta un 75% la frecuencia de aplicación de Veneno instantáneo durante 1 s, y se agrega 1 s adicional por cada punto de combo. Se activa una dosis por cada punto de combo:\n 1 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 1 + Attack power * 0.072] p. de daño\n 2 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Attack power * 0.144] p. de daño\n 3 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Attack power * 0.216] p. de daño\n 4 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Attack power * 0.288] p. de daño\n 5 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Attack power * 0.36] p. de daño"},
[399965] = {name = "Brebaje letal", additional_info = "[q]Otorga diversas mejoras a tus venenos:\n\n Cuando aplicas cualquier otro veneno a un objetivo, también aplicas Veneno mortal.\n\n Si tu arma no tiene un veneno aplicado, tiene una probabilidad de activar Veneno instantáneo como si estuviese aplicado.\n\n Veneno mortal y Veneno instantáneo ahora obtienen más daño de tu poder de ataque.\n\n Tu Veneno mortal ahora puede estar activo en los objetivos afectados por el Veneno mortal de otro Pícaro."},
[399966] = {name = "Habilidad de runa de piernas", additional_info = "Instante\n[q]Equipa un objeto de casilla de piernas con una runa grabada para activar una habilidad en esta casilla."},
[399967] = {name = "Habilidad de runa de manos", additional_info = "Instante\n[q]Equipa un objeto de casilla de manos con una runa grabada para activar una habilidad en esta casilla."},
[399968] = {name = "Envenenar", additional_info = "[q]Obtienes la habilidad Envenenar:\n\n\nRemate que inflige daño de veneno de forma instantánea según las dosis de Veneno mortal sobre el objetivo. Tras el ataque de Envenenar, aumenta un 75% la frecuencia de aplicación de Veneno instantáneo durante 1 s, y se agrega 1 s adicional por cada punto de combo. Se activa una dosis por cada punto de combo:\n 1 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 1 + Attack power * 0.072] p. de daño\n 2 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Attack power * 0.144] p. de daño\n 3 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Attack power * 0.216] p. de daño\n 4 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Attack power * 0.288] p. de daño\n 5 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Attack power * 0.36] p. de daño"},
[399969] = {name = "Brebaje letal", additional_info = "[q]Obtienes la habilidad Brebaje letal:\n\n\nOtorga diversas mejoras a tus venenos:\n\n Cuando aplicas cualquier otro veneno a un objetivo, también aplicas Veneno mortal.\n\n Si tu arma no tiene un veneno aplicado, tiene una probabilidad de activar Veneno instantáneo como si estuviese aplicado.\n\n Veneno mortal y Veneno instantáneo ahora obtienen más daño de tu poder de ataque.\n\n Tu Veneno mortal ahora puede estar activo en los objetivos afectados por el Veneno mortal de otro Pícaro."},
[399985] = {name = "Golpesombra", additional_info = "{20 p. de energía} {Alcance de 25 m}\nInstante\nRequiere Arma cuerpo a cuerpo\nRequiere Sigilo\n[q]Te teletransportas detrás de tu objetivo y ejecutas un ataque que le inflige un 150% de daño con arma. Debes estar en sigilo. Otorga 1 p. de combo."},
[399986] = {name = "Lanzamiento de shuriken", additional_info = "{30 p. de energía} {Alcance de 25 m}\n{Instante} {20 seg de reutilización}\n[q]Lanza un shuriken a tu enemigo y le inflige una cantidad de daño equivalente al 50% de tu poder de ataque, y también golpea a un máximo de 4 objetivos cercanos más. Otorga 1 p. de combo por cada objetivo golpeado."},
[400009] = {name = "Entre los ojos", additional_info = "{35 p. de energía} {Alcance de 20 m}\n20 seg de reutilización\nRequiere Arma a distancia\n[q]Remate a distancia que inflige daño por p. de combo, que aumenta según el poder de ataque y aturde al objetivo:\n\n 1 punto:  De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] p. de daño, 1 s de aturdimiento\n 2 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] p. de daño, 2 s de aturdimiento\n 3 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] p. de daño, 3 s de aturdimiento\n 4 puntos: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] p. de daño, 4 s de aturdimiento\n 5 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] p. de daño, 5 s de aturdimiento\n\n Comparte el tiempo de reutilización con Golpe en los riñones."},
[400012] = {name = "Danza de hojas", additional_info = "{25 p. de energía} {Alcance de 100 m}\nInstante\n[q]Remate que aumenta un 10% tu probabilidad de parar y otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5) p. Dura más por cada punto de combo:\n\n 1 punto: 14 s\n 2 puntos: 18 s\n 3 puntos: 22 s\n 4 puntos: 26 s\n 5 puntos: 30 s"},
[400014] = {name = "Heridas superficiales", additional_info = "[q]Recibes un 30% menos de daño físico cuando Danza de hojas está activa, y ese daño se reduce un 1% más por cada 12 p. de tu habilidad de defensa por encima de ( 60 * 5)p. Además, tu probabilidad de esquivar se multiplica un 50%, tienes un 6% menos de probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo, infliges un 20% menos de daño, la amenaza que generan tus acciones aumenta notablemente y tu habilidad Amago se reemplaza por Burla, que provoca al objetivo para que te ataque.\n\n\nProvoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."},
[400015] = {name = "Bravura ante los golpes", additional_info = nil},
[400016] = {name = "Bravura ante los golpes", additional_info = "[q]Cada vez que esquivas o paras un ataque, obtienes un 5% más de salud, que se acumula hasta 5 veces."},
[400023] = {name = "Burlar a la muerte", additional_info = "Instante\n[q]Cualquier ataque capaz de matarte solo reducirá tu salud a un 10% de tu salud máxima. Además, todo el daño recibido se reducirá hasta un 90% durante 3 s. Este efecto no puede ocurrir más de una vez por minuto."},
[400024] = {name = "Burlando a la muerte", additional_info = "Instante\n[q]Cualquier ataque capaz de matarte solo reducirá tu salud a un 10% de tu salud máxima. Además, todo el daño recibido se reducirá hasta un 90% durante 3 s. Este efecto no puede ocurrir más de una vez por minuto."},
[400029] = {name = "Paso de las Sombras", additional_info = "Alcance de 25 m\n{Instante} {30 seg de reutilización}\n[q]Intenta dar un paso en las sombras y reaparecer detrás de tu enemigo. Aumenta la velocidad de movimiento un 70% durante 3 s."},
[400031] = {name = "Golpesombra", additional_info = "[q]Obtienes la habilidad Golpesombra:\n\n\nTe teletransportas detrás de tu objetivo y ejecutas un ataque que le inflige un 150% de daño con arma. Debes estar en sigilo. Otorga 1 p. de combo."},
[400032] = {name = "Lanzamiento de shuriken", additional_info = "[q]Obtienes la habilidad Lanzamiento de shuriken:\n\n\nLanza un shuriken a tu enemigo y le inflige una cantidad de daño equivalente al 50% de tu poder de ataque, y también golpea a un máximo de 4 objetivos cercanos más. Otorga 1 p. de combo por cada objetivo golpeado."},
