[400037] = {name = "Paso de las Sombras", additional_info = "[q]Obtienes la habilidad Paso de las sombras:\n\n\nIntenta dar un paso en las sombras y reaparecer detrás de tu enemigo. Aumenta la velocidad de movimiento un 70% durante 3 s."},
[400038] = {name = "Danza de hojas", additional_info = "[q]Obtienes la habilidad Danza de hojas:\n\n\nRemate que aumenta un 10% tu probabilidad de parar y otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5) p. Dura más por cada punto de combo:\n\n 1 punto: 14 s\n 2 puntos: 18 s\n 3 puntos: 22 s\n 4 puntos: 26 s\n 5 puntos: 30 s"},
[400039] = {name = "Heridas superficiales", additional_info = "[q]Obtienes la habilidad Heridas superficiales:\n\n\nRecibes un 30% menos de daño físico cuando Danza de hojas está activa, y ese daño se reduce un 1% más por cada 12 p. de tu habilidad de defensa por encima de ( 60 * 5)p. Además, tu probabilidad de esquivar se multiplica un 50%, tienes un 6% menos de probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo, infliges un 20% menos de daño, la amenaza que generan tus acciones aumenta notablemente y tu habilidad Amago se reemplaza por Burla, que provoca al objetivo para que te ataque.\n\n\nProvoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."},
[400040] = {name = "Bravura ante los golpes", additional_info = "[q]Obtienes la habilidad Bravura ante los golpes:\n\n\nCada vez que esquivas o paras un ataque, obtienes un 5% más de salud, que se acumula hasta 5 veces."},
[400080] = {name = "Grabar pechera - Brebaje letal", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Brebaje letal:\n\n\nOtorga diversas mejoras a tus venenos:\n\n Cuando aplicas cualquier otro veneno a un objetivo, también aplicas Veneno mortal.\n\n Si tu arma no tiene un veneno aplicado, tiene una probabilidad de activar Veneno instantáneo como si estuviese aplicado.\n\n Veneno mortal y Veneno instantáneo ahora obtienen más daño de tu poder de ataque.\n\n Tu Veneno mortal ahora puede estar activo en los objetivos afectados por el Veneno mortal de otro Pícaro."},
[400081] = {name = "Grabar pantalones - Entre los ojos", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Entre los ojos:\n\n\nRemate a distancia que inflige daño por p. de combo, que aumenta según el poder de ataque y aturde al objetivo:\n\n 1 punto:  De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] p. de daño, 1 s de aturdimiento\n 2 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] p. de daño, 2 s de aturdimiento\n 3 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] p. de daño, 3 s de aturdimiento\n 4 puntos: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] p. de daño, 4 s de aturdimiento\n 5 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] p. de daño, 5 s de aturdimiento\n\n Comparte el tiempo de reutilización con Golpe en los riñones."},
[400082] = {name = "Grabar pechera - Heridas superficiales", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Heridas superficiales:\n\n\nRecibes un 30% menos de daño físico cuando Danza de hojas está activa, y ese daño se reduce un 1% más por cada 12 p. de tu habilidad de defensa por encima de ( 60 * 5)p. Además, tu probabilidad de esquivar se multiplica un 50%, tienes un 6% menos de probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo, infliges un 20% menos de daño, la amenaza que generan tus acciones aumenta notablemente y tu habilidad Amago se reemplaza por Burla, que provoca al objetivo para que te ataque.\n\n\nProvoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."},
[400093] = {name = "Grabar botas - Bravura ante los golpes", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Bravura ante los golpes:\n\n\nCada vez que esquivas o paras un ataque, obtienes un 5% más de salud, que se acumula hasta 5 veces."},
[400094] = {name = "Grabar guantes - Mutilar", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Mutilar:\n\n\nAtacas instantáneamente con ambas armas e infliges 95% de daño con arma más [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] p. adicionales con cada arma. El daño aumenta un 20% frente a objetivos envenenados. Otorga 2 p. de combo.\n\n Mutilar se beneficia de todos los talentos y efectos que se activan con Puñalada o que la modifican a menos que se explicite lo contrario."},
[400095] = {name = "Grabar pechera - Desenfunde rápido", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Desenfunde rápido:\n\n\nSaca tu arma a distancia, haz un disparo rápido contra un enemigo e inflige daño de arma a distancia normal y reduce la velocidad de movimiento del objetivo un 50% durante 6 s. Otorga 1 p. de combo.\n\n Desenfunde rápido se beneficia de todos los talentos y efectos que se activan por Golpe siniestro o lo modifican."},
[400096] = {name = "Grabar cinturón - Lanzamiento de shuriken", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Lanzamiento de shuriken:\n\n\nLanza un shuriken a tu enemigo y le inflige una cantidad de daño equivalente al 50% de tu poder de ataque, y también golpea a un máximo de 4 objetivos cercanos más. Otorga 1 p. de combo por cada objetivo golpeado."},
[400099] = {name = "Grabar pantalones - Danza de hojas", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Danza de hojas:\n\n\nRemate que aumenta un 10% tu probabilidad de parar y otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5) p. Dura más por cada punto de combo:\n\n 1 punto: 14 s\n 2 puntos: 18 s\n 3 puntos: 22 s\n 4 puntos: 26 s\n 5 puntos: 30 s"},
[400101] = {name = "Grabar cinturón - Paso de las sombras", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Paso de las Sombras:\n\n\nIntenta dar un paso en las sombras y reaparecer detrás de tu enemigo. Aumenta la velocidad de movimiento un 70% durante 3 s."},
[400102] = {name = "Grabar pantalones - Envenenar", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Envenenar:\n\n\nRemate que inflige daño de veneno de forma instantánea según las dosis de Veneno mortal sobre el objetivo. Tras el ataque de Envenenar, aumenta un 75% la frecuencia de aplicación de Veneno instantáneo durante 1 s, y se agrega 1 s adicional por cada punto de combo. Se activa una dosis por cada punto de combo:\n 1 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 1 + Attack power * 0.072] p. de daño\n 2 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Attack power * 0.144] p. de daño\n 3 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Attack power * 0.216] p. de daño\n 4 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Attack power * 0.288] p. de daño\n 5 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Attack power * 0.36] p. de daño"},
[400104] = {name = "Grabar pantalones - Paso de las Sombras", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Paso de las Sombras:\n\n\nIntenta dar un paso en las sombras y reaparecer detrás de tu enemigo. Aumenta la velocidad de movimiento un 70% durante 3 s."},
[400105] = {name = "Grabar guantes - Golpesombra", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Golpesombra:\n\n\nTe teletransportas detrás de tu objetivo y ejecutas un ataque que le inflige un 150% de daño con arma. Debes estar en sigilo. Otorga 1 p. de combo."},
[400573] = {name = "Explosión Arcana", additional_info = "{Instante} {3 min de reutilización}\n[q]Golpea al objetivo con energía e inflige daño Arcano. Cada vez que lanzas Explosión Arcana, el daño y la sanación de todos tus demás hechizos Arcanos aumenta un 15%, y el costo de maná de Explosión Arcana aumenta un 175%. El efecto se acumula hasta 4 veces y dura 6 s."},
[400574] = {name = "Explosión Arcana", additional_info = "{7% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Golpea al objetivo con energía, lo que inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 453 / 100] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 527 / 100] p. de daño Arcano. Cada vez que lanzas el hechizo Explosión Arcana, el daño de todos tus demás hechizos Arcanos aumentan un 15%, y el costo de maná de Explosión Arcana aumenta un 175%. El efecto se acumula hasta 4 veces y dura 6 s o hasta que se lance cualquier otro hechizo Arcano que inflija daño."},
[400586] = {name = "Explosión Arcana", additional_info = "{Instante} {3 min de reutilización}\n[q]Golpea al objetivo con energía e inflige daño Arcano. Cada vez que lanzas Explosión Arcana, el daño de todos tus demás hechizos Arcanos aumenta un 15%, y el costo de maná de Explosión Arcana aumenta un 175%. El efecto se acumula hasta 4 veces y dura 6 s."},
[400588] = {name = "Tromba de misiles", additional_info = "[q]Da a tu Explosión Arcana una probabilidad de un 40% y a Bola de Fuego y Descarga de Escarcha una probabilidad de un 20% de reducir la duración canalizada de tus siguientes Misiles Arcanos un 50%; reduce el costo de maná un 100% y disparará misiles cada 0.5 s.\n(Probabilidad de que accione: 50%)"},
[400589] = {name = "Tromba de misiles", additional_info = "Instante\n[q]Da a tu Explosión Arcana, Bola de Fuego y Descarga de Escarcha una probabilidad de reducir la duración canalizada de tu siguiente Misiles Arcanos un 50%; reduce el costo de maná un 100% y disparará misiles cada 0.5 s."},
[400610] = {name = "Tromba Arcana", additional_info = "{8% del maná base} {Alcance de 30 m}\n{Instante} {3 seg de reutilización}\n[q]Lanza varios misiles contra el objetivo enemigo que infligen entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 358 / 100] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 438 / 100] p. de daño Arcano. Este hechizo también tiene un 25% de probabilidad de activar Tromba de misiles."},
[400613] = {name = "Bomba viva", additional_info = "{22% del maná base} {Alcance de 35 m}\nInstante\n[q]El objetivo se convierte en una Bomba viva que recibe [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] p. de daño de Fuego durante 12 s. Después de 12 s o cuando se disipa el hechizo, el objetivo explota e inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] p. de daño de Fuego a todos los enemigos en un radio de 10 m.\n\n Bomba viva se beneficia de todos los talentos y efectos que activan o modifican Agostar."},
[400614] = {name = "Bomba viva", additional_info = "Alcance de 100 m\nInstante\n[q]El objetivo se convierte en una Bomba viva que recibe [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] p. de daño de Fuego durante hasta cancelación. Después de hasta cancelación o cuando se disipa el hechizo, el objetivo explota e inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] p. de daño de Fuego a todos los enemigos en un radio de 10 m."},
[400615] = {name = "Recalentamiento", additional_info = "[q]Explosión de Fuego siempre asestará un golpe crítico, se puede lanzar durante el lanzamiento de otro hechizo y no se ve afectada por el tiempo de reutilización global, pero su tiempo de reutilización aumenta a 15 s."},
[400616] = {name = "Explosión de Fuego", additional_info = "{115 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Golpea al enemigo y le inflige 110 to 134 p. de daño de Fuego."},
[400618] = {name = "Explosión de Fuego", additional_info = "{40 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Golpea al enemigo y le inflige 27 to 35 p. de daño de Fuego."},
