[400623] = {name = "Explosión de Fuego", additional_info = "{340 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Golpea al enemigo y le inflige 446 to 524 p. de daño de Fuego."},
[400624] = {name = "Una buena racha", additional_info = "[q]Cada vez que asestes 2 golpes críticos con hechizos no periódicos consecutivos con Bola de Fuego, Descarga de Pirofrío, Descarga de fuego fardo, Explosión de Fuego, Agostar o Bomba viva, tu próximo lanzamiento de Piroexplosión en 10 s será instantáneo y costará un 100% menos de maná."},
[400625] = {name = "Una buena racha", additional_info = "Instante\n[q]Cada vez que asestes 2 golpes críticos con hechizos consecutivos con Bola de Fuego, Explosión de Fuego, Agostar, Bomba viva, Piroarcano o Descarga de Pirofrío, tienes una probabilidad de que tu próximo lanzamiento de Piroexplosión en 10 s sea instantáneo."},
[400640] = {name = "Lanza de hielo", additional_info = "{8% del maná base} {Alcance de 30 m}\nInstante\n[q]Inflige entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 55 / 100 * ( 1 ) ] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 65 / 100 * ( 1 ) ] de daño de Escarcha a un objetivo enemigo. Inflige un 400% de daño contra objetivos congelados.\n\n Cuando tus otros hechizos de Escarcha infligen daño a un objetivo que no controla un jugador, aumentan un 20% el daño que recibe el objetivo de tu siguiente Lanza de hielo. Este efecto se acumula hasta 5 veces y requiere el talento Escalofrío invernal."},
[400647] = {name = "Dedos de Escarcha", additional_info = "[q]Da a tus efectos de enfriamiento una probabilidad de un 25% de otorgarte el efecto Dedos de Escarcha, que hace que tus siguientes 2 hechizos traten al objetivo como si estuviese congelado. Dura 15 s."},
[400669] = {name = "Dedos de Escarcha", additional_info = "Instante\n[q]Da a tus efectos de enfriamiento una probabilidad de otorgarte el efecto Dedos de Escarcha, que hace que tus siguientes hechizos traten al objetivo como si estuviese congelado. Dura 15 s."},
[400670] = {name = "Dedos de Escarcha", additional_info = "Instante\n[q]Da a tus efectos de enfriamiento una probabilidad de otorgarte el efecto Dedos de Escarcha, que hace que tus siguientes hechizos traten al objetivo como si estuviese congelado. Dura 15 s."},
[400730] = {name = "¡Bola de Fuego!", additional_info = "Instante\n[q]Tu siguiente hechizo Bola de Fuego, Descarga de fríoarcano, Descarga de fuego fardo o Descarga de Pirofrío es instantáneo y no cuesta maná.\n[q]Modifies Power Cost -999%:\nBola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Descarga de Pirofrío , Descarga de fríoarcano , Descarga de fuego fardo\n\nModifies Cast Time -9999%:\nBola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Bola de Fuego , Descarga de Pirofrío , Descarga de fríoarcano , Descarga de fuego fardo"},
[400731] = {name = "Congelación cerebral", additional_info = "[q]Tus hechizos de daño de Escarcha con efectos de enfriamiento tienen un 20% de probabilidad de hacer que tu siguiente hechizo Bola de Fuego, Descarga de fríoarcano, Descarga de fuego fardo o Descarga de Pirofrío sea instantáneo y no cueste maná.\n(Probabilidad de que accione: 20%)"},
[400735] = {name = "Faro temporal", additional_info = "Alcance de 100 m\nInstante\n[q]Registra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos."},
[401405] = {name = "Sanación cronomántica", additional_info = nil},
[401417] = {name = "Regeneración", additional_info = "{28% del maná base} {Alcance de 40 m}\nCanalizado (Hechizo de 3 seg)\n[q]Restablece [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] p. de salud al objetivo durante 3 s y aplica Faro temporal durante 30 s.\n\n Faro temporal\n\nRegistra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos."},
[401460] = {name = "Regeneración rápida", additional_info = "{32% del maná base} {Alcance de 40 m}\nCanalizado (Hechizo de 1.5 seg)\n[q]Restablece [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 75 / 100 * 3] p. de salud al objetivo durante 1.50 s y aplica Faro temporal durante 20 s.\n\n\nRegistra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos."},
[401462] = {name = "Retroceder en el tiempo", additional_info = "Alcance de 60 m\n{Instante} {30 seg de reutilización}\n[q]Tu objetivo actual con tu Faro temporal se sana inmediatamente de todo el daño recibido durante los últimos 5 segundos. Es ineficaz contra objetivos que no tenían un Faro temporal hace 5 segundos."},
[401488] = {name = "Grabar pantalones - Runa de Navajín", additional_info = "Instante\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Golpesombra:\n\n\nTe teletransportas detrás de tu objetivo y ejecutas un ataque que le inflige un 150% de daño con arma. Debes estar en sigilo. Otorga 1 p. de combo."},
[401489] = {name = "Tallado rúnico: Aprender Grabar Runa de Navajín", additional_info = nil},
[401495] = {name = "Navajín - Cambiar carta por runa", additional_info = nil},
[401502] = {name = "Descarga de Pirofrío", additional_info = "{14% del maná base} {Alcance de 35 m}\nHechizo de 3 seg\n[q]Lanza una Descarga de Pirofrío contra el enemigo, inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 325 / 100 * ( 1 ) ] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 379 / 100 * ( 1 ) ] p. de daño de Pirofrío, reduce la velocidad de movimiento un 40% e inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 12 / 100 * 3 * ( 1 ) ] p. de daño de Pirofrío extra durante 9 s. Este hechizo tendrá en cuenta la resistencia más baja entre las resistencias de Fuego o Escarcha del objetivo y cuenta como daño de Escarcha y Fuego."},
[401556] = {name = "Llama viva", additional_info = "{11% del maná base} {Alcance de 35 m}\n{Instante} {30 seg de reutilización}\n[q]Invoca una llama piroarcana que se mueve hacia el objetivo y deja un rastro de piroarcano. Este rastro inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100] p. de daño Piroarcano por s a los enemigos cercanos. Dura 10 s."},
[401558] = {name = "Llama viva", additional_info = "Rango ilimitado\nInstante\n[q]Inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100] p. de daño de Fuego cada 1 s."},
[401559] = {name = "Llama viva", additional_info = nil},
[401617] = {name = "Desenterrar tesoro", additional_info = "Hechizo de 3 seg 1 min de reutilización\n[q]Desentierra un tesoro en la ubicación marcada"},
[401645] = {name = "Receta: Lanza de hielo", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a encantar tu equipo con la Runa A."},
[401681] = {name = "Traducir notas de hechizo", additional_info = "Hechizo de 3 seg\nComponentes:\nManual de comprensión\n[q]Descifra las notas de hechizo con un manual de comprensión para aprender un nuevo hechizo de grabado."},
[401683] = {name = "[q2]Traducir notas de hechizo", additional_info = "Hechizo de 3 seg\nHerramientas: Escritos de gran mago\n[q]Intenta traducir las notas de hechizo para convertirlas en una nueva receta de tallado rúnico."},
[401684] = {name = "[q2]Traducir notas de hechizo", additional_info = "Hechizo de 3 seg\nHerramientas: Escritos de gran mago\n[q]Intenta traducir las notas de hechizo para convertirlas en una nueva receta de tallado rúnico."},
[401699] = {name = "[q2]Traducir notas de hechizo", additional_info = "Hechizo de 3 seg\nComponentes:\nNota de aprendiz de Azora: página 1 (8)\n[q]Combina 8 notas de aprendiz de Azora para descubrir una nueva receta de tallado rúnico."},
[401719] = {name = "Tromba Arcana", additional_info = "[q]Obtienes la habilidad Tromba Arcana:\n\n\nLanza varios misiles contra el objetivo enemigo que infligen entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 358 / 100] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 438 / 100] p. de daño Arcano. Este hechizo también tiene un 25% de probabilidad de activar Tromba de misiles."},
[401722] = {name = "Grabar capa - Tromba Arcana", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa Tromba Arcana:\n\n\nLanza varios misiles contra el objetivo enemigo que infligen entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 358 / 100] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 438 / 100] p. de daño Arcano. Este hechizo también tiene un 25% de probabilidad de activar Tromba de misiles."},
[401724] = {name = "Una buena racha", additional_info = "[q]Obtienes la habilidad Una buena racha:\n\n\nCada vez que asestes 2 golpes críticos con hechizos no periódicos consecutivos con Bola de Fuego, Descarga de Pirofrío, Descarga de fuego fardo, Explosión de Fuego, Agostar o Bomba viva, tu próximo lanzamiento de Piroexplosión en 10 s será instantáneo y costará un 100% menos de maná."},
[401725] = {name = "Congelación cerebral", additional_info = "[q]Obtienes la habilidad Congelación cerebral:\n\n\nTus hechizos de daño de Escarcha con efectos de enfriamiento tienen un 20% de probabilidad de hacer que tu siguiente hechizo Bola de Fuego, Descarga de fríoarcano, Descarga de fuego fardo o Descarga de Pirofrío sea instantáneo y no cueste maná."},
[401726] = {name = "Resguardo avanzado", additional_info = "[q]Obtienes la habilidad Resguardo avanzado:\n\n\nAhora puedes lanzar tus hechizos Escudo de maná, Resguardo contra la Escarcha y Resguardo contra el Fuego sobre cualquier objetivo aliado y absorben un 100% más de daño, y Escudo de maná consume un 50% menos de maná por el daño absorbido. Además, tu Eliminar maldición inferior es reemplazada con Eliminar maldición superior.\n\n\nElimina 1 maldición y 1 efecto de magia dañino de un objetivo aliado."},
[401729] = {name = "Explosión Arcana", additional_info = "[q]Obtienes la habilidad Explosión Arcana:\n\n\nGolpea al objetivo con energía, lo que inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 453 / 100] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 527 / 100] p. de daño Arcano. Cada vez que lanzas el hechizo Explosión Arcana, el daño de todos tus demás hechizos Arcanos aumentan un 15%, y el costo de maná de Explosión Arcana aumenta un 175%. El efecto se acumula hasta 4 veces y dura 6 s o hasta que se lance cualquier otro hechizo Arcano que inflija daño."},
[401731] = {name = "Bomba viva", additional_info = "[q]Obtienes la habilidad Bomba viva:\n\n\nEl objetivo se convierte en una Bomba viva que recibe [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] p. de daño de Fuego durante 12 s. Después de 12 s o cuando se disipa el hechizo, el objetivo explota e inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] p. de daño de Fuego a todos los enemigos en un radio de 10 m.\n\n Bomba viva se beneficia de todos los talentos y efectos que activan o modifican Agostar."},
[401732] = {name = "Lanza de hielo", additional_info = "[q]Obtienes la habilidad Lanza de hielo:\n\n\nInflige entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 55 / 100 * ( 1 ) ] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 65 / 100 * ( 1 ) ] de daño de Escarcha a un objetivo enemigo. Inflige un 400% de daño contra objetivos congelados.\n\n Cuando tus otros hechizos de Escarcha infligen daño a un objetivo que no controla un jugador, aumentan un 20% el daño que recibe el objetivo de tu siguiente Lanza de hielo. Este efecto se acumula hasta 5 veces y requiere el talento Escalofrío invernal."},
[401734] = {name = "Retroceder en el tiempo", additional_info = "[q]Obtienes la habilidad Retroceder en el tiempo:\n\n\nTu objetivo actual con tu Faro temporal se sana inmediatamente de todo el daño recibido durante los últimos 5 segundos. Es ineficaz contra objetivos que no tenían un Faro temporal hace 5 segundos."},
[401735] = {name = "Descarga de Pirofrío", additional_info = "[q]Obtienes la habilidad Descarga de Pirofrío:\n\n\nLanza una Descarga de Pirofrío contra el enemigo, inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 325 / 100 * ( 1 ) ] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 379 / 100 * ( 1 ) ] p. de daño de Pirofrío, reduce la velocidad de movimiento un 40% e inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 12 / 100 * 3 * ( 1 ) ] p. de daño de Pirofrío extra durante 9 s. Este hechizo tendrá en cuenta la resistencia más baja entre las resistencias de Fuego o Escarcha del objetivo y cuenta como daño de Escarcha y Fuego."},
[401736] = {name = "Tromba de misiles", additional_info = "[q]Obtienes la habilidad Tromba de misiles:\n\n\nDa a tu Explosión Arcana una probabilidad de un 40% y a Bola de Fuego y Descarga de Escarcha una probabilidad de un 20% de reducir la duración canalizada de tus siguientes Misiles Arcanos un 50%; reduce el costo de maná un 100% y disparará misiles cada 0.5 s."},
