[401764] = {name = "Grabar capa - Recalentamiento", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa Recalentamiento:\n\n\nExplosión de Fuego siempre asestará un golpe crítico, se puede lanzar durante el lanzamiento de otro hechizo y no se ve afectada por el tiempo de reutilización global, pero su tiempo de reutilización aumenta a 15 s."},
[401765] = {name = "Grabar pechera - Dedos de Escarcha", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Dedos de Escarcha:\n\n\nDa a tus efectos de enfriamiento una probabilidad de un 25% de otorgarte el efecto Dedos de Escarcha, que hace que tus siguientes 2 hechizos traten al objetivo como si estuviese congelado. Dura 15 s."},
[401767] = {name = "Grabar pechera - Regeneración", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Regeneración:\n\n\nRestablece [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] p. de salud al objetivo durante 3 s y aplica Faro temporal durante 30 s.\n\n Faro temporal\n\nRegistra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos."},
[401768] = {name = "Grabar pantalones - Llama viva", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Llama viva:\n\n\nInvoca una llama piroarcana que se mueve hacia el objetivo y deja un rastro de piroarcano. Este rastro inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100] p. de daño Piroarcano por s a los enemigos cercanos. Dura 10 s."},
[401798] = {name = "Alijo casi enterrado", additional_info = nil},
[401847] = {name = "Combinar trozos de mapa", additional_info = "Hechizo de 3 seg\nComponentes:\nTrozo superior derecho de mapa , Trozo superior izquierdo de mapa , Trozo inferior derecho de mapa , Trozo inferior izquierdo de mapa\n[q]Combina este objeto con 3 trozos más para completar el mapa."},
[401859] = {name = "Rezo de alivio", additional_info = "{15% del maná base} {Alcance de 40 m}\n{Instante} {10 seg de reutilización}\n[q]Lanza un hechizo sobre el objetivo que lo sanará [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] p. la próxima vez que reciba daño o sanación. Una vez sanado, Rezo de alivio pasará a otro miembro del grupo o banda en un radio de 20 m. Salta hasta 5 veces y dura 30 s después de cada salto. Este hechizo solo puede estar activo en un único objetivo a la vez."},
[401863] = {name = "Rezo de alivio", additional_info = "Rango ilimitado\nInstante\n[q]Lanza un hechizo sobre el objetivo que lo sanará la próxima vez que reciba daño. Una vez sanado, Rezo de alivio pasará a otro miembro del grupo o banda en un radio de 0 m. Salta hasta 0 veces y dura hasta cancelación después de cada salto. Este hechizo solo puede estar activo en un único objetivo a la vez."},
[401877] = {name = "Rezo de alivio", additional_info = "Rango ilimitado\nInstante\n[q]Lanza un hechizo sobre el objetivo que lo sanará la próxima vez que reciba daño o sanación. Una vez sanado, Rezo de alivio pasará a otro miembro del grupo o banda en un radio de 0 m. Salta hasta 0 veces y dura 30 s después de cada salto. Este hechizo solo puede estar activo en un único objetivo a la vez."},
