[401946] = {name = "Círculo de sanación", additional_info = "{56% del maná base} {Alcance de 40 m}\n{Instante} {6 seg de reutilización}\n[q]Restablece de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] p. de salud a todos los miembros del grupo del jugador objetivo en un radio de 43.5 m del objetivo."},
[401955] = {name = "Palabra de las Sombras: muerte", additional_info = "{12% del maná base} {Alcance de 30 m}\n{Instante} {12 seg de reutilización}\n[q]Una palabra de vínculo oscuro que inflige entre [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100] y [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] p. de daño de las Sombras al objetivo. Si el objetivo no muere a causa de Palabra de las Sombras: muerte, el taumaturgo recibe daño equivalente a un 50% del daño que intentó infligirle."},
[401956] = {name = "Traspié criomántico", additional_info = nil},
[401962] = {name = "Palabra de las Sombras: muerte", additional_info = "Instante\n[q]Una palabra de vínculo oscuro que inflige daño de las Sombras al objetivo. Si el objetivo no muere a causa de Palabra de las Sombras: muerte, el taumaturgo recibe daño equivalente a la cantidad de daño infligida al objetivo."},
