[402862] = {name = "Grabar guantes - Penitencia", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Penitencia:\n\n\nLanza una salva de Luz Sagrada al objetivo, inflige [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100] p. de daño Sagrado a un enemigo, o [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100] p. de sanación a un aliado de forma instantánea y cada 1 s durante 2 s."},
[402864] = {name = "Grabar yelmo - Ojo del Vacío", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Ojo del Vacío:\n\n\nInvoca un ojo del Vacío para que luche por ti durante 30 s. El ojo puede lanzar una serie de maldiciones sobre tu objetivo."},
[402877] = {name = "Flagelación", additional_info = "[q]Obtienes ira del daño físico recibido como si no tuvieras armadura."},
[402906] = {name = "Flagelación", additional_info = nil},
[402911] = {name = "Arremetida enfurecida", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {8 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Un golpe feroz que inflige un 115% de daño con arma, pero que solo se puede usar cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas. Las demás habilidades cuerpo a cuerpo que se usan cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas reducen 1 s el tiempo de reutilización restante de Arremetida enfurecida."},
[402913] = {name = "Regeneración iracunda", additional_info = "{Instante} {3 min de reutilización}\n[q]Te sana un 30% de tu salud máxima durante 10 s, pero solo se puede usar cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas. Se puede usar mientras estás aturdido."},
[402922] = {name = "Tiempo preciso", additional_info = "[q]Embate ahora es instantáneo, pero tiene un tiempo de reutilización de 6 s."},
[402927] = {name = "Ataque de la victoria", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {8 seg de reutilización}\n[q]Atacas al instante al objetivo, le infliges (1 + Attack power * 45 / 100) p. de daño y recuperas una cantidad de salud equivalente al 30% de tu salud máxima. Solo puede usarse durante 20 s tras haber matado a un enemigo que otorga experiencia u honor."},
[402975] = {name = "Estado victorioso", additional_info = "Instante\n[q]Se produce después de matar a un enemigo."},
[403172] = {name = "Tallado rúnico: Aprender Grabar Entre los ojos", additional_info = nil},
[403195] = {name = "Devastar", additional_info = "[q]Mientras estás en actitud defensiva y tienes un escudo equipado, Hender armadura también inflige daño equivalente al 150% del daño por segundo de tu arma equipada, y aumenta un 10% por aplicación de Hender armadura que ya haya en el objetivo. El daño de Devastar genera una gran cantidad de amenaza mientras estás en Actitud defensiva."},
[403196] = {name = "Devastar", additional_info = "Rango ilimitado\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Hender armadura también inflige un 150% de daño con arma, que aumenta un 10% por aplicación de Hender armadura que ya haya en el objetivo."},
[403215] = {name = "Grito de orden", additional_info = "Instante\n[q]El guerrero grita y aumenta el aguante de todos los miembros del grupo en un radio de 30 m en 2 p. Dura 5 min."},
[403218] = {name = "Ira infinita", additional_info = "[q]Generas un 25% más de ira por todo el daño que infliges."},
[403219] = {name = "Rayo furioso", additional_info = "[q]Atronar ahora aumenta el tiempo entre ataques un 6% más. Puede usarse en cualquier actitud, inflige un 100% más de daño e inflige un 50% más de amenaza."},
[403228] = {name = "Gancho", additional_info = "{15 p. de ira} {Alcance de 30 m}\n{Hechizo instantáneo} {35 seg de reutilización}\n[q]Lanzas una cadena con gancho para refrenar a un objetivo y atraerlo hacia ti. No puede utilizarse contra enemigos de nivel superior a ( 60 + 1) o que estén marcados como jefes."},
[403231] = {name = "Gancho", additional_info = "Rango ilimitado\n{Instante} {35 seg de reutilización}\n[q]Lanzas una cadena con gancho para refrenar a un objetivo y atraerlo hacia ti."},
[403233] = {name = "Gancho", additional_info = "Rango ilimitado\nInstante\n[q]Lanzas una cadena con gancho para refrenar a un objetivo y atraerlo hacia ti. Los objetivos no pueden aturdirse mientras son atraídos."},
[403332] = {name = "Disparo heroico", additional_info = "Alcance de 8 - 35 m\n6 seg de reutilización\nRequiere Arma a distancia\n[q]Dispara al objetivo con un arma a distancia e inflige un 300% de daño. Genera 20 p. de ira."},
[403338] = {name = "Intervenir", additional_info = "{10 p. de ira} {Alcance de 8 - 25 m}\n{Hechizo instantáneo} {30 seg de reutilización}\nRequiere Actitud defensiva\n[q]Corres a gran velocidad hacia un miembro del grupo, e interceptas el siguiente ataque cuerpo a cuerpo o a distancia que le hagan. Además, reduces su amenaza total un 10%."},
[403339] = {name = "Intervenir", additional_info = nil},
[403344] = {name = "Flagelación", additional_info = "[q]Obtienes la habilidad Flagelación:\n\n\nObtienes ira del daño físico recibido como si no tuvieras armadura."},
[403349] = {name = "Ira infinita", additional_info = "[q]Obtienes la habilidad Ira infinita:\n\n\nGeneras un 25% más de ira por todo el daño que infliges."},
[403352] = {name = "Frenesí sangriento", additional_info = "[q]Obtienes la habilidad Frenesí sangriento:\n\n\nAhora Desgarrar se puede usar en actitud rabiosa, su daño aumenta un 100% e inflige una mayor cantidad de daño, equivalente al 4% de tu poder de ataque, cada vez que inflige daño."},
[403355] = {name = "Devastar", additional_info = "[q]Obtienes la habilidad Devastar:\n\n\nMientras estás en actitud defensiva y tienes un escudo equipado, Hender armadura también inflige daño equivalente al 150% del daño por segundo de tu arma equipada, y aumenta un 10% por aplicación de Hender armadura que ya haya en el objetivo. El daño de Devastar genera una gran cantidad de amenaza mientras estás en Actitud defensiva."},
