[403446] = {name = "Grabar pantalones - Grito de orden", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Grito de orden:\n\n\nEl guerrero grita y aumenta el aguante de todos los miembros del grupo en un radio de 30 m en 2 p. Dura 5 min."},
[403467] = {name = "Grabar botas - Regeneración iracunda", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Regeneración iracunda:\n\n\nTe sana un 30% de tu salud máxima durante 10 s, pero solo se puede usar cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas. Se puede usar mientras estás aturdido."},
[403470] = {name = "Grabar guantes - Ataque de la victoria", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Ataque de la victoria:\n\n\nAtacas al instante al objetivo, le infliges (1 + Attack power * 45 / 100) p. de daño y recuperas una cantidad de salud equivalente al 30% de tu salud máxima. Solo puede usarse durante 20 s tras haber matado a un enemigo que otorga experiencia u honor."},
