[403474] = {name = "Grabar pechera - Frenesí sangriento", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera con la runa Frenesí sangriento:\n\n\nAhora Desgarrar se puede usar en actitud rabiosa, su daño aumenta un 100% e inflige una mayor cantidad de daño, equivalente al 4% de tu poder de ataque, cada vez que inflige daño."},
[403475] = {name = "Grabar guantes - Devastar", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Devastar:\n\n\nMientras estás en actitud defensiva y tienes un escudo equipado, Hender armadura también inflige daño equivalente al 150% del daño por segundo de tu arma equipada, y aumenta un 10% por aplicación de Hender armadura que ya haya en el objetivo. El daño de Devastar genera una gran cantidad de amenaza mientras estás en Actitud defensiva."},
[403476] = {name = "Grabar pantalones - Rayo furioso", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Rayo furioso:\n\n\nAtronar ahora aumenta el tiempo entre ataques un 6% más. Puede usarse en cualquier actitud, inflige un 100% más de daño e inflige un 50% más de amenaza."},
[403480] = {name = "Grabar pechera - Flagelación", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera con la runa Flagelación:\n\n\nObtienes ira del daño físico recibido como si no tuvieras armadura."},
[403489] = {name = "Grabar yelmo - Ira infinita", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Ira infinita:\n\n\nGeneras un 25% más de ira por todo el daño que infliges."},
[403501] = {name = "Poseer", additional_info = "{12% del maná base} {Alcance de 30 m}\n{Instante} {12 seg de reutilización}\n[q]Liberas un alma fantasmal contra un enemigo. Le inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] p. de daño y aumenta un 40% todo el daño de las Sombras con el tiempo que inflijas a ese objetivo durante 15 s. Cuando Poseer termina o se disipa, sanas por todo el daño que infligió al objetivo."},
[403506] = {name = "Poseer", additional_info = nil},
[403511] = {name = "Succión de alma", additional_info = "[q]Hace que tu Drenar alma inflija daño 3 veces más rápido y aumenta la cantidad drenada por tus hechizos Drenar vida y Drenar alma un 6% más por cada efecto de las sombras de tu brujo aplicado sobre el objetivo, hasta un máximo de un 18% adicional. Cuando Drenar alma se lanza sobre un objetivo que tiene menos de un 20% de salud, en cambio obtiene un 50% por cada efecto, hasta un máximo de un 150%. Además, tu Drenar alma ahora puede activar tu talento Ocaso.\n(Probabilidad de que accione: 8%)"},
[403619] = {name = "Armadura vil", additional_info = "28% del maná base\nInstante\n[q]Rodea al taumaturgo con energía vil que aumenta 1 p. el daño con hechizos y la sanación, más otro monto de daño con hechizos y sanación equivalente al 50% de tu espíritu. Además, recuperas un 2% de tu salud máxima cada 5 s. Un brujo solo puede tener un tipo de hechizo de Armadura activo a la vez. Dura 30 min."},
[403628] = {name = "Salva de descarga de las Sombras", additional_info = "[q]Tu Descarga de las Sombras ahora golpea a un máximo de 5 objetivos a una distancia de 10 m, pero inflige un 5% menos de daño."},
[403629] = {name = "Descarga de caos", additional_info = "{7% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg 12 seg de reutilización\n[q]Lanza una descarga de fuego caótico al enemigo que inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] p. de daño de Caos. Descarga de caos siempre golpea, no se puede resistir, y su conocimiento hace que todos tus hechizos de Fuego atraviesen los efectos de absorción. Los enemigos con 4 o más niveles por encima del tuyo tienen una alta probabilidad de resistir Descarga de caos."},
[403630] = {name = "Descarga de caos", additional_info = nil},
[403650] = {name = "Lago de fuego", additional_info = "Alcance de 100 m\nInstante\n[q]Lluvia de Fuego también deja un Lago de fuego en el suelo que aumenta un 50% todo el daño de Fuego que tú y tu mascota demoníaca infligen a los enemigos afectados."},
[403666] = {name = "Lago de fuego", additional_info = "[q]Tu Lluvia de fuego ya no se canaliza, pero obtiene un tiempo de reutilización de 8 s."},
[403668] = {name = "Canalización maestra", additional_info = "[q]Tu Drenar vida ya no requiere canalización, dura 15 s, tiene 15 s de tiempo de reutilización, cuesta un 100% más de maná y te sana por un 50% más cada vez que inflige daño."},
[403677] = {name = "Drenar vida", additional_info = "{110 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Transfiere 10 p. de salud por s del objetivo al taumaturgo. Dura 15 s."},
[403680] = {name = "Carga de profundidad", additional_info = nil},
[403683] = {name = "Carga de profundidad", additional_info = nil},
[403685] = {name = "Drenar vida", additional_info = "{170 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Transfiere 17 p. de salud por s del objetivo al taumaturgo. Dura 15 s."},
[403686] = {name = "Drenar vida", additional_info = "{270 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Transfiere 29 p. de salud por s del objetivo al taumaturgo. Dura 15 s."},
[403687] = {name = "Drenar vida", additional_info = "{370 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Transfiere 41 p. de salud por s del objetivo al taumaturgo. Dura 15 s."},
[403688] = {name = "Drenar vida", additional_info = "{480 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Transfiere 55 p. de salud por s del objetivo al taumaturgo. Dura 15 s."},
[403689] = {name = "Drenar vida", additional_info = "{600 p. de maná} {Alcance de 20 m}\n{Instante} {15 seg de reutilización}\n[q]Transfiere 71 p. de salud por s del objetivo al taumaturgo. Dura 15 s."},
[403789] = {name = "Metamorfosis", additional_info = "100% del maná base\nInstante\n[q]Te transformas en un demonio, lo que aumenta un 500% la armadura y un 15% la salud, reduce un 6% la probabilidad de que recibas un golpe crítico, aumenta un 50% tu amenaza y un 100% el maná obtenido por Transfusión de vida, pero reduce un 10% todo el daño que infliges. Metamorfosis transforma la funcionalidad de algunas habilidades y otorga algunas nuevas:\n\n Dolor abrasador: ahora es instantáneo.\n\n Descarga de las sombras: se convierte en Cuchilla de las Sombras, un ataque cuerpo a cuerpo de las Sombras que golpea a un máximo de 10 enemigos cercanos, pero tiene un tiempo de reutilización de 6 s.\n\n Miedo: se reemplaza con Amenaza.\n\n\nProvoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando.\n\n Carga de demonio\n\n\nCarga contra un enemigo y lo aturde durante 1 s. No se puede usar en combate.\n\n Aullido demoníaco\n\n\nObliga a todos los enemigos cercanos a concentrar sus ataques sobre ti durante 6 s."},
[403816] = {name = "Metamorfosis", additional_info = "[q]Te transformas en un demonio, lo que aumenta un 500% la armadura, reduce un 6% la probabilidad de que recibas un golpe crítico, aumenta un 50% tu amenaza y un 100% el maná obtenido por Transfusión de vida, y transforma la funcionalidad de algunas de tus habilidades:\n\n Dolor abrasador: Ahora es instantáneo.\n\n Descarga de las Sombras: Se convierte en Cuchilla de las Sombras, un ataque de las Sombras cuerpo a cuerpo que golpea a un máximo de 500 enemigos cercanos.\n\n Maldición de temeridad: Ahora también provoca a tu objetivo para que te ataque durante hasta cancelación.\n\n Aullido de terror: Ahora también obliga a todos los enemigos cercanos a que te ataquen durante hasta cancelación, pero el tiempo de reutilización aumenta a 10 minutos."},
[403828] = {name = "Amenaza", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {10 seg de reutilización}\n[q]Provoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."},
[403835] = {name = "Cuchilla de las Sombras", additional_info = "{12 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 3 to 7 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 5 * 5) p. Dura 15 s ]"},
[403839] = {name = "Cuchilla de las Sombras", additional_info = "{20 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 7 to 12 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 11 * 5) p. Dura 15 s ]"},
[403840] = {name = "Cuchilla de las Sombras", additional_info = "{35 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 14 to 23 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 17 * 5) p. Dura 15 s ]"},
[403841] = {name = "Cuchilla de las Sombras", additional_info = "{55 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 26 to 39 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 25 * 5) p. Dura 15 s ]"},
[403842] = {name = "Cuchilla de las Sombras", additional_info = "{80 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 42 to 64 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 33 * 5) p. Dura 15 s ]"},
[403843] = {name = "Cuchilla de las Sombras", additional_info = "{105 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 60 to 91 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 41 * 5) p. Dura 15 s ]"},
[403844] = {name = "Cuchilla de las Sombras", additional_info = "{132 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 82 to 124 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 49 * 5) p. Dura 15 s ]"},
[403848] = {name = "Cuchilla de las Sombras", additional_info = "{157 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 105 to 158 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 57 * 5) p. Dura 15 s ]"},
[403851] = {name = "Cuchilla de las Sombras", additional_info = "{185 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 128 to 193 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 60 * 5) p. Dura 15 s ]"},
[403852] = {name = "Cuchilla de las Sombras", additional_info = "{190 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Castiga a un máximo de 10 enemigos cercanos con un latigazo de sombras que inflige 136 to 204 p. a cada objetivo.\n\n Cuchillas de las Sombras activa y se beneficia de la mayoría de los talentos y efectos que Descarga de las Sombras activa y de los que se beneficia también.[ S03 - Tuning and Overrides Passive - All Classes : Golpear a un objetivo con Cuchillas de las Sombras también te otorga 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 60 * 5) p. Dura 15 s ]"},
[403858] = {name = "Poseer", additional_info = "[q]Obtienes la habilidad Poseer:\n\n\nLiberas un alma fantasmal contra un enemigo. Le inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] p. de daño y aumenta un 40% todo el daño de las Sombras con el tiempo que inflijas a ese objetivo durante 15 s. Cuando Poseer termina o se disipa, sanas por todo el daño que infligió al objetivo."},
[403860] = {name = "Descarga de caos", additional_info = "[q]Obtienes la habilidad Descarga de caos:\n\n\nLanza una descarga de fuego caótico al enemigo que inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] p. de daño de Caos. Descarga de caos siempre golpea, no se puede resistir, y su conocimiento hace que todos tus hechizos de Fuego atraviesen los efectos de absorción. Los enemigos con 4 o más niveles por encima del tuyo tienen una alta probabilidad de resistir Descarga de caos."},
[403863] = {name = "Succión de alma", additional_info = "[q]Obtienes la habilidad Succión de alma:\n\n\nHace que tu Drenar alma inflija daño 3 veces más rápido y aumenta la cantidad drenada por tus hechizos Drenar vida y Drenar alma un 6% más por cada efecto de las sombras de tu brujo aplicado sobre el objetivo, hasta un máximo de un 18% adicional. Cuando Drenar alma se lanza sobre un objetivo que tiene menos de un 20% de salud, en cambio obtiene un 50% por cada efecto, hasta un máximo de un 150%. Además, tu Drenar alma ahora puede activar tu talento Ocaso."},
[403868] = {name = "Canalización maestra", additional_info = "[q]Obtienes la habilidad Canalización maestra:\n\n\nTu Drenar vida ya no requiere canalización, dura 15 s, tiene 15 s de tiempo de reutilización, cuesta un 100% más de maná y te sana por un 50% más cada vez que inflige daño."},
[403871] = {name = "Salva de descarga de las Sombras", additional_info = "[q]Obtienes la habilidad Salva de descarga de las Sombras:\n\n\nTu Descarga de las Sombras ahora golpea a un máximo de 5 objetivos a una distancia de 10 m, pero inflige un 5% menos de daño."},
[403872] = {name = "Lago de fuego", additional_info = "[q]Obtienes la habilidad Lago de fuego:\n\n\nTu Lluvia de fuego ya no se canaliza, pero obtiene un tiempo de reutilización de 8 s."},
[403873] = {name = "Metamorfosis", additional_info = "[q]Obtienes la habilidad Metamorfosis:\n\n\nTe transformas en un demonio, lo que aumenta un 500% la armadura y un 15% la salud, reduce un 6% la probabilidad de que recibas un golpe crítico, aumenta un 50% tu amenaza y un 100% el maná obtenido por Transfusión de vida, pero reduce un 10% todo el daño que infliges. Metamorfosis transforma la funcionalidad de algunas habilidades y otorga algunas nuevas:\n\n Dolor abrasador: ahora es instantáneo.\n\n Descarga de las sombras: se convierte en Cuchilla de las Sombras, un ataque cuerpo a cuerpo de las Sombras que golpea a un máximo de 10 enemigos cercanos, pero tiene un tiempo de reutilización de 6 s.\n\n Miedo: se reemplaza con Amenaza.\n\n\nProvoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando.\n\n Carga de demonio\n\n\nCarga contra un enemigo y lo aturde durante 1 s. No se puede usar en combate.\n\n Aullido demoníaco\n\n\nObliga a todos los enemigos cercanos a concentrar sus ataques sobre ti durante 6 s."},
[403919] = {name = "Grabar guantes - Poseer", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Poseer:\n\n\nLiberas un alma fantasmal contra un enemigo. Le inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] p. de daño y aumenta un 40% todo el daño de las Sombras con el tiempo que inflijas a ese objetivo durante 15 s. Cuando Poseer termina o se disipa, sanas por todo el daño que infligió al objetivo."},
[403920] = {name = "Grabar capa - Succión de alma", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa Succión de alma:\n\n\nHace que tu Drenar alma inflija daño 3 veces más rápido y aumenta la cantidad drenada por tus hechizos Drenar vida y Drenar alma un 6% más por cada efecto de las sombras de tu brujo aplicado sobre el objetivo, hasta un máximo de un 18% adicional. Cuando Drenar alma se lanza sobre un objetivo que tiene menos de un 20% de salud, en cambio obtiene un 50% por cada efecto, hasta un máximo de un 150%. Además, tu Drenar alma ahora puede activar tu talento Ocaso."},
[403925] = {name = "Grabar guantes - Descarga de caos", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Descarga de caos:\n\n\nLanza una descarga de fuego caótico al enemigo que inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] p. de daño de Caos. Descarga de caos siempre golpea, no se puede resistir, y su conocimiento hace que todos tus hechizos de Fuego atraviesen los efectos de absorción. Los enemigos con 4 o más niveles por encima del tuyo tienen una alta probabilidad de resistir Descarga de caos."},
[403932] = {name = "Grabar pechera - Canalización maestra", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Canalización maestra:\n\n\nTu Drenar vida ya no requiere canalización, dura 15 s, tiene 15 s de tiempo de reutilización, cuesta un 100% más de maná y te sana por un 50% más cada vez que inflige daño."},
[403936] = {name = "Grabar guantes - Salva de descarga de las Sombras", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Salva de descarga de las Sombras:\n\n\nTu Descarga de las Sombras ahora golpea a un máximo de 5 objetivos a una distancia de 10 m, pero inflige un 5% menos de daño."},
[403937] = {name = "Grabar pechera - Lago de fuego", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Lago de fuego:\n\n\nTu Lluvia de fuego ya no se canaliza, pero obtiene un tiempo de reutilización de 8 s."},
[403938] = {name = "Grabar guantes - Metamorfosis", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Metamorfosis:\n\n\nTe transformas en un demonio, lo que aumenta un 500% la armadura y un 15% la salud, reduce un 6% la probabilidad de que recibas un golpe crítico, aumenta un 50% tu amenaza y un 100% el maná obtenido por Transfusión de vida, pero reduce un 10% todo el daño que infliges. Metamorfosis transforma la funcionalidad de algunas habilidades y otorga algunas nuevas:\n\n Dolor abrasador: ahora es instantáneo.\n\n Descarga de las sombras: se convierte en Cuchilla de las Sombras, un ataque cuerpo a cuerpo de las Sombras que golpea a un máximo de 10 enemigos cercanos, pero tiene un tiempo de reutilización de 6 s.\n\n Miedo: se reemplaza con Amenaza.\n\n\nProvoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando.\n\n Carga de demonio\n\n\nCarga contra un enemigo y lo aturde durante 1 s. No se puede usar en combate.\n\n Aullido demoníaco\n\n\nObliga a todos los enemigos cercanos a concentrar sus ataques sobre ti durante 6 s."},
