[407613] = {name = "Señal de la Luz", additional_info = "{7% del maná base} {Alcance de 40 m}\nInstante\n[q]El objetivo se convierte en una Señal de la Luz para todos los miembros de tu grupo o banda que se encuentren en un radio de 40 m. Cualquier sanación que lances sobre miembros de tu grupo o banda sanará también a la señal un 75% de la cantidad sanada. Solo un objetivo puede ser la Señal de la Luz cada vez. Dura 1 h."},
[407614] = {name = "Señal de la Luz", additional_info = "Alcance de 60 m\nInstante\n[q]El objetivo se convierte en una Señal de la Luz para todos los objetivos en un radio de 60 m. Cualquier sanación que realices sobre esos objetivos restablecerá también un 75% de la cantidad sanada a la señal."},
[407615] = {name = "Señal de la Luz", additional_info = "Alcance de 40 m\nInstante\n[q]El objetivo se convierte en una Señal de la Luz para todos los objetivos en un radio de 40 m. Cualquier sanación que realices sobre esos objetivos restablecerá también un 1% de la cantidad sanada a la señal. Solo un objetivo puede ser la Señal de la Luz cada vez. Dura hasta cancelación."},
[407624] = {name = "Maestría en auras", additional_info = "{Instante} {2 min de reutilización}\n[q]Provoca que tu Aura de concentración haga inmunes ante los efectos de silencio e interrupción a todos los objetivos afectados y mejore el efecto del resto de las auras un 100%. Dura 6 s."},
[407627] = {name = "Furia recta", additional_info = "Instante\n[q]Aumenta un 80% la amenaza que generan tus hechizos Sagrados, y cuando te sanan los hechizos de otros objetivos aliados, te otorga una cantidad de maná equivalente a un 25% de la cantidad sanada. Además, el daño que reduzca tu salud por debajo del 35% se reduce un 20%. Dura hasta cancelación."},
[407628] = {name = "Furia recta", additional_info = "Instante\n[q]Obtiene maná de la sanación recibida."},
[407631] = {name = "Mano de expiación", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {10 seg de reutilización}\n[q]Provocas al objetivo para que te ataque, pero no tiene efecto si el objetivo ya te está atacando.\n\n Cuando conoces esta habilidad, la bonificación de amenaza de Furia recta aumenta a 80% y cuando te sanan otros, Furia recta hace que obtengas una cantidad de maná equivalente a un 25% de la cantidad sanada. Además, mientras Furia recta está activa, el daño que deje tu salud por debajo del 35% se reduce un 20%. Furia recta permanecerá activa hasta que se cancele."},
[407632] = {name = "Martillo del honrado", additional_info = "{6% del maná base} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Da un martillazo al objetivo actual y a un máximo de 3 objetivos cercanos más, inflige 4 veces el daño por segundo de tu mano derecha como daño sagrado."},
[407653] = {name = "Relámpago bifurcado", additional_info = "Alcance de 30 m\nInstante\n[q]Golpea a un enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 0 objetivos e inflige daño de Naturaleza a cada uno."},
[407667] = {name = "Relámpago bifurcado", additional_info = "Alcance de 30 m\nInstante\n[q]Golpea a un enemigo con una descarga de relámpagos que se bifurca para alcanzar a todos los objetivos cercanos e infligirles daño de Naturaleza."},
[407669] = {name = "Escudo de vengador", additional_info = "{26% del maná base} {Alcance de 30 m}\n{Instante} {15 seg de reutilización}\n[q]Lanza un escudo Sagrado al enemigo que inflige de [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] a [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] p. de daño Sagrado, lo deja atontado y salta a los enemigos cercanos. Afecta a un total de 3 objetivos. Dura 5 s."},
[407676] = {name = "Golpe de cruzado", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {6 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Un golpe instantáneo que inflige un 75% de daño con arma como daño Sagrado y regenera un 5% de tu maná máximo. La duración de todos los efectos de Sentencia en el objetivo se restablece a 30 s."},
[407720] = {name = "Relámpago bifurcado", additional_info = "Alcance de 30 m\nInstante\n[q]Golpea a un enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 0 objetivos e inflige daño de Naturaleza a cada uno."},
[407736] = {name = "Relámpago bifurcado", additional_info = "Alcance de 30 m\nInstante\n[q]Golpea a un enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 0 objetivos e inflige daño de Naturaleza a cada uno."},
