[407778] = {name = "Tormenta divina", additional_info = "12% del maná base\n{Instante} {10 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque instantáneo con arma que inflige un 110% de daño con arma a un máximo de 4 enemigos que se encuentren en un radio de 8 m. La Tormenta divina sana a hasta 3 miembros del grupo o banda con un total del 25% del daño infligido."},
[407782] = {name = "Tormenta divina", additional_info = "Alcance de 100 m\nInstante\n[q]El daño infligido de Tormenta divina sana a los objetivos aliados."},
[407784] = {name = "Tormenta divina", additional_info = "Rango ilimitado\nInstante\n[q]El daño infligido con Tormenta divina sana a los objetivos aliados cercanos."},
[407788] = {name = "Cólera vengativa", additional_info = "8% del maná base\n{Instante} {3 min de reutilización}\n[q]Aumenta todo el daño y la sanación infligidos un 20% durante 20 s. Causa Abstinencia y no se puede usar mientras Abstinencia está activa."},
[407791] = {name = "Ira de Aku'mai", additional_info = "Instante\n[q]Aumenta el daño físico infligido por el taumaturgo en 25 p. y acelera sus ataques un 30% durante 15 s."},
[407794] = {name = "Perforación triple", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Inflige daño físico a un enemigo cada 3 s durante 15 s.\n(1s de reutilización)"},
[407798] = {name = "Sello de martirio", additional_info = "4% del maná base\nInstante\n[q]Te colmas de espíritu sagrado durante 30 s, lo que hace que cada uno de tus ataques cuerpo a cuerpo inflija un 50% de daño con arma a tu objetivo, pero pierdes una cantidad de salud equivalente al 10% del daño infligido. Cuando el sello está activo, los miembros de tu grupo y banda en un radio de 40 m obtienen una cantidad de maná equivalente al 65% del daño que recibas de este sello.\n\n Al desatar la energía de este sello, se juzgará a un enemigo y le infligirá instantáneamente un 85% de daño con arma a cambio de un 10% de salud del daño infligido.\n\n El sello y sentencia de esta habilidad se benefician de los talentos y efectos que modifican el sello y sentencia de Sello de rectitud."},
[407799] = {name = "Sello de martirio", additional_info = nil},
[407800] = {name = "Sello de martirio", additional_info = "Instante\n[q]Sello de martirio también daña al paladín."},
[407802] = {name = "Sello de martirio", additional_info = "Alcance de 40 m\nInstante\n[q]Obtiene maná del daño recibido por el paladín."},
[407803] = {name = "Sentencia de sangre", additional_info = nil},
[407804] = {name = "Sacrificio divino", additional_info = "{Instante} {2 min de reutilización}\n[q]Un 30% de todo el daño que reciben los miembros del grupo en un radio de 30 m se redirige al paladín durante 10 s. El daño que reduzca la salud del paladín por debajo del 20% romperá el efecto y aumentará un 10% el daño y la sanación que realiza durante 10 s. Sacrificio divino no se puede usar mientras estás bajo los efectos de Bendición de protección, Escudo divino o Protección divina, e impide que te marquen como objetivo de esas habilidades mientras está activo."},
[407805] = {name = "Sacrificio cumplido", additional_info = "{Instante} {3 min de reutilización}\n[q]El daño y la sanación aumentan después de tu sacrificio."},
[407811] = {name = "Rajar", additional_info = "Alcance de ataques cuerpo a cuerpo\nSiguiente cuerpo a cuerpo\n[q]Inflige daño con arma más 23 to 27 p. a un enemigo y a sus aliados cercanos. Afecta a un máximo de 3 objetivos."},
[407812] = {name = "Inmunidad a Flecha congelante", additional_info = nil},
[407813] = {name = "Flecha de Escarcha", additional_info = "Alcance de 5 - 30 m\nHechizo de 1 seg\nRequiere Arma a distancia\n[q]Dispara a un enemigo y le inflige daño físico."},
[407819] = {name = "Flecha de Escarcha", additional_info = "Alcance de 50 m\nHechizo de 1.5 seg\nRequiere Arma a distancia\n[q]Dispara a un enemigo y le inflige daño físico."},
[407821] = {name = "Flecha de Escarcha", additional_info = "Alcance de 50 m\nInstante\nRequiere Arma a distancia\n[q]Dispara a un enemigo y le inflige daño físico."},
[407822] = {name = "Flecha de Escarcha", additional_info = nil},
[407880] = {name = "Inspiración ejemplar", additional_info = "2% del maná base\nInstante\n[q]Tu presencia inspiradora periódicamente disipa efectos de miedo y sueño en miembros del grupo cercanos."},
[407881] = {name = "Inspiración ejemplar", additional_info = "Instante\n[q]Tu presencia inspiradora periódicamente disipa efectos de miedo y sueño en miembros del grupo cercanos."},
[407957] = {name = "Cólera vengativa", additional_info = nil},
[407973] = {name = "Golpe feroz", additional_info = "Alcance de 100 m\nInstante\n[q]Ataque extra."},
[407975] = {name = "Golpes feroces", additional_info = "Instante\n[q]Los miembros del grupo en un radio de 20 m obtienen mayor ferocidad de combate. Cada golpe cuerpo a cuerpo tiene una probabilidad de un 20% de otorgar un ataque extra al atacante con un 20% de poder de ataque extra. No tiene efecto si el miembro del grupo ya se ha beneficiado de Tótem Viento Furioso.\n(Probabilidad de que accione: 20%, 1.5s de reutilización)"},
[407977] = {name = "Golpes feroces", additional_info = "[q]Cuando estás en Forma felina, de oso o de oso temible, los miembros del grupo o banda en un radio de 100 m obtienen mayor ferocidad de combate. Cada golpe cuerpo a cuerpo tiene un 20% de probabilidad de otorgar un ataque extra al atacante con un 20% de poder de ataque extra. No tiene efecto si el objetivo ya se ha beneficiado de Tótem Viento Furioso."},
[407988] = {name = "Rugido salvaje", additional_info = "{25 p. de energía} {Alcance de 100 m}\nInstante\n[q]Remate que aumenta el daño físico infligido un 30% en Forma felina. Dura más por cada punto de combo:\n 1 p. : 14 segundos\n 2 p.: 19 segundos\n 3 p.: 24 segundos\n 4 p.: 29 segundos\n 5 p.: 34 segundos"},
[407989] = {name = "Rugido salvaje", additional_info = "Instante\nRequiere Forma felina\n[q]Remate que aumenta el daño físico infligido un 30%. Dura más por cada punto de combo:\n 1 p. : 14 s\n 2 p.: 19 s\n 3 p.: 24 s\n 4 p.: 29 s\n 5 p.: 34 s"},
[407993] = {name = "Destrozar", additional_info = "{40 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Forma felina\n[q]Destroza al objetivo, lo que le inflige un 270% del daño normal y provoca que reciba un 30% más de daño de los efectos de sangrado y Triturar durante 1 min. Otorga 1 p. de combo. Esta habilidad se beneficia de todos los efectos vinculados con Zarpa y Magullar y los activa."},
[407995] = {name = "Destrozar", additional_info = "{15 p. de ira} {Alcance de ataques cuerpo a cuerpo}\n{Hechizo instantáneo} {6 seg de reutilización}\nRequiere Forma de oso, Forma de oso temible\n[q]Destroza al objetivo, lo que le inflige un 160% del daño normal y provoca que reciba un 30% más de daño de los efectos de sangrado y Triturar durante 1 min. Esta habilidad se beneficia de todos los efectos vinculados con Zarpa y Magullar y los activa.\n\n Golpear a un objetivo con Destrozar (oso) también te otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s."},
[408013] = {name = "Engendrador de Brazanegra de élite", additional_info = nil},
[408014] = {name = "Aparición de brazanegra de élite", additional_info = nil},
[408024] = {name = "Instintos de supervivencia", additional_info = "{Instante} {3 min de reutilización}\n[q]Cuando se activa, te otorga un 30% de tu salud máxima y aumenta un 20% toda la sanación que no sea física que realizas durante 20 s. Después de que el efecto expira, los puntos de salud se pierden. Se puede usar en cualquier forma menos Forma de lechúcico lunar.\n\n Además, regeneras 5 p. de ira cada vez que esquivas mientras estás en Forma de oso o Forma de oso temible, 10 p. de energía mientras estás en Forma felina, o un 1% de tu maná máximo mientras estás en otra forma."},
[408025] = {name = "Instintos de supervivencia", additional_info = nil},
[408030] = {name = "Tallado rúnico: Aprender Grabar Succión de alma", additional_info = nil},
[408035] = {name = "Damien Kane - Cambiar almas por runa", additional_info = nil},
[408120] = {name = "Crecimiento salvaje", additional_info = "{45% del maná base} {Alcance de 40 m}\n{Instante} {6 seg de reutilización}\n[q]Restablece [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a todos los miembros del grupo del jugador objetivo en un radio de 43.5 m del objetivo durante 7 s. La sanación se aplica rápidamente al principio y luego más lentamente, cuando el Crecimiento salvaje alcanza su duración máxima."},
[408124] = {name = "Flor de vida", additional_info = "{14% del maná base} {Alcance de 40 m}\nInstante\n[q]Restablece [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al objetivo durante 7 s. Cuando Flor de vida se completa o disipa, el objetivo sana [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al instante y el druida recupera la mitad del costo del hechizo. El efecto se acumula hasta 3 veces en un mismo objetivo.\n(2s de reutilización)"},
[408245] = {name = "Flor de vida", additional_info = "Alcance de 40 m\nInstante\n[q]Sana al objetivo durante 7 s. Cuando Flor de vida completa su duración o se disipa, sana al objetivo al instante. Este efecto puede acumularse hasta 3 veces sobre el mismo objetivo."},
[408246] = {name = "Flor de vida", additional_info = "Instante\n[q]Obtiene maná cuando Flor de vida expira."},
[408247] = {name = "Nutrir", additional_info = "{26% del maná base} {Alcance de 40 m}\nHechizo de 2 seg\n[q]Restablece de [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] a [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a un objetivo aliado. Sana un 20% extra si tienes los efectos Rejuvenecimiento, Recrecimiento, Flor de vida o Crecimiento salvaje activos sobre el objetivo. Este hechizo se beneficia de todos los efectos vinculados con Toque de sanación o Recrecimiento y los activa."},
[408248] = {name = "Eclipse", additional_info = "[q]Fuego estelar aumenta un 30% la probabilidad de golpe crítico de tus dos próximas Cóleras, y Cólera reduce 1.0 s el tiempo de lanzamiento de tu próximo Fuego estelar. Los dos efectos pueden acumular un máximo de 4 cargas. Además, los dos hechizos obtienen un 70% de probabilidad en todo momento de no perder tiempo de lanzamiento cuando recibes daño."},
[408250] = {name = "Eclipse: solar", additional_info = "Instante\n[q]Aumenta la probabilidad de golpe crítico de Cólera."},
[408255] = {name = "Eclipse: lunar", additional_info = nil},
[408258] = {name = "Estado onírico", additional_info = "[q]Los golpes críticos con hechizos de daño no periódico o cualquier daño de Oleada de estrellas te otorgan un 50% de tu regeneración de maná mientras lanzas hechizos durante 8 s, y aumentan un 20% el daño Arcano y de Naturaleza infligido a objetivos no jugadores durante 12 s."},
[408261] = {name = "Estado onírico", additional_info = "Instante\n[q]Permite que un 50% de tu regeneración de maná continúe mientras lanzas hechizos."},
[408307] = {name = "Furia de la naturaleza", additional_info = "{Instante} {2 min de reutilización}\n[q]Aumenta tu poder de sanación un 90% de tu daño de hechizos de Naturaleza durante 30 s."},
[408309] = {name = "Gracia de Elune", additional_info = "{Instante} {2 min de reutilización}\n[q]Aumenta tu daño con hechizos un 55% de la diferencia entre tu poder de sanación y tu daño con hechizos. Dura 30 s."},
[408339] = {name = "Nova de Fuego", additional_info = "[q]Tu hechizo Tótem Nova de Fuego es reemplazado con Nova de Fuego, que hace que tu tótem de Fuego actual irradie daño en su ubicación."},
[408341] = {name = "Nova de Fuego", additional_info = "95 p. de maná\n{Instante} {10 seg de reutilización}\nHerramientas: Tótem de fuego\n[q]Inflige al instante 53 to 62 p. de daño de Fuego a los enemigos en un radio de 10 m de tu Tótem de fuego activo."},
[408342] = {name = "Nova de Fuego", additional_info = "170 p. de maná\n{Instante} {10 seg de reutilización}\nHerramientas: Tótem de fuego\n[q]Inflige al instante 110 to 124 p. de daño de Fuego a los enemigos en un radio de 10 m de tu Tótem de fuego activo."},
[408343] = {name = "Nova de Fuego", additional_info = "280 p. de maná\n{Instante} {10 seg de reutilización}\nHerramientas: Tótem de fuego\n[q]Inflige al instante 195 to 219 p. de daño de Fuego a los enemigos en un radio de 10 m de tu Tótem de fuego activo."},
[408344] = {name = "Nova de Fuego", additional_info = "395 p. de maná\n{Instante} {10 seg de reutilización}\nHerramientas: Tótem de fuego\n[q]Inflige al instante 295 to 331 p. de daño de Fuego a los enemigos en un radio de 10 m de tu Tótem de fuego activo."},
[408345] = {name = "Nova de Fuego", additional_info = "520 p. de maná\n{Instante} {10 seg de reutilización}\nHerramientas: Tótem de fuego\n[q]Inflige al instante 413 to 459 p. de daño de Fuego a los enemigos en un radio de 10 m de tu Tótem de fuego activo."},
[408423] = {name = "Nova de Fuego", additional_info = "Alcance de 30 m\nInstante\nHerramientas: Tótem de fuego"},
[408424] = {name = "Nova de Fuego", additional_info = "Alcance de 30 m\nInstante\nHerramientas: Tótem de fuego"},
[408426] = {name = "Nova de Fuego", additional_info = "Alcance de 30 m\nInstante\nHerramientas: Tótem de fuego"},
[408427] = {name = "Nova de Fuego", additional_info = "Alcance de 30 m\nInstante\nHerramientas: Tótem de fuego"},
[408428] = {name = "Nova de Fuego", additional_info = "Alcance de 30 m\nInstante\nHerramientas: Tótem de fuego"},
[408438] = {name = "Sobrecarga", additional_info = "[q]Da a tus hechizos Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava una probabilidad de un 60% de lanzar un segundo hechizo similar en el mismo objetivo sin costo adicional que inflige la mitad del daño o sanación y no genera amenaza.\n(Probabilidad de que accione: 60%)"},
[408439] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 7 to 9 p. de daño de Naturaleza."},
[408440] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 14 to 17 p. de daño de Naturaleza."},
[408441] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 23 to 29 p. de daño de Naturaleza."},
[408442] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 43 to 51 p. de daño de Naturaleza."},
[408443] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 65 to 75 p. de daño de Naturaleza."},
[408472] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 89 to 101 p. de daño de Naturaleza."},
[408473] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 117 to 133 p. de daño de Naturaleza."},
[408474] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nHechizo de 3 seg\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 145 to 163 p. de daño de Naturaleza."},
[408475] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 178 to 201 p. de daño de Naturaleza."},
[408477] = {name = "Descarga de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos sobre el objetivo e inflige 213 to 239 p. de daño de Naturaleza."},
[408479] = {name = "Cadena de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos al enemigo que inflige 99 to 114 p. de daño de Naturaleza y salta a otros enemigos cercanos. Cada salto reduce el daño en un 30%. Afecta a 3 objetivos en total."},
[408481] = {name = "Cadena de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos al enemigo que inflige 143 to 162 p. de daño de Naturaleza y salta a otros enemigos cercanos. Cada salto reduce el daño en un 30%. Afecta a 3 objetivos en total."},
[408482] = {name = "Cadena de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos al enemigo que inflige 195 to 219 p. de daño de Naturaleza y salta a otros enemigos cercanos. Cada salto reduce el daño en un 30%. Afecta a 3 objetivos en total."},
[408484] = {name = "Cadena de relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una descarga de relámpagos al enemigo que inflige 252 to 283 p. de daño de Naturaleza y salta a otros enemigos cercanos. Cada salto reduce el daño en un 30%. Afecta a 3 objetivos en total."},
[408490] = {name = "Ráfaga de lava", additional_info = "{10% del maná base} {Alcance de 30 m}\nHechizo de 2 seg 8 seg de reutilización\n[q]Lanzas al objetivo lava fundida que inflige de [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] a [605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] p. de daño de Fuego. Si el objetivo tiene tu Choque de llamas, Ráfaga de lava asestará un golpe crítico."},
[408491] = {name = "Ráfaga de lava", additional_info = "Alcance de 30 m\nInstante\n[q]Lanzas al objetivo lava fundida que inflige de [234 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] a [303 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] p. de daño de Fuego. Si el objetivo tiene tu Choque de llamas, Ráfaga de lava asestará un golpe crítico."},
[408496] = {name = "Especialización en doble empuñadura", additional_info = "[q]Cuando usas dos armas, aumenta un 5% tu probabilidad de golpear con ataques de hechizos y cuerpo a cuerpo, y tu habilidad Golpe de tormenta ahora golpea con ambas armas. También aumenta un 60% el daño que inflige tu arma de mano izquierda."},
[408498] = {name = "Arma vorágine", additional_info = "[q]Cuando infliges daño con un ataque cuerpo a cuerpo, tienes la posibilidad de reducir un 20%. El tiempo de lanzamiento y el costo de maná de tu siguiente hechizo Descarga de relámpagos, Cadena de relámpagos, Ola de sanación inferior o Ráfaga de lava. La probabilidad aumenta un 50% mientras tu arma de la mano derecha esté encantada con Arma Viento Furioso, y un 50% más si usas un arma de dos manos. Se acumula un máximo de 5 veces. Dura 30 s."},
[408501] = {name = "¡Vorágine lista!", additional_info = nil},
[408505] = {name = "Arma vorágine", additional_info = "Instante\n[q]Reduce el tiempo de lanzamiento y el costo de maná de tu siguiente Descarga de relámpagos, Cadena de relámpagos, Ola de sanación inferior o Ráfaga de lava un 20%."},
[408507] = {name = "Latigazo de lava", additional_info = "{1% del maná base} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Cargas con lava el arma de tu mano izquierda e infliges instantáneamente un 100% de daño con arma con tu mano izquierda. El daño aumenta un 150% si tu arma de mano izquierda está encantada con Lengua de Fuego."},
[408510] = {name = "Escudo de agua", additional_info = "Instante\n[q]El taumaturgo queda rodeado por 3 esferas de agua que le dan un 1% del maná máximo cada 5 s. Cada hechizo o ataque cuerpo a cuerpo o a distancia que golpee al taumaturgo restaura un 4% del maná máximo y consume una de las esferas. Solo se activará una esfera cada varios segundos. Dura 10 min. El chamán solo puede activar un escudo elemental a la vez.\n(3.5s de reutilización)"},
[408511] = {name = "Escudo de agua", additional_info = "Instante\n[q]Obtiene maná cuando recibe golpes y Escudo de agua está activo."},
[408514] = {name = "Escudo de tierra", additional_info = "{5% del maná base} {Alcance de 40 m}\nInstante\n[q]Protege al objetivo con un escudo de tierra que reduce el tiempo perdido de lanzamiento o canalización cuando recibe un 30% de daño y provoca que los ataques sanen [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] p. al objetivo escudado. Este efecto solo puede ocurrir una vez cada pocos segundos. 9 cargas. Dura 10 min. Escudo de tierra solo puede utilizarse en un objetivo a la vez.\n(3.5s de reutilización)"},
[408519] = {name = "Escudo de tierra", additional_info = "Rango ilimitado\nInstante\n[q]Sana por Escudo de tierra."},
[408521] = {name = "Mareas Vivas", additional_info = "{18% del maná base} {Alcance de 40 m}\n{Instante} {6 seg de reutilización}\n[q]Restablece de [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] a [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. de salud a un objetivo aliado y [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. más durante 15 s. Tus lanzamientos de Sanación en cadena sobre ese objetivo principal en menos de 15 s aumentarán el efecto de Sanación en cadena un 25%. Este hechizo también activa Despertar ancestral."},
[408524] = {name = "Maestría con escudos", additional_info = "[q]Cada vez que bloqueas, regeneras una cantidad de maná equivalente al 8% de tu maná máximo y obtienes una cantidad de armadura equivalente al 30% del valor de armadura de tu escudo, que se acumula hasta 5 veces. También aumenta un 10% la probabilidad de bloqueo y un 15% el valor de bloqueo.\n\n Además, cada vez que usas una habilidad de Choque, obtienes 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s."},
[408525] = {name = "Maestría con escudos", additional_info = "Instante\n[q]Aumenta la armadura un 30% del valor de armadura de tu escudo durante 15 s, se acumula hasta 7 veces."},
[408531] = {name = "Tradición de tierra", additional_info = "[q]Cuando Arma Muerdepiedras está activa en tu arma de mano derecha y tienes un escudo equipado, generas un 65% más de amenaza, obtienes un 25% más de salud, recibes un 10% menos de daño, obtienes un 6% menos de probabilidad de recibir golpes críticos de ataques cuerpo a cuerpo y Choque de tierra provoca a los objetivos para que te ataquen. Además, tiene un tiempo de reutilización aparte de los demás hechizos de Choque, pero su alcance se reduce a cuerpo a cuerpo. Sin embargo, el alcance de tu Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava se reduce 20 m."},
[408680] = {name = "Tradición de tierra", additional_info = "Instante\n[q]Cuando Arma Muerdepiedras está activa en tu arma de mano derecha, generas un 65% más de amenaza, obtienes un 25% más de salud, recibes un 10% menos de daño, obtienes un 6% menos de probabilidad de recibir golpes críticos de ataques cuerpo a cuerpo y Choque de tierra provoca a los objetivos para que te ataquen y tiene un tiempo de reutilización aparte de los demás hechizos de Choque."},
[408681] = {name = "Choque de tierra", additional_info = "{30 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Impacta al objetivo de forma instantánea con fuerza de conmoción, que inflige 19 to 22 p. de daño de Naturaleza. También interrumpe el lanzamiento de hechizos e impide que se lancen hechizos de esa escuela durante 2 s. Genera una gran amenaza y provoca al objetivo."},
[408683] = {name = "Choque de tierra", additional_info = "{50 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Impacta al objetivo de forma instantánea con fuerza de conmoción, que inflige 35 to 38 p. de daño de Naturaleza. También interrumpe el lanzamiento de hechizos e impide que se lancen hechizos de esa escuela durante 2 s. Genera una gran amenaza y provoca al objetivo."},
[408685] = {name = "Choque de tierra", additional_info = "{85 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Impacta al objetivo de forma instantánea con fuerza de conmoción, que inflige 65 to 69 p. de daño de Naturaleza. También interrumpe el lanzamiento de hechizos e impide que se lancen hechizos de esa escuela durante 2 s. Genera una gran amenaza y provoca al objetivo."},
[408687] = {name = "Choque de tierra", additional_info = "{145 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Impacta al objetivo de forma instantánea con fuerza de conmoción, que inflige 126 to 134 p. de daño de Naturaleza. También interrumpe el lanzamiento de hechizos e impide que se lancen hechizos de esa escuela durante 2 s. Genera una gran amenaza y provoca al objetivo."},
[408688] = {name = "Choque de tierra", additional_info = "{240 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Impacta al objetivo de forma instantánea con fuerza de conmoción, que inflige 235 to 249 p. de daño de Naturaleza. También interrumpe el lanzamiento de hechizos e impide que se lancen hechizos de esa escuela durante 2 s. Genera una gran amenaza y provoca al objetivo."},
[408689] = {name = "Choque de tierra", additional_info = "{345 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Impacta al objetivo de forma instantánea con fuerza de conmoción, que inflige 372 to 394 p. de daño de Naturaleza. También interrumpe el lanzamiento de hechizos e impide que se lancen hechizos de esa escuela durante 2 s. Genera una gran amenaza y provoca al objetivo."},
[408690] = {name = "Choque de tierra", additional_info = "{450 p. de maná} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Impacta al objetivo de forma instantánea con fuerza de conmoción, que inflige 517 to 545 p. de daño de Naturaleza. También interrumpe el lanzamiento de hechizos e impide que se lancen hechizos de esa escuela durante 2 s. Genera una gran amenaza y provoca al objetivo."},
[408693] = {name = "Choque de tierra", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Provoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."},
[408696] = {name = "Espíritu del alfa", additional_info = "{8% del maná base} {Alcance de 30 m}\nInstante\n[q]Infunde al objetivo con el espíritu de un lobo alfa y aumenta toda la amenaza generada por el objetivo un 45% durante 30 min. El límite es de 1 objetivo. Si se lanza sobre un objetivo que no sea él mismo, el Chamán también obtiene Beta leal, lo que aumenta un 5% el daño físico infligido y reduce toda la amenaza generada un 30% durante 30 min. Un objetivo no puede tener Espíritu del alfa y Beta leal al mismo tiempo."},
[408699] = {name = "Acecho", additional_info = "Alcance de 100 m\nInstante\n[q]Tus golpes con Emboscada y Puñalada desequilibran a tu objetivo, lo que aumenta el tiempo entre sus ataques cuerpo a cuerpo un 10% y reduce su velocidad de movimiento un 50% durante 8 s."},
[408700] = {name = "Acecho", additional_info = "[q]Tus golpes con Emboscada y Puñalada desequilibran a tu objetivo, lo que aumenta el tiempo entre sus ataques cuerpo a cuerpo un 10% y reduce su velocidad de movimiento un 50% durante 8 s."},
