[409064] = {name = "Adivinación de runas", additional_info = "Alcance de 15 m\nCanalizado (Hechizo de 0 seg)\n[q]Ofusca la mente del objetivo con energía de las Sombras, causando 0.0 p. de daño de las Sombras durante hasta cancelación y ralentizando su movimiento en un 0%."},
[409073] = {name = "Aniquilación", additional_info = "[q]Tus ataques cuerpo a cuerpo generan 0 p. de ira."},
