[409076] = {name = "Dolor y sufrimiento", additional_info = nil},
[409163] = {name = "Grabar cinturón - Ira concentrada", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Ira concentrada:\n\n\nReduce el costo de ira de tus habilidades ofensivas en 3."},
[409214] = {name = "Tanque contra élite", additional_info = nil},
[409215] = {name = "Tanque contra élite", additional_info = nil},
[409239] = {name = "Abanico de cuchillos", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Lanza instantáneamente las dos armas a todos los objetivos que se encuentren en un radio de 8 m, lo que inflige un 50% de daño con arma."},
[409240] = {name = "Abanico de cuchillos", additional_info = "50 p. de energía\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Lanza instantáneamente las dos armas a todos los objetivos que se encuentren en un radio de 8 m, lo que inflige un 75% de daño con arma con dagas y un 50% de daño con arma con cualquier otra arma."},
[409317] = {name = "Fuerza del alma", additional_info = nil},
[409324] = {name = "Guía ancestral", additional_info = "{Instante} {1 min de reutilización}\n[q]Durante los próximos 10 s, un 25% de tu daño se convierte en sanación para un máximo de 3 miembros de grupo cercanos, y un 100% de tu sanación se convierte en daño contra tu objetivo de Choque de llamas más reciente."},
[409333] = {name = "Guía ancestral", additional_info = "Alcance de 40 m\nInstante\n[q]Durante los próximos 10 s, un 25% de tu daño se convierte en sanación para un máximo de 3 miembros de grupo cercanos, y un 100% de tu sanación se convierte en daño contra tu objetivo de Choque de llamas más reciente."},
[409337] = {name = "Guía ancestral", additional_info = "Alcance de 40 m\nInstante\n[q]Durante los próximos 10 s, un 25% de tu daño se convierte en sanación para un máximo de 3 miembros de grupo cercanos, y un 100% de tu sanación se convierte en daño contra tu objetivo de Choque de llamas más reciente."},
[409368] = {name = "Maestría de bestias", additional_info = "[q]El daño y la salud de tu mascota aumentan un 15%, y su regeneración de enfoque aumenta un 50%. Además, el Bramido de tu mascota también provoca al objetivo para que la ataque durante 3 s."},
[409372] = {name = "Bramido", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Provoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."},
[409379] = {name = "Matar", additional_info = "{1.5% del maná base} {Alcance de 45 m}\n{Instante} {1 min de reutilización}\n[q]Da la orden de matar y aumenta un 60% el daño que inflige tu mascota con Zarpa y Mordedura durante 30 s. Cada Zarpa o Mordedura que realiza la mascota reduce la bonificación de daño un 20%."},
[409396] = {name = "Matar", additional_info = "Alcance de 45 m\nInstante\n[q]Da la orden de matar, aumenta un 60% el daño que inflige tu mascota con Zarpa y Mordedura durante 30 s. Cada Zarpa o Mordedura que inflige la mascota reduce la bonificación de daño un 20%."},
[409418] = {name = "Matar", additional_info = "Rango ilimitado\n{Instante} {1 min de reutilización}\n[q]Da la orden de matar, aumenta un 60% el daño de tu mascota con Zarpa y Mordedura durante 30 s. Cada Zarpa o Mordedura que inflige la mascota reduce la bonificación de daño un 20%."},
[409423] = {name = "Cadáver reventado", additional_info = nil},
[409428] = {name = "Maestro Tirador", additional_info = "[q]Aumenta un 5% tu probabilidad de golpe crítico y reduce un 25% el costo de todas tus habilidades de Disparo."},
[409433] = {name = "Disparo de quimera", additional_info = "{6% del maná base} {Alcance de 8 - 35 m}\n6 seg de reutilización\nRequiere Arma a distancia\n[q]Infliges un 135% de daño con arma, lo que renueva la Picadura actual de tu objetivo y activa un efecto:\n\n Picadura de serpiente: Inflige instantáneamente un 48% del daño infligido por tu Picadura de serpiente.\n\n Picadura de víbora: Restaura instantáneamente una cantidad de maná igual al 60% del maná drenado por tu Picadura de víbora.\n\n Picadura de escórpido: Intenta Desarmar al objetivo durante 10 s. Este efecto solo puede ocurrir una vez por minuto."},
[409493] = {name = "Disparo de quimera: serpiente", additional_info = "Alcance de 100 m\n[q]Infliges un 135% de daño con arma, lo que renueva la Picadura actual de tu objetivo y activa un efecto:\n\n Picadura de serpiente: inflige instantáneamente un 48% del daño infligido por tu Picadura de serpiente.\n\n Picadura de víbora: restaura instantáneamente una cantidad de maná igual al 60% del maná drenado por tu Picadura de víbora.\n\n Picadura de escórpido: Intenta Desarmar al objetivo durante 10 s. Este efecto solo puede ocurrir una vez por minuto."},
[409494] = {name = "Disparo de quimera: víbora", additional_info = "Alcance de 100 m\n[q]Infliges un 135% de daño con arma, lo que renueva la Picadura actual de tu objetivo y activa un efecto:\n\n Picadura de serpiente: inflige instantáneamente un 48% del daño infligido por tu Picadura de serpiente.\n\n Picadura de víbora: restaura instantáneamente una cantidad de maná igual al 60% del maná drenado por tu Picadura de víbora.\n\n Picadura de escórpido: Intenta Desarmar al objetivo durante 10 s. Este efecto solo puede ocurrir una vez por minuto."},
[409495] = {name = "Disparo de quimera: escórpido", additional_info = "Alcance de 100 m\n[q]Infliges un 135% de daño con arma, lo que renueva la Picadura actual de tu objetivo y activa un efecto:\n\n Picadura de serpiente: inflige instantáneamente un 48% del daño infligido por tu Picadura de serpiente.\n\n Picadura de víbora: restaura instantáneamente una cantidad de maná igual al 60% del maná drenado por tu Picadura de víbora.\n\n Picadura de escórpido: Intenta Desarmar al objetivo durante 10 s. Este efecto solo puede ocurrir una vez por minuto."},
[409504] = {name = "Exponer debilidad", additional_info = "[q]Tus golpes críticos cuerpo a cuerpo y a distancia aumentan tu poder de ataque un monto equivalente al 40% de tu agilidad actual durante 7 s."},
[409507] = {name = "Exponer debilidad", additional_info = "Instante\n[q]Tus golpes críticos a distancia aumentan tu poder de ataque un monto equivalente al 40% de tu agilidad durante 7 s."},
[409510] = {name = "Trampa congelante", additional_info = "{50 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de Escarcha en una ubicación cercana que congela al primer enemigo que se acerca. El objetivo no podrá realizar ningún tipo de acción durante un máximo de 10 s. Cualquier daño infligido romperá el hielo. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409512] = {name = "Trampa congelante", additional_info = "{75 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de Escarcha en una ubicación cercana que congela al primer enemigo que se acerca. El objetivo no podrá realizar ningún tipo de acción durante un máximo de 15 s. Cualquier daño infligido romperá el hielo. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409519] = {name = "Trampa congelante", additional_info = "{100 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de Escarcha en una ubicación cercana que congela al primer enemigo que se acerca. El objetivo no podrá realizar ningún tipo de acción durante un máximo de 20 s. Cualquier daño infligido romperá el hielo. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409520] = {name = "Trampa de Escarcha", additional_info = "60 p. de maná\n{Instante} {15 seg de reutilización}\n[q]Coloca una trampa de escarcha en una ubicación cercana que crea una mancha de hielo a su alrededor durante 30 s cuando el primer enemigo se acerca. Todos los enemigos en un radio de 10 m se ralentizarán un 60% mientras estén en el área de efecto. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409521] = {name = "Trampa de inmolación", additional_info = "{50 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que quemará al primer enemigo que se acerque y le infligirá 105 p. de daño de Fuego durante 15 s. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409524] = {name = "Trampa de inmolación", additional_info = "{90 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que quemará al primer enemigo que se acerque y le infligirá 215 p. de daño de Fuego durante 15 s. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409526] = {name = "Trampa de inmolación", additional_info = "{135 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que quemará al primer enemigo que se acerque y le infligirá 340 p. de daño de Fuego durante 15 s. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409528] = {name = "Trampa de inmolación", additional_info = "{190 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que quemará al primer enemigo que se acerque y le infligirá 510 p. de daño de Fuego durante 15 s. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409530] = {name = "Trampa de inmolación", additional_info = "{245 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que quemará al primer enemigo que se acerque y le infligirá 690 p. de daño de Fuego durante 15 s. La trampa dura 1 min. Solo puede haber una trampa activa a la vez."},
[409532] = {name = "Trampa explosiva", additional_info = "{275 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que explota cuando un enemigo se acerca, lo que inflige 104 to 135 p. de daño de Fuego y 150 p. de daño de Fuego extra durante 20 s a todos los objetivos en un radio de 10 m. La trampa existirá durante 1 min. Solo se puede activar una trampa a la vez."},
[409534] = {name = "Trampa explosiva", additional_info = "{395 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que explota cuando un enemigo se acerca, lo que inflige 145 to 193 p. de daño de Fuego y 240 p. de daño de Fuego extra durante 20 s a todos los objetivos en un radio de 10 m. La trampa existirá durante 1 min. Solo se puede activar una trampa a la vez."},
[409535] = {name = "Trampa explosiva", additional_info = "{520 p. de maná} {Alcance de 35 m}\n15 seg de reutilización\n[q]Coloca una trampa de fuego en una ubicación cercana que explota cuando un enemigo se acerca, lo que inflige 208 to 265 p. de daño de Fuego y 330 p. de daño de Fuego extra durante 20 s a todos los objetivos en un radio de 10 m. La trampa existirá durante 1 min. Solo se puede activar una trampa a la vez."},
[409541] = {name = "Lanzador de trampas", additional_info = "[q]Ahora puedes colocar tus Trampas congelante, de inmolación y explosiva en cualquier ubicación en un radio de 35 m. Además, tus trampas de Fuego y Escarcha ahora tienen tiempos de reutilización compartidos para cada escuela."},
[409552] = {name = "Disparo explosivo", additional_info = "{3.5% del maná base} {Alcance de 8 - 35 m}\n6 seg de reutilización\nRequiere Arma a distancia\n[q]Disparas una carga explosiva al objetivo enemigo que inflige [Ranged attack power * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Ranged attack power * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño de Fuego a todos los enemigos en un radio de 8 m. La carga volverá a infligir daño por segundo durante 2 s más."},
[409554] = {name = "Disparo explosivo", additional_info = "Rango ilimitado\n[q]Lanzas una carga explosiva al objetivo enemigo, que inflige (Ranged attack power * 0.14 + 10)-(Ranged attack power * 0.14 + 10) p. de daño de Fuego. La carga golpeará al objetivo cada segundo durante hasta cancelación más. Comparte el tiempo de reutilización con Disparo arcano."},
[409580] = {name = "Corazón del león", additional_info = "8% del maná base\nInstante\n[q]El cazador invoca el corazón de un león, lo que aumenta un 10% las estadísticas totales y 200 p. el poder de ataque de todos los aliados cercanos y aumenta las estadísticas totales del Cazador un 10% más."},
[409583] = {name = "Corazón del león", additional_info = "Alcance de 100 m\nInstante\n[q]El cazador invoca el corazón de un león, lo que aumenta un 10% las estadísticas totales de todos los aliados cercanos y aumenta las estadísticas totales del Cazador un 10% más."},
[409593] = {name = "Disparo mortal", additional_info = "{3% del maná base} {Alcance de 35 m}\n12 seg de reutilización\nRequiere Arma a distancia\n[q]Tratas de rematar a un objetivo herido con un disparo a larga distancia que inflige un 100% de daño con arma y luego [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos."},
[409687] = {name = "Especialización en doble empuñadura", additional_info = "[q]Aumenta el daño infligido por tu arma de mano izquierda un 60%, y hace que tu Golpe de raptor golpee con ambas armas cuando portas dos armas."},
[409691] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 2 to 3 p. el daño cuerpo a cuerpo."},
[409693] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 5 p. el daño cuerpo a cuerpo."},
[409748] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 10 to 11 p. el daño cuerpo a cuerpo."},
[409750] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 17 p. el daño cuerpo a cuerpo."},
[409751] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 25 p. el daño cuerpo a cuerpo."},
[409752] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 40 p. el daño cuerpo a cuerpo."},
[409754] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 55 p. el daño cuerpo a cuerpo."},
[409755] = {name = "Golpe de raptor", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque contundente que aumenta 70 p. el daño cuerpo a cuerpo."},
[409805] = {name = "Golpes feroces", additional_info = "[q]Obtienes la habilidad Golpes feroces:\n\n\nCuando estás en Forma felina, de oso o de oso temible, los miembros del grupo o banda en un radio de 100 m obtienen mayor ferocidad de combate. Cada golpe cuerpo a cuerpo tiene un 20% de probabilidad de otorgar un ataque extra al atacante con un 20% de poder de ataque extra. No tiene efecto si el objetivo ya se ha beneficiado de Tótem Viento Furioso."},
[409809] = {name = "Instintos de supervivencia", additional_info = "[q]Obtienes la habilidad Instintos de supervivencia:\n\n\nCuando se activa, te otorga un 30% de tu salud máxima y aumenta un 20% toda la sanación que no sea física que realizas durante 20 s. Después de que el efecto expira, los puntos de salud se pierden. Se puede usar en cualquier forma menos Forma de lechúcico lunar.\n\n Además, regeneras 5 p. de ira cada vez que esquivas mientras estás en Forma de oso o Forma de oso temible, 10 p. de energía mientras estás en Forma felina, o un 1% de tu maná máximo mientras estás en otra forma."},
[409810] = {name = "Crecimiento salvaje", additional_info = "[q]Obtienes la habilidad Crecimiento salvaje:\n\n\nRestablece [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a todos los miembros del grupo del jugador objetivo en un radio de 43.5 m del objetivo durante 7 s. La sanación se aplica rápidamente al principio y luego más lentamente, cuando el Crecimiento salvaje alcanza su duración máxima."},
[409813] = {name = "Eclipse", additional_info = "[q]Obtienes la habilidad Eclipse:\n\n\nFuego estelar aumenta un 30% la probabilidad de golpe crítico de tus dos próximas Cóleras, y Cólera reduce 1.0 s el tiempo de lanzamiento de tu próximo Fuego estelar. Los dos efectos pueden acumular un máximo de 4 cargas. Además, los dos hechizos obtienen un 70% de probabilidad en todo momento de no perder tiempo de lanzamiento cuando recibes daño."},
[409819] = {name = "Rugido salvaje", additional_info = "[q]Obtienes la habilidad Rugido salvaje:\n\n\nRemate que aumenta el daño físico infligido un 30% en Forma felina. Dura más por cada punto de combo:\n 1 p. : 14 segundos\n 2 p.: 19 segundos\n 3 p.: 24 segundos\n 4 p.: 29 segundos\n 5 p.: 34 segundos"},
[409824] = {name = "Flor de vida", additional_info = "[q]Reduce 0.5 s el tiempo de reutilización global de tu Rejuvenecimiento y Flor de vida, y obtienes la habilidad Flor de vida:\n\n\nRestablece [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al objetivo durante 7 s. Cuando Flor de vida se completa o disipa, el objetivo sana [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al instante y el druida recupera la mitad del costo del hechizo. El efecto se acumula hasta 3 veces en un mismo objetivo."},
[409826] = {name = "Furia de la naturaleza", additional_info = "[q]Obtienes la habilidad Furia de la naturaleza:\n\n\nAumenta tu poder de sanación un 90% de tu daño de hechizos de Naturaleza durante 30 s."},
[409828] = {name = "Destrozar", additional_info = "[q]Obtienes la habilidad Destrozar (oso) y se remplaza tu habilidad Zarpa con Destrozar (felino). Esta habilidad se beneficia de todos los efectos vinculados con Zarpa y Magullar y los activa.\n\n\nDestroza al objetivo, lo que le inflige un 160% del daño normal y provoca que reciba un 30% más de daño de los efectos de sangrado y Triturar durante 1 min. Esta habilidad se beneficia de todos los efectos vinculados con Zarpa y Magullar y los activa.\n\n Golpear a un objetivo con Destrozar (oso) también te otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s.\n\n\nDestroza al objetivo, lo que le inflige un 270% del daño normal y provoca que reciba un 30% más de daño de los efectos de sangrado y Triturar durante 1 min. Otorga 1 p. de combo. Esta habilidad se beneficia de todos los efectos vinculados con Zarpa y Magullar y los activa."},
[409830] = {name = "Nutrir", additional_info = "[q]Obtienes la habilidad Nutrir:\n\n\nRestablece de [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] a [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a un objetivo aliado. Sana un 20% extra si tienes los efectos Rejuvenecimiento, Recrecimiento, Flor de vida o Crecimiento salvaje activos sobre el objetivo. Este hechizo se beneficia de todos los efectos vinculados con Toque de sanación o Recrecimiento y los activa."},
[409831] = {name = "Estado onírico", additional_info = "[q]Obtienes la habilidad Estado onírico:\n\n\nLos golpes críticos con hechizos de daño no periódico o cualquier daño de Oleada de estrellas te otorgan un 50% de tu regeneración de maná mientras lanzas hechizos durante 8 s, y aumentan un 20% el daño Arcano y de Naturaleza infligido a objetivos no jugadores durante 12 s."},
[409832] = {name = "Furia de Tempestira", additional_info = "[q]Obtienes la habilidad Furia de Tempestira:\n\n\nReduce un 100% el costo de maná de Cólera y cada vez que infliges daño con Cólera tienes una probabilidad de un 12% de que tu siguiente lanzamiento de Toque de sanación en 15 s sea instantáneo y pueda lanzarse en cualquier cambio de forma. Permite lanzar Cólera en forma de Árbol de la vida."},
[409856] = {name = "Ritual de espíritu", additional_info = "Alcance de 30 m\nCanalizado (Hechizo de 10 min)\n[q]Comienza un ritual para liberar el espíritu de un aventurero caído."},
[409858] = {name = "Dummy Trigger", additional_info = nil},
[409906] = {name = "Señal de la Luz", additional_info = "[q]Obtienes la habilidad Señal de luz:\n\n\nEl objetivo se convierte en una Señal de la Luz para todos los miembros de tu grupo o banda que se encuentren en un radio de 40 m. Cualquier sanación que lances sobre miembros de tu grupo o banda sanará también a la señal un 75% de la cantidad sanada. Solo un objetivo puede ser la Señal de la Luz cada vez. Dura 1 h."},
[409911] = {name = "Mano de expiación", additional_info = "[q]Obtienes la habilidad Mano de expiación:\n\n\nProvocas al objetivo para que te ataque, pero no tiene efecto si el objetivo ya te está atacando.\n\n Cuando conoces esta habilidad, la bonificación de amenaza de Furia recta aumenta a 80% y cuando te sanan otros, Furia recta hace que obtengas una cantidad de maná equivalente a un 25% de la cantidad sanada. Además, mientras Furia recta está activa, el daño que deje tu salud por debajo del 35% se reduce un 20%. Furia recta permanecerá activa hasta que se cancele."},
[409914] = {name = "Golpe de cruzado", additional_info = "[q]Obtienes la habilidad Golpe de cruzado:\n\n\nUn golpe instantáneo que inflige un 75% de daño con arma como daño Sagrado y regenera un 5% de tu maná máximo. La duración de todos los efectos de Sentencia en el objetivo se restablece a 30 s."},
[409918] = {name = "Inspiración (Sentencia)", additional_info = nil},
[409920] = {name = "Reliquia de aprendizaje (Sentencia)", additional_info = nil},
[409922] = {name = "Martillo del honrado", additional_info = "[q]Obtienes la habilidad Martillo del honrado:\n\n\nDa un martillazo al objetivo actual y a un máximo de 3 objetivos cercanos más, inflige 4 veces el daño por segundo de tu mano derecha como daño sagrado."},
[409924] = {name = "Tormenta divina", additional_info = "[q]Obtienes la habilidad Tormenta divina:\n\n\nUn ataque instantáneo con arma que inflige un 110% de daño con arma a un máximo de 4 enemigos que se encuentren en un radio de 8 m. La Tormenta divina sana a hasta 3 miembros del grupo o banda con un total del 25% del daño infligido."},
[409925] = {name = "Luz divina", additional_info = "[q]Obtienes la habilidad Luz divina:\n\n\nRestaura de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100] p. de salud a un objetivo aliado. Un 50% de la sanación excedente del objetivo se convierte en un escudo de absorción que dura 15 s. Lanzar Luz divina múltiples veces no acumula este escudo.\n\n Luz divina se beneficia de todos los talentos y efectos que se activan por Luz Sagrada o que la modifican."},
[409930] = {name = "Tratado sobre sentencia", additional_info = nil},
[409932] = {name = "Maestría en auras", additional_info = "[q]Obtienes la habilidad Maestría en auras:\n\n\nProvoca que tu Aura de concentración haga inmunes ante los efectos de silencio e interrupción a todos los objetivos afectados y mejore el efecto del resto de las auras un 100%. Dura 6 s."},
[409933] = {name = "Escudo de vengador", additional_info = "[q]Obtienes la habilidad Escudo de vengador:\n\n\nLanza un escudo Sagrado al enemigo que inflige de [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] a [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] p. de daño Sagrado, lo deja atontado y salta a los enemigos cercanos. Afecta a un total de 3 objetivos. Dura 5 s."},
[409934] = {name = "Cólera vengativa", additional_info = "[q]Obtienes la habilidad Cólera vengativa:\n\n\nAumenta todo el daño y la sanación infligidos un 20% durante 20 s. Causa Abstinencia y no se puede usar mientras Abstinencia está activa."},
[409935] = {name = "Mano de sacrificio", additional_info = "[q]Obtienes la habilidad Mano de sacrificio:\n\n\nHace que el miembro del grupo o banda transfiera un 30% del daño recibido al taumaturgo. Dura 12 s o hasta que el taumaturgo haya transferido un 100% de su salud máxima."},
[409936] = {name = "Inspiración ejemplar", additional_info = "[q]Obtienes la habilidad Inspiración ejemplar:\n\n\nTu presencia inspiradora periódicamente disipa efectos de miedo y sueño en miembros del grupo cercanos."},
[409938] = {name = "Nova de Fuego", additional_info = "[q]Obtienes la habilidad Nova de Fuego, que reemplaza tu Tótem Nova de Fuego:\n\n\nTu hechizo Tótem Nova de Fuego es reemplazado con Nova de Fuego, que hace que tu tótem de Fuego actual irradie daño en su ubicación."},
[409940] = {name = "Especialización en doble empuñadura", additional_info = "[q]Obtienes la habilidad Especialización en doble empuñadura:\n\n\nCuando usas dos armas, aumenta un 5% tu probabilidad de golpear con ataques de hechizos y cuerpo a cuerpo, y tu habilidad Golpe de tormenta ahora golpea con ambas armas. También aumenta un 60% el daño que inflige tu arma de mano izquierda."},
[409941] = {name = "Escudo de agua", additional_info = "[q]Obtienes la habilidad Escudo de agua:\n\n\nEl taumaturgo queda rodeado por 3 esferas de agua que le dan un 1% del maná máximo cada 5 s. Cada hechizo o ataque cuerpo a cuerpo o a distancia que golpee al taumaturgo restaura un 4% del maná máximo y consume una de las esferas. Solo se activará una esfera cada varios segundos. Dura 10 min. El chamán solo puede activar un escudo elemental a la vez."},
[409943] = {name = "Maestría con escudos", additional_info = "[q]Obtienes la habilidad Maestría con escudos:\n\n\nCada vez que bloqueas, regeneras una cantidad de maná equivalente al 8% de tu maná máximo y obtienes una cantidad de armadura equivalente al 30% del valor de armadura de tu escudo, que se acumula hasta 5 veces. También aumenta un 10% la probabilidad de bloqueo y un 15% el valor de bloqueo.\n\n Además, cada vez que usas una habilidad de Choque, obtienes 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s."},
[409944] = {name = "Guía ancestral", additional_info = "[q]Obtienes la habilidad Guía ancestral:\n\n\nDurante los próximos 10 s, un 25% de tu daño se convierte en sanación para un máximo de 3 miembros de grupo cercanos, y un 100% de tu sanación se convierte en daño contra tu objetivo de Choque de llamas más reciente."},
[409945] = {name = "Sobrecarga", additional_info = "[q]Obtienes la habilidad Sobrecarga:\n\n\nDa a tus hechizos Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava una probabilidad de un 60% de lanzar un segundo hechizo similar en el mismo objetivo sin costo adicional que inflige la mitad del daño o sanación y no genera amenaza."},
[409946] = {name = "Arma vorágine", additional_info = "[q]Obtienes la habilidad Arma vorágine:\n\n\nCuando infliges daño con un ataque cuerpo a cuerpo, tienes la posibilidad de reducir un 20%. El tiempo de lanzamiento y el costo de maná de tu siguiente hechizo Descarga de relámpagos, Cadena de relámpagos, Ola de sanación inferior o Ráfaga de lava. La probabilidad aumenta un 50% mientras tu arma de la mano derecha esté encantada con Arma Viento Furioso, y un 50% más si usas un arma de dos manos. Se acumula un máximo de 5 veces. Dura 30 s."},
[409947] = {name = "Escudo de tierra", additional_info = "[q]Obtienes la habilidad Escudo de tierra:\n\n\nProtege al objetivo con un escudo de tierra que reduce el tiempo perdido de lanzamiento o canalización cuando recibe un 30% de daño y provoca que los ataques sanen [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] p. al objetivo escudado. Este efecto solo puede ocurrir una vez cada pocos segundos. 9 cargas. Dura 10 min. Escudo de tierra solo puede utilizarse en un objetivo a la vez."},
[409951] = {name = "Espíritu del alfa", additional_info = "[q]Obtienes la habilidad Espíritu del alfa:\n\n\nInfunde al objetivo con el espíritu de un lobo alfa y aumenta toda la amenaza generada por el objetivo un 45% durante 30 min. El límite es de 1 objetivo. Si se lanza sobre un objetivo que no sea él mismo, el Chamán también obtiene Beta leal, lo que aumenta un 5% el daño físico infligido y reduce toda la amenaza generada un 30% durante 30 min. Un objetivo no puede tener Espíritu del alfa y Beta leal al mismo tiempo."},
[409952] = {name = "Ráfaga de lava", additional_info = "[q]Obtienes la habilidad Ráfaga de lava:\n\n\nLanzas al objetivo lava fundida que inflige de [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] a [605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] p. de daño de Fuego. Si el objetivo tiene tu Choque de llamas, Ráfaga de lava asestará un golpe crítico."},
[409953] = {name = "Latigazo de lava", additional_info = "[q]Obtienes la habilidad Latigazo de lava:\n\n\nCargas con lava el arma de tu mano izquierda e infliges instantáneamente un 100% de daño con arma con tu mano izquierda. El daño aumenta un 150% si tu arma de mano izquierda está encantada con Lengua de Fuego."},
[409954] = {name = "Mareas Vivas", additional_info = "[q]Obtienes la habilidad Mareas Vivas:\n\n\nRestablece de [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] a [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. de salud a un objetivo aliado y [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. más durante 15 s. Tus lanzamientos de Sanación en cadena sobre ese objetivo principal en menos de 15 s aumentarán el efecto de Sanación en cadena un 25%. Este hechizo también activa Despertar ancestral."},
[409955] = {name = "Tradición de tierra", additional_info = "[q]Obtienes la habilidad Tradición de tierra:\n\n\nCuando Arma Muerdepiedras está activa en tu arma de mano derecha y tienes un escudo equipado, generas un 65% más de amenaza, obtienes un 25% más de salud, recibes un 10% menos de daño, obtienes un 6% menos de probabilidad de recibir golpes críticos de ataques cuerpo a cuerpo y Choque de tierra provoca a los objetivos para que te ataquen. Además, tiene un tiempo de reutilización aparte de los demás hechizos de Choque, pero su alcance se reduce a cuerpo a cuerpo. Sin embargo, el alcance de tu Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava se reduce 20 m."},
[409957] = {name = "Disparo firme", additional_info = "[q]Obtienes la habilidad Disparo firme:\n\n\nUn disparo firme que inflige un 100% de daño con arma a distancia."},
[409958] = {name = "Maestro Tirador", additional_info = "[q]Obtienes la habilidad Maestro tirador:\n\n\nAumenta un 5% tu probabilidad de golpe crítico y reduce un 25% el costo de todas tus habilidades de Disparo."},
[409959] = {name = "Exponer debilidad", additional_info = "[q]Obtienes la habilidad Exponer debilidad:\n\n\nTus golpes críticos cuerpo a cuerpo y a distancia aumentan tu poder de ataque un monto equivalente al 40% de tu agilidad actual durante 7 s."},
[409960] = {name = "Matacobras", additional_info = "[q]Obtienes la habilidad Matacobras:\n\n\nMordedura de mangosta ahora tiene un 10% de probabilidad de activarse en cada uno de tus ataques cuerpo a cuerpo, y un 100% de probabilidad cuando un enemigo esquiva. Esta probabilidad se acumula, y aumenta un 10% por cada ataque subsiguiente si no se restablece. Mordedura de mangosta también inflige daño adicional equivalente a un 45% de tu poder de ataque."},
[409961] = {name = "Especialización en doble empuñadura", additional_info = "[q]Obtienes la habilidad Especialista en doble empuñadura:\n\n\nAumenta el daño infligido por tu arma de mano izquierda un 60%, y hace que tu Golpe de raptor golpee con ambas armas cuando portas dos armas."},
[409962] = {name = "Maestría de bestias", additional_info = "[q]Obtienes la habilidad Maestría de bestias:\n\n\nEl daño y la salud de tu mascota aumentan un 15%, y su regeneración de enfoque aumenta un 50%. Además, el Bramido de tu mascota también provoca al objetivo para que la ataque durante 3 s."},
[409963] = {name = "Invocar espíritu", additional_info = nil},
[409968] = {name = "Lanzador de trampas", additional_info = "[q]Obtienes la habilidad Lanzador de trampas:\n\n\nAhora puedes colocar tus Trampas congelante, de inmolación y explosiva en cualquier ubicación en un radio de 35 m. Además, tus trampas de Fuego y Escarcha ahora tienen tiempos de reutilización compartidos para cada escuela."},
[409974] = {name = "Disparo mortal", additional_info = "[q]Obtienes la habilidad Disparo mortal:\n\n\nTratas de rematar a un objetivo herido con un disparo a larga distancia que inflige un 100% de daño con arma y luego [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos."},
[409976] = {name = "Disparo de quimera", additional_info = "[q]Obtienes la habilidad Disparo de quimera:\n\n\nInfliges un 135% de daño con arma, lo que renueva la Picadura actual de tu objetivo y activa un efecto:\n\n Picadura de serpiente: Inflige instantáneamente un 48% del daño infligido por tu Picadura de serpiente.\n\n Picadura de víbora: Restaura instantáneamente una cantidad de maná igual al 60% del maná drenado por tu Picadura de víbora.\n\n Picadura de escórpido: Intenta Desarmar al objetivo durante 10 s. Este efecto solo puede ocurrir una vez por minuto."},
[409978] = {name = "Disparo explosivo", additional_info = "[q]Obtienes la habilidad Disparo explosivo:\n\n\nDisparas una carga explosiva al objetivo enemigo que inflige [Ranged attack power * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Ranged attack power * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño de Fuego a todos los enemigos en un radio de 8 m. La carga volverá a infligir daño por segundo durante 2 s más."},
[409979] = {name = "Lobo solitario", additional_info = "[q]Obtienes la habilidad Lobo solitario:\n\n\nInfliges un 25% más de daño con todos tus ataques cuando no tienes una mascota activa."},
[409988] = {name = "Force Player Cast Delayed Banish", additional_info = nil},
[409999] = {name = "Grabar guantes - Señal de la Luz", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Señal de la Luz:\n\n\nEl objetivo se convierte en una Señal de la Luz para todos los miembros de tu grupo o banda que se encuentren en un radio de 40 m. Cualquier sanación que lances sobre miembros de tu grupo o banda sanará también a la señal un 75% de la cantidad sanada. Solo un objetivo puede ser la Señal de la Luz cada vez. Dura 1 h."},
[410001] = {name = "Grabar guantes - Mano de expiación", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Mano de expiación:\n\n\nProvocas al objetivo para que te ataque, pero no tiene efecto si el objetivo ya te está atacando.\n\n Cuando conoces esta habilidad, la bonificación de amenaza de Furia recta aumenta a 80% y cuando te sanan otros, Furia recta hace que obtengas una cantidad de maná equivalente a un 25% de la cantidad sanada. Además, mientras Furia recta está activa, el daño que deje tu salud por debajo del 35% se reduce un 20%. Furia recta permanecerá activa hasta que se cancele."},
[410002] = {name = "Grabar guantes - Golpe de cruzado", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Golpe de cruzado:\n\n\nUn golpe instantáneo que inflige un 75% de daño con arma como daño Sagrado y regenera un 5% de tu maná máximo. La duración de todos los efectos de Sentencia en el objetivo se restablece a 30 s."},
[410005] = {name = "Grabar pantalones - Maestría en auras", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Maestría en auras:\n\n\nProvoca que tu Aura de concentración haga inmunes ante los efectos de silencio e interrupción a todos los objetivos afectados y mejore el efecto del resto de las auras un 100%. Dura 6 s."},
[410008] = {name = "Grabar pantalones - Escudo de vengador", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Escudo de vengador:\n\n\nLanza un escudo Sagrado al enemigo que inflige de [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] a [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] p. de daño Sagrado, lo deja atontado y salta a los enemigos cercanos. Afecta a un total de 3 objetivos. Dura 5 s."},
[410010] = {name = "Grabar pantalones - Mano de sacrificio", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Mano de sacrificio:\n\n\nHace que el miembro del grupo o banda transfiera un 30% del daño recibido al taumaturgo. Dura 12 s o hasta que el taumaturgo haya transferido un 100% de su salud máxima."},
[410011] = {name = "Grabar pantalones - Inspiración ejemplar", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Inspiración ejemplar:\n\n\nTu presencia inspiradora periódicamente disipa efectos de miedo y sueño en miembros del grupo cercanos."},
[410013] = {name = "Grabar brazal - Martillo del honrado", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Martillo del honrado:\n\n\nDa un martillazo al objetivo actual y a un máximo de 3 objetivos cercanos más, inflige 4 veces el daño por segundo de tu mano derecha como daño sagrado."},
[410014] = {name = "Grabar pechera - Tormenta divina", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera con la runa Tormenta divina:\n\n\nUn ataque instantáneo con arma que inflige un 110% de daño con arma a un máximo de 4 enemigos que se encuentren en un radio de 8 m. La Tormenta divina sana a hasta 3 miembros del grupo o banda con un total del 25% del daño infligido."},
[410015] = {name = "Grabar capa - Luz divina", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa Luz divina:\n\n\nRestaura de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100] p. de salud a un objetivo aliado. Un 50% de la sanación excedente del objetivo se convierte en un escudo de absorción que dura 15 s. Lanzar Luz divina múltiples veces no acumula este escudo.\n\n Luz divina se beneficia de todos los talentos y efectos que se activan por Luz Sagrada o que la modifican."},
[410021] = {name = "Grabar pechera - Golpes salvajes", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Golpes feroces:\n\n\nCuando estás en Forma felina, de oso o de oso temible, los miembros del grupo o banda en un radio de 100 m obtienen mayor ferocidad de combate. Cada golpe cuerpo a cuerpo tiene un 20% de probabilidad de otorgar un ataque extra al atacante con un 20% de poder de ataque extra. No tiene efecto si el objetivo ya se ha beneficiado de Tótem Viento Furioso."},
[410023] = {name = "Grabar pantalones - Rugido salvaje", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Rugido salvaje:\n\n\nRemate que aumenta el daño físico infligido un 30% en Forma felina. Dura más por cada punto de combo:\n 1 p. : 14 segundos\n 2 p.: 19 segundos\n 3 p.: 24 segundos\n 4 p.: 29 segundos\n 5 p.: 34 segundos"},
[410025] = {name = "Grabar guantes - Destrozar", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Destrozar:\n\n\nDestroza al objetivo, lo que le inflige un 160% del daño normal y provoca que reciba un 30% más de daño de los efectos de sangrado y Triturar durante 1 min. Esta habilidad se beneficia de todos los efectos vinculados con Zarpa y Magullar y los activa.\n\n Golpear a un objetivo con Destrozar (oso) también te otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s."},
[410027] = {name = "Grabar botas - Instintos de supervivencia", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Instintos de supervivencia:\n\n\nCuando se activa, te otorga un 30% de tu salud máxima y aumenta un 20% toda la sanación que no sea física que realizas durante 20 s. Después de que el efecto expira, los puntos de salud se pierden. Se puede usar en cualquier forma menos Forma de lechúcico lunar.\n\n Además, regeneras 5 p. de ira cada vez que esquivas mientras estás en Forma de oso o Forma de oso temible, 10 p. de energía mientras estás en Forma felina, o un 1% de tu maná máximo mientras estás en otra forma."},
[410028] = {name = "Grabar guantes - Crecimiento salvaje", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Crecimiento salvaje:\n\n\nRestablece [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a todos los miembros del grupo del jugador objetivo en un radio de 43.5 m del objetivo durante 7 s. La sanación se aplica rápidamente al principio y luego más lentamente, cuando el Crecimiento salvaje alcanza su duración máxima."},
[410029] = {name = "Grabar cinturón - Eclipse", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Eclipse:\n\n\nFuego estelar aumenta un 30% la probabilidad de golpe crítico de tus dos próximas Cóleras, y Cólera reduce 1.0 s el tiempo de lanzamiento de tu próximo Fuego estelar. Los dos efectos pueden acumular un máximo de 4 cargas. Además, los dos hechizos obtienen un 70% de probabilidad en todo momento de no perder tiempo de lanzamiento cuando recibes daño."},
[410033] = {name = "Grabar pantalones - Flor de vida", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Flor de vida:\n\nReduce 0.5 s el tiempo de reutilización global de tu Rejuvenecimiento y Flor de vida, y obtienes la habilidad Flor de vida:\n\n\nRestablece [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al objetivo durante 7 s. Cuando Flor de vida se completa o disipa, el objetivo sana [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al instante y el druida recupera la mitad del costo del hechizo. El efecto se acumula hasta 3 veces en un mismo objetivo."},
[410059] = {name = "Grabar cinturón - Nutrir", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Nutrir:\n\n\nRestablece de [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] a [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a un objetivo aliado. Sana un 20% extra si tienes los efectos Rejuvenecimiento, Recrecimiento, Flor de vida o Crecimiento salvaje activos sobre el objetivo. Este hechizo se beneficia de todos los efectos vinculados con Toque de sanación o Recrecimiento y los activa."},
[410060] = {name = "Grabar botas - Estado onírico", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Estado onírico:\n\n\nLos golpes críticos con hechizos de daño no periódico o cualquier daño de Oleada de estrellas te otorgan un 50% de tu regeneración de maná mientras lanzas hechizos durante 8 s, y aumentan un 20% el daño Arcano y de Naturaleza infligido a objetivos no jugadores durante 12 s."},
[410061] = {name = "Grabar pechera - Furia de Tempestira", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Furia de Tempestira:\n\n\nReduce un 100% el costo de maná de Cólera y cada vez que infliges daño con Cólera tienes una probabilidad de un 12% de que tu siguiente lanzamiento de Toque de sanación en 15 s sea instantáneo y pueda lanzarse en cualquier cambio de forma. Permite lanzar Cólera en forma de Árbol de la vida."},
[410093] = {name = "Grabar cinturón - Nova de fuego", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Nova de Fuego:\n\n\nTu hechizo Tótem Nova de Fuego es reemplazado con Nova de Fuego, que hace que tu tótem de Fuego actual irradie daño en su ubicación."},
[410094] = {name = "Grabar pechera - Sobrecarga", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Sobrecarga:\n\n\nDa a tus hechizos Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava una probabilidad de un 60% de lanzar un segundo hechizo similar en el mismo objetivo sin costo adicional que inflige la mitad del daño o sanación y no genera amenaza."},
[410095] = {name = "Grabar guantes - Ráfaga de lava", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Ráfaga de lava:\n\n\nLanzas al objetivo lava fundida que inflige de [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] a [605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] p. de daño de Fuego. Si el objetivo tiene tu Choque de llamas, Ráfaga de lava asestará un golpe crítico."},
[410096] = {name = "Grabar pechera - Especialización en doble empuñadura", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Especialización en doble empuñadura:\n\n\nCuando usas dos armas, aumenta un 5% tu probabilidad de golpear con ataques de hechizos y cuerpo a cuerpo, y tu habilidad Golpe de tormenta ahora golpea con ambas armas. También aumenta un 60% el daño que inflige tu arma de mano izquierda."},
[410097] = {name = "Grabar guantes - Escudo de agua", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Escudo de agua:\n\n\nEl taumaturgo queda rodeado por 3 esferas de agua que le dan un 1% del maná máximo cada 5 s. Cada hechizo o ataque cuerpo a cuerpo o a distancia que golpee al taumaturgo restaura un 4% del maná máximo y consume una de las esferas. Solo se activará una esfera cada varios segundos. Dura 10 min. El chamán solo puede activar un escudo elemental a la vez."},
[410098] = {name = "Grabar pechera - Maestría con escudos", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Maestría con escudos:\n\n\nCada vez que bloqueas, regeneras una cantidad de maná equivalente al 8% de tu maná máximo y obtienes una cantidad de armadura equivalente al 30% del valor de armadura de tu escudo, que se acumula hasta 5 veces. También aumenta un 10% la probabilidad de bloqueo y un 15% el valor de bloqueo.\n\n Además, cada vez que usas una habilidad de Choque, obtienes 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s."},
[410099] = {name = "Grabar pantalones - Guía ancestral", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Guía ancestral:\n\n\nDurante los próximos 10 s, un 25% de tu daño se convierte en sanación para un máximo de 3 miembros de grupo cercanos, y un 100% de tu sanación se convierte en daño contra tu objetivo de Choque de llamas más reciente."},
[410100] = {name = "Grabar cinturón - Arma vorágine", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Arma vorágine:\n\n\nCuando infliges daño con un ataque cuerpo a cuerpo, tienes la posibilidad de reducir un 20%. El tiempo de lanzamiento y el costo de maná de tu siguiente hechizo Descarga de relámpagos, Cadena de relámpagos, Ola de sanación inferior o Ráfaga de lava. La probabilidad aumenta un 50% mientras tu arma de la mano derecha esté encantada con Arma Viento Furioso, y un 50% más si usas un arma de dos manos. Se acumula un máximo de 5 veces. Dura 30 s."},
[410101] = {name = "Grabar pantalones - Escudo de tierra", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Escudo de tierra:\n\n\nProtege al objetivo con un escudo de tierra que reduce el tiempo perdido de lanzamiento o canalización cuando recibe un 30% de daño y provoca que los ataques sanen [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] p. al objetivo escudado. Este efecto solo puede ocurrir una vez cada pocos segundos. 9 cargas. Dura 10 min. Escudo de tierra solo puede utilizarse en un objetivo a la vez."},
[410103] = {name = "Grabar botas - Espíritu del alfa", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Espíritu del alfa:\n\n\nInfunde al objetivo con el espíritu de un lobo alfa y aumenta toda la amenaza generada por el objetivo un 45% durante 30 min. El límite es de 1 objetivo. Si se lanza sobre un objetivo que no sea él mismo, el Chamán también obtiene Beta leal, lo que aumenta un 5% el daño físico infligido y reduce toda la amenaza generada un 30% durante 30 min. Un objetivo no puede tener Espíritu del alfa y Beta leal al mismo tiempo."},
[410104] = {name = "Grabar guantes - Latigazo de lava", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Latigazo de lava:\n\n\nCargas con lava el arma de tu mano izquierda e infliges instantáneamente un 100% de daño con arma con tu mano izquierda. El daño aumenta un 150% si tu arma de mano izquierda está encantada con Lengua de Fuego."},
[410105] = {name = "Grabar brazales - Mareas Vivas", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa\n Mareas Vivas:\n\n\nRestablece de [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] a [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. de salud a un objetivo aliado y [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. más durante 15 s. Tus lanzamientos de Sanación en cadena sobre ese objetivo principal en menos de 15 s aumentarán el efecto de Sanación en cadena un 25%. Este hechizo también activa Despertar ancestral."},
[410107] = {name = "Grabar pantalones - Tradición de la tierra", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Tradición de tierra:\n\n\nCuando Arma Muerdepiedras está activa en tu arma de mano derecha y tienes un escudo equipado, generas un 65% más de amenaza, obtienes un 25% más de salud, recibes un 10% menos de daño, obtienes un 6% menos de probabilidad de recibir golpes críticos de ataques cuerpo a cuerpo y Choque de tierra provoca a los objetivos para que te ataquen. Además, tiene un tiempo de reutilización aparte de los demás hechizos de Choque, pero su alcance se reduce a cuerpo a cuerpo. Sin embargo, el alcance de tu Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava se reduce 20 m."},
[410109] = {name = "Grabar cinturón - Disparo firme", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Disparo firme:\n\n\nUn disparo firme que inflige un 100% de daño con arma a distancia."},
[410110] = {name = "Grabar pechera - Maestría de bestias", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Maestría de bestias:\n\n\nEl daño y la salud de tu mascota aumentan un 15%, y su regeneración de enfoque aumenta un 50%. Además, el Bramido de tu mascota también provoca al objetivo para que la ataque durante 3 s."},
[410111] = {name = "Grabar pantalones - Disparo mortal", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Disparo mortal:\n\n\nTratas de rematar a un objetivo herido con un disparo a larga distancia que inflige un 100% de daño con arma y luego [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos."},
[410113] = {name = "Grabar pechera - Maestro tirador", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o tu toga con la runa Maestro tirador:\n\n\nAumenta un 5% tu probabilidad de golpe crítico y reduce un 25% el costo de todas tus habilidades de Disparo."},
[410114] = {name = "Grabar cinturón - Exponer debilidad", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Exponer debilidad:\n\n\nTus golpes críticos cuerpo a cuerpo y a distancia aumentan tu poder de ataque un monto equivalente al 40% de tu agilidad actual durante 7 s."},
[410115] = {name = "Matacobras", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Matacobras:\n\n\nMordedura de mangosta ahora tiene un 10% de probabilidad de activarse en cada uno de tus ataques cuerpo a cuerpo, y un 100% de probabilidad cuando un enemigo esquiva. Esta probabilidad se acumula, y aumenta un 10% por cada ataque subsiguiente si no se restablece. Mordedura de mangosta también inflige daño adicional equivalente a un 45% de tu poder de ataque."},
[410116] = {name = "Grabar botas - Especialización en doble empuñadura", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Especialización en doble empuñadura:\n\n\nAumenta el daño infligido por tu arma de mano izquierda un 60%, y hace que tu Golpe de raptor golpee con ambas armas cuando portas dos armas."},
[410118] = {name = "Grabar botas - Lanzador de trampas", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Lanzador de trampas:\n\n\nAhora puedes colocar tus Trampas congelante, de inmolación y explosiva en cualquier ubicación en un radio de 35 m. Además, tus trampas de Fuego y Escarcha ahora tienen tiempos de reutilización compartidos para cada escuela."},
[410121] = {name = "Grabar guantes - Disparo de quimera", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Disparo de quimera:\n\n\nInfliges un 135% de daño con arma, lo que renueva la Picadura actual de tu objetivo y activa un efecto:\n\n Picadura de serpiente: Inflige instantáneamente un 48% del daño infligido por tu Picadura de serpiente.\n\n Picadura de víbora: Restaura instantáneamente una cantidad de maná igual al 60% del maná drenado por tu Picadura de víbora.\n\n Picadura de escórpido: Intenta Desarmar al objetivo durante 10 s. Este efecto solo puede ocurrir una vez por minuto."},
[410122] = {name = "Grabar pechera - Lobo solitario", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Lobo solitario:\n\n\nInfliges un 25% más de daño con todos tus ataques cuando no tienes una mascota activa."},
[410123] = {name = "Grabar guantes - Disparo explosivo", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Disparo explosivo:\n\n\nDisparas una carga explosiva al objetivo enemigo que inflige [Ranged attack power * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Ranged attack power * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño de Fuego a todos los enemigos en un radio de 8 m. La carga volverá a infligir daño por segundo durante 2 s más."},
[410140] = {name = "Veneno de araña", additional_info = nil},
[410156] = {name = "Golpe de tormenta", additional_info = "Rango ilimitado\nInstante\n[q]Te otorga un ataque extra. Además, las 2 próximas fuentes que inflijan daño de Naturaleza al objetivo aumentan un 20%. Dura 12 s."},
