[410275] = {name = "Aventurero herido - Dar runa de paladín", additional_info = nil},
[410412] = {name = "Burla", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {10 seg de reutilización}\n[q]Provoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."},
[410657] = {name = "Duelo a muerte", additional_info = nil},
[410659] = {name = "Desterrar espíritu", additional_info = nil},
[410662] = {name = "Destierro tardío", additional_info = nil},
