[410881] = {name = "Área santificada", additional_info = nil},
[410935] = {name = "Meditaciones sobre la Luz", additional_info = nil},
[410958] = {name = "Aprender Runa de Recuerdo", additional_info = "Hechizo de 3 seg\n[q]Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[410970] = {name = "Meditaciones sobre el vacío", additional_info = nil},
[410971] = {name = "Aprender Runa de Profecía", additional_info = "Hechizo de 3 seg\n[q]Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[411115] = {name = "Supervivencia del más fuerte", additional_info = "[q]Reduce un 6% la probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo y reduce un 10% todo el daño recibido. El daño recibido se reduce un 10% más cuando estás en Forma de oso o Forma de oso temible."},
[411124] = {name = "Supervivencia del más fuerte", additional_info = "Instante\nRequiere Forma de oso, Forma de oso temible\n[q]Reduce un 10% todo el daño recibido."},
[411128] = {name = "Flagelo", additional_info = "{50 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Forma felina\n[q]Flagela a los enemigos cercanos, les inflige un 250% de daño con arma y genera 1 p. de combo sobre tu objetivo actual."},
[411186] = {name = "Colocar cebo", additional_info = "Hechizo de 1 seg\nComponentes:\nCarne de ave de Mulgore\n[q]Coloca un cebo cerca de la morada de un gato montés."},
