[411608] = {name = "Domesticar perro de la pradera", additional_info = nil},
[411622] = {name = "Almizcle de perro de la pradera", additional_info = "{Instante} {10 min de reutilización}\n[q]Tu habilidad Domesticar bestia también funciona en perros de la pradera (como mascota de compañía)"},
[411624] = {name = "Domesticar bestia", additional_info = "Alcance de 30 m\nInstante\n[q]Comienza a domesticar una bestia para que se convierta en tu compañera. Tu armadura se reduce un 100% durante 20 s mientras te concentras en la domesticación de la bestia. Si pierdes la atención de la bestia por cualquier motivo, el proceso de domesticación fracasará. Cuando la domestiques, la bestia estará triste y no será leal. Intenta alimentar a la mascota de inmediato para hacerla feliz."},
[411631] = {name = "Domesticar bestia", additional_info = "{60% del maná base} {Alcance de 30 m}\nCanalizado (Hechizo de 20 seg)\n[q]Comienza a domesticar una bestia para que se convierta en tu compañera. Tu armadura se reduce un 100% durante 20 s mientras te concentras en la domesticación de la bestia. Si pierdes la atención de la bestia por cualquier motivo, el proceso de domesticación fracasará. Cuando la domestiques, la bestia estará triste y no será leal. Intenta alimentar a la mascota de inmediato para hacerla feliz."},
[411684] = {name = "Cargar", additional_info = "Alcance de 8 - 25 m\n{Instante} {15 seg de reutilización}\n[q]Carga contra un enemigo, genera 0 p. de ira y lo aturde durante 1 s."},
[411688] = {name = "Carga aturdidora", additional_info = "Alcance de 8 - 25 m\nInstante\nRequiere Actitud de batalla"},
[411774] = {name = "Torbellino", additional_info = "Canalizado (Hechizo de 2 seg)\n[q]Ataca a los enemigos cercanos con un torbellino de acero que dura 2 s e inflige el daño normal más 50 p."},
