[411956] = {name = "Maldición de Brazanegra", additional_info = "Alcance de 100 m\nInstante\n[q]Maldice al objetivo con agonía e inflige 600 p. de daño de las Sombras durante 12 s. El daño provocado aumenta progresivamente a medida que la maldición alcanza su duración completa."},
[411959] = {name = "Miedo", additional_info = "Alcance de 100 m\nInstante\n[q]Causa miedo en el enemigo y hace que huya durante 4 s. Solo se puede asustar a 1 objetivo cada vez."},
