[412018] = {name = "Escudo sacro", additional_info = "Rango ilimitado\nInstante\n[q]Cada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe 36 p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante 6 s. No puede obtener este efecto más de una vez cada 6 s. Dura 6 s."},
[412019] = {name = "Escudo sacro", additional_info = "{12% del maná base} {Alcance de 40 m}\nInstante\n[q]Cada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante un máximo de 6 s. Además, provoca que tu Destello de Luz sane a los objetivos con Escudo sacro un 100% más durante 12 s. No pueden obtener este efecto más de una vez cada 6 s. Dura 1 min. Solo un objetivo puede tener este efecto a la vez."},
[412020] = {name = "Destello de Luz", additional_info = "Alcance de 100 m\nInstante\n[q]Sana en el tiempo."},
[412040] = {name = "Fragor de sombra", additional_info = nil},
