[412080] = {name = "Golpe de las Sombras", additional_info = nil},
[412096] = {name = "Tempestad carmesí", additional_info = "{35 p. de energía} {Alcance de 8 m}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Remate que corta a todos los enemigos en un radio de 8 m e inflige daño de sangrado con el tiempo a las víctimas. Dura más e inflige más daño por cada punto de combo.\n\n 1 p. : (Attack power * 0.30) p. de daño durante 4 s.\n 2 p.: (Attack power * 0.45) p. de daño durante 6 s.\n 3 p.: (Attack power * 0.60) p. de daño durante 8 s.\n 4 p.: (Attack power * 0.75) p. de daño durante 10 s.\n 5 p.: (Attack power * 0.90) p. de daño durante 12 s.\n\n Tempestad carmesí se beneficia de todos los talentos y efectos que se activan de Ruptura o que lo modifican."},
[412107] = {name = "Odio a cero", additional_info = nil},
[412113] = {name = "Eliminar maldición superior", additional_info = "{10% del maná base} {Alcance de 30 m}\nInstante\n[q]Elimina 1 maldición y 1 efecto de magia dañino de un objetivo aliado."},
[412114] = {name = "Potenciación del Vacío", additional_info = nil},
[412115] = {name = "Resguardo avanzado", additional_info = "[q]Ahora puedes lanzar tus hechizos Escudo de maná, Resguardo contra la Escarcha y Resguardo contra el Fuego sobre cualquier objetivo aliado y absorben un 100% más de daño, y Escudo de maná consume un 50% menos de maná por el daño absorbido. Además, tu Eliminar maldición inferior es reemplazada con Eliminar maldición superior.\n\n\nElimina 1 maldición y 1 efecto de magia dañino de un objetivo aliado."},
[412116] = {name = "Escudo de maná", additional_info = "{40 p. de maná} {Alcance de 40 m}\nInstante\n[q]Absorbe 240 p. del daño físico que recibiría un objetivo aliado a cambio de maná. Drena 1 p. de maná del mago taumaturgo por cada p. de daño absorbido. Dura 1 min."},
[412118] = {name = "Escudo de maná", additional_info = "{60 p. de maná} {Alcance de 40 m}\nInstante\n[q]Absorbe 420 p. del daño físico que recibiría un objetivo aliado a cambio de maná. Drena 1 p. de maná del mago taumaturgo por cada p. de daño absorbido. Dura 1 min."},
[412120] = {name = "Escudo de maná", additional_info = "{80 p. de maná} {Alcance de 40 m}\nInstante\n[q]Absorbe 600 p. del daño físico que recibiría un objetivo aliado a cambio de maná. Drena 1 p. de maná del mago taumaturgo por cada p. de daño absorbido. Dura 1 min."},
[412121] = {name = "Escudo de maná", additional_info = "{100 p. de maná} {Alcance de 40 m}\nInstante\n[q]Absorbe 780 p. del daño físico que recibiría un objetivo aliado a cambio de maná. Drena 1 p. de maná del mago taumaturgo por cada p. de daño absorbido. Dura 1 min."},
[412122] = {name = "Escudo de maná", additional_info = "{120 p. de maná} {Alcance de 40 m}\nInstante\n[q]Absorbe 960 p. del daño físico que recibiría un objetivo aliado a cambio de maná. Drena 1 p. de maná del mago taumaturgo por cada p. de daño absorbido. Dura 1 min."},
