[412286] = {name = "Incendio", additional_info = "[q]Aumenta tu probabilidad de golpe crítico con todos los hechizos un 15%, pero tus golpes críticos con hechizos que no son periódicos ahora tienen un costo de maná adicional de un 1% de tu maná base."},
