[412322] = {name = "Poder con hechizos", additional_info = "[q]Aumenta la bonificación de daño del golpe crítico de todos los hechizos un 50%."},
[412324] = {name = "Esclarecimiento", additional_info = "[q]Infliges un 10% más de daño cuando tienes más del 70% de maná. Cuando tienes menos del 30% de maná, conservas un 10% de tu regeneración de maná durante el lanzamiento de hechizos."},
[412325] = {name = "Esclarecimiento", additional_info = "Instante\n[q]Permite que un 10% de tu regeneración de maná continúe mientras lanzas hechizos."},
