[412689] = {name = "Aflicción eterna", additional_info = "[q]Drenar vida, Drenar alma, Descarga de las Sombras, Cuchilla de las Sombras, Dolor abrasador, Incinerar y Poseer restablecen la duración de tu Corrupción sobre el objetivo al máximo."},
[412698] = {name = "Aflicción eterna", additional_info = nil},
[412718] = {name = "Practicar doble empuñadura", additional_info = "Alcance de 10 m\nHechizo de 6 seg\nComponentes:\nPececito luminoso crudo\n[q]Intenta filetear un pececito luminoso crudo."},
[412727] = {name = "Tácticas demoníacas", additional_info = "[q]Aumenta un 10% la probabilidad de que tú y tu mascota asesten un golpe crítico cuerpo a cuerpo y con hechizos."},
[412732] = {name = "Conocimiento demoníaco", additional_info = "[q]Aumenta tu daño y sanación con hechizos por un valor equivalente a un 3% de la suma total del aguante más el intelecto de tu mascota demoníaca."},
[412735] = {name = "Conocimiento demoníaco", additional_info = nil},
[412758] = {name = "Incinerar", additional_info = "{14% del maná base} {Alcance de 30 m}\nHechizo de 2.25 seg\n[q]Quema a tu enemigo, inflige de [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] a [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] p. de daño y aumenta todo el daño de Fuego que infliges un 40% durante los próximos 15 s."},
[412783] = {name = "Metamorfosis: Carga de demonio", additional_info = nil},
[412784] = {name = "Metamorfosis: Aullido demoníaco", additional_info = nil},
[412787] = {name = "Interrumpir", additional_info = "{5% del maná base} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {10 seg de reutilización}\n[q]Asfixia a tu enemigo con una sobrecarga de energía de las Sombras que inflige 10 p. de daño, interrumpe el lanzamiento de hechizos e impide que se puedan lanzar hechizos de esa misma escuela durante 5 s."},
[412788] = {name = "Carga de demonio", additional_info = "{5% del maná base} {Alcance de 8 - 25 m}\n{Instante} {15 seg de reutilización}\n[q]Carga contra un enemigo y lo aturde durante 1 s. No se puede usar en combate."},
[412789] = {name = "Aullido demoníaco", additional_info = "5% del maná base\n{Instante} {10 min de reutilización}\n[q]Obliga a todos los enemigos cercanos a concentrar sus ataques sobre ti durante 6 s."},
[412790] = {name = "Golpe infernal", additional_info = "Alcance de 8 - 25 m\n{Instante} {45 seg de reutilización}\n[q]Salta en el aire y golpea a todos los enemigos en un radio de 8 m del área objetivo, lo que inflige 100 p. de daño de las Sombras y los aturde durante 2 s."},
[412798] = {name = "Danza de los malvados", additional_info = "[q]Tú y tu mascota demoníaca obtienen una probabilidad de esquivar equivalente a un 70% de tu probabilidad de golpe crítico con hechizos cada vez que asestas un golpe crítico a un enemigo, y los dos recuperan un 2% del maná máximo."},
[412800] = {name = "Danza de los malvados", additional_info = "Instante\n[q]Aumenta la probabilidad de esquivar por un valor equivalente a un 70% de tu probabilidad de golpe crítico con hechizos."},
[413031] = {name = "Doble empuñadura", additional_info = nil},
[413045] = {name = "Potenciación del Vacío", additional_info = nil},
[413052] = {name = "Fragor de sombra", additional_info = nil},
[413247] = {name = "Serendipia", additional_info = "Rango ilimitado\nInstante\n[q]Modifies Cast Time -19%:\nRezo de sanación , Rezo de sanación , Rezo de sanación , Rezo de sanación , Rezo de sanación , Sanación inferior , Sanación inferior , Sanación inferior , Sanación superior , Sanación superior , Sanación superior , Sanación superior , Sanación superior , Sanar , Sanar , Sanar , Sanar"},
[413248] = {name = "Serendipia", additional_info = "[q]Sanar con Sanación relámpago reduce un 20% el tiempo de lanzamiento de tu siguiente Sanación inferior, Sanar, Sanación superior o Rezo de sanación durante 20 s. Se acumula hasta 3 veces."},
[413251] = {name = "Dolor y sufrimiento", additional_info = "[q]Explosión mental, Púa mental y Tortura mental restablecen al máximo la duración de una de tus habilidades Palabra de las Sombras: dolor, Plaga del Vacío o Toque vampírico sobre el objetivo. Siempre se restablecerá la habilidad a la que le quede menos tiempo restante."},
[413259] = {name = "Abrasamiento mental", additional_info = "{28% del maná base} {Alcance de 30 m}\nCanalizado (Hechizo de 6 seg)\n[q]Provoca una explosión de magia de las Sombras que daña al objetivo enemigo y a otros enemigos cercanos. Inflige de [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] a [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] p. de daño de las Sombras cada 1 s durante 6 s a todos los enemigos en un radio de 10 m del objetivo."},
[413260] = {name = "Abrasamiento mental", additional_info = "Alcance de 100 m\nInstante\n[q]Provoca una explosión de magia de las Sombras alrededor del objetivo enemigo que inflige 70 to 78 p. de daño de las Sombras cada 1 s durante hasta cancelación a todos los enemigos en un radio de 10 m del objetivo."},
[413301] = {name = "Máquina de guerra", additional_info = "[q]Matar a un enemigo que otorga experiencia y honor genera 10 p. de ira."},
[413302] = {name = "Efecto de ira de Máquina de guerra", additional_info = nil},
[413338] = {name = "Ícono de baluarte", additional_info = nil},
[413380] = {name = "Oleada de sangre", additional_info = "[q]Golpe heroico, Sed de sangre y Torbellino tienen una probabilidad de un 30% de hacer que tu siguiente Embate en 15 s sea instantáneo, golpee con ambas armas cuerpo a cuerpo y no cueste ira.\n(Probabilidad de que accione: 30%)"},
[413399] = {name = "Oleada de sangre", additional_info = "Instante\n[q]Modifies Cast Time -99%:\nEmbate , Embate , Embate , Embate\n\nModifies Power Cost -99%:\nEmbate , Embate , Embate , Embate"},
[413404] = {name = "Furia enfilada", additional_info = "[q]Cuando usas dos armas, tu velocidad de movimiento aumenta un 10% y obtienes un 4% de velocidad de ataque cada vez que tu ataque automático cuerpo a cuerpo golpea al mismo objetivo de tu ataque automático anterior. Se acumula un máximo de 5 veces. Dura 10 s o hasta que tu ataque automático golpee a otro objetivo."},
[413429] = {name = "Ícono diádico", additional_info = nil},
[413432] = {name = "Ícono lítico", additional_info = nil},
[413446] = {name = "Disparo automático", additional_info = "Alcance de 8 - 35 m\nInstante\n[q]Dispara automáticamente al objetivo con el arco hasta que se cancela."},
[413476] = {name = "Actitud de gladiador pasiva", additional_info = nil},
[413479] = {name = "Escudo de actitud de gladiador pasiva", additional_info = nil},
[413548] = {name = "Modo Ilimitado", additional_info = "Rango ilimitado\nInstante\n[q]Modo Ilimitado habilitado. Inmune a todos los efectos de control de masas.\n El daño fatal se absorbe.\n Sana un 100% de salud cada 5 s."},
[413589] = {name = "Atronar", additional_info = nil},
[413651] = {name = "Combinar flores de la pradera", additional_info = "Hechizo de 3 seg\nComponentes:\nFlor de la pradera (3)\n[q]Combina 3 flores de la pradera para hacer una corona."},
