[415059] = {name = "Custodiado por la Luz", additional_info = "[q]Cada vez que golpeas a un objetivo con tu arma cuerpo a cuerpo, obtienes un 5% de tu maná máximo cada 3 s durante 15 s, pero tus hechizos de sanación sanan un 50% menos durante esta regeneración de maná."},
[415068] = {name = "Exorcismo", additional_info = "{85 p. de maná} {Alcance de 30 m}\n{Instante} {15 seg de reutilización}\n[q]Inflige 90 to 102 p. de daño Sagrado a un objetivo enemigo y tiene un 100% de probabilidad de asestar un golpe crítico contra los demonios y no-muertos."},
