[415073] = {name = "Exorcismo", additional_info = "{345 p. de maná} {Alcance de 30 m}\n{Instante} {15 seg de reutilización}\n[q]Inflige 505 to 563 p. de daño Sagrado a un objetivo enemigo y tiene un 100% de probabilidad de asestar un golpe crítico contra los demonios y no-muertos."},
[415076] = {name = "Exorcista", additional_info = "[q]Exorcismo ahora puede lanzarse sobre cualquier objetivo y tiene un 100% más de probabilidad de golpe crítico contra los no-muertos y demonios."},
[415093] = {name = "Summon Lightning VFX", additional_info = nil},
[415096] = {name = "Coherencia", additional_info = "[q]Hace que la efectividad de tu Sanación en cadena solo se reduzca un 35% por salto y que la efectividad de Cadena de relámpagos solo se reduzca un 20% por salto. Además, hace que ambas salten a 1 objetivo más."},
[415100] = {name = "Oleada de poder", additional_info = "[q]Cada vez que Choque de llamas inflige daño, tiene un 5% de probabilidad de restablecer el tiempo de reutilización de Ráfaga de lava y Cadena de relámpagos, y de hacer que el próximo lanzamiento de Ráfaga de lava o Cadena de relámpagos en 10 s sea instantáneo. Cada vez que Mareas Vivas sana, tiene un 5% de probabilidad de hacer que tu siguiente Sanación en cadena en 10 s sea instantáneo. Además, cada 5 s obtienes maná equivalente a un 15% de tu intelecto.\n(Probabilidad de que accione: 5%)"},
[415105] = {name = "Oleada de poder", additional_info = "Instante\n[q]Modifies Cast Time -100%:\nCadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Ráfaga de lava , Ráfaga de lava"},
