[415231] = {name = "Quemar", additional_info = "[q]Tu Choque de llamas ahora golpea a un máximo de 5 objetivos, dura 6 s más e inflige un 100% más de daño. Además, mientras tu arma equipada en la mano derecha esté imbuida con Arma Lengua de Fuego, tu daño con hechizos aumenta una cantidad equivalente al 150% de tu intelecto."},
[415233] = {name = "Lobo fantasmal", additional_info = "100 p. de maná\nHechizo de 3 seg\n[q]Convierte al Chamán en un Lobo fantasmal, lo que aumenta un 40% la velocidad y reduce un 10% todo el daño recibido."},
[415236] = {name = "Lluvia de sanación", additional_info = "{21% del maná base} {Alcance de 40 m}\nHechizo de 2 seg 10 seg de reutilización\n[q]Selecciona el área de 15 m alrededor del jugador objetivo y sana [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] p. de salud por s a todos los miembros del grupo del jugador objetivo."},
