[415292] = {name = "Vida terrestre", additional_info = "Alcance de 100 m\nInstante\n[q]Restablece [16 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 4] p. de salud durante 12 s s."},
[415320] = {name = "Golpe lateral", additional_info = "{1.5% del maná base} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {30 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Tú y tu mascota infligen un 100% de daño cuerpo a cuerpo de forma instantánea y en simultáneo. Después, infliges un 8% más de daño durante 10 s. Este efecto se acumula un máximo de 3 veces. Los ataques básicos de tu mascota tienen un 50% de probabilidad de restablecer el tiempo de reutilización de Golpe lateral."},
[415326] = {name = "Golpe lateral", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Tú y tu mascota infligen un 100% de daño cuerpo a cuerpo de forma instantánea y en simultáneo. Después, tu Mordedura de mangosta y Golpe de raptor infligen un 0% más de daño durante hasta cancelación. Este efecto se acumula un máximo de 1 veces. Golpe de raptor tiene un 0% de probabilidad de restablecer el tiempo de reutilización de Golpe lateral."},
