[415405] = {name = "Matanza rápida", additional_info = "[q]Reduce el tiempo de reutilización de Fuego rápido un 80%. Fuego rápido ahora también otorga un 40% más de velocidad de ataque cuerpo a cuerpo, y tu siguiente habilidad de Disparo en un período de 20 s después de matar a un objetivo que otorga experiencia u honor inflige un 20% de daño extra."},
[415407] = {name = "Matanza rápida", additional_info = "Instante\n[q]Modifies Damage/Healing Done +21%:\nDisparo Arcano , Disparo Arcano , Disparo Arcano , Disparo Arcano , Disparo Arcano , Disparo Arcano , Disparo Arcano , Disparo Arcano , Disparo de conmoción , Disparo de dispersión , Disparo de distracción , Disparo de distracción , Disparo de distracción , Disparo de distracción , Disparo de distracción , Disparo de distracción , Disparo de puntería , Disparo de puntería , Disparo de puntería , Disparo de puntería , Disparo de puntería , Disparo de puntería , Disparo de quimera , Disparo de quimera: serpiente , Disparo explosivo , Disparo tranquilizante , Multidisparo , Multidisparo , Multidisparo , Multidisparo , Multidisparo"},
