[415423] = {name = "Aspecto de la víbora", additional_info = "Instante\n[q]El cazador asume el aspecto de la víbora, lo que hace que tus ataques automáticos cuerpo a cuerpo y a distancia regeneren maná, pero reduce el daño total un 10%. Además, obtienes un 10% del maná máximo cada 3 s. El maná obtenido se basa en la velocidad de tu arma. Solo puede haber un aspecto activo cada vez."},
[415424] = {name = "Aspecto de la víbora", additional_info = nil},
[415428] = {name = "Reflejos felinos", additional_info = "[q]Aumenta un 20% tu probabilidad de esquivar y un 9% la de tu mascota. Además, reduce un 50% el tiempo de reutilización de tu habilidad Golpe lateral."},
[415429] = {name = "Hunter Pet Scaling", additional_info = nil},
[415431] = {name = "Evasión", additional_info = nil},
[415449] = {name = "Habilidad de runa de cintura", additional_info = "Instante\n[q]Equipa un objeto de casilla de cintura con una runa grabada para activar una habilidad en esta casilla."},
[415450] = {name = "Habilidad de runa de pies", additional_info = "Instante\n[q]Equipa un objeto de casilla de pies con una runa grabada para activar una habilidad en esta casilla."},
[415452] = {name = "Flagelo mejorado", additional_info = "[q]Obtienes la habilidad Flagelo mejorado:\n\n\nMientras estás en forma felina, tu Flagelo se convierte en Flagelo (felino) y, mientras estás en forma de oso, tu Flagelo golpea a un máximo de 7 enemigos más.\n\n Flagelo (felino)\n\nFlagela a los enemigos cercanos, les inflige un 250% de daño con arma y genera 1 p. de combo sobre tu objetivo actual."},
[415457] = {name = "Abanico de cuchillos", additional_info = "[q]Obtienes la habilidad Abanico de cuchillos:\n\n\nLanza instantáneamente las dos armas a todos los objetivos que se encuentren en un radio de 8 m, lo que inflige un 75% de daño con arma con dagas y un 50% de daño con arma con cualquier otra arma."},
[415459] = {name = "Poder con hechizos", additional_info = "[q]Obtienes la habilidad Poder con hechizos:\n\n\nAumenta la bonificación de daño del golpe crítico de todos los hechizos un 50%."},
[415460] = {name = "Incendio", additional_info = "[q]Obtienes la habilidad Incendio:\n\n\nAumenta tu probabilidad de golpe crítico con todos los hechizos un 15%, pero tus golpes críticos con hechizos que no son periódicos ahora tienen un costo de maná adicional de un 1% de tu maná base."},
[415467] = {name = "Regeneración en masa", additional_info = "[q]Obtienes la habilidad Regeneración en masa:\n\n\nSana [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] p. de salud a todos los miembros del grupo del jugador objetivo que estén en un radio de 43.5 m del jugador objetivo durante 3 s y aplica Faro temporal a cada objetivo durante 15 s.\n\n Faro temporal\n\nRegistra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos."},
[415481] = {name = "Dolor y sufrimiento", additional_info = "[q]Obtienes la habilidad Dolor y sufrimiento:\n\n\nExplosión mental, Púa mental y Tortura mental restablecen al máximo la duración de una de tus habilidades Palabra de las Sombras: dolor, Plaga del Vacío o Toque vampírico sobre el objetivo. Siempre se restablecerá la habilidad a la que le quede menos tiempo restante."},
[415596] = {name = "Maestría con escudos", additional_info = "[q]Obtienes la habilidad Maestría con escudos:"},
[415598] = {name = "Actitud de gladiador", additional_info = "[q]Obtienes la habilidad Estilo del gladiador:\n\n\nUna actitud agresiva que aumenta el daño un 10% cuando llevas un escudo y aumenta un 10% la probabilidad de bloqueo, pero que reduce un 30% la armadura y un 30% la amenaza generada. Además, obtienes un 50% más de ira cuando tu ataque automático daña a un enemigo que no te tiene como objetivo.\n\n Cuando llevas un escudo en la Actitud de gladiador, puedes usar todas las habilidades que están restringidas a otras actitudes."},
[415599] = {name = "Furia enfilada", additional_info = "[q]Obtienes la habilidad Furia enfilada:\n\n\nCuando usas dos armas, tu velocidad de movimiento aumenta un 10% y obtienes un 4% de velocidad de ataque cada vez que tu ataque automático cuerpo a cuerpo golpea al mismo objetivo de tu ataque automático anterior. Se acumula un máximo de 5 veces. Dura 10 s o hasta que tu ataque automático golpee a otro objetivo."},
[415604] = {name = "Aflicción eterna", additional_info = "[q]Obtienes la habilidad Aflicción eterna:\n\n\nDrenar vida, Drenar alma, Descarga de las Sombras, Cuchilla de las Sombras, Dolor abrasador, Incinerar y Poseer restablecen la duración de tu Corrupción sobre el objetivo al máximo."},
[415605] = {name = "Tácticas demoníacas", additional_info = "[q]Obtienes la habilidad Tácticas demoníacas:\n\n\nAumenta un 10% la probabilidad de que tú y tu mascota asesten un golpe crítico cuerpo a cuerpo y con hechizos."},
[415703] = {name = "Escudo sacro", additional_info = "[q]Obtienes la habilidad Escudo sacro:\n\n\nCada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante un máximo de 6 s. Además, provoca que tu Destello de Luz sane a los objetivos con Escudo sacro un 100% más durante 12 s. No pueden obtener este efecto más de una vez cada 6 s. Dura 1 min. Solo un objetivo puede tener este efecto a la vez."},
[415706] = {name = "El arte de la guerra", additional_info = "[q]Obtienes la habilidad El arte de la guerra:\n\n\nTus golpes críticos cuerpo a cuerpo reducen el tiempo de reutilización restante de Exorcismo en 2 s y el costo de maná de Exorcismo un 80%."},
[415709] = {name = "Supervivencia del más fuerte", additional_info = "[q]Obtienes la habilidad Supervivencia del más fuerte:\n\n\nReduce un 6% la probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo y reduce un 10% todo el daño recibido. El daño recibido se reduce un 10% más cuando estás en Forma de oso o Forma de oso temible."},
[415712] = {name = "Oleada de poder", additional_info = "[q]Obtienes la habilidad Oleada de poder:\n\n\nCada vez que Choque de llamas inflige daño, tiene un 5% de probabilidad de restablecer el tiempo de reutilización de Ráfaga de lava y Cadena de relámpagos, y de hacer que el próximo lanzamiento de Ráfaga de lava o Cadena de relámpagos en 10 s sea instantáneo. Cada vez que Mareas Vivas sana, tiene un 5% de probabilidad de hacer que tu siguiente Sanación en cadena en 10 s sea instantáneo. Además, cada 5 s obtienes maná equivalente a un 15% de tu intelecto."},
[415713] = {name = "Maña mental", additional_info = "[q]Obtienes la habilidad Maña mental:\n\n\nInfligir daño con Golpe de tormenta aumenta tu poder de ataque una cantidad equivalente al 150% de tu intelecto, y aumenta el daño de tus hechizos una cantidad equivalente al 35% de tu poder de ataque total durante 30 s."},
[415714] = {name = "Lluvia de sanación", additional_info = "[q]Obtienes la habilidad Lluvia de sanación:\n\n\nSelecciona el área de 15 m alrededor del jugador objetivo y sana [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] p. de salud por s a todos los miembros del grupo del jugador objetivo."},
[415717] = {name = "Reflejos felinos", additional_info = "[q]Obtienes la habilidad Reflejos felinos:\n\n\nAumenta un 20% tu probabilidad de esquivar y un 9% la de tu mascota. Además, reduce un 50% el tiempo de reutilización de tu habilidad Golpe lateral."},
[415718] = {name = "Aspecto de la víbora", additional_info = "[q]Obtienes la habilidad Aspecto de la víbora:\n\n\nEl cazador asume el aspecto de la víbora, lo que hace que tus ataques automáticos cuerpo a cuerpo y a distancia regeneren maná, pero reduce el daño total un 10%. Además, obtienes un 10% del maná máximo cada 3 s. El maná obtenido se basa en la velocidad de tu arma. Solo puede haber un aspecto activo cada vez."},
[415719] = {name = "Bloquear y cargar", additional_info = "[q]Obtienes la habilidad Bloquear y cargar:\n\n\nCada vez que colocas una trampa, tu próxima habilidad de Disparo (salvo Disparo de dispersión) en 20 s no cuesta maná ni incurre en tiempo de reutilización."},
[415720] = {name = "Disparo mortal", additional_info = "[q]Obtienes la habilidad Disparo mortal:\n\n\nTratas de rematar a un objetivo herido con un disparo a larga distancia que inflige un 100% de daño con arma y luego [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos."},
[415723] = {name = "Especialista cuerpo a cuerpo", additional_info = "[q]Obtienes la habilidad Especialista cuerpo a cuerpo:\n\n\nTu Golpe de raptor ahora es instantáneo, y Mordedura de mangosta y Golpe de raptor tienen un 40% de probabilidad de reiniciar los tiempos de reutilización de Mordedura de mangosta y Golpe de raptor con cada ataque."},
[415725] = {name = "Acecho", additional_info = "[q]Obtienes la habilidad Acecho:\n\n\nTus golpes con Emboscada y Puñalada desequilibran a tu objetivo, lo que aumenta el tiempo entre sus ataques cuerpo a cuerpo un 10% y reduce su velocidad de movimiento un 50% durante 8 s."},
[415729] = {name = "Esclarecimiento", additional_info = "[q]Obtienes la habilidad Esclarecimiento:\n\n\nInfliges un 10% más de daño cuando tienes más del 70% de maná. Cuando tienes menos del 30% de maná, conservas un 10% de tu regeneración de maná durante el lanzamiento de hechizos."},
[415734] = {name = "Descarga de fríoarcano", additional_info = "[q]Obtienes la habilidad Descarga de fríoarcano:\n\n\nLanza una Descarga de Fríoarcano contra el enemigo, inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 305 / 100 * ( 1 ) ] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 355 / 100 * ( 1 ) ] p. de daño de Fríoarcano y reduce la velocidad de movimiento un 40% durante 9 s. Este hechizo tendrá en cuenta la resistencia más baja entre las resistencias de Escarcha o Arcana del objetivo y cuenta como daño de Escarcha y Arcano."},
[415737] = {name = "Serendipia", additional_info = "[q]Obtienes la habilidad Serendipia:\n\n\nSanar con Sanación relámpago reduce un 20% el tiempo de lanzamiento de tu siguiente Sanación inferior, Sanar, Sanación superior o Rezo de sanación durante 20 s. Se acumula hasta 3 veces."},
[415738] = {name = "Abrasamiento mental", additional_info = "[q]Obtienes la habilidad Abrasamiento mental:\n\n\nProvoca una explosión de magia de las Sombras que daña al objetivo enemigo y a otros enemigos cercanos. Inflige de [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] a [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] p. de daño de las Sombras cada 1 s durante 6 s a todos los enemigos en un radio de 10 m del objetivo."},
[415739] = {name = "Fuerza del alma", additional_info = "[q]Sanación inferior, Sanar, Sanación superior y Sanación relámpago reducen 2 s la duración restante de Alma debilitada en objetivos que sanan. Además, los objetivos de Palabra de poder: escudo obtendrán ira al recibir daño aunque el daño sea absorbido, y Furia recta se activará con el daño absorbido por tu Palabra de poder: escudo como si fuera una sanación."},
[415740] = {name = "Fuerza del alma", additional_info = "[q]Obtienes la habilidad Fuerza del alma:\n\n\nSanación inferior, Sanar, Sanación superior y Sanación relámpago reducen 2 s la duración restante de Alma debilitada en objetivos que sanan. Además, los objetivos de Palabra de poder: escudo obtendrán ira al recibir daño aunque el daño sea absorbido, y Furia recta se activará con el daño absorbido por tu Palabra de poder: escudo como si fuera una sanación."},
[415743] = {name = "Oleada de sangre", additional_info = "[q]Obtienes la habilidad Oleada de sangre:\n\n\nGolpe heroico, Sed de sangre y Torbellino tienen una probabilidad de un 30% de hacer que tu siguiente Embate en 15 s sea instantáneo, golpee con ambas armas cuerpo a cuerpo y no cueste ira."},
[415744] = {name = "Tiempo preciso", additional_info = "[q]Obtienes la habilidad Sincronización de precisión:\n\n\nEmbate ahora es instantáneo, pero tiene un tiempo de reutilización de 6 s."},
[415745] = {name = "Ira concentrada", additional_info = "[q]Obtienes la habilidad Ira concentrada:\n\n\nReduce el costo de ira de tus habilidades ofensivas en 3."},
[415749] = {name = "Conocimiento demoníaco", additional_info = "[q]Obtienes la habilidad Conocimiento demoníaco:\n\n\nAumenta tu daño y sanación con hechizos por un valor equivalente a un 3% de la suma total del aguante más el intelecto de tu mascota demoníaca."},
[415750] = {name = "Incinerar", additional_info = "[q]Obtienes la habilidad Incinerar:\n\n\nQuema a tu enemigo, inflige de [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] a [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] p. de daño y aumenta todo el daño de Fuego que infliges un 40% durante los próximos 15 s."},
[415751] = {name = "Danza de los malvados", additional_info = "[q]Obtienes la habilidad Danza de los malvados:\n\n\nTú y tu mascota demoníaca obtienen una probabilidad de esquivar equivalente a un 70% de tu probabilidad de golpe crítico con hechizos cada vez que asestas un golpe crítico a un enemigo, y los dos recuperan un 2% del maná máximo."},
[415755] = {name = "Custodiado por la Luz", additional_info = "[q]Obtienes la habilidad Custodiado por la Luz:\n\n\nCada vez que golpeas a un objetivo con tu arma cuerpo a cuerpo, obtienes un 5% de tu maná máximo cada 3 s durante 15 s, pero tus hechizos de sanación sanan un 50% menos durante esta regeneración de maná."},
[415756] = {name = "Maestría en auras", additional_info = "[q]Obtienes la habilidad Maestría en auras:\n\n\nProvoca que tu Aura de concentración haga inmunes ante los efectos de silencio e interrupción a todos los objetivos afectados y mejore el efecto del resto de las auras un 100%. Dura 6 s."},
[415760] = {name = "Lacerar", additional_info = "[q]Obtienes la habilidad Lacerar:\n\n\nLacera al objetivo enemigo y hace que sangre por [(9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) * 20 / 100 * 5] p. de daño durante 15 s más un 20% de daño con arma por aplicación existente de Lacerar en el objetivo. Genera una gran cantidad de amenaza. Este efecto se acumula hasta 5 veces en el mismo objetivo."},
[415761] = {name = "Semilla viviente", additional_info = "[q]Obtienes la habilidad Semilla viviente:\n\n\nCuando haces una sanación crítica a tu objetivo con cualquier hechizo de sanación no periódico, plantas una Semilla viviente en el objetivo con un 50% de la cantidad sanada. La Semilla viviente florecerá la próxima vez que el objetivo reciba daño o una sanación no periódica. Dura 15 s."},
[415762] = {name = "Fuegos de Elune", additional_info = "[q]Obtienes la habilidad Fuegos de Elune:\n\n\nAlgunos de tus hechizos y habilidades extienden la duración de tus efectos de daño y sanación con el tiempo en el objetivo:\n\n Fuego estelar extiende 6 s la duración de Fuego lunar.\n Cólera extiende 3 s la duración de Fuego solar.\n Recrecimiento extiende 6 s la duración de Rejuvenecimiento.\n Triturar extiende 2 s la duración de Destripar.\n\n Cada efecto solo se puede extender hasta completar su duración inicial."},
[415768] = {name = "Quemar", additional_info = "[q]Obtienes la habilidad Quemar:\n\n\nTu Choque de llamas ahora golpea a un máximo de 5 objetivos, dura 6 s más e inflige un 100% más de daño. Además, mientras tu arma equipada en la mano derecha esté imbuida con Arma Lengua de Fuego, tu daño con hechizos aumenta una cantidad equivalente al 150% de tu intelecto."},
[415813] = {name = "Lobo fantasmal superior", additional_info = "[q]Ahora puedes usar tu habilidad Lobo fantasmal en interiores, y reduce todo el daño que recibes un 10% mientras está activa."},
[415816] = {name = "Golpe de dracoleón", additional_info = "[q]Obtienes la habilidad Golpe de dracoleón:\n\n\nReemplaza tu habilidad Picadura de dracoleón por Golpe de dracoleón, un golpe brutal que inflige un 140% de daño de arma y hace que el objetivo sangre y reciba daño con el tiempo.\n\n Golpe de dracoleón requiere que tengas el talento Picadura de dracoleón y reemplaza las habilidades de Picadura de dracoleón que se encuentran en el libro de hechizos de Supervivencia."},
[415817] = {name = "Matanza rápida", additional_info = "[q]Obtienes la habilidad Matanza rápida:\n\n\nReduce el tiempo de reutilización de Fuego rápido un 80%. Fuego rápido ahora también otorga un 40% más de velocidad de ataque cuerpo a cuerpo, y tu siguiente habilidad de Disparo en un período de 20 s después de matar a un objetivo que otorga experiencia u honor inflige un 20% de daño extra."},
[415818] = {name = "Instrucción de francotirador", additional_info = "[q]Obtienes la habilidad Instrucción de francotirador:\n\n\nAumenta un 2% la probabilidad de golpe crítico de tus habilidades de Disparo mientras no te hayas movido durante los últimos 2 s, y se acumula por segundo hasta un máximo de 5 veces. Al alcanzar 2 acumulaciones o más, tu Disparo de puntería se vuelve instantáneo. Si te mueves, perderás 1 acumulación por segundo."},
[415822] = {name = "Furia de raptor", additional_info = "[q]Obtienes la habilidad Furia de raptor:\n\n\nGolpe de raptor aumenta un 15% el daño infligido por Golpe de raptor y Mordedura de mangosta durante 30 s. Se acumula hasta 5 veces. Las aplicaciones posteriores no extienden la duración de este efecto."},
[415918] = {name = "Grabar capa - Tempestad carmesí", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa Tempestad carmesí:\n\n\nRemate que corta a todos los enemigos en un radio de 8 m e inflige daño de sangrado con el tiempo a las víctimas. Dura más e inflige más daño por cada punto de combo.\n\n 1 p. : (Attack power * 0.30) p. de daño durante 4 s.\n 2 p.: (Attack power * 0.45) p. de daño durante 6 s.\n 3 p.: (Attack power * 0.60) p. de daño durante 8 s.\n 4 p.: (Attack power * 0.75) p. de daño durante 10 s.\n 5 p.: (Attack power * 0.90) p. de daño durante 12 s.\n\n Tempestad carmesí se beneficia de todos los talentos y efectos que se activan de Ruptura o que lo modifican."},
[415922] = {name = "Grabar capa - Trabuco", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa Trabuco:\n\n\nDispara una descarga de mosquete a un máximo de 4 enemigos en un cono frente a ti que inflige de [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Attack power] a [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Attack power] p. de daño físico."},
[415926] = {name = "Grabar botas - Acecho", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Acecho:\n\n\nTus golpes con Emboscada y Puñalada desequilibran a tu objetivo, lo que aumenta el tiempo entre sus ataques cuerpo a cuerpo un 10% y reduce su velocidad de movimiento un 50% durante 8 s."},
[415934] = {name = "Grabar botas - Poder con hechizos", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Poder con hechizos:\n\n\nAumenta la bonificación de daño del golpe crítico de todos los hechizos un 50%."},
[415936] = {name = "Grabar guantes - Bomba viva", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Bomba viva:\n\n\nEl objetivo se convierte en una Bomba viva que recibe [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] p. de daño de Fuego durante 12 s. Después de 12 s o cuando se disipa el hechizo, el objetivo explota e inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] p. de daño de Fuego a todos los enemigos en un radio de 10 m.\n\n Bomba viva se beneficia de todos los talentos y efectos que activan o modifican Agostar."},
[415939] = {name = "Grabar pantalones - Regeneración en masa", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Regeneración en masa:\n\n\nSana [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] p. de salud a todos los miembros del grupo del jugador objetivo que estén en un radio de 43.5 m del jugador objetivo durante 3 s y aplica Faro temporal a cada objetivo durante 15 s.\n\n Faro temporal\n\nRegistra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos."},
[415942] = {name = "Grabar pechera - Esclarecimiento", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Esclarecimiento:\n\n\nInfliges un 10% más de daño cuando tienes más del 70% de maná. Cuando tienes menos del 30% de maná, conservas un 10% de tu regeneración de maná durante el lanzamiento de hechizos."},
[415948] = {name = "Grabar cinturón - Descarga de fríoarcano", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Descarga de fríoarcano:\n\n\nLanza una Descarga de Fríoarcano contra el enemigo, inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 305 / 100 * ( 1 ) ] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 355 / 100 * ( 1 ) ] p. de daño de Fríoarcano y reduce la velocidad de movimiento un 40% durante 9 s. Este hechizo tendrá en cuenta la resistencia más baja entre las resistencias de Escarcha o Arcana del objetivo y cuenta como daño de Escarcha y Arcano."},
[415988] = {name = "Vahi Partehuesos - Intercambiar cabeza de centauro por fragmento de runa", additional_info = nil},
[415991] = {name = "Grabar yelmo - Dolor y sufrimiento", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Dolor y sufrimiento:\n\n\nExplosión mental, Púa mental y Tortura mental restablecen al máximo la duración de una de tus habilidades Palabra de las Sombras: dolor, Plaga del Vacío o Toque vampírico sobre el objetivo. Siempre se restablecerá la habilidad a la que le quede menos tiempo restante."},
[415995] = {name = "Grabar pechera - Serendipia", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Serendipia:\n\n\nSanar con Sanación relámpago reduce un 20% el tiempo de lanzamiento de tu siguiente Sanación inferior, Sanar, Sanación superior o Rezo de sanación durante 20 s. Se acumula hasta 3 veces."},
[415996] = {name = "Grabar guantes - Abrasamiento mental", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Abrasamiento mental:\n\n\nProvoca una explosión de magia de las Sombras que daña al objetivo enemigo y a otros enemigos cercanos. Inflige de [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] a [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] p. de daño de las Sombras cada 1 s durante 6 s a todos los enemigos en un radio de 10 m del objetivo."},
[415997] = {name = "Grabar pechera - Fuerza del alma", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Fuerza del alma:\n\n\nSanación inferior, Sanar, Sanación superior y Sanación relámpago reducen 2 s la duración restante de Alma debilitada en objetivos que sanan. Además, los objetivos de Palabra de poder: escudo obtendrán ira al recibir daño aunque el daño sea absorbido, y Furia recta se activará con el daño absorbido por tu Palabra de poder: escudo como si fuera una sanación."},
[416002] = {name = "Grabar botas - Actitud de gladiador", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Actitud de gladiador:\n\n\nUna actitud agresiva que aumenta el daño un 10% cuando llevas un escudo y aumenta un 10% la probabilidad de bloqueo, pero que reduce un 30% la armadura y un 30% la amenaza generada. Además, obtienes un 50% más de ira cuando tu ataque automático daña a un enemigo que no te tiene como objetivo.\n\n Cuando llevas un escudo en la Actitud de gladiador, puedes usar todas las habilidades que están restringidas a otras actitudes."},
[416003] = {name = "Grabar guantes - Furia enfilada", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Furia enfilada:\n\n\nCuando usas dos armas, tu velocidad de movimiento aumenta un 10% y obtienes un 4% de velocidad de ataque cada vez que tu ataque automático cuerpo a cuerpo golpea al mismo objetivo de tu ataque automático anterior. Se acumula un máximo de 5 veces. Dura 10 s o hasta que tu ataque automático golpee a otro objetivo."},
[416004] = {name = "Grabar cinturón - Oleada de sangre", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Oleada de sangre:\n\n\nGolpe heroico, Sed de sangre y Torbellino tienen una probabilidad de un 30% de hacer que tu siguiente Embate en 15 s sea instantáneo, golpee con ambas armas cuerpo a cuerpo y no cueste ira."},
[416005] = {name = "Grabar cinturón - Tiempo preciso", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Sincronización de precisión:\n\n\nEmbate ahora es instantáneo, pero tiene un tiempo de reutilización de 6 s."},
[416008] = {name = "Grabar pantalones - Aflicción eterna", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Aflicción eterna:\n\n\nDrenar vida, Drenar alma, Descarga de las Sombras, Cuchilla de las Sombras, Dolor abrasador, Incinerar y Poseer restablecen la duración de tu Corrupción sobre el objetivo al máximo."},
[416009] = {name = "Grabar pechera - Tácticas demoníacas", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Tácticas demoníacas:\n\n\nAumenta un 10% la probabilidad de que tú y tu mascota asesten un golpe crítico cuerpo a cuerpo y con hechizos."},
[416014] = {name = "Grabar botas - Conocimiento demoníaco", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Conocimiento demoníaco:\n\n\nAumenta tu daño y sanación con hechizos por un valor equivalente a un 3% de la suma total del aguante más el intelecto de tu mascota demoníaca."},
[416015] = {name = "Grabar brazales - Incinerar", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Incinerar:\n\n\nQuema a tu enemigo, inflige de [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] a [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] p. de daño y aumenta todo el daño de Fuego que infliges un 40% durante los próximos 15 s."},
[416017] = {name = "Grabar botas - Danza de los malvados", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Danza de los malvados:\n\n\nTú y tu mascota demoníaca obtienen una probabilidad de esquivar equivalente a un 70% de tu probabilidad de golpe crítico con hechizos cada vez que asestas un golpe crítico a un enemigo, y los dos recuperan un 2% del maná máximo."},
[416028] = {name = "Grabar botas - Escudo sacro", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Escudo sacro:\n\n\nCada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante un máximo de 6 s. Además, provoca que tu Destello de Luz sane a los objetivos con Escudo sacro un 100% más durante 12 s. No pueden obtener este efecto más de una vez cada 6 s. Dura 1 min. Solo un objetivo puede tener este efecto a la vez."},
[416031] = {name = "Grabar botas - El arte de la guerra", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa El arte de la guerra:\n\n\nTus golpes críticos cuerpo a cuerpo reducen el tiempo de reutilización restante de Exorcismo en 2 s y el costo de maná de Exorcismo un 80%."},
[416035] = {name = "Grabar botas - Custodiado por la Luz", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Custodiado por la Luz:\n\n\nCada vez que golpeas a un objetivo con tu arma cuerpo a cuerpo, obtienes un 5% de tu maná máximo cada 3 s durante 15 s, pero tus hechizos de sanación sanan un 50% menos durante esta regeneración de maná."},
[416037] = {name = "Grabar pantalones - Maestría en auras", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Maestría en auras:\n\n\nProvoca que tu Aura de concentración haga inmunes ante los efectos de silencio e interrupción a todos los objetivos afectados y mejore el efecto del resto de las auras un 100%. Dura 6 s."},
[416042] = {name = "Grabar pechera - Supervivencia del más fuerte", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Supervivencia del más fuerte:\n\n\nReduce un 6% la probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo y reduce un 10% todo el daño recibido. El daño recibido se reduce un 10% más cuando estás en Forma de oso o Forma de oso temible."},
[416044] = {name = "Grabar guantes - Fuego solar", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Fuego solar:\n\n\nQuema al enemigo e inflige de [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] a [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza, además de [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza extra durante 12 s.\n\n Además, mientras estás en Forma de oso, Forma felina o Forma de oso temible, tu Fuego lunar es reemplazado por Fuego solar (oso) o Fuego solar (felino). Este hechizo se beneficia de todos los efectos vinculados con Fuego lunar y los activa.\n\n Fuego solar (oso)\nQuema al enemigo e inflige de [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] a [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza, además de [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza extra durante 12 s.\n\n Fuego solar (felino)\nQuema al enemigo e inflige de [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] a [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza, además de [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza extra durante 12 s. Otorga 1 p. de combo."},
[416049] = {name = "Grabar pantalones - Lacerar", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa\n Lacerar:\n\n\nLacera al objetivo enemigo y hace que sangre por [(9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) * 20 / 100 * 5] p. de daño durante 15 s más un 20% de daño con arma por aplicación existente de Lacerar en el objetivo. Genera una gran cantidad de amenaza. Este efecto se acumula hasta 5 veces en el mismo objetivo."},
[416050] = {name = "Grabar pechera - Semilla viviente", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Semilla viviente:\n\n\nCuando haces una sanación crítica a tu objetivo con cualquier hechizo de sanación no periódico, plantas una Semilla viviente en el objetivo con un 50% de la cantidad sanada. La Semilla viviente florecerá la próxima vez que el objetivo reciba daño o una sanación no periódica. Dura 15 s."},
[416051] = {name = "Grabar brazales - Fuegos de Elune", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Fuegos de Elune:\n\n\nAlgunos de tus hechizos y habilidades extienden la duración de tus efectos de daño y sanación con el tiempo en el objetivo:\n\n Fuego estelar extiende 6 s la duración de Fuego lunar.\n Cólera extiende 3 s la duración de Fuego solar.\n Recrecimiento extiende 6 s la duración de Rejuvenecimiento.\n Triturar extiende 2 s la duración de Destripar.\n\n Cada efecto solo se puede extender hasta completar su duración inicial."},
[416054] = {name = "Grabar cinturón - Oleada de poder", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Oleada de poder:\n\n\nCada vez que Choque de llamas inflige daño, tiene un 5% de probabilidad de restablecer el tiempo de reutilización de Ráfaga de lava y Cadena de relámpagos, y de hacer que el próximo lanzamiento de Ráfaga de lava o Cadena de relámpagos en 10 s sea instantáneo. Cada vez que Mareas Vivas sana, tiene un 5% de probabilidad de hacer que tu siguiente Sanación en cadena en 10 s sea instantáneo. Además, cada 5 s obtienes maná equivalente a un 15% de tu intelecto."},
[416055] = {name = "Grabar yelmo - Maña mental", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Maña mental:\n\n\nInfligir daño con Golpe de tormenta aumenta tu poder de ataque una cantidad equivalente al 150% de tu intelecto, y aumenta el daño de tus hechizos una cantidad equivalente al 35% de tu poder de ataque total durante 30 s."},
[416057] = {name = "Grabar pechera - Lluvia de sanación", additional_info = "Hechizo de 3 seg\nRequiere Pecho, Pecho\n[q]Graba tu pechera o toga con la runa Lluvia de sanación:\n\n\nSelecciona el área de 15 m alrededor del jugador objetivo y sana [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] p. de salud por s a todos los miembros del grupo del jugador objetivo."},
[416062] = {name = "Grabar capa - Coherencia", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa Coherencia:\n\n\nHace que la efectividad de tu Sanación en cadena solo se reduzca un 35% por salto y que la efectividad de Cadena de relámpagos solo se reduzca un 20% por salto. Además, hace que ambas salten a 1 objetivo más."},
[416066] = {name = "Grabar yelmo - Quemar", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Quemar:\n\n\nTu Choque de llamas ahora golpea a un máximo de 5 objetivos, dura 6 s más e inflige un 100% más de daño. Además, mientras tu arma equipada en la mano derecha esté imbuida con Arma Lengua de Fuego, tu daño con hechizos aumenta una cantidad equivalente al 150% de tu intelecto."},
[416081] = {name = "Coherencia", additional_info = "[q]Obtienes la habilidad Coherencia:\n\n\nHace que la efectividad de tu Sanación en cadena solo se reduzca un 35% por salto y que la efectividad de Cadena de relámpagos solo se reduzca un 20% por salto. Además, hace que ambas salten a 1 objetivo más."},
[416083] = {name = "Grabar yelmo - Reflejos felinos", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Reflejos felinos:\n\n\nAumenta un 20% tu probabilidad de esquivar y un 9% la de tu mascota. Además, reduce un 50% el tiempo de reutilización de tu habilidad Golpe lateral."},
[416084] = {name = "Grabar cinturón - Aspecto de la víbora", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Aspecto de la víbora:\n\n\nEl cazador asume el aspecto de la víbora, lo que hace que tus ataques automáticos cuerpo a cuerpo y a distancia regeneren maná, pero reduce el daño total un 10%. Además, obtienes un 10% del maná máximo cada 3 s. El maná obtenido se basa en la velocidad de tu arma. Solo puede haber un aspecto activo cada vez."},
[416085] = {name = "Grabar yelmo - Bloquear y cargar", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Bloquear y cargar:\n\n\nCada vez que colocas una trampa, tu próxima habilidad de Disparo (salvo Disparo de dispersión) en 20 s no cuesta maná ni incurre en tiempo de reutilización."},
[416086] = {name = "Grabar cinturón - Especialista cuerpo a cuerpo", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Especialista cuerpo a cuerpo:\n\n\nTu Golpe de raptor ahora es instantáneo, y Mordedura de mangosta y Golpe de raptor tienen un 40% de probabilidad de reiniciar los tiempos de reutilización de Mordedura de mangosta y Golpe de raptor con cada ataque."},
[416087] = {name = "Grabar cinturón - Disparo mortal", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Disparo mortal:\n\n\nTratas de rematar a un objetivo herido con un disparo a larga distancia que inflige un 100% de daño con arma y luego [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos."},
[416089] = {name = "Grabar botas - Golpe de dracoleón", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Golpe de dracoleón:\n\n\nReemplaza tu habilidad Picadura de dracoleón por Golpe de dracoleón, un golpe brutal que inflige un 140% de daño de arma y hace que el objetivo sangre y reciba daño con el tiempo.\n\n Golpe de dracoleón requiere que tengas el talento Picadura de dracoleón y reemplaza las habilidades de Picadura de dracoleón que se encuentran en el libro de hechizos de Supervivencia."},
[416090] = {name = "Grabar yelmo - Matanza rápida", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Matanza rápida:\n\n\nReduce el tiempo de reutilización de Fuego rápido un 80%. Fuego rápido ahora también otorga un 40% más de velocidad de ataque cuerpo a cuerpo, y tu siguiente habilidad de Disparo en un período de 20 s después de matar a un objetivo que otorga experiencia u honor inflige un 20% de daño extra."},
[416091] = {name = "Grabar pantalones - Instrucción de francotirador", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Instrucción de francotirador:\n\n\nAumenta un 2% la probabilidad de golpe crítico de tus habilidades de Disparo mientras no te hayas movido durante los últimos 2 s, y se acumula por segundo hasta un máximo de 5 veces. Al alcanzar 2 acumulaciones o más, tu Disparo de puntería se vuelve instantáneo. Si te mueves, perderás 1 acumulación por segundo."},
[416093] = {name = "Grabar brazales - Furia de raptor", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Furia de raptor:\n\n\nGolpe de raptor aumenta un 15% el daño infligido por Golpe de raptor y Mordedura de mangosta durante 30 s. Se acumula hasta 5 veces. Las aplicaciones posteriores no extienden la duración de este efecto."},
