[416244] = {name = "Sanación en cadena", additional_info = "Alcance de 40 m\nInstante\n[q]Restablece 166 to 191 p. de salud al objetivo aliado y salta para sanar objetivos adicionales cercanos. Si se lanza sobre un miembro del grupo, la sanación solo saltará hacia otros miembros del grupo. Cada sanación conserva un 50% de la efectividad con cada salto. Sana a un total de 3 objetivos."},
[416245] = {name = "Sanación en cadena", additional_info = "Alcance de 40 m\nInstante\n[q]Restablece 210 to 240 p. de salud al objetivo aliado y salta para sanar objetivos adicionales cercanos. Si se lanza sobre un miembro del grupo, la sanación solo saltará hacia otros miembros del grupo. Cada sanación conserva un 50% de la efectividad con cada salto. Sana a un total de 3 objetivos."},
[416246] = {name = "Sanación en cadena", additional_info = "Alcance de 40 m\nInstante\n[q]Restablece 283 to 324 p. de salud al objetivo aliado y salta para sanar objetivos adicionales cercanos. Si se lanza sobre un miembro del grupo, la sanación solo saltará hacia otros miembros del grupo. Cada sanación conserva un 50% de la efectividad con cada salto. Sana a un total de 3 objetivos."},
[416247] = {name = "Ola de sanación", additional_info = "Alcance de 40 m\nInstante\n[q]Restablece 18 to 25 p. de salud a un objetivo aliado."},
