[416288] = {name = "Combinar trozos de mapa", additional_info = "Hechizo de 3 seg\nComponentes:\nTrozo superior derecho de mapa , Trozo superior izquierdo de mapa , Trozo inferior derecho de mapa , Trozo inferior izquierdo de mapa\n[q]Combina este objeto con 3 trozos más para completar el mapa."},
