[416304] = {name = "Desenterrar tesoro", additional_info = "Hechizo de 3 seg 1 min de reutilización\n[q]Desentierra un tesoro en la ubicación marcada"},
[416316] = {name = "Ola de sanación", additional_info = "Alcance de 40 m\nInstante\n[q]Restablece 34 to 43 p. de salud a un objetivo aliado."},
