[417045] = {name = "Furia del tigre", additional_info = "{Instante} {30 seg de reutilización}\n[q]Aumenta un 15% el daño infligido durante 6 s y te otorga 60 p. de energía al instante."},
[417046] = {name = "Rey de la selva", additional_info = "[q]Furia del tigre ahora aumenta todo el daño físico que infliges un 15% en lugar de un monto fijo, y te otorga 60 p. de energía de forma instantánea. Ya no tiene un tiempo de reutilización global, sino que ahora tiene su propio tiempo de reutilización de 30 s. Además, Furia del tigre persistirá al estar en Forma felina, pero se cancelará al cambiar a Forma de oso o Forma de oso temible."},
[417051] = {name = "Reacción natural", additional_info = "[q]Aumenta un 0% tu probabilidad de esquivar y regeneras 5 p. de ira cada vez que esquivas mientras estás en Forma de oso o Forma de oso temible, 10 p. de energía mientras estás en Forma felina o un 1% de tu maná máximo mientras estás en otra forma."},
