[417123] = {name = "Restauración mejorada", additional_info = "[q]Ahora tus hechizos Rejuvenecimiento y Recrecimiento pueden estar activos sobre objetivos afectados por el Rejuvenecimiento o Recrecimiento de otro Druida."},
[417135] = {name = "Vientos huracanados", additional_info = "[q]Aumenta un 100% el daño infligido por tu Huracán, ya no tiene tiempo de reutilización y su costo de maná se reduce un 60%."},
[417141] = {name = "Rabia", additional_info = "{Instante} {3 min de reutilización}\n[q]Cuando se activa, esta habilidad provoca que tu habilidad Destrozar (oso) y Lacerar golpeen a un máximo de 3 objetivos, que Lacerar no cueste ira y que Destrozar (oso) no tenga tiempo de reutilización, además de reducir un 50% el costo de energía de todas tus habilidades de Forma felina. Dura 15 s. Requiere Forma de oso, Forma felina o Forma de oso temible para activarse.\n\n Elimina el efecto de miedo y te hace inmune al miedo mientras dura."},
[417145] = {name = "Cornada", additional_info = "[q]Golpear a un objetivo con Lacerar, Flagelo o Magullar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Destrozar (oso) y de otorgar 10 p. de ira. Golpear a un objetivo con Destrozar (felina) o Triturar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Furia del tigre.\n(Probabilidad de que accione: 15%, 100ms de reutilización)"},
[417146] = {name = "Floración", additional_info = nil},
[417147] = {name = "Floración", additional_info = "Alcance de 100 m\n{Instante} {10 seg de reutilización}\n[q]Restablece [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] p. de salud a todos los miembros del grupo o banda en un radio de 15 m del área seleccionada cada 5 s durante 15 s."},
[417148] = {name = "Floración", additional_info = "Alcance de 100 m\nInstante\n[q]Restablece [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] p. de salud a todos los miembros del grupo en un radio de 15 m del objetivo."},
[417149] = {name = "Floración", additional_info = "[q]Tu Alivio presto ahora también provoca Floración, que sana [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] p. de salud cada 1 s a todos los miembros del grupo en un radio de 15 m de la ubicación del objetivo de Alivio presto durante 15 s."},
[417157] = {name = "Oleada de estrellas", additional_info = "Alcance de 30 m\n{Instante} {6 seg de reutilización}\n[q]Lanza oleadas de energías estelares que infligen de [248 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1 * 1)] a [304 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1 * 1)] p. de daño Arcano y aumenta el daño infligido por tus próximos lanzamientos de 1 Fuego estelar en un 80 % por 15 s.\n\n Oleada de estrellas se beneficia de la mayor parte de los talentos y efectos que se activan o benefician de Cólera o Fuego estelar y también los activa."},
[417159] = {name = "Renovación", additional_info = "{Instante} {1.5 min de reutilización}\n[q]Te sanas al instante un 30% de tu salud máxima. Se puede utilizar en todas las formas."},
