[425151] = {name = "S03 - Rogue 25 Quest Reward", additional_info = nil},
[425168] = {name = "Oleada Arcana", additional_info = "[q]Obtienes la habilidad Oleada Arcana:\n\n\nDesata todo tu maná restante en forma de una oleada de energía concentrada contra el objetivo y le inflige entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 226 / 100] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 264 / 100] p. de daño Arcano que aumenta hasta un 300% según tu maná restante. Después se activa tu regeneración de maná normal y aumenta un 300% durante 8 s."},
[425169] = {name = "Venas heladas", additional_info = "[q]Obtienes la habilidad Venas heladas:\n\n\nAcelera tu lanzamiento de hechizos, lo que aumenta la velocidad con la que lanzas hechizos un 20% y reduce un 100% el retraso sufrido por los ataques dañinos mientras lanzas hechizos. Dura 20 s."},
[425170] = {name = "Grabar pantalones - Venas heladas", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Venas heladas:\n\n\nAcelera tu lanzamiento de hechizos, lo que aumenta la velocidad con la que lanzas hechizos un 20% y reduce un 100% el retraso sufrido por los ataques dañinos mientras lanzas hechizos. Dura 20 s."},
[425171] = {name = "Grabar pantalones - Oleada Arcana", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Oleada Arcana:\n\n\nDesata todo tu maná restante en forma de una oleada de energía concentrada contra el objetivo y le inflige entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 226 / 100] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 264 / 100] p. de daño Arcano que aumenta hasta un 300% según tu maná restante. Después se activa tu regeneración de maná normal y aumenta un 300% durante 8 s."},
[425187] = {name = "Preservación cronoestática", additional_info = "[q]Obtienes la habilidad Preservación cronoestática:\n\n\nCombina magia Arcana, de Fuego y de Escarcha para congelar energía cronomántica y guardarla para más adelante. Puedes almacenar esta energía durante un máximo de 20 s, hasta que haga combustión y se consuma. Cuando se libera, sana de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 220 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 330 / 100] p. de salud a un objetivo aliado.\n\n Este hechizo se considera Arcano, de Fuego y de Escarcha para las interacciones con otros hechizos, talentos y efectos."},
[425189] = {name = "Grabar botas - Preservación cronoestática", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Preservación cronoestática:\n\n\nCombina magia Arcana, de Fuego y de Escarcha para congelar energía cronomántica y guardarla para más adelante. Puedes almacenar esta energía durante un máximo de 20 s, hasta que haga combustión y se consuma. Cuando se libera, sana de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 220 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 330 / 100] p. de salud a un objetivo aliado.\n\n Este hechizo se considera Arcano, de Fuego y de Escarcha para las interacciones con otros hechizos, talentos y efectos."},
