[425280] = {name = "Esperanza renovada", additional_info = "[q]El efecto de tus sanaciones de Sanación relámpago, Sanación inferior, Sanar, Sanación superior y Penitencia aumenta un 20% cuando se lanzan sobre objetivos con Alma debilitada."},
[425284] = {name = "Espíritu del redentor", additional_info = "{Instante} {2 min de reutilización}\n[q]Actívalo para convertirte en un Espíritu redentor durante 10 s. Mientras estés en esta forma, puedes lanzar cualquier hechizo de sanación sin costo, pero no puedes moverte, atacar, ser atacado o ser objetivo de ningún hechizo o efecto. Requiere el talento Espíritu redentor para activarse, y no serás Espíritu redentor al morir."},
[425285] = {name = "Invocar elemental pútrido", additional_info = "Alcance de 10 m\nInstante\n[q]Llama los espíritus de los elementos."},
[425294] = {name = "Dispersión", additional_info = "{Instante} {2 min de reutilización}\n[q]Te conviertes en energía de las Sombras pura y reduces todo el daño recibido un 90%. No puedes atacar ni lanzar hechizos, pero regeneras un 6% de maná cada 1 s durante 6 s. Dispersión se puede lanzar mientras estás aturdido, asustado o silenciado, quita todos los efectos de frenado y de reducción del movimiento al lanzarlo y te hace inmune a ellos mientras dura."},
[425302] = {name = "Renovar potenciado", additional_info = "[q]Obtienes la habilidad Renovar potenciado:\n\n\nAhora tu Renovar sana una vez más inmediatamente cuando se aplica, y obtiene un 15% más de beneficios cada vez que sana con tus efectos que potencian sanaciones.\n\n Además, tu Renovar ahora puede estar activo sobre objetivos afectados por el Renovar de otro sacerdote."},
[425303] = {name = "Esperanza renovada", additional_info = "[q]Obtienes la habilidad Esperanza renovada:\n\n\nEl efecto de tus sanaciones de Sanación relámpago, Sanación inferior, Sanar, Sanación superior y Penitencia aumenta un 20% cuando se lanzan sobre objetivos con Alma debilitada."},
[425304] = {name = "Espíritu del redentor", additional_info = "[q]Obtienes la habilidad Espíritu del redentor:\n\n\nActívalo para convertirte en un Espíritu redentor durante 10 s. Mientras estés en esta forma, puedes lanzar cualquier hechizo de sanación sin costo, pero no puedes moverte, atacar, ser atacado o ser objetivo de ningún hechizo o efecto. Requiere el talento Espíritu redentor para activarse, y no serás Espíritu redentor al morir."},
[425307] = {name = "Dispersión", additional_info = "[q]Obtienes la habilidad Dispersión:\n\n\nTe conviertes en energía de las Sombras pura y reduces todo el daño recibido un 90%. No puedes atacar ni lanzar hechizos, pero regeneras un 6% de maná cada 1 s durante 6 s. Dispersión se puede lanzar mientras estás aturdido, asustado o silenciado, quita todos los efectos de frenado y de reducción del movimiento al lanzarlo y te hace inmune a ellos mientras dura."},
[425309] = {name = "Grabar cinturón - Renovar potenciado", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Renovar potenciado:\n\n\nAhora tu Renovar sana una vez más inmediatamente cuando se aplica, y obtiene un 15% más de beneficios cada vez que sana con tus efectos que potencian sanaciones.\n\n Además, tu Renovar ahora puede estar activo sobre objetivos afectados por el Renovar de otro sacerdote."},
[425310] = {name = "Grabar cinturón - Esperanza renovada", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Esperanza renovada:\n\n\nEl efecto de tus sanaciones de Sanación relámpago, Sanación inferior, Sanar, Sanación superior y Penitencia aumenta un 20% cuando se lanzan sobre objetivos con Alma debilitada."},
[425312] = {name = "Grabar botas - Espíritu del redentor", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Espíritu del redentor:\n\n\nActívalo para convertirte en un Espíritu redentor durante 10 s. Mientras estés en esta forma, puedes lanzar cualquier hechizo de sanación sin costo, pero no puedes moverte, atacar, ser atacado o ser objetivo de ningún hechizo o efecto. Requiere el talento Espíritu redentor para activarse, y no serás Espíritu redentor al morir."},
[425314] = {name = "Grabar botas - Dispersión", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa\n Dispersión:\n\n\nTe conviertes en energía de las Sombras pura y reduces todo el daño recibido un 90%. No puedes atacar ni lanzar hechizos, pero regeneras un 6% de maná cada 1 s durante 6 s. Dispersión se puede lanzar mientras estás aturdido, asustado o silenciado, quita todos los efectos de frenado y de reducción del movimiento al lanzarlo y te hace inmune a ellos mientras dura."},
[425321] = {name = "Anillos del Bosque del Ocaso - Entregar runa", additional_info = nil},
[425336] = {name = "Ira del chamán", additional_info = "{Instante} {1 min de reutilización}\n[q]Reduce un 20% todo el daño que recibes y regeneras una cantidad de maná equivalente al 5% de tu maná máximo por segundo durante 15 s. Los miembros de tu grupo y banda en un radio de 40 m también recibirán un 18% del maná que recibas con este efecto."},
[425339] = {name = "Explosión de arrabio", additional_info = "18% del maná base\n{Instante} {6 seg de reutilización}\n[q]Hasta 10 enemigos en un cono frente a ti reciben entre [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Attack power] y [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Attack power] p. de daño de Fuego. Esta habilidad genera una alta cantidad de amenaza. El daño periódico de Choque de llamas tiene un 10% de probabilidad de reiniciar el tiempo de reutilización de Explosión de arrabio."},
[425340] = {name = "Explosión de arrabio", additional_info = "[q]Obtienes la habilidad Explosión de arrabio:\n\n\nHasta 10 enemigos en un cono frente a ti reciben entre [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Attack power] y [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Attack power] p. de daño de Fuego. Esta habilidad genera una alta cantidad de amenaza. El daño periódico de Choque de llamas tiene un 10% de probabilidad de reiniciar el tiempo de reutilización de Explosión de arrabio."},
[425341] = {name = "Lobo fantasmal superior", additional_info = "[q]Obtienes la habilidad Lobo fantasmal superior:\n\n\nAhora puedes usar tu habilidad Lobo fantasmal en interiores, y reduce todo el daño que recibes un 10% mientras está activa."},
[425343] = {name = "Grabar pantalones - Lobo fantasmal superior", additional_info = "Hechizo de 3 seg\nRequiere Pantalones\n[q]Graba tus pantalones con la runa Lobo fantasmal superior:\n\n\nAhora puedes usar tu habilidad Lobo fantasmal en interiores, y reduce todo el daño que recibes un 10% mientras está activa."},
[425344] = {name = "Grabar guantes - Explosión de arrabio", additional_info = "Hechizo de 3 seg\nRequiere [Gloves][q]Graba tus guantes con la runa Explosión de arrabio:\n\n\nHasta 10 enemigos en un cono frente a ti reciben entre [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Attack power] y [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Attack power] p. de daño de Fuego. Esta habilidad genera una alta cantidad de amenaza. El daño periódico de Choque de llamas tiene un 10% de probabilidad de reiniciar el tiempo de reutilización de Explosión de arrabio."},
[425412] = {name = "Asalto frenético", additional_info = "[q]Mientras blandes un arma de dos manos, tu velocidad de ataque aumenta un 40% y tus golpes cuerpo a cuerpo exitosos generan 2 p. más de ira, o 4 p. más de ira si son golpes críticos."},
[425415] = {name = "Enfurecer", additional_info = nil},
[425418] = {name = "Consumido por la ira", additional_info = "[q]Te enfurece (lo que activa las habilidades que requieren ese estado) durante 12 s después de que superas los 60 p. de ira. Además, Torbellino también golpea con armas cuerpo a cuerpo de mano izquierda cuando estás enfurecido."},
[425421] = {name = "Belisario", additional_info = "[q]Tus habilidades Cargar, Interceptar e Intervenir ahora se pueden usar en combate y en cualquier actitud. Además, eliminarán todos los efectos de reducción de movimiento cuando se activan."},
[425428] = {name = "Golpe rápido", additional_info = "[q]Obtienes la habilidad Golpe rápido:\n\n\nUn ataque imprudente instantáneo cuerpo a cuerpo con tu arma de dos manos inflige de (Attack power * 30 / 100) a (Attack power * 40 / 100) p. de daño físico. Esta habilidad se beneficia de todos los efectos vinculados con Golpe heroico y los activa."},
[425429] = {name = "Arremetida enfurecida", additional_info = "[q]Obtienes la habilidad Arremetida enfurecida:\n\n\nUn golpe feroz que inflige un 115% de daño con arma, pero que solo se puede usar cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas. Las demás habilidades cuerpo a cuerpo que se usan cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas reducen 1 s el tiempo de reutilización restante de Arremetida enfurecida."},
[425430] = {name = "Belisario", additional_info = "[q]Obtienes la habilidad Belisario:\n\n\nTus habilidades Cargar, Interceptar e Intervenir ahora se pueden usar en combate y en cualquier actitud. Además, eliminarán todos los efectos de reducción de movimiento cuando se activan."},
[425440] = {name = "Consumido por la ira", additional_info = "[q]Obtienes la habilidad Consumido por la ira:\n\n\nTe enfurece (lo que activa las habilidades que requieren ese estado) durante 12 s después de que superas los 60 p. de ira. Además, Torbellino también golpea con armas cuerpo a cuerpo de mano izquierda cuando estás enfurecido."},
[425442] = {name = "Asalto frenético", additional_info = "[q]Obtienes la habilidad Asalto frenético:\n\n\nMientras blandes un arma de dos manos, tu velocidad de ataque aumenta un 40% y tus golpes cuerpo a cuerpo exitosos generan 2 p. más de ira, o 4 p. más de ira si son golpes críticos."},
