[426178] = {name = "Grabar cinturón - Vaina de Luz", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Vaina de Luz:\n\n\nInfligir daño con tu arma cuerpo a cuerpo aumenta tu daño con hechizos una cantidad equivalente al 30% de tu poder de ataque durante 1 min."},
[426179] = {name = "Infusión de Luz", additional_info = "[q]Obtienes la habilidad Infusión de Luz:\n\n\nAumenta un 50% el daño y la sanación realizados por tu Choque sagrado, reduce el tiempo de reutilización de Choque sagrado a 6 s, y tus golpes críticos con Choque sagrado restablecen su costo de maná y reducen 3 s su tiempo de reutilización restante."},
[426180] = {name = "Grabar cinturón - Infusión de Luz", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Infusión de Luz:\n\n\nAumenta un 50% el daño y la sanación realizados por tu Choque sagrado, reduce el tiempo de reutilización de Choque sagrado a 6 s, y tus golpes críticos con Choque sagrado restablecen su costo de maná y reducen 3 s su tiempo de reutilización restante."},
