[428739] = {name = "Congelación profunda", additional_info = "{9% del maná base} {Alcance de 30 m}\n{Instante} {30 seg de reutilización}\n[q]Aturde al objetivo durante 5 s. Solo se puede usar con objetivos congelados. Inflige de [462 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] a [538 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] p. de daño a los objetivos inmunes de forma permanente al aturdimiento."},
[428740] = {name = "Charco corrosivo", additional_info = nil},
[428741] = {name = "Armadura de arrabio", additional_info = "28% del maná base\nInstante\n[q]Inflige [10 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)] p. de daño de Fuego al recibir un golpe, aumenta un 5% tu probabilidad de golpe crítico con hechizos y reduce un 5% la probabilidad de recibir un golpe crítico. Solo puede haber un hechizo de armadura activo sobre el mago a la vez. Dura 30 min."},
