[428920] = {name = "Congelación profunda", additional_info = nil},
[429125] = {name = "Venas heladas", additional_info = "3% del maná base\n{Instante} {3 min de reutilización}\n[q]Acelera tu lanzamiento de hechizos, lo que aumenta la velocidad con la que lanzas hechizos un 20% y reduce un 100% el retraso sufrido por los ataques dañinos mientras lanzas hechizos. Dura 20 s."},
[429133] = {name = "Santuario mejorado", additional_info = "[q]Aumenta un 100% el daño que previene tu Bendición de salvaguardia, y aumenta el daño que inflige tu Bendición de salvaguardia un monto equivalente al 20% de tu valor de bloqueo con escudo."},
[429139] = {name = "Cólera", additional_info = "[q]Ahora tu daño de Consagración puede ser un golpe crítico, y el daño de tus hechizos Exorcismo, Choque sagrado, Cólera sagrada y Consagración obtiene una probabilidad de golpe crítico equivalente a tu probabilidad de golpe crítico cuerpo a cuerpo."},
[429142] = {name = "Fanatismo", additional_info = "[q]Aumenta un 18% tu probabilidad de golpe crítico con hechizos Sagrados. Además, tus hechizos de sanación crítica sanan al objetivo un 60% de la cantidad sanada durante 12 s."},
[429144] = {name = "Poder purificador", additional_info = "[q]Reduce un 50% el tiempo de reutilización de Exorcismo y Cólera sagrada. Cólera sagrada ahora se puede lanzar a cualquier objetivo y aturdirá a objetivos no-muertos y demoníacos durante 2 s."},
[429145] = {name = "Cólera sagrada", additional_info = "645 p. de manáHechizo de 2 seg 1 min de reutilización\n[q]Lanza descargas de poder sagrado en todas direcciones, inflige 368 to 435 p. de daño Sagrado a todos los objetivos en un radio de 20 m y aturde a los objetivos del tipo demonios y no-muertos durante 2 s."},
[429146] = {name = "Cólera sagrada", additional_info = "805 p. de manáHechizo de 2 seg 1 min de reutilización\n[q]Lanza descargas de poder sagrado en todas direcciones, inflige 490 to 576 p. de daño Sagrado a todos los objetivos en un radio de 20 m y aturde a los objetivos del tipo demonios y no-muertos durante 2 s."},
[429147] = {name = "Aturdir", additional_info = nil},
[429151] = {name = "Martillo de cólera", additional_info = "{12% del maná base} {Alcance de 30 m}\nInstante\n[q]Lanza un martillo que golpea al enemigo y le inflige de [300 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) + 0.15 * Spell power + 0.15 * Attack power] a [300 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) + 0.15 * Spell power + 0.15 * Attack power] p. de daño Sagrado. Solo se puede usar sobre enemigos que tienen como máximo un 20% de salud."},
[429152] = {name = "Martillo de cólera mejorado", additional_info = "[q]El lanzamiento de Martillo de cólera ahora es instantáneo y su tiempo de reutilización se restablece cada vez que daña a un enemigo con menos del 10% de salud."},
