[429242] = {name = "Grabar brazales - Gracia de la Luz", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Gracia de Luz:\n\n\nTu hechizo Luz Sagrada reduce 0.5 s el tiempo de lanzamiento de tu próxima Luz Sagrada. Dura 15 s."},
[429243] = {name = "Gracia de Luz", additional_info = "[q]Obtienes la habilidad Gracia de Luz:\n\n\nTu hechizo Luz Sagrada reduce 0.5 s el tiempo de lanzamiento de tu próxima Luz Sagrada. Dura 15 s."},
[429245] = {name = "Santuario mejorado", additional_info = "[q]Obtienes la habilidad Santuario mejorado:\n\n\nAumenta un 100% el daño que previene tu Bendición de salvaguardia, y aumenta el daño que inflige tu Bendición de salvaguardia un monto equivalente al 20% de tu valor de bloqueo con escudo."},
[429247] = {name = "Grabar yelmo - Santuario mejorado", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Santuario mejorado:\n\n\nAumenta un 100% el daño que previene tu Bendición de salvaguardia, y aumenta el daño que inflige tu Bendición de salvaguardia un monto equivalente al 20% de tu valor de bloqueo con escudo."},
[429248] = {name = "Cólera", additional_info = "[q]Obtienes la habilidad Cólera:\n\n\nAhora tu daño de Consagración puede ser un golpe crítico, y el daño de tus hechizos Exorcismo, Choque sagrado, Cólera sagrada y Consagración obtiene una probabilidad de golpe crítico equivalente a tu probabilidad de golpe crítico cuerpo a cuerpo."},
[429249] = {name = "Grabar yelmo - Cólera", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Cólera:\n\n\nAhora tu daño de Consagración puede ser un golpe crítico, y el daño de tus hechizos Exorcismo, Choque sagrado, Cólera sagrada y Consagración obtiene una probabilidad de golpe crítico equivalente a tu probabilidad de golpe crítico cuerpo a cuerpo."},
[429250] = {name = "Fanatismo", additional_info = "[q]Obtienes la habilidad Fanatismo:\n\n\nAumenta un 18% tu probabilidad de golpe crítico con hechizos Sagrados. Además, tus hechizos de sanación crítica sanan al objetivo un 60% de la cantidad sanada durante 12 s."},
[429251] = {name = "Grabar yelmo - Fanatismo", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Fanatismo:\n\n\nAumenta un 18% tu probabilidad de golpe crítico con hechizos Sagrados. Además, tus hechizos de sanación crítica sanan al objetivo un 60% de la cantidad sanada durante 12 s."},
[429254] = {name = "Poder purificador", additional_info = "[q]Obtienes la habilidad Poder purificador:\n\n\nReduce un 50% el tiempo de reutilización de Exorcismo y Cólera sagrada. Cólera sagrada ahora se puede lanzar a cualquier objetivo y aturdirá a objetivos no-muertos y demoníacos durante 2 s."},
[429255] = {name = "Grabar brazales - Poder purificador", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Poder purificador:\n\n\nReduce un 50% el tiempo de reutilización de Exorcismo y Cólera sagrada. Cólera sagrada ahora se puede lanzar a cualquier objetivo y aturdirá a objetivos no-muertos y demoníacos durante 2 s."},
[429259] = {name = "Martillo de cólera mejorado", additional_info = "[q]Obtienes la habilidad Martillo de cólera mejorado:\n\n\nEl lanzamiento de Martillo de cólera ahora es instantáneo y su tiempo de reutilización se restablece cada vez que daña a un enemigo con menos del 10% de salud."},
[429261] = {name = "Grabar brazales - Martillo de cólera mejorado", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Martillo de cólera:\n\n\nEl lanzamiento de Martillo de cólera ahora es instantáneo y su tiempo de reutilización se restablece cada vez que daña a un enemigo con menos del 10% de salud."},
[429283] = {name = "Pandemia", additional_info = "[q]Obtienes la habilidad Pandemia:\n\n\nEl daño periódico de tus habilidades Corrupción, Aflicción inestable, Maldición de agonía, Inmolar, Maldición del Apocalipsis y Succionar vida ahora pueden ser golpes críticos."},
[429303] = {name = "Congelación profunda", additional_info = "[q]Obtienes la habilidad Congelación profunda:\n\n\nAturde al objetivo durante 5 s. Solo se puede usar con objetivos congelados. Inflige de [462 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] a [538 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] p. de daño a los objetivos inmunes de forma permanente al aturdimiento."},
[429304] = {name = "Grabar yelmo - Congelación profunda", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Congelación profunda:\n\n\nAturde al objetivo durante 5 s. Solo se puede usar con objetivos congelados. Inflige de [462 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] a [538 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] p. de daño a los objetivos inmunes de forma permanente al aturdimiento."},
[429305] = {name = "Anomalía temporal", additional_info = "[q]Obtienes la habilidad Anomalía temporal:\n\n\nLanza un orbe de energía temporal que avanza lentamente y, cada 2 s, otorga a todos los miembros del grupo cercanos un escudo que absorbe [100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100] p. de daño durante 15 s. El valor de este escudo aumenta si los miembros del grupo se mantienen cerca del orbe."},
[429306] = {name = "Grabar yelmo - Anomalía temporal", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Anomalía temporal:\n\n\nLanza un orbe de energía temporal que avanza lentamente y, cada 2 s, otorga a todos los miembros del grupo cercanos un escudo que absorbe [100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100] p. de daño durante 15 s. El valor de este escudo aumenta si los miembros del grupo se mantienen cerca del orbe."},
[429307] = {name = "Armadura de arrabio", additional_info = "[q]Obtienes la habilidad Armadura de arrabio:\n\n\nInflige [10 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)] p. de daño de Fuego al recibir un golpe, aumenta un 5% tu probabilidad de golpe crítico con hechizos y reduce un 5% la probabilidad de recibir un golpe crítico. Solo puede haber un hechizo de armadura activo sobre el mago a la vez. Dura 30 min."},
[429308] = {name = "Grabar brazales - Armadura de arrabio", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Armadura de arrabio:\n\n\nInflige [10 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)] p. de daño de Fuego al recibir un golpe, aumenta un 5% tu probabilidad de golpe crítico con hechizos y reduce un 5% la probabilidad de recibir un golpe crítico. Solo puede haber un hechizo de armadura activo sobre el mago a la vez. Dura 30 min."},
[429309] = {name = "Grabar brazales - Desplazamiento", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Desplazamiento:\n\n\nTe teletransporta de regreso al último lugar desde donde usaste la Traslación y restablece su tiempo de reutilización. Solo puede usarse durante 10 s después de usar Traslación."},
[429310] = {name = "Descarga de fuego fardo", additional_info = "[q]Obtienes la habilidad Descarga de fuego fardo:\n\n\nLibera una ráfaga de magia en bruto que distorsiona la realidad contra tu enemigo. Inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 280 / 100] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 420 / 100] p. de daño Quimérico. Cada vez que lanzas Descarga de fuego fardo, el daño de tu siguiente Descarga de fuego fardo en 30 s aumentará un 25% y tu espíritu caerá un 20% durante 30 s. Estos dos efectos se acumulan un máximo de 5 veces. Si esto provoca que tu espíritu llegue a 0 p., morirás inmediatamente. Este hechizo tendrá en cuenta la resistencia más baja entre las resistencias Arcana, de Fuego y de Escarcha."},
[429311] = {name = "Grabar brazales - Descarga de fuego fardo", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Descarga de fuego fardo:\n\n\nLibera una ráfaga de magia en bruto que distorsiona la realidad contra tu enemigo. Inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 280 / 100] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 420 / 100] p. de daño Quimérico. Cada vez que lanzas Descarga de fuego fardo, el daño de tu siguiente Descarga de fuego fardo en 30 s aumentará un 25% y tu espíritu caerá un 20% durante 30 s. Estos dos efectos se acumulan un máximo de 5 veces. Si esto provoca que tu espíritu llegue a 0 p., morirás inmediatamente. Este hechizo tendrá en cuenta la resistencia más baja entre las resistencias Arcana, de Fuego y de Escarcha."},
