[429743] = {name = "Explosivos para demoliciones", additional_info = nil},
[429748] = {name = "Golpe rápido", additional_info = "[q]Reemplaza tu habilidad Golpe heroico por Golpe rápido:\n\n\nUn ataque imprudente instantáneo cuerpo a cuerpo con tu arma de dos manos inflige de (Attack power * 30 / 100) a (Attack power * 40 / 100) p. de daño físico. Esta habilidad se beneficia de todos los efectos vinculados con Golpe heroico y los activa."},
[429765] = {name = "Golpe rápido", additional_info = "{20 p. de ira} {Alcance de ataques cuerpo a cuerpo}\nHechizo instantáneo\nRequiere Dos manos\n[q]Un ataque imprudente instantáneo cuerpo a cuerpo con tu arma de dos manos inflige de (Attack power * 30 / 100) a (Attack power * 40 / 100) p. de daño físico. Esta habilidad se beneficia de todos los efectos vinculados con Golpe heroico y los activa."},
[429820] = {name = "Lluvia de estrellas", additional_info = "Alcance de 30 m\nCanalizado (Hechizo de 10 seg)\n[q]Inflige 118 to 132 p. de daño Arcano a los enemigos en un área seleccionada cada 2 s durante 10 s."},
[429821] = {name = "Flecha abrasadora", additional_info = "Alcance de 50 m\nRequiere Arma a distancia\nComponentes:\nAlquitrán\n[q]Dispara una flecha llameante al enemigo e inflige daño con arma más 150 p. Todo daño infligido se basa en la magia del Fuego."},
[429822] = {name = "Rajar", additional_info = "Alcance de 15 m\nSiguiente cuerpo a cuerpo\n[q]Inflige daño normal a un enemigo y a sus aliados cercanos. Afecta hasta a 5 objetivos."},
[429823] = {name = "Fuego lunar", additional_info = "{15% del maná base} {Alcance de 50 m}\nInstante\n[q]Inflige 285 to 315 p. de daño Arcano a un enemigo y luego 71 to 79 p. más de daño cada 3 s durante 12 s."},
[429825] = {name = "Cadena de relámpagos", additional_info = "Alcance de 30 mHechizo de 3 seg 6 seg de reutilización\n[q]Golpea al enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 80 objetivos e inflige mayor daño de Naturaleza a cada objetivo sucesivo."},
[429827] = {name = "Choque", additional_info = "{15% del maná base} {Alcance de 20 m}\n{Instante} {6 seg de reutilización}\n[q]Lanza instantáneamente una descarga de relámpago a un enemigo y le inflige daño de Naturaleza."},
[429836] = {name = "Consagrado por la Luz", additional_info = nil},
[429838] = {name = "Incinerar", additional_info = "{14% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Inflige 60 to 65 p. de daño de fuego a tu objetivo."},
[429856] = {name = "Invocar sable de la noche de las centinelas", additional_info = "Hechizo de 3 seg\n[q]Invoca un sable de la noche de las centinelas de aprendiz. Solo puede usarse en Vallefresno."},
[429857] = {name = "Invocar lobo escolta", additional_info = "Hechizo de 3 seg\n[q]Invoca un lobo escolta de aprendiz. Solo puede usarse en Vallefresno."},
[429863] = {name = "Armadura de batalla de poderío", additional_info = "[q]Aumenta tu probabilidad de golpear un 1%.\n(Probabilidad de que accione: 20%)"},
[429864] = {name = "Armadura de batalla de poderío", additional_info = "[q]Aumenta tu fuerza 12 p.\n(Probabilidad de que accione: 20%)"},
[429865] = {name = "Armadura de batalla de poderío", additional_info = "[q]Mientras Temeridad está activa, tu Ejecutar inflige daño como si tuvieras 5 p. más de ira.\n(Probabilidad de que accione: 20%)"},
[429867] = {name = "Locura del Vacío", additional_info = "Instante\n[q]Desciende hacia la locura, aumenta un 10% la velocidad de ataque y la amenaza que generas durante 10 s."},
[429868] = {name = "Locura del Vacío", additional_info = "Instante\n[q]Desciende hacia la locura, aumenta un 10% el daño con hechizos y la amenaza que generas durante 10 s."},
[429869] = {name = "[q4]Guanteletes de cuero tocados por el Vacío", additional_info = "Hechizo de 45 seg\nComponentes:\nFragmento del Vacío , Guantes de cuero fortalecido\n[q4]Guanteletes de cuero tocados por el Vacío\nSe liga al recogerlo\nÚnico-Equipado: [Void-Touched] (1)Manos Cuero\n70 armadura\n+5 aguante\n+7 intelecto\n+6 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 25\nRequierePeletería\n(100)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Uso: Desciende hacia la locura, aumenta un 10% el daño con hechizos y la amenaza que generas durante 10 s. (10 Min Reutilización)"},
