[429961] = {name = "Desenrollar bolsa", additional_info = "Hechizo de 6 seg 1 hora de reutilización\n[q]Desenrolla una bolsa de dormir. Usarla para dormir durante al menos un minuto otorgará una bonificación a la experiencia obtenida, que se acumula un máximo de 3 veces."},
[429972] = {name = "[q2]Perspicacia oscura", additional_info = "Hechizo de 2 seg\n[q]Reflexiona en una tumba solitaria específica en Bosque del Ocaso para recibir una profecía."},
