[430318] = {name = "Reintegración", additional_info = "Alcance de 30 m\nHechizo de 10 seg\nComponentes:\nPergamino de reintegración\n[q]Devuelve a un jugador muerto a la vida con un 15% de salud y maná. No se puede utilizar estando en combate."},
