[431389] = {name = "Regeneración frenética mejorada", additional_info = "[q]Ahora puedes usar Regeneración frenética en todas las formas, excepto Forma de lechúcico lunar, o cuando no estás usando ninguna forma. Ahora convierte tu recurso activo en salud por segundo durante 10 s. Un máximo de 10 p. de ira, 10 p. de energía o un 20% del maná base se convierte en un máximo de 10% de salud por segundo."},
[431446] = {name = "Cornada", additional_info = "[q]Obtienes la habilidad Cornada:\n\n\nGolpear a un objetivo con Lacerar, Flagelo o Magullar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Destrozar (oso) y de otorgar 10 p. de ira. Golpear a un objetivo con Destrozar (felina) o Triturar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Furia del tigre."},
[431447] = {name = "Grabar yelmo - Cornada", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Cornada:\n\n\nGolpear a un objetivo con Lacerar, Flagelo o Magullar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Destrozar (oso) y de otorgar 10 p. de ira. Golpear a un objetivo con Destrozar (felina) o Triturar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Furia del tigre."},
[431448] = {name = "Piel de corteza mejorada", additional_info = "[q]Obtienes la habilidad Piel de corteza mejorada:\n\n\nAhora Piel de corteza puede lanzarse sobre aliados, ya no penaliza la velocidad de combate cuerpo a cuerpo ni el tiempo de lanzamiento de hechizos, y puede usarse durante un cambio de forma."},
[431449] = {name = "Grabar yelmo - Piel de corteza mejorada", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Piel de corteza mejorada:\n\n\nAhora Piel de corteza puede lanzarse sobre aliados, ya no penaliza la velocidad de combate cuerpo a cuerpo ni el tiempo de lanzamiento de hechizos, y puede usarse durante un cambio de forma."},
[431450] = {name = "Vientos huracanados", additional_info = "[q]Obtienes la habilidad Vientos huracanados:\n\n\nAumenta un 100% el daño infligido por tu Huracán, ya no tiene tiempo de reutilización y su costo de maná se reduce un 60%."},
[431451] = {name = "Grabar yelmo - Vientos huracanados", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Vientos huracanados:\n\n\nAumenta un 100% el daño infligido por tu Huracán, ya no tiene tiempo de reutilización y su costo de maná se reduce un 60%."},
[431457] = {name = "¡Lanzamiento de paria!", additional_info = nil},
[431458] = {name = "Regeneración frenética mejorada", additional_info = "[q]Obtienes la habilidad Regeneración frenética mejorada:\n\n\nAhora puedes usar Regeneración frenética en todas las formas, excepto Forma de lechúcico lunar, o cuando no estás usando ninguna forma. Ahora convierte tu recurso activo en salud por segundo durante 10 s. Un máximo de 10 p. de ira, 10 p. de energía o un 20% del maná base se convierte en un máximo de 10% de salud por segundo."},
[431461] = {name = "Grabar brazales - Regeneración frenética mejorada", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Regeneración frenética mejorada:\n\n\nAhora puedes usar Regeneración frenética en todas las formas, excepto Forma de lechúcico lunar, o cuando no estás usando ninguna forma. Ahora convierte tu recurso activo en salud por segundo durante 10 s. Un máximo de 10 p. de ira, 10 p. de energía o un 20% del maná base se convierte en un máximo de 10% de salud por segundo."},
[431466] = {name = "Floración", additional_info = "[q]Obtienes la habilidad Floración:\n\n\nTu Alivio presto ahora también provoca Floración, que sana [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] p. de salud cada 1 s a todos los miembros del grupo en un radio de 15 m de la ubicación del objetivo de Alivio presto durante 15 s."},
[431468] = {name = "Grabar brazales - Floración", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Floración:\n\n\nTu Alivio presto ahora también provoca Floración, que sana [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] p. de salud cada 1 s a todos los miembros del grupo en un radio de 15 m de la ubicación del objetivo de Alivio presto durante 15 s."},
[431567] = {name = "Trotamundos autosuficiente", additional_info = nil},
[431600] = {name = "Enfocar fuego", additional_info = "[q]Obtienes la habilidad Enfocar fuego:\n\n\nConsume todas las aplicaciones de Frenesí de tu mascota, lo que aumenta un 3% tu velocidad de ataque a distancia y otorga 4 p. de enfoque a tu mascota por cada aplicación de Frenesí consumida. Dura 20 s.\n\n Tu mascota obtiene Frenesí cada vez que usa un ataque básico, lo que aumenta un 6% su velocidad de ataque cuerpo a cuerpo durante 10 s. Se acumula un máximo de 5 veces."},
[431601] = {name = "Grabar brazales - Enfocar fuego", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Enfocar fuego:\n\n\nConsume todas las aplicaciones de Frenesí de tu mascota, lo que aumenta un 3% tu velocidad de ataque a distancia y otorga 4 p. de enfoque a tu mascota por cada aplicación de Frenesí consumida. Dura 20 s.\n\n Tu mascota obtiene Frenesí cada vez que usa un ataque básico, lo que aumenta un 6% su velocidad de ataque cuerpo a cuerpo durante 10 s. Se acumula un máximo de 5 veces."},
[431606] = {name = "Frenesí", additional_info = "Alcance de 100 m\nInstante\n[q]Aumenta un 6% la velocidad de ataque cuerpo a cuerpo de tu mascota durante 10 s."},
[431610] = {name = "TNT", additional_info = "[q]Obtienes la habilidad TNT:\n\n\nAumenta un 10% el daño infligido por Disparo explosivo y todas tus trampas de daño. Además, el daño inicial de Trampa explosiva y el daño periódico total de tu Trampa de inmolación aumentan un 25% de tu poder de ataque cuerpo a cuerpo o a distancia."},
[431611] = {name = "Grabar brazales - TNT", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa TNT:\n\n\nAumenta un 10% el daño infligido por Disparo explosivo y todas tus trampas de daño. Además, el daño inicial de Trampa explosiva y el daño periódico total de tu Trampa de inmolación aumentan un 25% de tu poder de ataque cuerpo a cuerpo o a distancia."},
[431622] = {name = "Égida divina", additional_info = "[q]Las sanaciones críticas crean un escudo protector sobre el objetivo, que absorbe el 30% de la cantidad sanada. Dura 12 s."},
[431624] = {name = "Égida divina", additional_info = "Rango ilimitado\nInstante\n[q]Las sanaciones críticas tienen una probabilidad de crear un escudo protector alrededor del objetivo, que absorbe un porcentaje de la cantidad sanada. Dura 12 s."},
[431649] = {name = "Égida divina", additional_info = "[q]Obtienes la habilidad Égida divina:\n\n\nLas sanaciones críticas crean un escudo protector sobre el objetivo, que absorbe el 30% de la cantidad sanada. Dura 12 s."},
