[431655] = {name = "Púa mental", additional_info = "{6% del maná base} {Alcance de 35 m}\nHechizo de 1.5 seg\n[q]Golpea al objetivo, le inflige de [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] a [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] p. de daño de Friosombra y aumenta un 30% la probabilidad de golpe crítico de tu próxima Explosión mental contra el objetivo. Este efecto se acumula un máximo de 3 veces."},
[431662] = {name = "Púa mental", additional_info = "[q]Obtienes la habilidad Púa mental:\n\n\nGolpea al objetivo, le inflige de [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] a [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] p. de daño de Friosombra y aumenta un 30% la probabilidad de golpe crítico de tu próxima Explosión mental contra el objetivo. Este efecto se acumula un máximo de 3 veces."},
[431663] = {name = "Grabar cinturón - Púa mental", additional_info = "Hechizo de 3 seg\nRequiere Cinturón\n[q]Graba tu cinturón con la runa Púa mental:\n\n\nGolpea al objetivo, le inflige de [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] a [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] p. de daño de Friosombra y aumenta un 30% la probabilidad de golpe crítico de tu próxima Explosión mental contra el objetivo. Este efecto se acumula un máximo de 3 veces."},
