[431743] = {name = "Grabar yelmo - Pandemia", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Pandemia:\n\n\nEl daño periódico de tus habilidades Corrupción, Aflicción inestable, Maldición de agonía, Inmolar, Maldición del Apocalipsis y Succionar vida ahora pueden ser golpes críticos."},
[431745] = {name = "Grabar yelmo - Explosión de humo", additional_info = "Hechizo de 3 seg\nRequiere Yelmos\n[q]Graba tu yelmo con la runa Explosión de humo:\n\n\nTu habilidad Conflagrar también otorga un 30% de celeridad de lanzamiento de hechizos durante 15 s y ya no consume Inmolar."},
[431747] = {name = "Grabar brazales - Aflicción inestable", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Aflicción inestable:\n\n\nLa energía de las Sombras destruye poco a poco al objetivo e inflige [242 * 6 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] p. de daño durante 18 s. Además, quien disipe tu hechizo Aflicción inestable recibirá [242 * 227 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] p. de daño y quedará silenciado durante 5 s. Solo puede haber un hechizo Aflicción inestable o Inmolar activo sobre un objetivo por brujo."},
[431748] = {name = "Aflicción inestable", additional_info = "[q]Obtienes la habilidad Aflicción inestable:\n\n\nLa energía de las Sombras destruye poco a poco al objetivo e inflige [242 * 6 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] p. de daño durante 18 s. Además, quien disipe tu hechizo Aflicción inestable recibirá [242 * 227 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] p. de daño y quedará silenciado durante 5 s. Solo puede haber un hechizo Aflicción inestable o Inmolar activo sobre un objetivo por brujo."},
[431754] = {name = "Invocar guardia vil", additional_info = "[q]Obtienes la habilidad Invocar guardia vil:\n\n\nInvoca a un guardia vil bajo las órdenes del brujo.\n\n El guardia vil se beneficia de todos los talentos y efectos que se activan de cualquiera de tus otros esbirros demonios o los benefician."},
[431756] = {name = "Grabar brazales - Invocar guardia vil", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Invocar guardia vil:\n\n\nInvoca a un guardia vil bajo las órdenes del brujo.\n\n El guardia vil se beneficia de todos los talentos y efectos que se activan de cualquiera de tus otros esbirros demonios o los benefician."},
[431757] = {name = "Aura de inmolación", additional_info = "[q]Obtienes la habilidad Aura de inmolación:\n\n\nQuema a los enemigos cercanos por [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100] p. de daño cada vez que un enemigo te ataca cuerpo a cuerpo (no más de una vez por segundo), reduce todo el daño mágico recibido un 10%, y aumenta el daño de Fuego infligido un 10%. Dura hasta cancelación."},
[431758] = {name = "Grabar brazales - Aura de inmolación", additional_info = "Hechizo de 3 seg\nRequiere [Bracers][q]Graba tus brazales con la runa Aura de inmolación:\n\n\nQuema a los enemigos cercanos por [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100] p. de daño cada vez que un enemigo te ataca cuerpo a cuerpo (no más de una vez por segundo), reduce todo el daño mágico recibido un 10%, y aumenta el daño de Fuego infligido un 10%. Dura hasta cancelación."},
