[435949] = {name = "[q4]Almófar de escamas brillantes hiperconductivo", additional_info = "Hechizo de 45 seg\nComponentes:\nPlacas de veraplata de bajo fondo , Escama múrloc gruesa (10), Cuero con resplandor tenue (5), Gniodino aislante\n[q4]Almófar de escamas brillantes hiperconductivo\nSe liga al recogerlo\nCabeza Malla\n242 armadura\n+14 aguante\n+15 intelecto\nDurabilidad 85 / 85\nNecesitas ser de nivel 40\nRequierePeletería\n(225)\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Causa un choque hiperconductivo que te inflige 312 to 688 p. de daño al instante, pero también aumenta tu velocidad de lanzamiento de hechizos un 20% durante 10 s. (10 Min Reutilización)"},
[435950] = {name = "Patrón: Almófar de escamas brillantes hiperconductivo", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar un almófar de escamas brillantes hiperconductivo."},
[435951] = {name = "[q4]Caperuza de canalizador gneuroconductiva", additional_info = "Hechizo de 45 seg\nComponentes:\nGniodino aislante , Pellejo grueso curtido (5), Cuero con resplandor tenue (5), Arcanofilamento hiperconductivo\n[q4]Caperuza de canalizador gneuroconductiva\nSe liga al recogerlo\nCabeza Cuero\n118 armadura\n+11 aguante\n+12 intelecto\n+11 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 40\nRequierePeletería\n(225)\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Obtienes meditación neuromántica, que te permite conservar un 100% de tu regeneración de maná en el lanzamiento de hechizos, y aumenta el daño y la sanación realizados con hechizos hasta 50 p. durante 20 s. (10 Min Reutilización)"},
[435952] = {name = "Patrón: Caperuza de canalizador gneuroconductiva", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar una caperuza de canalizador gneuroconductiva."},
[435953] = {name = "[q4]Caperuza de escamas resistente a la radiación", additional_info = "Hechizo de 45 seg\nComponentes:\nPlacas de veraplata de bajo fondo , Pellejo grueso curtido (5), Cuero con resplandor tenue (5), Gniodino aislante\n[q4]Caperuza de escamas resistente a la radiación\nSe liga al recogerlo\nCabeza Malla\n[q2]342 armadura\n+10 aguante\n+10 intelecto\nDurabilidad 85 / 85\nNecesitas ser de nivel 40\nRequierePeletería\n(225)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 32 p. el poder de ataque.\n[q2]Uso: Activa los protocolos de mitigación de radiación de este casco, lo que hace que elimines inmediatamente todos los efectos de veneno activos y obtengas inmunidad a todo el daño de Naturaleza durante 3 s. (10 Min Reutilización)"},
[435954] = {name = "Patrón: caperuza de escamas resistente a la radiación", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar una caperuza de escamas resistente a la radiación."},
[435956] = {name = "[q3]Engranajes de veraplata pulidos", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de veraplata , Pila de engranajes deslustrados (5)\n[q3]Engranajes de veraplata pulidos"},
[435957] = {name = "Esquema: engranajes de veraplata pulidos", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar un conjunto de engranajes de veraplata pulidos."},
[435958] = {name = "[q4]Murotuerca de veraplata giratorio", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero\nComponentes:\nPlacas de veraplata de bajo fondo (3), Engranajes de veraplata pulidos (5), Cuero con resplandor tenue (2), Envoltura de mitril (2), Girocronátomo (2), Barra de mitril (15)\n[q4]Murotuerca de veraplata giratorio\nSe liga al recogerlo\nMano izquierda Escudo\n1760 armadura\n29 bloqueo\n+9 fuerza\n+10 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 40\nRequiereIngeniería\n(225)\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 1%.\n[q2]Equipar: Cuando realizas un bloqueo exitoso, los engranajes afilados giratorios de este escudo infligen 5 to 10 p. de daño físico al atacante y 2 to 10 p. de daño físico al portador.\n[q]\"Los bordes giratorios de este escudo son realmente filosos. Parece tan peligroso para el portador como para el atacante.\""},
[435959] = {name = "Esquema: Murotuerca de veraplata giratorio", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar un murotuerca de veraplata giratorio."},
[435960] = {name = "[q4]Envoltura dorada hiperconductiva", additional_info = "Hechizo de 45 seg\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nEngranajes de veraplata pulidos (3), Arcanofilamento hiperconductivo (3), Cuero con resplandor tenue , Barra de oro (10)\n[q4]Envoltura dorada hiperconductiva\nSe liga al recogerlo\nCintura Tela\n40 armadura\n+9 aguante\nDurabilidad 35 / 35\nNecesitas ser de nivel 40\nRequiereIngeniería\n(225)\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Uso: Sacas una moneda hiperconductiva de tu cinturón y la tiras al aire. Si sale cara, obtienes un 3% más de probabilidad de infligir golpes críticos con todos los hechizos y ataques durante 30 s. Si sale cruz, obtienes un 10% de velocidad de movimiento durante 30 s. (15 Min Reutilización)\n[q]\"Este cinturón tintinea levemente cuando te mueves.\""},
[435961] = {name = "Esquema: Envoltura dorada hiperconductiva", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar una envoltura dorada hiperconductiva"},
[435962] = {name = "Tratado sobre salvación", additional_info = nil},
[435963] = {name = "Bomba de radiación de alto rendimiento", additional_info = "Alcance de 25 m\nHechizo de 1 seg\n[q]Inflige 150 to 250 p. de daño de Fuego en el radio de la explosión, además de 25 p. de daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante hasta cancelación."},
[435964] = {name = "[q2]Bomba de radiación de alto rendimiento", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero\nComponentes:\nPólvora sólida , Residuos radioactivos de Gnomeregan , Barra de mitril (2)\n[q2]Bomba de radiación de alto rendimiento\n(2)\nNecesitas ser de nivel 35\nRequiereIngeniería\n(200)\n[q2]Uso: Inflige 150 to 250 p. de daño de Fuego en el radio de la explosión, además de 25 p. de daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante hasta cancelación. (1 Min Reutilización)"},
[435965] = {name = "Esquema: bomba de radiación de alto rendimiento", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar un paquete de bombas de radiación de alto rendimiento."},
[435966] = {name = "[q2]Bomba de radiación para tontos", additional_info = "Hechizo de 8 seg\nHerramientas: Martillo de herrero\nComponentes:\nPólvora sólida (2), Residuos radioactivos de Gnomeregan , Barra de mitril (2)\n[q2]Bomba de radiación para tontos\n(2)\nNecesitas ser de nivel 40\n[q2]Uso: Inflige 112 to 188 p. de daño de Fuego en el radio de la explosión, además de 10 p. de daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante 10 s. (1 Min Reutilización)\n[q]\"Una versión menor pero no menos letal de su contraparte más compleja para aquellos que carezcan de la aptitud pero rebosen de confianza.\""},
[435967] = {name = "Esquema: bomba de radiación para tontos", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar bombas de radiación para tontos."},
[435968] = {name = "Bomba de radiación para tontos", additional_info = "Alcance de 25 m\nHechizo de 1.5 seg\n[q]Inflige 112 to 188 p. de daño de Fuego en el radio de la explosión, además de 10 p. de daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante 10 s."},
[435969] = {name = "[q3]Gniodino aislante", additional_info = "Hechizo de 3 seg\nComponentes:\nVial emplomado , Cajón de solución de gniodino maculada (5)\n[q3]Gniodino aislante"},
[435970] = {name = "Receta: gniodino aislante", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a destilar un vial de gniodino aislante."},
[435971] = {name = "Poción de rejuvenecimiento levemente irradiada", additional_info = "Hechizo de 3 seg\nComponentes:\nCajón de solución de gniodino maculada , Poción de Rejuvenecimiento menor , Residuos radioactivos de Gnomeregan (3), Vial de cristal (5)\n(6)\nNecesitas ser de nivel 35\n[q2]Uso: Restaura 262 to 438 p. de maná y 340 to 460 p. de salud. También aumenta 40 p. el poder de ataque y 35 p. el daño que infligen todos los hechizos durante 20 s. (2 Min Reutilización)\n[q]\"Los efectos secundarios pueden incluir mareos, sequedad en la boca, fatiga, pérdida de apetito, envenenamiento radiactivo agudo, mutación y muerte. Úsala solo como se indica.\""},
[435972] = {name = "Receta: Poción de rejuvenecimiento levemente irradiada", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a preparar una poción de rejuvenecimiento levemente irradiada."},
[435973] = {name = "Irradiación leve", additional_info = "Instante\n[q]Restaura 262 to 438 p. de maná y 340 to 460 p. de salud. También aumenta 40 p. el poder de ataque y 35 p. el daño que infligen todos los hechizos durante 20 s."},
[435974] = {name = "Reducir aguante 05", additional_info = "[q]-5 p. de aguante."},
[435975] = {name = "Irradiated Set Spell Dam 11", additional_info = "[q]Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos."},
[435976] = {name = "Poder de ataque: feral (+20)", additional_info = "Requiere Forma felina, Forma de oso, Forma de oso temible\n[q]+20 p. de poder de ataque solo en las formas felina, de oso y de oso temible."},
[435977] = {name = "Hiperconductor energizado", additional_info = "[q]El lanzamiento de hechizos tiene la probabilidad de aumentar hasta 40 p. el daño y la sanación que realizas durante 10 s.\n(Probabilidad de que accione: 10%)"},
[435978] = {name = "Hiperconductor energizado", additional_info = "Instante\n[q]Aumenta hasta 40 p. el daño y la sanación de los hechizos y efectos mágicos."},
[435980] = {name = "Meditación menor", additional_info = "[q]Permite que un 10% de tu regeneración de maná continúe mientras lanzas hechizos."},
[435981] = {name = "Energizar", additional_info = "Instante\n[q]Restaura 100 p. de maná."},
