[437169] = {name = "Portal de invocación", additional_info = "{12% del maná base} {Alcance de 30 m}\nCanalizado (Hechizo de 2 min) 2 min de reutilización\nComponentes:\nFragmento de alma\n[q]Da comienzo a un ritual que crea un portal de invocación. Dos miembros del grupo o banda pueden usar el portal de invocación para invocar a un miembro del grupo o banda seleccionado. El portal para el ritual requiere al taumaturgo y 2 miembros del grupo o banda más para que se complete. Para poder participar, los jugadores deben estar fuera de combate y tienen que hacer clic con el botón derecho del ratón en el portal y no moverse hasta que se haya completado el ritual."},
[437280] = {name = "Teletransporte a la Cuenca Abrasadora", additional_info = "Alcance de 20 m\nInstante\n[q]Envía al jugador a Gnomeregan."},
