[437306] = {name = "Somnolencia profunda", additional_info = nil},
[437311] = {name = "Portal de invocación", additional_info = "{12% del maná base} {Alcance de 30 m}\nHechizo de 5 seg\nComponentes:\nFragmento de alma\n[q]Da comienzo a un ritual que crea un portal de invocación. Dos miembros del grupo o banda pueden usar el portal de invocación para invocar a un miembro del grupo o banda seleccionado. El portal para el ritual requiere al taumaturgo y 2 miembros del grupo o banda más para que se complete. Para poder participar, los jugadores deben estar fuera de combate y tienen que hacer clic con el botón derecho del ratón en el portal y no moverse hasta que se haya completado el ritual."},
[437324] = {name = "Somnolencia profunda", additional_info = "Instante\n[q]Entrar en contacto con una nube de somnolencia hace que el objetivo se duerma durante 15 s, lo que reduce el daño y la sanación recibidos un 99%."},
[437327] = {name = "Inspiración cargada", additional_info = "Instante\n[q]Controlas la energía arcana latente del aire a tu alrededor para obtener inspiración cargada, que reduce un 50% el costo de maná de todos los hechizos, y aumenta hasta 50 p. el daño y la sanación realizados durante 12 s."},
[437340] = {name = "Resistencia a radiación radical", additional_info = "Instante\n[q]Activa los protocolos de mitigación de radiación de este casco, lo que hace que elimines inmediatamente todos los efectos de veneno activos y obtengas inmunidad a todo el daño de Naturaleza durante 3 s."},
[437346] = {name = "Furia del soñador", additional_info = nil},
[437349] = {name = "Choque neurológico", additional_info = "Instante\n[q]Causa un choque neurológico que te inflige 343 to 757 p. de daño al instante, pero también aumenta tu velocidad de ataque cuerpo a cuerpo y a distancia un 20% durante 10 s."},
[437353] = {name = "Aliento corrosivo", additional_info = "Alcance de 100 m\nHechizo de 4 seg\n[q]El taumaturgo exhala una oleada de magia corrosiva contra el objetivo que inflige 1140 to 1260 p. de daño de Naturaleza y reduce su armadura un 33% durante 20 s."},
[437357] = {name = "Meditación neuromántica", additional_info = "Instante\n[q]Obtienes meditación neuromántica, que te permite conservar un 100% de tu regeneración de maná en el lanzamiento de hechizos, y aumenta el daño y la sanación realizados con hechizos hasta 50 p. durante 20 s."},
[437362] = {name = "Choque hiperconductivo", additional_info = "Instante\n[q]Causa un choque hiperconductivo que te inflige 312 to 688 p. de daño al instante, pero también aumenta tu velocidad de lanzamiento de hechizos un 20% durante 10 s."},
[437367] = {name = "Engranajes afilados", additional_info = "{Instante} {5 seg de reutilización}\n[q]Cuando realizas un bloqueo exitoso, los engranajes afilados giratorios de este escudo infligen 5 to 10 p. de daño físico al atacante y 2 to 10 p. de daño físico al portador."},
[437368] = {name = "Moneda de la suerte", additional_info = "Instante\n[q]Sacas una moneda hiperconductiva de tu cinturón y la tiras al aire. Si sale cara, obtienes un 3% más de probabilidad de infligir golpes críticos con todos los hechizos y ataques durante 30 s. Si sale cruz, obtienes un 10% de velocidad de movimiento durante 30 s."},
[437375] = {name = "Barrido de cola", additional_info = "Alcance de 30 m\nInstante\n[q]Inflige 760 to 840 p. de daño a los objetivos que están detrás del taumaturgo y los repele."},
[437377] = {name = "Concentración intensa", additional_info = "Instante\n[q]Obtienes concentración intensa, que reduce la velocidad de movimiento un 20%, pero también aumenta 50 p. tu resistencia contra hechizos de todas las escuelas y aumenta la velocidad de ataque cuerpo a cuerpo un 20% durante 10 s."},
[437382] = {name = "Fuerza de voluntad reforzada", additional_info = "Instante\n[q]Obtienes fuerza de voluntad reforzada, que impide los efectos de silenciamiento e interrupción y el retraso de hechizos durante 10 s."},
[437388] = {name = "Engranajes afilados", additional_info = "Instante"},
[437390] = {name = "Veneno aletargante", additional_info = "Hechizo de 0.5 seg\n[q]El taumaturgo escupe un veneno aletargante a los jugadores que inflige 300 p. de daño de Naturaleza cada 3 s durante 15 s. Este veneno reduce la probabilidad de golpe un 50% y aumenta los costos de habilidades un 100%."},
[437398] = {name = "Pesadilla lúcida", additional_info = "Hechizo de 6 seg 5 seg de reutilización\n[q]El taumaturgo destroza la mente de todos los jugadores lúcidos y les inflige 30000 p. de daño de las Sombras."},
[437410] = {name = "Somnolencia profunda", additional_info = "Hechizo de 3 seg\n[q]El taumaturgo entra en una somnolencia profunda durante 20 s que reduce el daño recibido un 99%."},
