[440658] = {name = "Escudo de rectitud", additional_info = "{6% del maná base} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {6 seg de reutilización}\n[q]Embiste al objetivo con tu escudo e inflige daño Sagrado basado en tu valor de bloqueo más [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100] p. extra."},
[440664] = {name = "Fango", additional_info = "Rango ilimitado\nInstante\n[q]Radiactivo viscoso crea un charco de baba tóxica que inflige 150 p. de daño de Naturaleza cada 5 s a los jugadores parados sobre él.\n\n Además, reduce la velocidad de movimiento los jugadores afectados un 150%."},
[440666] = {name = "Vindicador", additional_info = "[q]Cuando se activa tu talento Vindicación, también reduce el poder de ataque del objetivo ( 30 /- 3) p. por punto de talento y aumenta tu fuerza, agilidad y poder de ataque un 5% por punto de talento. Aumenta la duración de Vindicación a 30 s."},
