[440858] = {name = "Grabar capa - Orbe congelado", additional_info = "Hechizo de 3 seg\nRequiere Capa\n[q]Graba tu capa con la runa\n Orbe congelado:\n\n\nArroja un orbe de hielo en espiral que se mueve rápidamente hacia adelante durante 16 s. Mientras se mueve, cada 1 s el orbe inflige [90 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] p. de daño de Escarcha y aplica un enfriamiento que reduce un 30% la velocidad de movimiento de todos los enemigos que atraviesa. La primera vez que le inflige daño a un enemigo, su movimiento se ralentiza y tiene un 100% de probabilidad de activar la runa Dedos de Escarcha."},
[440859] = {name = "Orbe congelado", additional_info = "[q]Obtienes la habilidad Orbe congelado:\n\n\nArroja un orbe de hielo en espiral que se mueve rápidamente hacia adelante durante 16 s. Mientras se mueve, cada 1 s el orbe inflige [90 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] p. de daño de Escarcha y aplica un enfriamiento que reduce un 30% la velocidad de movimiento de todos los enemigos que atraviesa. La primera vez que le inflige daño a un enemigo, su movimiento se ralentiza y tiene un 100% de probabilidad de activar la runa Dedos de Escarcha."},
[440870] = {name = "Exterminación", additional_info = "[q]Tu hechizo Fuego de alma ya no tiene tiempo de reutilización. Además, cuando tu Descarga de las sombras, Cuchilla de las Sombras, Incinerar o Fuego de alma golpea a un objetivo con menos de un 35% de salud, el tiempo de lanzamiento de tu hechizo Fuego de alma se reduce un 40% durante 10 s. Los Fuegos de alma lanzados bajo el efecto de Exterminación no cuestan fragmentos."},
[440873] = {name = "Exterminación", additional_info = "Instante\n[q]Modifies Cast Time -39%:\nFuego de alma , Fuego de alma"},
[440882] = {name = "Armadura infernal", additional_info = "3% del maná base\n{Instante} {1 min de reutilización}\n[q]Tu espíritu es imbuido con energía demoníaca que reduce todo el daño mágico recibido por un porcentaje equivalente a un 60% de la reducción de daño físico de tu armadura. Dura 10 s."},
[440892] = {name = "Marca del caos", additional_info = "[q]Todas tus maldiciones, excepto Maldición de las Sombras y Maldición de los Elementos, ahora aplican la Marca del caos, lo que reduce [max(min( 56 + 19, 75), 27)] p. las resistencias del objetivo a lo Arcano, el Fuego, la Escarcha, las Sombras y la Naturaleza y aumenta un [max(min(( 56 - 8) * 0.125 + 4, 10), 4)]% todo el daño con hechizos que recibe de esas escuelas mientras permanece maldito."},
[440895] = {name = "Marca del caos", additional_info = "Instante\n[q]Modifies Critical Strike Chance +101:\nArea Death (TEST) , Conflagrar , Conflagrar , Conflagrar , Conflagrar , Descarga de caos , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Descarga de las Sombras , Dolor abrasador , Dolor abrasador , Dolor abrasador , Dolor abrasador , Dolor abrasador , Dolor abrasador , Fuego de alma , Fuego de alma , Incinerar , Inmolar , Inmolar , Inmolar , Inmolar , Inmolar , Inmolar , Inmolar , Inmolar , Invocación , Quemadura de las Sombras , Quemadura de las Sombras , Quemadura de las Sombras , Quemadura de las Sombras , Quemadura de las Sombras , Quemadura de las Sombras"},
[440922] = {name = "Grabar botas - Exterminación", additional_info = "Hechizo de 3 seg\nRequiere [Boots][q]Graba tus botas con la runa Exterminación:\n\n\nTu hechizo Fuego de alma ya no tiene tiempo de reutilización. Además, cuando tu Descarga de las sombras, Cuchilla de las Sombras, Incinerar o Fuego de alma golpea a un objetivo con menos de un 35% de salud, el tiempo de lanzamiento de tu hechizo Fuego de alma se reduce un 40% durante 10 s. Los Fuegos de alma lanzados bajo el efecto de Exterminación no cuestan fragmentos."},
