[442813] = {name = "Especialización en espadas", additional_info = "[q]Aumenta 5 p. la habilidad con espadas y espadas de dos manos. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo."},
[442876] = {name = "Especialización en hachas", additional_info = "[q]Aumenta 5 p. la habilidad con hachas y hachas de dos manos. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo."},
[442881] = {name = "Especialización en mazas", additional_info = "[q]Aumenta 5 p. la habilidad con mazas y mazas de dos manos. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo."},
[442887] = {name = "Especialización en dagas", additional_info = "[q]Aumenta 5 p. la habilidad con dagas. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo."},
[442890] = {name = "Especialización en armas de puño", additional_info = "[q]Aumenta 5 p. la habilidad con armas de puño (sin armas). Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo."},
[442891] = {name = "Especialización en armas a distancia", additional_info = "[q]Aumenta 5 p. la habilidad con arcos, armas de fuego, ballestas y armas arrojadizas. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo."},
[442892] = {name = "Especialización en armas de asta", additional_info = "[q]Aumenta 5 p. la habilidad con bastones y armas de asta. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo."},
[442893] = {name = "Especialización en lo Arcano", additional_info = "[q]Aumenta la probabilidad de golpear con hechizos Arcanos un 6%. No se acumula con otras runas de anillo."},
[442894] = {name = "Especialización en Fuego", additional_info = "[q]Aumenta la probabilidad de golpear con hechizos de Fuego un 6%. No se acumula con otras runas de anillo."},
[442895] = {name = "Especialización en Escarcha", additional_info = "[q]Aumenta la probabilidad de golpear con hechizos de Escarcha un 6%. No se acumula con otras runas de anillo."},
[442896] = {name = "Especialización en Naturaleza", additional_info = "[q]Aumenta la probabilidad de golpear con hechizos de Naturaleza un 6%. No se acumula con otras runas de anillo."},
[442897] = {name = "Especialización en las Sombras", additional_info = "[q]Aumenta la probabilidad de golpear con hechizos de las Sombras un 6%. No se acumula con otras runas de anillo."},
[442898] = {name = "Especialización Sagrada", additional_info = "[q]Aumenta la probabilidad de golpear con hechizos Sagrados un 6%. No se acumula con otras runas de anillo."},
[442901] = {name = "Especialización en cambio de forma", additional_info = "Requiere Forma felina, Forma de oso, Forma de oso temible\n[q]Aumenta la probabilidad de golpear con ataques cuerpo a cuerpo un 3% y reduce la probabilidad de que los enemigos esquiven tus ataques cuerpo a cuerpo un 3% mientras estás en Forma de oso, Forma felina o Forma de oso temible. No se acumula con otras runas de anillo."},
[442945] = {name = "Salvado por la Luz", additional_info = nil},
