[443518] = {name = "Cuerda de escalar", additional_info = "Rango ilimitado\nHechizo de 2 seg\n[q]Lanzas una cadena con gancho para refrenar a un objetivo y atraerlo hacia ti."},
[443540] = {name = "Rayo de estatua", additional_info = "Alcance de 100 m\nCanalizado (Hechizo de 0 seg)\n[q]Ofusca la mente del objetivo con energía de las Sombras, causando 0.0 p. de daño de las Sombras durante hasta cancelación y ralentizando su movimiento en un 0%."},
[443630] = {name = "Abalorio de JcJ", additional_info = "Instante\n[q]Elimina todos los efectos de reducción de movimiento y todos los efectos que provocan pérdida de control de tu personaje."},
[443631] = {name = "Efecto de Semilla de renovación", additional_info = "Alcance de 100 m\nInstante\n[q]Hace crecer una Flor Sanadora del cadáver de un humanoide o bestia durante 1 min. La flora sana 24 p. a los miembros del grupo en un radio de 20 m cada 2 s."},
[443632] = {name = "Capucha de ratero", additional_info = "Instante\n[q]Aumenta en 3 tu nivel de sigilo efectivo. Aumenta 2 m el radio de Desactivar trampa y Robar, y 5 m el radio de Distraer."},
[443634] = {name = "Crear agua de océano", additional_info = nil},
[443635] = {name = "Crear agua de océano", additional_info = "Instante\n[q]Crea 20 botellas de agua de manantial, lo que proporciona al mago y a sus aliados algo para beber.\n\n Los objetos creados por arte de magia desaparecen si el jugador permanece desconectado durante más de 15 min."},
