[443990] = {name = "Aullido aterrador", additional_info = "Hechizo de 2 seg\n[q]Emite un aullido aterrador que inflige 1500 p. de daño de las Sombras a todos los enemigos y hace que todos los enemigos huyan aterrorizados durante 4 s."},
