[446179] = {name = "[q4]Hombreras de pavor", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte\n[q4]Hombreras de pavor\nSe liga al recogerlo\nHombro Placas\n472 armadura\n+12 fuerza\n+12 agilidad\n+12 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\nRequiereHerrería\n(250)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Tus ataques cuerpo a cuerpo tienen una probabilidad de aumentar tu velocidad de ataque un 5% y tu poder de ataque 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446183] = {name = "[q4]Manto de paranoia", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Cuero quimérico (8), Cuero basto (4)\n[q4]Manto de paranoia\nSe liga al recogerlo\nHombro Cuero\n129 armadura\n+16 agilidad\n+14 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 50\nRequierePeletería\n(250)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Tus ataques cuerpo a cuerpo tienen una probabilidad de aumentar tu velocidad de ataque un 5% y tu poder de ataque 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446185] = {name = "[q4]Bufas chillonas", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Dragontina negra (8), Cuero basto (8)\n[q4]Bufas chillonas\nSe liga al recogerlo\nHombro Malla\n268 armadura\n+17 agilidad\n+14 intelecto\nDurabilidad 85 / 85\nNecesitas ser de nivel 50\nRequierePeletería\n(250)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Los ataques cuerpo a cuerpo y a distancia tienen una probabilidad de aumentar tu poder de ataque 60 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446186] = {name = "[q4]Guardahombros de anillas cacófonos", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Dragontina negra (4), Cuero basto (10)\n[q4]Guardahombros de anillas cacófonos\nSe liga al recogerlo\nHombro Malla\n268 armadura\n+12 fuerza\n+12 agilidad\n+12 aguante\n+12 intelecto\nDurabilidad 85 / 85\nNecesitas ser de nivel 50\nRequierePeletería\n(250)\n[q2]Equipar: Tus ataques cuerpo a cuerpo tienen una probabilidad de aumentar tu velocidad de ataque un 5% y tu poder de ataque 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446188] = {name = "[q4]Guardahombros aterrorizadores", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte\n[q4]Guardahombros aterrorizadores\nSe liga al recogerlo\nHombro Placas\n472 armadura\n+10 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\nRequiereHerrería\n(250)\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 24 p. el daño que infligen los hechizos y efectos Sagrados.\n[q2]Equipar: Tus ataques cuerpo a cuerpo y hechizos dañinos tienen una probabilidad de aumentar el daño con hechizos hasta un máximo de 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446189] = {name = "[q4]Hombreras de obsesión", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Esencia de agua , Cuero basto (12)\n[q4]Hombreras de obsesión\nSe liga al recogerlo\nHombro Cuero\n129 armadura\n+12 intelecto\n+16 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 50\nRequierePeletería\n(250)\n[q2]Equipar: Aumenta hasta 29 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Los hechizos de sanación tienen una probabilidad de aumentar tu sanación hasta un máximo de 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446190] = {name = "[q4]Manto de anillas gemebundo", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Dragontina verde (8), Cuero basto (8)\n[q4]Manto de anillas gemebundo\nSe liga al recogerlo\nHombro Malla\n268 armadura\n+10 aguante\n+11 intelecto\nDurabilidad 85 / 85\nNecesitas ser de nivel 50\nRequierePeletería\n(250)\n[q2]Equipar: Aumenta hasta 31 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s.\n[q2]Equipar: Los hechizos de sanación tienen una probabilidad de aumentar tu sanación hasta un máximo de 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446191] = {name = "[q4]Espaldares torvos", additional_info = "Hechizo de 45 seg\nHerramientas: Martillo de herrero\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte\n[q4]Espaldares torvos\nSe liga al recogerlo\nHombro Placas\n472 armadura\n+10 aguante\n+13 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\nRequiereHerrería\n(250)\n[q2]Equipar: Aumenta hasta 31 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 2 p. de maná cada 5 s.\n[q2]Equipar: Los hechizos de sanación tienen una probabilidad de aumentar tu sanación hasta un máximo de 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446192] = {name = "[q4]Membrana de neurosis oscura", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Pellejo basto curtido (2), Cuero basto (6)\n[q4]Membrana de neurosis oscura\nSe liga al recogerlo\nHombro Cuero\n129 armadura\n+14 intelecto\nDurabilidad 70 / 70\nNecesitas ser de nivel 50\nRequierePeletería\n(250)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 20 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Tus ataques cuerpo a cuerpo y hechizos dañinos tienen una probabilidad de aumentar el daño con hechizos hasta un máximo de 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446193] = {name = "[q4]Espaldares de mente fracturada", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Tela vil (8), Madeja de paño rúnico (8)\n[q4]Espaldares de mente fracturada\nSe liga al recogerlo\nHombro Tela\n64 armadura\n+14 intelecto\n+12 espíritu\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\nRequiereSastrería\n(250)\n[q2]Equipar: Aumenta hasta 18 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Los hechizos que infligen daño tienen una probabilidad de aumentar tu velocidad de lanzamiento de hechizos un 10% durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446194] = {name = "[q4]Manto de demencia", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Esencia viva (4), Madeja de paño rúnico (10)\n[q4]Manto de demencia\nSe liga al recogerlo\nHombro Tela\n64 armadura\n+12 aguante\n+13 intelecto\n+12 espíritu\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\nRequiereSastrería\n(250)\n[q2]Equipar: Aumenta hasta 20 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Los hechizos de sanación tienen una probabilidad de aumentar tu sanación hasta un máximo de 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446195] = {name = "[q4]Hombreras del trastornado", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Tela vil (6), Esencia de agua , Madeja de paño rúnico (3)\n[q4]Hombreras del trastornado\nSe liga al recogerlo\nHombro Tela\n[q2]104 armadura\n+15 aguante\n+13 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\nRequiereSastrería\n(250)\n[q2]Equipar: Aumenta hasta 13 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Los hechizos que infligen daño tienen una probabilidad de aumentar 30 p. tu daño con hechizos y un 2% la probabilidad de esquivar durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
[446212] = {name = "Flagelo/Triturar mejorado", additional_info = "Flagelo/Triturar mejorado\n[q]Aumenta un 2% el daño de Flagelo y Triturar."},
[446213] = {name = "Escudo Sagrado mejorado", additional_info = "[q]Aumenta un 2% la probabilidad de bloqueo de tu próximo hechizo Escudo Sagrado."},
[446214] = {name = "Enseñar Armamentos de pesadilla: herrería", additional_info = nil},
[446215] = {name = "Enseñar Armamentos de pesadilla: peletería", additional_info = nil},
[446217] = {name = "Enseñar Armamentos de pesadilla: sastrería", additional_info = nil},
[446219] = {name = "Gritos de linaje corrompido", additional_info = "Alcance de 100 m\nInstante\n[q]Aumenta 10 p. el poder de ataque, el daño con hechizos y la sanación."},
[446220] = {name = "Tótem de linaje atormentado", additional_info = "[q]Choque de llamas otorga 10 p. de poder de ataque, daño con hechizos y sanación durante 12 s."},
[446226] = {name = "[q4]Frasco de pesadillas perpetuas", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Vial de cristal\n[q4]Frasco de pesadillas perpetuas\nSe liga al recogerlo\nNecesitas ser de nivel 50\nRequiereAlquimia\n(250)\n[q2]Uso: Aumenta el poder de ataque a distancia y cuerpo a cuerpo 45 p. Los beneficios de este frasco solo se aplican en áreas que están bajo la influencia de la pesadilla. (30 Seg Reutilización)\n[q]\"Por mucho que intentes beber su contenido, este frasco nunca se vaciará.\""},
[446228] = {name = "Poder de pesadilla", additional_info = "Instante\n[q]Aumenta el poder de ataque a distancia y cuerpo a cuerpo 45 p. Los beneficios de este frasco solo se aplican en áreas que están bajo la influencia de la pesadilla."},
[446229] = {name = "Enseñar Armamentos de pesadilla: alquimia", additional_info = nil},
[446231] = {name = "Ascenso de la serpiente", additional_info = "Instante\n[q]Infunde al taumaturgo con una bendición de los dioses primigenios. El poder de ataque cuerpo a cuerpo y a distancia aumenta 150 p. durante 12 s."},
[446233] = {name = "Activador de Ascenso de la serpiente", additional_info = "[q]Otorga una pequeña probabilidad de infundir al portador con una bendición de la serpiente cuando inflige daño cuerpo a cuerpo o a distancia. El poder de ataque cuerpo a cuerpo y a distancia aumenta 150 p. durante 12 s.\n(Probabilidad de que accione: 3%, 2m de reutilización)"},
[446236] = {name = "[q4]Avambrazos de invocador potenciados por el Vacío", additional_info = "Hechizo de 45 seg\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Avambrazos potenciados por el Vacío , Núcleo de poder de oro (2), Trasto de torio (2)\n[q4]Avambrazos de invocador potenciados por el Vacío\nSe liga al recogerlo\nMuñeca Tela\n37 armadura\n+7 aguante\n+8 intelecto\nDurabilidad 35 / 35\nNecesitas ser de nivel 50\nRequiereIngeniería\n(250)\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Ofrece protección contra ciertos tipos de ataques psíquicos.\n[q2]Uso: Canaliza el poder del Vacío, lo que otorga inmunidad al miedo durante 15 s. (10 Min Reutilización)\n[q]\"Incluye las mejores partes del diseño original de Ziri, con algunas modificaciones extra.\""},
[446237] = {name = "[q4]Avambrazos de destripador potenciados por el Vacío", additional_info = "Hechizo de 45 seg\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Avambrazos potenciados por el Vacío , Pólvora densa (3), Rubí estrella (2)\n[q4]Avambrazos de destripador potenciados por el Vacío\nSe liga al recogerlo\nMuñeca Cuero\n75 armadura\n+9 fuerza\n+18 agilidad\n+5 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 50\nRequiereIngeniería\n(250)\n[q2]Equipar: Ofrece protección contra ciertos tipos de ataques psíquicos.\n[q2]Uso: Canaliza el poder del Vacío, lo que otorga inmunidad al miedo durante 15 s. (10 Min Reutilización)\n[q]\"Incluye las mejores partes del diseño original de Ziri, con algunas modificaciones extra.\""},
[446238] = {name = "[q4]Avambrazos de protector potenciados por el Vacío", additional_info = "Hechizo de 45 seg\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nSemilla de pesadilla (10), Manto de pesadillas inerte , Avambrazos potenciados por el Vacío , Núcleo de poder de oro (2), Tubo de torio (2)\n[q4]Avambrazos de protector potenciados por el Vacío\nSe liga al recogerlo\nMuñeca Placas\n275 armadura\n+10 fuerza\n+12 aguante\nDurabilidad 55 / 55\nNecesitas ser de nivel 50\nRequiereIngeniería\n(250)\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 19 p.\n[q2]Equipar: Ofrece protección contra ciertos tipos de ataques psíquicos.\n[q2]Uso: Canaliza el poder del Vacío, lo que otorga inmunidad al miedo durante 15 s. (10 Min Reutilización)\n[q]\"Incluye las mejores partes del diseño original de Ziri, con algunas modificaciones extra.\""},
[446239] = {name = "Enseñar Armamentos de pesadilla: ingeniería", additional_info = nil},
[446240] = {name = "Sigilo de sueños vivos", additional_info = "Alcance de 30 m\nHechizo de 3 seg\n[q]Otorga un sigilo encantado de sueños vivos que te potencia para aumentar hasta 30 p. el daño y la sanación realizados con hechizos, y aumenta el poder de ataque 30 p. durante 30 min. Esto solo aplica fuera de combate."},
[446243] = {name = "[q2]Sigilo de sueños vivos", additional_info = "Hechizo de 3 seg\nHerramientas: Vara rúnica de veraplata\nComponentes:\nPolvo onírico (5)\n[q2]Sigilo encantado: sueños vivos\nSe liga al recogerlo\nÚnico (5)\nNecesitas ser de nivel 50\nRequiereEncantamiento\n(250)\n[q2]Uso: Otorga un sigilo encantado de sueños vivos que te potencia para aumentar hasta 30 p. el daño y la sanación realizados con hechizos, y aumenta el poder de ataque 30 p. durante 30 min. Esto solo aplica fuera de combate. (30 Min Reutilización)"},
[446244] = {name = "Enseñar Armamentos de pesadilla: encantamiento", additional_info = nil},
[446256] = {name = "Mojo atal'ai de magia prohibida", additional_info = "Instante\n[q]Aumenta 40 p. el poder con hechizos. Los golpes con hechizos exitosos tienen una probabilidad de liberar una Descarga de las Sombras contra el objetivo. Solo puede haber un tipo de poción atal'ai activa a la vez. Esto no tiene efecto fuera del Templo Sumergido.\n(Probabilidad de que accione: 25%, 40s de reutilización)"},
[446258] = {name = "Descarga de las Sombras", additional_info = "{70 p. de maná} {Alcance de 40 m}\nHechizo de 2.8 seg\n[q]Lanza una descarga sombría contra el enemigo que inflige 204 to 236 p. de daño de las Sombras."},
[446265] = {name = "Rocas en caída", additional_info = "Instante\n[q]Cae una lluvia ácida que inflige 1000 p. de daño de naturaleza a todos los jugadores que golpea."},
