[446289] = {name = "Fuerza implacable", additional_info = "Instante\n[q]Aumenta el daño cuerpo a cuerpo y a distancia en 20 p. durante 20 s. Cada vez que alcances a un objetivo, esta bonificación se reducirá en 1 p."},
