[446296] = {name = "Despertar muerto", additional_info = nil},
[446297] = {name = "Poder incontenible", additional_info = "Instante\n[q]Aumenta hasta 96 p. tu daño con hechizos y hasta 192 p. tu sanación durante 20 s. Cada vez que lanzas un hechizo, la bonificación pierde 8 p. de daño con hechizos y 16 p. de sanación."},
