[446310] = {name = "Armadura frágil", additional_info = "Instante\n[q]Aumenta 1000 p. tu armadura y 20 p. tu habilidad de defensa durante 20 s. Cada vez que recibes daño cuerpo a cuerpo o a distancia, esta bonificación pierde 100 p. de armadura y 2 p. de defensa."},
[446311] = {name = "Hora de la baba", additional_info = nil},
