[446314] = {name = "Armadura frágil", additional_info = nil},
[446317] = {name = "Drenar vida", additional_info = "Alcance de 40 m\nInstante\n[q]Roba 39 p. de vida al objetivo enemigo."},
[446319] = {name = "Triple cerrojo", additional_info = "Alcance de 45 m\nHechizo de 2 seg\n[q]Inflige daño elemental."},
[446322] = {name = "Sudario esmeralda", additional_info = "Instante\n[q]Reduce la amenaza que generas un 30% durante 20 s."},
[446327] = {name = "Enfurecer", additional_info = "Instante\n[q]Aumenta 20 p. el daño infligido y un 5% la velocidad de ataque durante 15 s."},
[446335] = {name = "Frenesí vudú", additional_info = "Alcance de 30 m\nInstante\n[q]Inspirado por el mojo de guerra, tu tamaño aumenta y tu fuerza sube 35 p. para corresponderse con tu tamaño nuevo. Dura 10 s."},
[446336] = {name = "Mojo Atal'ai de guerra", additional_info = "Instante\n[q]Aumenta el poder de ataque cuerpo a cuerpo y a distancia 48 p. Con cada ataque cuerpo a cuerpo o a distancia, hay una probabilidad de aumentar de tamaño, lo que aumenta la fuerza o la agilidad (el mayor de los dos) 35 p. durante 10 s. Solo puede haber un tipo de poción atal'ai activa a la vez en cualquier momento. Esto no tiene efecto fuera del Templo Sumergido.\n(Probabilidad de que accione: 15%, 40s de reutilización)"},
[446338] = {name = "Cadena de relámpagos", additional_info = "{150 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg 6 seg de reutilización\n[q]Golpea al enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 3 objetivos e inflige mayor daño de Naturaleza a cada objetivo sucesivo."},
[446339] = {name = "Tótem de esqueletos atal'ai", additional_info = "Instante\n[q]Lanza un Tótem atal'ai que dura 1 min e invoca periódicamente un esqueleto de atal'ai. Cada esqueleto dura 30 s."},
[446348] = {name = "Náuseas vomitivas", additional_info = nil},
[446354] = {name = "Embate con escudo", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Escudo\n[q]Inflige 20 p. de daño a un enemigo y lo aturde durante 2 s."},
[446355] = {name = "Punta de escudo", additional_info = nil},
[446356] = {name = "Bloqueo mejorado", additional_info = "Instante\n[q]Aumenta la probabilidad de bloqueo del taumaturgo un 85% durante 6 s."},
[446357] = {name = "Odio a cero", additional_info = "(Probabilidad de que accione: 50%)"},
[446358] = {name = "Atacar", additional_info = nil},
[446360] = {name = "Guardianes de Hukku", additional_info = "Instante\n[q]Invoca a los esbirros demoníacos de Hukku para ayudarlo en combate. Se quedarán hasta que los retires."},
