[450607] = {name = "Peste vagante", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 2 seg 7 min de reutilización\n[q]Enferma a un enemigo durante 5 min, aumenta 5 p. el daño físico que recibe y reduce 30 p. su aguante. El objetivo enfermo tiene un 10% de probabilidad de propagar su enfermedad a uno de sus aliados cercanos cuando lo golpean en combate.\n(Probabilidad de que accione: 10%)"},
[450608] = {name = "S03 - Druid Energize Trigger - Wildheart Raiment", additional_info = "[q]Un 2% de probabilidad de que el lanzamiento de hechizos te energice con 300 p. de maná, un 6% de probabilidad de que al asestar un ataque automático cuerpo a cuerpo te energices con 40 p. de energía, y un 3% de probabilidad al recibir un golpe cuerpo a cuerpo de que te energices con 10 p. de ira.\n(Probabilidad de que accione: 6%)"},
[450625] = {name = "Item - Crusader's Wrath Proc - Lightforge Armor", additional_info = "[q]Un 6% de probabilidad de que los ataques automáticos cuerpo a cuerpo y un 4% de probabilidad de que el lanzamiento de hechizos aumenten tu daño y sanación realizada con hechizos y efectos mágicos hasta 95 p. durante 10 s.\n(Probabilidad de que accione: 6%)"},
[450626] = {name = "Item - The Furious Storm Proc", additional_info = "[q]Un 6% de probabilidad de que los ataques automáticos con la mano derecha y un 4% de probabilidad de que el lanzamiento de hechizos aumenten tu daño y sanación realizada con hechizos y efectos mágicos hasta 95 p. durante 10 s.\n(Probabilidad de que accione: 6%)"},
