[459312] = {name = "Especialización en defensa", additional_info = "[q]La habilidad de defensa aumenta 25 p. No se acumula con otras runas de anillo."},
[459313] = {name = "Grabar anillo - Especialización en defensa", additional_info = "Hechizo de 3 seg\nRequiere Anillo\n[q]Graba tu anillo con la runa de Especialización en defensa:\n\n\nLa habilidad de defensa aumenta 25 p. No se acumula con otras runas de anillo."},
