[459592] = {name = "Cortefusta", additional_info = "Alcance de 45 m\nHechizo de 1.5 seg\n[q]Ataca a los enemigos cercanos con un torbellino de acero que dura 10 s e inflige el daño normal más 50 p."},
[459593] = {name = "Aumento de daño por Multidisparo", additional_info = "[q]Aumenta un 4% el daño infligido con tu hechizo de Multidisparo."},
[459594] = {name = "Reducción de costo de Cambio de forma", additional_info = "[q]Reduce 150 p. el costo de maná de todos los cambios de forma."},
[459595] = {name = "Reducción de retardo de lanzamiento de Cólera", additional_info = "[q]Te otorga un 50% de probabilidad de evitar la interrupción que ocasiona el daño cuando lanzas Cólera."},
