[459599] = {name = "Aumento de amortiguación del escudo de maná", additional_info = "[q]Aumenta la amortiguación de daño de tu Escudo de maná 285 p."},
[459600] = {name = "Reducción de retardo de lanzamiento de Explosión arcana", additional_info = "[q]Te otorga un 50% de probabilidad de evitar la interrupción que ocasiona el daño cuando lanzas Explosión Arcana."},
