[459699] = {name = "Resguardo de miedo", additional_info = "Instante\n[q]Obtienes la habilidad Resguardo de miedo:\n\n\nProtege al objetivo amistoso del miedo. El siguiente efecto de miedo usado contra el objetivo fallará y consumirá la protección. Dura 10 min."},
[459702] = {name = "Rezo desesperado", additional_info = "Instante\n[q]Obtienes la habilidad Rezo desesperado:\n\n\nSana instantáneamente 1340 to 1579 p."},
[459703] = {name = "Rebote", additional_info = "Instante\n[q]Obtienes la habilidad Rebote:\n\n\nEl sacerdote se rodea de energía antimagia. Los hechizos contra él quemarán 105 p. de maná del atacante causando 1 p. de daño de las Sombras por cada punto de maná quemado. Dura 15 s."},
[459705] = {name = "Fragmentos estelares", additional_info = "Instante\n[q]Obtienes la habilidad Fragmentos estelares:\n\n\nLanza una lluvia de Fragmentos estelares sobre la cabeza del enemigo objetivo causando 936 p. de daño Arcano durante 6 s."},
[459706] = {name = "Gracia de Elune", additional_info = "Instante\n[q]Obtienes la habilidad Gracia de Elune:\n\n\nReduce el daño a distancia en 95 p. y aumenta la probabilidad de esquivar en un 10% durante 15 s."},
[459709] = {name = "Guardia de las Sombras", additional_info = "Instante\n[q]Obtienes la habilidad Guardia de las Sombras:\n\n\nEl taumaturgo se rodea de sombras. Si el taumaturgo recibe un golpe de hechizo o ataque cuerpo a cuerpo o a distancia, el atacante recibirá 116 p. de daño de las Sombras. Los atacantes solo recibirán daño cada pocos s. Este daño no causa amenaza. 3 cargas. Dura 10 min."},
[459710] = {name = "Maleficio de debilidad", additional_info = "Instante\n[q]Obtienes la habilidad Maleficio de debilidad:\n\n\nDebilita al objetivo reduciendo el daño que causa en 20 p. y reduce la eficacia de cualquier sanación en un 20%. Dura 2 min."},
[459713] = {name = "Peste devoradora", additional_info = "Instante\n[q]Obtienes la habilidad Peste devoradora:\n\n\nProvoca en el objetivo una enfermedad que causa 904 p. de daño de las Sombras durante 24 s. El daño causado por la Peste devoradora sana al taumaturgo."},
[459714] = {name = "Toque de debilidad", additional_info = "Instante\n[q]Obtienes la habilidad Toque de debilidad:\n\n\nEl próximo ataque cuerpo a cuerpo contra el taumaturgo causará 64 p. de daño de las Sombras y reducirá el daño infligido en 20 p. durante 2 min."},
