[461632] = {name = "Agua bendita de Stratholme", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 6618 p. de maná durante 30 s. Debes permanecer sentado mientras bebes."},
[461633] = {name = "Arma Estigma de Escarcha", additional_info = "160 p. de maná\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Imbuye el arma del Chamán con escarcha. Cada golpe tiene una probabilidad de infligir 187 p. más de daño de Escarcha y de ralentizar la velocidad de movimiento del objetivo un 25% durante 8 s. Dura 1 hora."},
[461634] = {name = "Arma Lengua de Fuego", additional_info = "155 p. de maná\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Imbuye el arma del Chamán con fuego. Cada golpe inflige de 37 a 112 p. más de daño de Fuego, según la velocidad del arma. Las armas más lentas infligen más daño de Fuego por golpe. Dura 1 hora."},
[461635] = {name = "Arma Muerdepiedras", additional_info = "150 p. de maná\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Imbuye el arma del Chamán, aumenta 653 p. su poder de ataque cuerpo a cuerpo y permite que los ataques cuerpo a cuerpo generen más amenaza cuando se usa esa arma. Dura 1 hora."},
[461636] = {name = "Arma Viento Furioso", additional_info = "165 p. de maná\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Imbuye el arma del Chamán con viento. Cada golpe tiene un 20% de probabilidad de otorgarte 2 ataques más con 333 p. más de poder de ataque cuerpo a cuerpo. Dura 1 hora."},
[461637] = {name = "Cambio de fase", additional_info = "{Instante} {10 seg de reutilización}\n[q]Pone al diablillo fuera de fase respecto al mundo, de modo que no puede ser atacado a no ser que ataque."},
[461645] = {name = "[q0]Sobrehombros de dragontina azul filosa", additional_info = "Hechizo de 1 min\nComponentes:\nCuero basto (28), Dragontina azul (30), Cuero encantado (2), Pellejo basto curtido , Hilo rúnico\n[q3]Sobrehombros de dragontina azul filosa\nSe liga al equiparlo\nHombro Malla\n262 armadura\n+6 intelecto\n+6 resistencia a Arcano\nDurabilidad 70 / 70\nNecesitas ser de nivel 54\n[q2]Equipar: Aumenta hasta 25 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Malla de dragón azul (0/3)\n[q0]Coraza de dragontina azul filosa\nLeotardos de dragontina azul filosa\nSobrehombros de dragontina azul filosa"},
