[461698] = {name = "Fragmentos de los Dioses", additional_info = "[q]Tus lanzamientos de hechizos tienen una probabilidad de invocar sirvientes de la Escama o de la Llama.\n(Probabilidad de que accione: 10%, 10s de reutilización)"},
