[469301] = {name = "Domesticar bestia", additional_info = "Alcance de 30 m\nHechizo de 3 seg\n[q]Comienza a domesticar una bestia para que se convierta en tu compañera. Tu armadura se reduce un 0% durante hasta cancelación mientras te concentras en la domesticación de la bestia. Si pierdes la atención de la bestia por cualquier motivo, el proceso de domesticación fracasará. Cuando la domestiques, la bestia estará triste y no será leal. Intenta alimentar a la mascota de inmediato para hacerla feliz."},
[469306] = {name = "Domesticar bestia", additional_info = "Alcance de 30 m\nHechizo de 3 seg\n[q]Comienza a domesticar una bestia para que se convierta en tu compañera. Tu armadura se reduce un 0% durante hasta cancelación mientras te concentras en la domesticación de la bestia. Si pierdes la atención de la bestia por cualquier motivo, el proceso de domesticación fracasará. Cuando la domestiques, la bestia estará triste y no será leal. Intenta alimentar a la mascota de inmediato para hacerla feliz."},
[469320] = {name = "Ráfaga de lava", additional_info = "{10% del maná base} {Alcance de 40 m}\nHechizo de 3 seg\n[q]Lanzas al objetivo lava fundida que inflige de [875 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] a [1125 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] p. de daño de Fuego. Si el objetivo tiene tu Choque de llamas, Ráfaga de lava asestará un golpe crítico."},
