[470080] = {name = "Ídolo de enfoque felino", additional_info = "[q]Tu habilidad Mordedura feroz ya no convierte la energía adicional en daño y devuelve 30 p. de energía al esquivar, fallar o parar."},
[470081] = {name = "Tótem de tormentas embravecidas", additional_info = "[q]Mientras tienes un escudo equipado, tus ataques cuerpo a cuerpo con Arma Muerdepiedras activan tu runa Arma vorágine con un 100 + (5 * ComboPoints)% más de frecuencia."},
