[470235] = {name = "Tótem de flujo astral", additional_info = "[q]Aumenta el poder de ataque de los ataques con arma Viento furioso 68 p."},
[470240] = {name = "Tótem de corrientes conductoras", additional_info = "[q]Mientras Arma Estigma de Escarcha está activa en tu arma de mano derecha, las activaciones de tu Escudo de agua reducen un 20% el tiempo de lanzamiento de tu siguiente Cadena de relámpagos en 15 s, y aumenta un 20% su daño. Se acumula hasta 5 veces."},
[470246] = {name = "Tratado sobre cólera", additional_info = "[q]Infligir daño con tu Choque sagrado reduce el tiempo de lanzamiento y el costo de maná de tu siguiente Cólera sagrada lanzada en menos de 15 s un 20% y aumenta su daño un 20%. Este efecto se acumula hasta 5 veces."},
[470263] = {name = "Tratado sobre revancha", additional_info = "[q]Tu Escudo de vengador golpea a 2 objetivos menos, pero golpeará a su objetivo 2 veces."},
[470264] = {name = "Escudo de vengador", additional_info = nil},
[470265] = {name = "Escudo de vengador", additional_info = "Alcance de 40 m\nInstante\n[q]Lanza un Escudo sagrado al enemigo que inflige de [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] a [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] p. de daño Sagrado y lo atonta. A continuación, salta a los enemigos cercanos. Afecta a 1 objetivos en total. Dura 5 s."},
[470266] = {name = "Aumentar sanación de Nutrir", additional_info = "[q]Aumenta hasta 77 p. la sanación de Nutrir."},
[470269] = {name = "Ídolo de crueldad", additional_info = "[q]Aumenta el daño inicial y el periódico causado por Lacerar 7 p. con cada aplicación."},
[470270] = {name = "Ídolo de enfoque felino", additional_info = nil},
[470271] = {name = "Tratado sobre cólera", additional_info = "Instante\n[q]Modifies Cast Time -19%:\nCólera Sagrada , Cólera Sagrada\n\nModifies Power Cost -19%:\nCólera Sagrada , Cólera Sagrada\n\nModifies Damage/Healing Done +21%:\nCólera Sagrada , Cólera Sagrada"},
[470272] = {name = "Tótem de corrientes conductoras", additional_info = "Instante\n[q]Modifies Cast Time -19%:\nCadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos\n\nModifies Damage/Healing Done +21%:\nCadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos , Cadena de relámpagos"},
