[471399] = {name = "Fórmula: lustre trol magnífico", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear lustre trol magnífico."},
[471400] = {name = "Lustre trol magnífico", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nFrasco de mojo (3), Frasco de gran mojo (3), Fragmento luminoso grande (2), Vial imbuido\n[q]Crea lustre trol magnífico.\nNecesitas ser de nivel 45\n[q2]Uso: Cuando se aplica al escudo objetivo, aumenta hasta 36 p. el daño y la sanación, y aumenta un 1% la probabilidad de golpe crítico con hechizos. Dura 30 minutos.\n5 cargas"},
[471401] = {name = "Lustre trol magnífico", additional_info = "Hechizo de 3 seg\nRequiere Armas\n[q]Cuando se aplica al escudo objetivo, aumenta hasta 36 p. el daño y la sanación, y aumenta un 1% la probabilidad de golpe crítico con hechizos. Dura 30 minutos."},
[471402] = {name = "Aumentar daño con hechizos 36 y 1% el golpe crítico", additional_info = "[q]Aumenta hasta 36 p. el daño y la sanación realizados con hechizos y efectos mágicos. También aumenta un 1% la probabilidad de asestar un golpe crítico con hechizos."},
