[473384] = {name = "Invocar escudero", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 1 seg\n[q]Usa el manual para llamar a tu escudero Argenta y darle una lección de entrenamiento en combate contra silítidos. Los silítidos derrotados en presencia del escudero aumentan tu reputación con el Alba Argenta."},
[473387] = {name = "Cuerno del Alba", additional_info = "Rango ilimitado\nInstante\n[q]Reúne a los miembros de tu grupo o banda cercanos, aumenta un 10% su probabilidad de golpe crítico con hechizos, un 5% su probabilidad de golpe crítico con ataques cuerpo a cuerpo o a distancia, y 140 p. su poder de ataque. Dura 2 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios."},
[473399] = {name = "Arrullo de cantaflor", additional_info = "Alcance de 30 m\nInstante\n[q]Invoca una melodía que aumenta un 5% la probabilidad de golpe crítico cuerpo a cuerpo, a distancia o con hechizos, y 15 p. los atributos de todos los miembros de tu grupo o banda durante 1 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios."},
[473403] = {name = "Bendición de Neptulon", additional_info = "Alcance de 100 m\nInstante\n[q]Aumenta 200 p. el poder de ataque, un 15% el aguante y un 3% la probabilidad de golpe crítico con hechizos de todos los miembros de tu grupo o banda durante 2 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios."},
[473441] = {name = "Poderío de Roca Negra", additional_info = "Rango ilimitado\nInstante\n[q]Aumenta 300 p. los puntos de salud. 15% de celeridad a los ataques cuerpo a cuerpo. 10 p. de regeneración de maná cada 5 s."},
[473450] = {name = "Daño de fortuna de las Sombras", additional_info = "Rango ilimitado\nInstante\n[q]Aumenta un 10% el daño infligido de todos los miembros de tu grupo o banda durante 2 h."},
[473466] = {name = "Caldero de aguardiente", additional_info = "Alcance de 30 m\nInstante\n[q]Invoca un caldero de aguardiente durante 10 min que todos los miembros de tu grupo o banda pueden usar para aumentar 35 p. el poder de ataque cuerpo a cuerpo y el tamaño durante 1 h."},
[473469] = {name = "Aguardiente purificada", additional_info = "Instante\n[q]Aumenta 35 p. tu poder de ataque cuerpo a cuerpo y tu tamaño durante 1 h."},
[473476] = {name = "Sueños de Zandalar", additional_info = "Rango ilimitado\nInstante\n[q]Aumenta un 10% la velocidad de movimiento y un 15% las estadísticas de todos los miembros de tu grupo o banda durante 2 h."},
[473477] = {name = "Serenata Cantaflor", additional_info = nil},
[473482] = {name = "Disyunción elemental", additional_info = "Alcance de 20 m\nInstante\n[q]Debilita a los miembros elementales del Consejo Abisal de Silithus, lo que reduce todo el daño que infligen un 20%. Dura 2 min."},
[473493] = {name = "Trampa de arena explosiva", additional_info = "Alcance de 35 m\n15 seg de reutilización\n[q]Colocas una trampa en un lugar cercano que explota cuando se acerca un silítido de Colmen'Ashi, Colmen'Regal o Colmen'Zora, lo que hace que el silítido reciba un 6% de su salud como daño cada 3 s durante 15 s."},
[473496] = {name = "Trampa de arena explosiva", additional_info = nil},
[473525] = {name = "Rayo congelamático", additional_info = "Alcance de 35 m\n[q]Congela a un silítido en las colmenas Colmen'Ashi, Colmen'Regal o Colmen'Zora durante 1 min. Cualquier daño cancela el efecto."},
[473544] = {name = "Escabullida", additional_info = "Instante\n[q]Inhalar este incienso hace que te desvanezcas entre las sombras, lo que te permite escabullirte mientras estés en Colmen'Ashi, Colmen'Regal o Colmen'Zora, pero reduce un 50% tu velocidad. Dura 1 min."},
[473561] = {name = "Lazo", additional_info = "Alcance de 30 m\nInstante\n[q]Lanzas la cuerda antigua para sujetar a un silítido de Colmen'Ashi, Colmen'Regal o Colmen'Zora y atraerlo hacia ti. No puede utilizarse contra enemigos de nivel superior a ( 60 + 1) o que estén marcados como jefes."},
[473568] = {name = "Lazo", additional_info = nil},
[473570] = {name = "Lazo", additional_info = nil},
