[473702] = {name = "Invocar anciano", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 1 seg\n[q]Usa la rama para invocar a un Anciano de la Guerra para que te ayude a combatir a los silítidos."},
[473847] = {name = "Invocar Tanque de batalla qiraji verde claro", additional_info = "Hechizo de 3 seg\n[q]Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz."},
[473848] = {name = "Invocar Tanque de batalla qiraji verde claro", additional_info = "Instante\n[q]Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz."},
