[1213271] = {name = "Trampa de inmolación", additional_info = "245 p. de maná\n{Instante} {15 seg de reutilización}\n[q]Coloca una trampa de fuego que quema al primer enemigo que se acerca y le inflige 690 p. de daño de Fuego durante 15 s. La trampa dura 1 min. Las trampas solo pueden colocarse cuando estás fuera de combate y solo puede haber una trampa activa a la vez."},
[1213272] = {name = "Disparar", additional_info = "Alcance de 5 - 30 m\nInstante\nRequiere Arma a distancia\n[q]Dispara a un enemigo y le inflige daño físico."},
