[1213353] = {name = "S03 - Item - TAQ - Paladin - Holy 4P Bonus", additional_info = "[q]Tus sanaciones sobre el objetivo de tu Señal de la Luz también sanan al objetivo aliado más cercano por un 90%."},
[1213355] = {name = "Choque", additional_info = "Alcance de 20 m\nInstante\n[q]Golpea instantáneamente a un enemigo con choques de relámpagos que infligen 339 to 377 p. de daño de Naturaleza."},
[1213356] = {name = "Dominar mente", additional_info = "Alcance de 20 m\nHechizo de 2 seg\n[q]Controla a un enemigo humanoide de nivel 25 o inferior durante 5 s, pero aumenta el tiempo entre sus ataques un 100%."},
[1213366] = {name = "Jom Gabbar", additional_info = "Instante\n[q]Aumenta 70 p. el poder de ataque, y otros 70 p. cada 2 s. Dura 20 s."},
[1213367] = {name = "Jom Gabbar", additional_info = nil},
[1213375] = {name = "La coraza del perforador", additional_info = "{Instante} {1 seg de reutilización}\n[q]Absorbe 1200 p. de daño. Dura 20 s."},
[1213377] = {name = "Señal conjunta", additional_info = nil},
[1213381] = {name = "Golpe de antaño", additional_info = nil},
[1213390] = {name = "Golpe de antaño", additional_info = "[q]Te otorga un 1% de probabilidad por pieza de armadura de antaño equipada de realizar un ataque adicional con los golpes cuerpo a cuerpo o a distancia.\n(Probabilidad de que accione: 8%, 200ms de reutilización)"},
[1213393] = {name = "Disparo de antaño", additional_info = nil},
[1213395] = {name = "Disparo de antaño", additional_info = "(Probabilidad de que accione: 8%, 200ms de reutilización)"},
[1213397] = {name = "S03 - Item - TAQ - Paladin - Retribution 2P Bonus", additional_info = "[q]Aumenta un 150% el daño de Golpe de cruzado."},
[1213398] = {name = "Hechizo de antaño", additional_info = "[q]Aumenta un 2% la velocidad de lanzamiento de tus hechizos por cada pieza de armadura de antaño equipada."},
[1213405] = {name = "Sanación de antaño", additional_info = "[q]Aumenta un 2% la efectividad de tus hechizos de sanación y protección por cada pieza de armadura de antaño equipada."},
[1213406] = {name = "S03 - Item - TAQ - Paladin - Retribution 4P Bonus", additional_info = "[q]Tus ataques básicos con armas cuerpo a cuerpo de dos manos aumentan un 35% el daño de tu siguiente lanzamiento de Exorcismo en los próximos 20 s. Se acumula hasta 3 veces."},
[1213407] = {name = "Pericia de antaño", additional_info = "[q]Reduce un 1% la probabilidad de que esquiven o paren tus ataques por cada pieza de armadura de antaño equipada."},
[1213408] = {name = "Bendición de reyes", additional_info = nil},
[1213410] = {name = "S03 - Item - TAQ - Paladin - Protection 2P Bonus", additional_info = "[q]Tu Bendición de salvaguardia también aumenta un 10% todas las estadísticas cuando la lanzas sobre ti."},
[1213411] = {name = "Vacío Abisal", additional_info = "[q]Otorga al portador un 100% de probabilidad de resucitar con un 20% de salud y maná. (3 min de tiempo de reutilización)."},
[1213412] = {name = "Vacío Abisal", additional_info = nil},
[1213413] = {name = "S03 - Item - TAQ - Paladin - Protection 4P Bonus", additional_info = "[q]Escudo del honrado hace que el lanzamiento de tu próxima Luz Sagrada sea instantáneo. Si la lanzas sobre ti, restaurará un 100% de su costo de maná y no será afectada por Custodiado por la Luz."},
[1213414] = {name = "Vacío Abisal", additional_info = nil},
[1213415] = {name = "Protección de rectitud", additional_info = "Instante\n[q]Modifies Cast Time -99%:\nLuz Sagrada , Luz Sagrada , Luz Sagrada , Luz Sagrada , Luz Sagrada , Luz Sagrada , Luz Sagrada , Luz Sagrada , Luz Sagrada"},
[1213417] = {name = "Golpe de relámpagos", additional_info = "[q]Probabilidad de golpear a tu objetivo cuerpo a cuerpo con relámpagos que infligen 317 to 517 p. de daño de Naturaleza."},
[1213418] = {name = "Golpe de relámpagos", additional_info = "Alcance de 20 m\nInstante\n[q]Golpe de relámpagos que inflige 317 to 517 p. de daño de Naturaleza."},
[1213419] = {name = "Heroísmo", additional_info = "[q]A veces sana 170 to 230 p. de daño al portador cuando daña a un enemigo cuerpo a cuerpo."},
[1213420] = {name = "Heroísmo", additional_info = "Instante\n[q]A veces sana 170 to 230 p. de daño al portador cuando ataca a un enemigo."},
[1213421] = {name = "Aura del dragón azul", additional_info = "[q]5% de probabilidad de que, al lanzar un hechizo con éxito, un 100% de tu regeneración de maná continúe mientras lanzas hechizos durante 15 s.\n(Probabilidad de que accione: 5%)"},
[1213422] = {name = "Aura del dragón azul", additional_info = "Instante\n[q]5% de probabilidad de que, al lanzar un hechizo con éxito, un 100% de tu regeneración de maná continúe mientras lanzas hechizos durante 15 s."},
[1213441] = {name = "Golpe siniestro", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Inflige daño normal más 1 p. a un enemigo."},
[1213442] = {name = "Garrote", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Inflige 36 p. de daño a un enemigo cada 3 s durante 18 s cuando atacas con sigilo."},
[1213450] = {name = "Corrupción", additional_info = "Alcance de 30 m\nHechizo de 2 seg\n[q]Corrompe a los enemigos cercanos, lo que inflige daño de las Sombras cada 3 s durante 24 s."},
[1213451] = {name = "Lluvia de Fuego", additional_info = "{15 p. de maná} {Alcance de 30 m}\nCanalizado (Hechizo de 9 seg)\n[q]Invoca una lluvia de arrabio que quema a todos los enemigos del área seleccionada y les inflige 3 p. de daño de Fuego cada 3 s durante 9 s."},
[1213452] = {name = "Miedo", additional_info = "Alcance de 20 m\nHechizo de 1.5 seg\n[q]Causa miedo en el enemigo y hace que huya durante 4 s. Solo se puede asustar a 1 objetivo cada vez."},
[1213461] = {name = "Protección de rectitud", additional_info = nil},
[1213462] = {name = "Embate con escudo", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Escudo\n[q]Inflige 20 p. de daño a un enemigo y lo aturde durante 2 s."},
[1213463] = {name = "Cargar", additional_info = "Alcance de 8 - 25 m\nInstante\n[q]Carga contra un enemigo, le inflige daño normal más 0 p. y aturde al oponente durante hasta cancelación."},
[1213464] = {name = "Atronar", additional_info = "Instante\n[q]Inflige 24 to 26 p. de daño de Naturaleza a los enemigos cercanos, lo que aumenta un 33% el tiempo entre sus ataques y reduce un 40% su velocidad de movimiento durante 10 s."},
[1213465] = {name = "Grito intimidador", additional_info = "Alcance de 10 m\nInstante\n[q]Grita a un enemigo, lo que lo paraliza con terror durante 8 s y hace que todos los demás enemigos cercanos huyan despavoridos."},
[1213466] = {name = "Lobo Crines de Acero", additional_info = "Instante\n[q]Invoca 1 lobo Crines de Acero para acompañar al taumaturgo hasta que lo retire."},
[1213467] = {name = "S03 - Item - RAQ - Paladin - Retribution 3P Bonus", additional_info = "[q]Con un arma de una mano equipada, Golpe de cruzado ahora libera el efecto de Sentencia de tus Sellos, pero no consume el Sello."},
[1213477] = {name = "Cadena de relámpagos", additional_info = "{150 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg 6 seg de reutilización\n[q]Golpea al enemigo con una descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 3 objetivos e inflige mayor daño de Naturaleza a cada objetivo sucesivo."},
[1213478] = {name = "Diseño: jaula de cabeza filoespina", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una jaula de cabeza filoespina."},
[1213479] = {name = "Escudo de relámpagos", additional_info = "{5 p. de maná} {Alcance de 30 m}\n{Instante} {10 seg de reutilización}\n[q]Rodea al taumaturgo con 3 bolas de relámpagos que tienen un 50% de probabilidad de golpear a los atacantes cuerpo a cuerpo o a distancia e infligirles 2 p. de daño. Cada vez que el escudo de relámpagos contraataca, se disipa una bola de relámpagos. Así, el escudo se disipa después de 10 min o después de golpear 3 veces.\n(Probabilidad de que accione: 50%)"},
[1213480] = {name = "Tótem Nexo Terrestre", additional_info = "40 p. de maná\nInstante\nHerramientas: Tótem de tierra\n[q]Invoca un Tótem Nexo Terrestre que dura 45 s y reduce periódicamente la velocidad de movimiento de los enemigos cercanos a un 50% de lo normal."},
[1213481] = {name = "[q4]Jaula de cabeza filoespina", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (15), Barra de torio de infusión obsidiana (3), Cuero encantado (4), Garra maligna (10), Quitina de silítido monstruosa (4)\n[q4]Jaula de cabeza filoespina\nSe liga al equiparlo\nCabeza Placas\n722 armadura\n+14 fuerza\n+40 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, le inflige 100 p. de daño de Naturaleza al atacante. Genera el doble de amenaza que la cantidad de daño infligido.\n[q2]Equipar: Aumenta 9 p. el índice de defensa."},
[1213482] = {name = "Choque de llamas", additional_info = "{110 p. de maná} {Alcance de 20 m}\nInstante\n[q]Quema instantáneamente a un enemigo y luego inflige daño de Fuego adicional cada 3 s durante 12 s."},
[1213483] = {name = "Diseño: hombreras de placas filoespina", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer unas hombreras de placas filoespina."},
[1213484] = {name = "[q4]Hombreras de placas filoespina", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (15), Barra de torio de infusión obsidiana (3), Cuero encantado (4), Garra maligna (10), Quitina de silítido monstruosa (4)\n[q4]Hombreras de placas filoespina\nSe liga al equiparlo\nHombro Placas\n667 armadura\n+11 fuerza\n+29 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, le inflige 80 p. de daño de Naturaleza al atacante. Genera el doble de amenaza que la cantidad de daño infligido.\n[q2]Equipar: Aumenta 7 p. el índice de defensa."},
[1213489] = {name = "Diseño: placa de batalla filoespina", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una placa de batalla filoespina."},
[1213490] = {name = "[q4]Placa de batalla filoespina", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (20), Barra de torio de infusión obsidiana (4), Cuero encantado (4), Garra maligna (10), Quitina de silítido monstruosa (8)\n[q4]Placa de batalla filoespina\nSe liga al equiparlo\nPecho Placas\n889 armadura\n+12 fuerza\n+40 aguante\nDurabilidad 165 / 165\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, le inflige 100 p. de daño de Naturaleza al atacante. Genera el doble de amenaza que la cantidad de daño infligido.\n[q2]Equipar: Aumenta 10 p. el índice de defensa."},
[1213491] = {name = "Diseño: atracadora de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una atracadora de obsidiana."},
[1213492] = {name = "[q4]Atracadora de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (40), Barra de torio de infusión obsidiana (10), Cuero encantado (8), Piedra de pulir de obsidiana (6), Ídolo de alabastro (4), Ídolo de la guerra (2)\n[q4]Atracadora de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)Dos manos Hacha\n203 - 340 p. de daño Velocidad 3.70\n(73.38 p. de daño por segundo)\n+40 fuerza\n+30 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1213496] = {name = "Diseño: adalid de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una adalid de obsidiana."},
[1213498] = {name = "[q4]Adalid de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (40), Barra de torio de infusión obsidiana (10), Cuero encantado (8), Piedra de pulir de obsidiana (6), Ídolo bermellón (4), Ídolo de la Vida (2)\n[q4]Adalid de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)Dos manos Espada\n117 - 176 p. de daño Velocidad 2.00\n(73.25 p. de daño por segundo)\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Probabilidad al acertar: Te sana 270 to 450 p. y aumenta tu fuerza 120 p. durante 30 s.\n[q2]Probabilidad al acertar: Aumenta 20 p. el daño infligido y un 5% la velocidad de ataque durante 15 s.\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1213499] = {name = "Diseño: destructora de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una destructora de obsidiana."},
[1213500] = {name = "[q4]Destructora de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (40), Barra de torio de infusión obsidiana (10), Piedra de pulir de obsidiana (8), Ídolo de alabastro (4), Ídolo bermellón (4), Ídolo de la Noche (2)\n[q4]Destructora de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)Dos manos Maza\n117 - 176 p. de daño Velocidad 2.00\n(73.25 p. de daño por segundo)\n+40 fuerza\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: +260 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Probabilidad al acertar: Aturde al objetivo durante 3 s.\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1213501] = {name = "Diseño: martillo de tormenta de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un martillo de tormenta de obsidiana."},
[1213502] = {name = "[q4]Martillo de tormenta de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (30), Barra de torio de infusión obsidiana (8), Cuero encantado (5), Piedra de pulir de obsidiana (6), Ídolo de obsidiana (3), Ídolo de Renacer (2)\n[q4]Martillo de tormenta de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)Mano derecha Maza\n49 - 117 p. de daño Velocidad 2.00\n(41.50 p. de daño por segundo)\n+10 aguante\n+8 intelecto\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Probabilidad al acertar: Golpea a un máximo de 3 objetivos e inflige 105 to 145 p. de daño de Naturaleza.\n[q2]Equipar: Aumenta hasta 60 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1213503] = {name = "Diseño: hoja sabia de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una hoja sabia de obsidiana."},
[1213504] = {name = "[q4]Hoja sabia de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (30), Barra de torio de infusión obsidiana (8), Cristal nexo (3), Piedra de pulir de obsidiana (3), Ídolo de obsidiana (3), Ídolo del sabio (2)\n[q4]Hoja sabia de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)Mano derecha Espada\n37 - 88 p. de daño Velocidad 1.50\n(41.67 p. de daño por segundo)\n+14 aguante\n+12 intelecto\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 60 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Las resistencias mágicas de los objetivos de tus hechizos se reducen 20 p.\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1213505] = {name = "Diseño: defensora de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una defensora de obsidiana."},
[1213506] = {name = "[q4]Defensora de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (30), Barra de torio de infusión obsidiana (8), Piedra de pulir de obsidiana (6), Ídolo bermellón (3), Ídolo de obsidiana (3), Ídolo del Sol (2)\n[q4]Defensora de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)Mano derecha Hacha\n106 - 198 p. de daño Velocidad 2.70\n(56.30 p. de daño por segundo)\n+11 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 9 p. el índice de defensa.\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1213509] = {name = "Patrón: refuerzo para armadura de quitina resplandeciente", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a fabricar un refuerzo para armadura de quitina resplandeciente."},
[1213513] = {name = "[q3]Refuerzo para armadura de quitina resplandeciente", additional_info = "Hechizo de 25 seg\nComponentes:\nQuitina de silítido con púas (5), Tela lunar (3), Refuerzo para armadura del Núcleo\n[q3]Refuerzo para armadura de quitina resplandeciente\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta de forma permanente hasta 10 p. el daño y la sanación con hechizos de un objeto para el torso, las piernas, las manos o los pies. Solo puede usarse en objetos de nivel 45 o superior."},
[1213518] = {name = "Patrón: refuerzo para armadura de quitina afilada", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a fabricar un refuerzo para armadura de quitina afilada."},
[1213519] = {name = "[q3]Refuerzo para armadura de quitina afilada", additional_info = "Hechizo de 25 seg\nComponentes:\nQuitina de silítido con púas (5), Pellejo basto curtido (3), Refuerzo para armadura del Núcleo\n[q3]Refuerzo para armadura de quitina afilada\nNecesitas ser de nivel 50\n[q2]Uso: Hace que un objeto para el torso, las piernas, las manos o los pies inflija, de forma permanente, 20 p. de daño de Naturaleza al atacante cuando recibe un golpe en combate. Solo puede usarse en objetos de nivel 45 o superior."},
[1213520] = {name = "Patrón: capucha zarzafilo", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear una capucha zarzafilo."},
[1213521] = {name = "[q4]Capucha zarzafilo", additional_info = "Hechizo de 25 seg\nComponentes:\nQuitina de silítido con púas (15), Cuero encantado (8), Madeja de seda qiraji (8), Pellejo basto curtido (8)\n[q4]Capucha zarzafilo\nSe liga al equiparlo\nCabeza Cuero\n[q2]268 armadura\n+15 agilidad\n+37 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, le inflige 100 p. de daño de Naturaleza al atacante. Genera el doble de amenaza que la cantidad de daño infligido.\n[q2]Equipar: Aumenta 9 p. el índice de defensa."},
[1213522] = {name = "Patrón: hombreras zarzafilo", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear unas hombreras zarzafilo."},
[1213523] = {name = "[q4]Hombreras zarzafilo", additional_info = "Hechizo de 25 seg\nComponentes:\nQuitina de silítido con púas (15), Cuero encantado (8), Madeja de seda qiraji (8), Pellejo basto curtido (8)\n[q4]Hombreras zarzafilo\nSe liga al equiparlo\nHombro Cuero\n[q2]234 armadura\n+8 agilidad\n+29 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, le inflige 80 p. de daño de Naturaleza al atacante. Genera el doble de amenaza que la cantidad de daño infligido.\n[q2]Equipar: Aumenta 7 p. el índice de defensa."},
[1213524] = {name = "Patrón: cueros zarzafilo", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear unos cueros zarzafilo."},
[1213525] = {name = "[q4]Cueros zarzafilo", additional_info = "Hechizo de 25 seg\nComponentes:\nQuitina de silítido con púas (22), Cuero encantado (12), Madeja de seda qiraji (12), Pellejo basto curtido (12)\n[q4]Cueros zarzafilo\nSe liga al equiparlo\nPecho Cuero\n[q2]312 armadura\n+15 agilidad\n+38 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, le inflige 100 p. de daño de Naturaleza al atacante. Genera el doble de amenaza que la cantidad de daño infligido.\n[q2]Equipar: Aumenta 10 p. el índice de defensa."},
[1213526] = {name = "Patrón: capucha vampírica", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar una capucha vampírica."},
[1213527] = {name = "[q4]Capucha vampírica", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de seda qiraji (15), Tela lunar (8), Cuero encantado (8), Hilo rúnico\n[q4]Capucha vampírica\nSe liga al equiparlo\nCabeza Tela\n[q2]178 armadura\n+40 aguante\n+10 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, tiene un 20% de probabilidad de robarle 50 p. de vida al objetivo. (Probabilidad de que accione: 20%)\n[q2]Equipar: Aumenta 9 p. el índice de defensa."},
[1213529] = {name = "Patrón: chal vampírico", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar un chal vampírico."},
