[1213534] = {name = "[q4]Bufanda de seda qiraji", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de seda qiraji (9), Quitina de silítido con púas (8), Pellejo basto curtido (4), Cuero encantado (8), Hilo rúnico\n[q4]Bufanda de seda qiraji\nSe liga al equiparlo\nEspalda\n56 armadura\n+23 fuerza\n+6 aguante\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[1213536] = {name = "[q4]Manteo de seda qiraji", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de seda qiraji (9), Quitina de silítido con púas (8), Pellejo basto curtido (4), Cuero encantado (8), Hilo rúnico\n[q4]Manteo de seda qiraji\nSe liga al equiparlo\nEspalda\n56 armadura\n+23 agilidad\n+6 aguante\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[1213537] = {name = "Patrón: manteo de seda qiraji", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar un manteo de seda qiraji."},
[1213538] = {name = "[q4]Capa de seda qiraji", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de seda qiraji (9), Quitina de silítido con púas (8), Pellejo basto curtido (4), Cuero encantado (8), Hilo rúnico\n[q4]Capa de seda qiraji\nSe liga al equiparlo\nEspalda\n56 armadura\n+6 aguante\n+7 intelecto\n+7 espíritu\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 25 p. el daño y la sanación de los hechizos y efectos mágicos."},
[1213539] = {name = "Patrón: capa de seda qiraji", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar una capa de seda qiraji."},
[1213540] = {name = "[q4]Mantón de seda qiraji", additional_info = "Hechizo de 1 min\nComponentes:\nMadeja de seda qiraji (9), Quitina de silítido con púas (8), Pellejo basto curtido (4), Cuero encantado (8), Hilo rúnico\n[q4]Mantón de seda qiraji\nSe liga al equiparlo\nEspalda\n56 armadura\n+7 aguante\n+10 intelecto\n+8 espíritu\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 31 p. la sanación realizada y hasta 11 p. el daño que infligen todos los efectos y hechizos mágicos."},
[1213541] = {name = "Patrón: mantón de seda qiraji", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a confeccionar un mantón de seda qiraji."},
[1213544] = {name = "Frasco de pena implacable", additional_info = "Hechizo de 25 seg\nHerramientas: Piedra filosofal\nComponentes:\nEsencia eterna superior , Cardo de colmena , Frasco de sabiduría destilada , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta hasta 80 p. la sanación realizada por hechizos y efectos mágicos, hasta 27 p. el daño que infligen los hechizos y efectos mágicos y 12 p. la regeneración de maná cada 5 s durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte. (3 Seg Reutilización)"},
[1213545] = {name = "Receta: frasco de pena implacable", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un frasco de pena implacable."},
[1213546] = {name = "Frasco de conocimiento antiguo", additional_info = "Hechizo de 25 seg\nHerramientas: Piedra filosofal\nComponentes:\nEsencia eterna superior , Veneno de acechador qiraji , Frasco de poder supremo , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta hasta 180 p. el daño que infligen los hechizos y efectos mágicos durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte. (3 Seg Reutilización)"},
[1213547] = {name = "Receta: frasco de conocimiento antiguo", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un frasco de conocimiento antiguo."},
[1213548] = {name = "Frasco de los dioses antiguos", additional_info = "Hechizo de 25 seg\nHerramientas: Piedra filosofal\nComponentes:\nEsencia eterna superior , Quitina de silítido monstruosa , Frasco de los titanes , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta 100 p. el aguante y 10 p. el valor de defensa durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte. (3 Seg Reutilización)"},
[1213550] = {name = "Receta: frasco de los dioses antiguos", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un frasco de los dioses antiguos."},
[1213552] = {name = "Frasco de locura", additional_info = "Hechizo de 25 seg\nHerramientas: Piedra filosofal\nComponentes:\nEsencia eterna superior , Bilis de gusano de arena antiguo , Frasco de resistencia cromática , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta 50 p. el poder de ataque durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte. (3 Seg Reutilización)"},
[1213553] = {name = "Receta: frasco de locura", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un frasco de locura."},
[1213559] = {name = "Elixir del tejón mielero", additional_info = "Hechizo de 3 seg\nComponentes:\nSalviargenta de montaña (2), Cardo de colmena (2), Veneno de acechador qiraji , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta 30 p. la agilidad, un 2% la probabilidad de asestar un golpe crítico y 15 p. la resistencia a la Naturaleza durante 1 h. (3 Seg Reutilización)"},
[1213560] = {name = "Receta: elixir del tejón mielero", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un elixir del tejón mielero."},
[1213563] = {name = "Elixir del señor de la magia", additional_info = "Hechizo de 3 seg\nComponentes:\nFlor de plaga (2), Cardo de colmena (2), Veneno de acechador qiraji , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta el daño con hechizos hasta un máximo de 40 p. y la resistencia a la Naturaleza 15 p. durante 1 h. (3 Seg Reutilización)"},
