[1213565] = {name = "Elixir de los Ladoférreo", additional_info = "Hechizo de 3 seg\nComponentes:\nSetelo (2), Cardo de colmena (2), Veneno de acechador qiraji , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta 450 p. la armadura, 5 p. la defensa y 15 p. la resistencia a la Naturaleza durante 1 h. (3 Seg Reutilización)"},
[1213566] = {name = "Receta: elixir de los Ladoférreo", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un elixir de los Ladoférreo."},
[1213571] = {name = "Elixir de prontitud", additional_info = "Hechizo de 3 seg\nComponentes:\nHojasueño (2), Cardo de colmena (2), Veneno de acechador qiraji , Vial de cristal\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 15% la velocidad de carrera del jugador durante 1 h. (3 Seg Reutilización)"},
[1213572] = {name = "Receta: elixir de prontitud", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un elixir de prontitud."},
[1213573] = {name = "Megabomba arcana", additional_info = "Hechizo de 25 seg\nComponentes:\nConversor de arcanita delicado , Cristal nexo , Paño rúnico\n(6)\nNecesitas ser de nivel 60\n[q2]Uso: Drena 1075 to 1525 p. de maná de todos los que estén en el radio de la explosión y convierte un 50% del maná drenado en daño que se inflige al objetivo. Además, silencia a los objetivos en el radio de la explosión durante 5 s. (1 Min Reutilización)"},
[1213575] = {name = "Esquema: megabomba arcana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una megabomba arcana."},
[1213576] = {name = "El fumigador", additional_info = "Hechizo de 25 seg\nComponentes:\nVeneno de acechador qiraji , Pólvora densa de obsidiana (2), Paño rúnico\nNecesitas ser de nivel 60\n[q2]Uso: Estalla cuando se activa, lo que inflige 650 to 950 p. de daño de Fuego a todos los enemigos cercanos y te inflige 475 to 725 p. de daño. Inflige más daño a las criaturas silítidas en Silithus. (5 Min Reutilización)"},
[1213577] = {name = "Esquema: el fumigador", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer el fumigador."},
[1213578] = {name = "Bomba de obsidiana", additional_info = "Hechizo de 25 seg\nComponentes:\nPólvora densa de obsidiana (3), Quitina de silítido con púas , Seda qiraji , Piedra densa\n(4)\nNecesitas ser de nivel 60\n[q2]Uso: Inflige 530 to 670 p. de daño de Fuego en un radio de 5 m. (1 Min Reutilización)"},
[1213579] = {name = "Esquema: bomba de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una bomba de obsidiana."},
[1213586] = {name = "[q3]Generador BU3N 4-0ND4", additional_info = "Hechizo de 25 seg\nComponentes:\nPólvora densa de obsidiana (20), Cardo de colmena (30), Madeja de seda qiraji (8), Veneno de acechador qiraji (8), Bilis de gusano de arena antiguo (8), Quitina de silítido con púas (8)\n[q3]Generador BU3N 4-0ND4\n(2)\nSe liga al recogerlo\nÚnico\nNecesitas ser de nivel 60\n[q2]Uso: Se convierte en un generador BU3N 4-0ND4 que repara objetos dañados y compra objetos sobrantes. Después de 10 min, su motor interno falla y debe recuperarse. (4 H Reutilización)"},
[1213587] = {name = "Esquema: generador BU3N 4-0ND4", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un generador de buenas vibras."},
[1213588] = {name = "[q4]Disco reactivo a la fuerza mejorado", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nDisco reactivo a la fuerza , Quitina de silítido con púas (4), Barra de torio de infusión obsidiana (8), Pólvora densa de obsidiana (5)\n[q4]Disco reactivo a la fuerza mejorado\n(2)\nSe liga al equiparlo\nMano izquierda Escudo\n2822 armadura\n52 bloqueo\n+20 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 7 p. el índice de defensa.\n[q2]Equipar: Al ser bloqueado por el escudo libera una carga eléctrica que inflige daño a los enemigos cercanos. (1s de reutilización)\n[q2]Uso: Carga la energía que contiene el escudo durante 3 s para infligir 450 to 750 p. de daño de Naturaleza a todos los enemigos cercanos. Después de usarlo, el escudo necesita 10 s para recargarse. (2 Min Reutilización)"},
[1213589] = {name = "Esquema: disco reactivo a la fuerza mejorado", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un disco reactivo a la fuerza mejorado."},
[1213593] = {name = "[q4]Piedra de velocidad", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nQuitina de silítido monstruosa (10), Bilis de gusano de arena antiguo (10), Cristal nexo (6), Piedra de pulir de obsidiana (6), Cardopresto (20)\n[q4]Piedra de velocidad\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 2% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta un 2% tu velocidad de ataque."},
[1213594] = {name = "Fórmula: piedra de velocidad", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear una piedra de velocidad."},
[1213595] = {name = "[q4]Lágrima de la Soñadora", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nQuitina de silítido monstruosa (10), Bilis de gusano de arena antiguo (10), Cristal nexo (4), Barra de torio de infusión obsidiana (10), Cardo de colmena (10)\n[q4]Lágrima de la Soñadora\nSe liga al equiparlo\nÚnico-Equipado: [Crystallized Tear] (1)Abalorio\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 46 p. el daño y la sanación de los hechizos y efectos mágicos."},
[1213596] = {name = "Fórmula: lágrima de la Soñadora", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear una lágrima de la Soñadora."},
[1213598] = {name = "[q4]Magnetita de represalia", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nQuitina de silítido con púas (10), Bilis de gusano de arena antiguo (5), Cristal nexo (4), Barra de torio de infusión obsidiana (10), Veneno de acechador qiraji (10)\n[q4]Magnetita de represalia\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\n+23 aguante\nNecesitas ser de nivel 60\n[q2]Equipar: Reduce un 1% la probabilidad de que esquiven o paren tus ataques.\n[q2]Equipar: Aumenta 11 p. el índice de defensa.\n[q2]Equipar: Cuando recibe un golpe en combate, le inflige 80 p. de daño de Naturaleza al atacante. Genera el doble de amenaza que la cantidad de daño infligido."},
[1213599] = {name = "Fórmula: magnetita de represalia", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear una magnetita de represalia."},
[1213600] = {name = "[q4]Cronómetro encantado", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nBarra de torio de infusión obsidiana (3), Pólvora densa de obsidiana (6), Fragmento luminoso grande (4), Poción de presteza (3)\n[q4]Cronómetro encantado\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 40% la velocidad de carrera durante 10 s. (2 Min Reutilización)"},
[1213601] = {name = "Fórmula: cronómetro encantado", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear un cronómetro encantado."},
[1213603] = {name = "[q4]Broche con rubí incrustado", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nQuitina de silítido con púas (10), Bilis de gusano de arena antiguo (5), Cristal nexo (6), Barra de torio de infusión obsidiana (10), Cardo de colmena (10), Veneno de acechador qiraji (10)\n[q4]Broche con rubí incrustado\nSe liga al equiparlo\nÚnico-Equipado: [Jeweled Healing Focus] (1)Abalorio\n+18 intelecto\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 68 p. la sanación realizada y hasta 23 p. el daño que infligen todos los efectos y hechizos mágicos."},
[1213604] = {name = "Fórmula: broche con rubí incrustado", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear un broche con rubí incrustado."},
[1213607] = {name = "[q3]Pergamino: cólera del enjambre", additional_info = "Hechizo de 3 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nEsencia eterna superior , Paño rúnico\n[q3]Pergamino: cólera del enjambre\nSe liga al recogerlo\nNecesitas ser de nivel 60\nRequiereEncantamiento\n(300)\n[q2]Uso: Lee el pergamino para invocar la cólera del enjambre y potenciar a tu banda, lo que aumenta hasta 40 p. el daño y la sanación realizados con hechizos, y aumenta el poder de ataque 40 p. durante 1 h. (1 Min Reutilización)"},
[1213608] = {name = "Fórmula: pergamino: cólera del enjambre", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a conjurar un pergamino: cólera del enjambre."},
[1213610] = {name = "Repelente encantado", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nVeneno de acechador qiraji (3), Cardo de colmena (3), Polvo de ilusión (2)\n[q]Crea repelente encantado.\nNecesitas ser de nivel 60\n[q2]Uso: Cuando se aplica al arma o al escudo objetivo, aumenta hasta 45 p. el daño con hechizos y aumenta un 1% la probabilidad de golpe crítico con hechizos. Dura 30 minutos.\n5 cargas"},
[1213611] = {name = "Fórmula: repelente encantado", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a crear repelente encantado."},
