[1213619] = {name = "Aumentar daño Sagrado 20", additional_info = "[q]Aumenta hasta 20 p. el daño que infligen los efectos y hechizos Sagrados."},
[1213622] = {name = "Encantar guantes: Poder Sagrado", additional_info = "Hechizo de 5 seg\nRequiere [Gloves]Herramientas: Vara rúnica de arcanita\nComponentes:\nCristal nexo (2), Fragmento luminoso grande (5), Agua bendita de Stratholme (5), Costuras desgarradas de abominación (2)\n[q]Encanta unos guantes de forma permanente para que aumenten hasta 20 p. el daño Sagrado."},
[1213623] = {name = "Fórmula: encantar guantes: Poder Sagrado", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a encantar de forma permanente unos guantes para que aumenten 20 p. el daño Sagrado infligido por hechizos y habilidades."},
