[1213886] = {name = "Frasco de pena implacable", additional_info = "Instante\n[q]Aumenta hasta 80 p. la sanación realizada por hechizos y efectos mágicos, hasta 27 p. el daño que infligen los hechizos y efectos mágicos y 12 p. la regeneración de maná cada 5 s durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte."},
[1213892] = {name = "Frasco de conocimiento antiguo", additional_info = "Instante\n[q]Aumenta hasta 180 p. el daño que infligen los hechizos y efectos mágicos durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte."},
[1213894] = {name = "S03 - Item - TAQ - Shaman - Restoration 4P Bonus", additional_info = "[q]Reduce el tiempo de lanzamiento de Sanación en cadena 0.5 s."},
[1213897] = {name = "Frasco de locura", additional_info = "Instante\n[q]Aumenta 50 p. el poder de ataque durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte."},
[1213900] = {name = "S03 - Item - TAQ - Shaman - Elemental 2P Bonus", additional_info = "[q]Tienes una probabilidad del 70% de evitar las interrupciones por daño mientras lanzas Descarga de relámpagos, Cadena de relámpagos o Ráfaga de lava, y aumenta un 10% la probabilidad de activar tu talento Enfoque elemental."},
[1213901] = {name = "Frasco de los dioses antiguos", additional_info = "Instante\n[q]Aumenta 100 p. el aguante y 10 p. el valor de defensa durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte."},
[1213902] = {name = "S03 - Item - TAQ - Shaman - Elemental 4P Bonus", additional_info = "[q]Aumenta un 60% la bonificación de daño por golpe crítico con tus hechizos de Fuego, Escarcha y Naturaleza."},
[1213904] = {name = "Elixir del tejón mielero", additional_info = "Instante\n[q]Aumenta 30 p. la agilidad, un 2% la probabilidad de asestar un golpe crítico y 15 p. la resistencia a la Naturaleza durante 1 h."},
[1213910] = {name = "S03 - Item - TAQ - Shaman - Enhancement 2P Bonus", additional_info = "[q]Aumenta el daño de Golpe de tormenta y Latigazo de lava un 50%. Este efecto aumenta un 100% si se utiliza un arma de dos manos."},
[1213914] = {name = "Elixir del señor de la magia", additional_info = "{Instante} {1 seg de reutilización}\n[q]Aumenta el daño con hechizos hasta un máximo de 40 p. y la resistencia a la Naturaleza 15 p. durante 1 h."},
[1213915] = {name = "Ardiendo", additional_info = nil},
[1213916] = {name = "Ardiendo", additional_info = nil},
[1213917] = {name = "Elixir de los Ladoférreo", additional_info = "Instante\n[q]Aumenta 450 p. la armadura, 5 p. la defensa y 15 p. la resistencia a la Naturaleza durante 1 h."},
[1213918] = {name = "S03 - Item - TAQ - Shaman - Enhancement 4P Bonus", additional_info = "[q]Tus golpes críticos de Golpe de tormenta, Latigazo de lava y Ráfaga de lava hacen que tu objetivo arda y reciba un 30% del daño infligido durante 4 s."},
[1213922] = {name = "Elixir de prontitud", additional_info = "Instante\n[q]Aumenta un 15% la velocidad de carrera del jugador durante 1 h."},
[1213924] = {name = "Megabomba arcana", additional_info = "Alcance de 15 m\nHechizo de 1.5 seg\n[q]Drena 1075 to 1525 p. de maná de todos los que estén en el radio de la explosión y convierte un 50% del maná drenado en daño que se inflige al objetivo. Además, silencia a los objetivos en el radio de la explosión durante 5 s."},
[1213930] = {name = "S03 - Item - TAQ - Shaman - Tank 2P Bonus", additional_info = "[q]Dañar a un objetivo con Golpe de tormenta, Ráfaga de lava o Explosión de arrabio también reduce un 10% todo el daño que recibes durante 10 s."},
[1213934] = {name = "Refuerzo tormentoso", additional_info = nil},
[1213935] = {name = "El fumigador", additional_info = "Instante\n[q]Estalla cuando se activa, lo que inflige 650 to 950 p. de daño de Fuego a todos los enemigos cercanos y te inflige 475 to 725 p. de daño. Inflige más daño a las criaturas silítidas en Silithus."},
[1213937] = {name = "S03 - Item - TAQ - Shaman - Tank 4P Bonus", additional_info = "[q]Cuando lanzas Espíritu del alfa sobre ti mismo, también aumenta tu salud un 5%, tu amenaza generada un 25%, y todo el daño que inflijas un 5%."},
