[1214125] = {name = "Filo de obsidiana", additional_info = "Alcance de 20 m\n[q]Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus.\n(2.1s de reutilización)"},
[1214136] = {name = "Relámpagos divergentes", additional_info = "Instante\n[q]Después de 8 s, inflige una gran cantidad de daño que se reparte entre todos los afectados."},
[1214137] = {name = "[q4]Buscacorazones de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nBarra de arcanita (30), Barra de torio de infusión obsidiana (8), Piedra de pulir de obsidiana (6), Ídolo de obsidiana (3), Ídolo de ónice (3), Ídolo de Muerte (2)\n[q4]Buscacorazones de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)Una mano Daga\n67 - 125 p. de daño Velocidad 1.70\n(56.47 p. de daño por segundo)\n+11 fuerza\n+10 aguante\nDurabilidad 65 / 65\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando dañas a tu objetivo con hechizos directos o ataques cuerpo a cuerpo. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1214138] = {name = "Diseño: buscacorazones de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un buscacorazones de obsidiana."},
[1214139] = {name = "Esquema: escopeta de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una escopeta de obsidiana."},
[1214143] = {name = "Filo de obsidiana", additional_info = "Alcance de 20 m\n[q]Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando golpeas a tu objetivo con un ataque a distancia. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus.\n(2.1s de reutilización)"},
[1214145] = {name = "[q4]Escopeta de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de arcanita (30), Barra de torio de infusión obsidiana (8), Cristal nexo (3), Ídolo luminiscente (3), Ídolo de jaspe (3), Ídolo de la Disputa (2)\n[q4]Escopeta de obsidiana\nSe liga al equiparlo\nÚnico-Equipado: [Obsidian Weapon] (1)A distancia Arma de fuego\n101 - 189 p. de daño Velocidad 3.30\n(43.94 p. de daño por segundo)\n+9 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 31 p. el poder de ataque a distancia.\n[q2]Equipar: Otorga la probabilidad de infligir 325 to 500 p. de daño de Fuego cuando golpeas a tu objetivo con un ataque a distancia. La mayoría de los golpes infligen más daño a las criaturas silítidas de Silithus. (2.1s de reutilización)"},
[1214151] = {name = "S03 - Item - RAQ - Warlock - Tank 3P Bonus", additional_info = "[q]Durante 6 s después de usar Cuchilla de las Sombras, tu Dolor abrasador golpea a 1 objetivo más que esté en un radio cuerpo a cuerpo."},
