[1214257] = {name = "[q4]Garra negra del Destructor", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Cuero encantado (8), Frasco de poder supremo\n[q4]Garra negra del Destructor\nSe liga al equiparlo\nManos Malla\n298 armadura\n+15 aguante\nDurabilidad 50 / 50\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 50 p. el poder de ataque.\n[q2]Equipar: En ataques cuerpo a cuerpo o a distancia que alcancen al objetivo, obtienes 30 p. de maná y, si es posible, absorbes 30 p. de maná del objetivo."},
[1214258] = {name = "Activador de drenaje de maná", additional_info = "[q]En ataques cuerpo a cuerpo o a distancia que alcancen al objetivo, obtienes 30 p. de maná y, si es posible, absorbes 30 p. de maná del objetivo."},
[1214259] = {name = "Drenaje de maná", additional_info = nil},
[1214261] = {name = "Drenaje de maná", additional_info = nil},
[1214263] = {name = "Púas quitinosas", additional_info = "Instante\n[q]Hace que te salgan pinchos que infligen 150 p. de daño de Naturaleza al golpear a tus atacantes. Dura 30 s."},
[1214270] = {name = "[q4]Escudo dentado de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Barra de torio encantado (8), Esencia de tierra (4)\n[q4]Escudo dentado de obsidiana\nSe liga al equiparlo\nMano izquierda Escudo\n2822 armadura\n52 bloqueo\n+12 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 14 p.\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 20% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 20%, 20s de reutilización)"},
[1214271] = {name = "Diseño: escudo dentado de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer un escudo dentado de obsidiana."},
[1214272] = {name = "Activador de Silencio", additional_info = "[q]Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 20% de probabilidad de ser silenciado durante 3 s.\n(Probabilidad de que accione: 20%, 20s de reutilización)"},
[1214273] = {name = "Silencio", additional_info = "Alcance de 50 m\nInstante\n[q]Silencia al enemigo y le impide lanzar hechizos durante 3 s."},
[1214274] = {name = "[q4]Guerrera de malla de obsidiana", additional_info = "Hechizo de 1 min\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (15), Fragmento de obsidiana pequeño (36), Cuero encantado (12), Piedra guardián (10), Diamante de Azeroth (4)\n[q4]Guerrera de malla de obsidiana\nSe liga al equiparlo\nPecho Malla\n476 armadura\n+24 aguante\nDurabilidad 140 / 140\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 76 p. el poder de ataque.\n[q2]Equipar: Se reduce 40 p. el daño con hechizos recibido."},
[1214275] = {name = "Diseño: guerrera de malla de obsidiana", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Te enseña a hacer una guerrera de malla de obsidiana."},
[1214276] = {name = "Reducción de daño con hechizos", additional_info = "[q]Se reduce 40 p. el daño con hechizos recibido."},
[1214278] = {name = "Golpe de tierra", additional_info = "Instante\n[q]Aumenta 328 p. tu poder de ataque cuerpo a cuerpo y a distancia. El efecto dura 20 s."},
[1214279] = {name = "Detonación de hechizo", additional_info = nil},
[1214280] = {name = "Detonación de hechizo", additional_info = "[q]Te otorga una probabilidad de que, cuando tus hechizos dañinos impacten, el daño de tus hechizos y efectos aumente hasta 193 p. durante 10 s.\n(Probabilidad de que accione: 5%)"},
[1214281] = {name = "Forma de naga", additional_info = "Instante\n[q]Te transformas en un naga durante 5 min."},
[1214283] = {name = "Tigre espectral presto", additional_info = "Hechizo de 3 seg\n[q]Invoca y retira a un tigre espectral presto. Es una montura muy veloz."},
[1214284] = {name = "Forma dracónida", additional_info = "Instante\n[q]Te transforma en un dracónido durante 5 min."},
[1214285] = {name = "Triturar mejorado/Mordedura feroz", additional_info = "Triturar mejorado/Mordedura feroz\n[q]Aumenta el daño de Mordedura feroz y Triturar un 3%."},
[1214286] = {name = "Flagelo mejorado/Destrozar", additional_info = "Flagelo mejorado/Destrozar\n[q]Aumenta un 3% el daño de Flagelo y Destrozar."},
[1214289] = {name = "Ídolo de Salud", additional_info = "[q]Tus hechizos Curar envenenamiento, Suprimir veneno y Eliminar maldición también restablecen 200 p. de salud al objetivo cuando se lanzan."},
[1214290] = {name = "Ídolo de Salud", additional_info = "{95 p. de maná} {Rango ilimitado}\nInstante\n[q]Restablece 200 p. de salud a tu objetivo."},
