[1218071] = {name = "Arrullo de cantaflor", additional_info = "Alcance de 30 m\nInstante\n[q]Invoca una melodía que aumenta un 5% la probabilidad de golpe crítico cuerpo a cuerpo, a distancia o con hechizos, y 15 p. los atributos de todos los miembros de tu grupo o banda durante 1 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios."},
[1218072] = {name = "Bendición de Neptulon", additional_info = "Alcance de 100 m\nInstante\n[q]Aumenta 200 p. el poder de ataque, un 15% el aguante y un 3% la probabilidad de golpe crítico con hechizos de todos los miembros de tu grupo o banda durante 2 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios."},
[1218073] = {name = "Daño de fortuna de las Sombras", additional_info = "Rango ilimitado\nInstante\n[q]Aumenta un 10% el daño infligido de todos los miembros de tu grupo o banda durante 2 h."},
[1218074] = {name = "Poderío de Roca Negra", additional_info = "Rango ilimitado\nInstante\n[q]Aumenta 300 p. los puntos de salud. 15% de celeridad a los ataques cuerpo a cuerpo. 10 p. de regeneración de maná cada 5 s. Dura 1 h."},
[1218075] = {name = "Sueños de Zandalar", additional_info = "Rango ilimitado\nInstante\n[q]Aumenta un 10% la velocidad de movimiento y un 15% las estadísticas de todos los miembros de tu grupo o banda durante 2 h."},
