[1218092] = {name = "Quietud", additional_info = nil},
[1218121] = {name = "Cuerno del Alba", additional_info = "Rango ilimitado\nInstante\n[q]Reúne a los miembros de tu grupo o banda cercanos, aumenta un 10% su probabilidad de golpe crítico con hechizos, un 5% su probabilidad de golpe crítico con ataques cuerpo a cuerpo o a distancia, y 140 p. su poder de ataque. Dura 2 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios."},
[1218134] = {name = "Disparo tranquilizante", additional_info = "{270 p. de maná} {Alcance de 35 m}\n20 seg de reutilización\nRequiere Arma a distancia\n[q]Intenta eliminar 1 efecto de Frenesí de una criatura enemiga."},
[1218154] = {name = "Golpes de lo siniestro", additional_info = "Instante\n[q]Modifies Jump Targets +2:\nGolpe siniestro , Golpe siniestro , Golpe siniestro , Golpe siniestro , Golpe siniestro , Golpe siniestro , Golpe siniestro , Golpe siniestro"},
