[1218232] = {name = "Autoridad de los Páramos Congelados", additional_info = nil},
[1218240] = {name = "Disparo mortal", additional_info = "Alcance de 10 - 200 m\n[q]Tratas de rematar a un objetivo herido con un disparo a larga distancia que inflige un 587% de daño con arma y luego [587 / 100 * 587 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos."},
[1218271] = {name = "Autoridad de los Páramos Congelados", additional_info = "Instante\n[q]Las fuerzas de la Plaga se vuelven más fuertes."},
[1218275] = {name = "Autoridad de los Páramos Congelados", additional_info = "Instante\n[q]Las fuerzas de la Plaga se vuelven más fuertes."},
[1218276] = {name = "Autoridad de los Páramos Congelados", additional_info = "Instante\n[q]Las fuerzas de la Plaga se vuelven más fuertes."},
[1218283] = {name = "Autoridad de los Páramos Congelados", additional_info = "Instante\n[q]El mismísimo Rey Exánime ha tomado nota. Aquí no queda ningún atisbo de esperanza."},
[1218285] = {name = "Bloqueando y cargando", additional_info = nil},
