[1218352] = {name = "Helar", additional_info = "[q]Otorga a tus hechizos de daño de Escarcha un 100% de probabilidad de aplicar el efecto de Escalofrío invernal, que aumenta un 2% la probabilidad de que un hechizo de Escarcha inflija un golpe crítico al objetivo durante 15 s. Se acumula hasta 5 veces."},
[1218358] = {name = "Frenesí rabioso", additional_info = "Alcance de 30 m\nInstante\n[q]Provoca un Frenesí rabioso al objetivo, lo que aumenta 91 p. su poder de ataque cuerpo a cuerpo pero reduce 640 p. su armadura durante 2 min. Los enemigos rabiosos no huirán e ignorarán los efectos de Miedo y Horror."},
[1218360] = {name = "Machaque", additional_info = nil},
