[1218423] = {name = "S03 - Item - Naxxramas - Druid - Restoration 2P Bonus", additional_info = "[q]Ahora, cada vez que el objetivo de tu Flor de vida recibe daño, hay un 100% de probabilidad de que Flor de vida le restaure la misma cantidad de salud que restablece cuando se disipa su efecto."},
[1218427] = {name = "S03 - Item - Naxxramas - Druid - Restoration 4P Bonus", additional_info = "[q]Cada vez que tu Rejuvenecimiento de rango 10 u 11 sana a un objetivo, tienes una probabilidad del 25% de restaurar 60 p. de maná, 8 p. de energía o 2 p. de ira a tu objetivo."},
[1218429] = {name = "S03 - Item - Naxxramas - Druid - Restoration 6P Bonus", additional_info = "[q]Tus Rejuvenecimiento y Recrecimiento restablecen su duración por completo cada vez que su objetivo recibe daño de un enemigo no-muerto."},
[1218443] = {name = "S03 - Item - Naxxramas - Druid - Balance 2P Bonus", additional_info = "[q]Tus Fuego lunar y Fuego solar infligen un 20% más de daño."},
