[1218445] = {name = "S03 - Item - Naxxramas - Druid - Balance 6P Bonus", additional_info = "[q]Cuando tu Oleada de estrellas golpea a un objetivo no-muerto, la duración restante del efecto activo de tu Lluvia de estrellas se restablece en 10 s."},
[1218476] = {name = "S03 - Item - Naxxramas - Druid - Feral 2P Bonus", additional_info = "[q]Tu Arañazo ahora inflige su daño periódico contra objetivos que no están controlados por el jugador cada 1 s, y aumenta el total de daño con el tiempo un 200%."},
