[1218478] = {name = "S03 - Item - Naxxramas - Druid - Feral 6P Bonus", additional_info = "[q]Cada vez que infliges daño de sangrado a un objetivo no-muerto, aumentan un 1% el daño y el daño crítico que infliges contra los no-muertos durante 30 s. Se acumula hasta 12 veces."},
[1218479] = {name = "Matanza de no-muertos", additional_info = nil},
