[1218485] = {name = "Jarabe de las arenas", additional_info = "Instante\n[q]Aumenta todo el daño infligido contra objetivos en Silithus, Ahn'Qiraj, las Tierras de la Peste del Este y Naxxramas un 2%, y aumenta el daño crítico infligido contra objetivos en estas áreas un 2% más."},
[1218499] = {name = "Conducto ardiente", additional_info = nil},
