[1218582] = {name = "S03 - Item - Naxxramas - Hunter - Melee 2P Bonus", additional_info = "[q]Tu Golpe de dracoleón y Mordedura de mangosta infligen un 30% más de daño inicial."},
[1218583] = {name = "S03 - Item - Naxxramas - Hunter - Melee 4P Bonus", additional_info = "[q]Reduce 2 s el tiempo de reutilización de tu habilidad Golpe de dracoleón, 1 s el tiempo de reutilización de tu habilidad Golpe de raptor y 8 s el tiempo de reutilización de tu habilidad Golpe lateral."},
[1218587] = {name = "Matanza de no-muertos", additional_info = nil},
