[1218592] = {name = "S03 - Item - Naxxramas - Mage - Arcane 2P Bonus", additional_info = "[q]Los aliados que tienen tu Faro temporal restauran [Spell power * 67 / 1000 + (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 8 / 100] p. de salud cada 1 s."},
