[1219580] = {name = "Encantar arma 2M: hechicería desbocada", additional_info = "Hechizo de 5 seg\nHerramientas: Vara rúnica de arcanita\nComponentes:\nCristal nexo (3), Polvo de ilusión (24), Sangre de héroes , Loto cárdeno (6)\n[q]Encanta un arma de dos manos de forma permanente para que otorgue 65 p. de poder con hechizos."},
[1219581] = {name = "Encantar escudo: aguante superior", additional_info = "Hechizo de 5 seg\nRequiere Armadura\nHerramientas: Vara rúnica de arcanita\nComponentes:\nFragmento luminoso grande (6), Polvo de ilusión (18), Esencia de tierra (2)\n[q]Encanta un escudo de forma permanente para que otorgue 12 p. de aguante."},
[1219586] = {name = "Encantar guantes: fuerza excelente", additional_info = "Hechizo de 5 seg\nRequiere Armadura\nHerramientas: Vara rúnica de arcanita\nComponentes:\nEsencia eterna superior (7), Polvo de ilusión (21), Esencia de Fuego (2)\n[q]Encanta unos guantes de forma permanente para que otorguen 15 p. de fuerza."},
[1219587] = {name = "Encantar capa: agilidad", additional_info = "Hechizo de 5 seg\nRequiere Armadura\nHerramientas: Vara rúnica de arcanita\nComponentes:\nEsencia eterna superior (3), Polvo de ilusión (9), Esencia de Fuego\n[q]Encanta una capa de forma permanente para que otorgue 5 p. de agilidad."},
[1219682] = {name = "Resbalar", additional_info = nil},
[1219706] = {name = "Rejuvenecimiento", additional_info = "Rango ilimitado\nInstante\n[q]Restaura 8 p. de energía."},
[1219707] = {name = "Rejuvenecimiento", additional_info = "Rango ilimitado\nInstante\n[q]Restaura 20 p. de ira."},
[1219708] = {name = "Rejuvenecimiento", additional_info = "Rango ilimitado\nInstante\n[q]Restaura 60 p. de maná."},
[1219728] = {name = "Estrellamiento glacial", additional_info = nil},
[1219729] = {name = "Estrellamiento glacial", additional_info = "Instante\n[q]Cuando esta aura expira, recibe un gran daño de Escarcha que se divide entre todos los aliados cercanos."},
[1219732] = {name = "Estrellamiento glacial", additional_info = "Instante\n[q]Cuando esta aura expira, recibe un gran daño de Escarcha que se divide entre todos los aliados cercanos."},
[1219733] = {name = "Estrellamiento glacial", additional_info = nil},
[1219740] = {name = "Alma del táctico", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del táctico:\n\nDespués de cargar actitudes, el costo de ira de tu próxima habilidad ofensiva se reduce 10 p."},
[1219741] = {name = "Espíritus atrapantes", additional_info = "Rango ilimitado\nInstante\n[q]Inflige 462 to 538 p. de daño de las Sombras cada 1 s. Reduce un 35% la velocidad de movimiento."},
[1219742] = {name = "Alma del veterano de guerra", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del veterano de guerra:\n\nDurante 15 s después de cambiar de actitud, puedes usar habilidades que requieren la actitud anterior como si aún la tuvieras."},
[1219743] = {name = "Alma del augur de batalla", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el augur de batalla:\n\nDurante los primeros 15 s después de activar una actitud, puedes obtener un beneficio adicional:\n\n Actitud de batalla/Actitud de gladiador: aumenta un 5% el daño infligido.\n\n Actitud rabiosa: aumenta un 5% la probabilidad de golpe crítico.\n\n Actitud defensiva: reduce un 5% el daño físico recibido."},
[1219744] = {name = "Espíritus atrapantes", additional_info = nil},
[1219745] = {name = "Alma del buscasangre", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del buscasangre:\n\nLos golpes críticos de Abrumar restablecen la duración máxima de Desgarrar en tu objetivo."},
[1219747] = {name = "Alma del titán", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del titán:\n\nTus habilidades Golpe heroico, Embate y Abrumar infligen un 10 + (5 * ComboPoints)% más de daño."},
[1219748] = {name = "Alma del destructor", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del destructor:\n\nTus golpes de Embate restablecen el tiempo de reutilización de tus habilidades Golpe mortal, Sed de sangre y Embate con escudo."},
[1219749] = {name = "Alma del lazomortal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del lazomortal:\n\nReduce un 50% el tiempo de reutilización de tu Deseo de muerte."},
[1219751] = {name = "Alma del sanguinista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sanguinista:\n\nInfliges un 15% más de daño mientras un enemigo cercano esté afectado por tu Desgarrar y tus Heridas profundas."},
[1219752] = {name = "Alma del bloqueador prístino", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del bloqueador prístino:\n\nAumenta 30 p. el valor de bloqueo de tu escudo."},
[1219753] = {name = "Alma del salvaje", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del salvaje:\n\nObtienes 1 p. más de ira cada vez que recibes o infliges daño con ataques automáticos."},
[1219754] = {name = "Alma de animosidad", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de animosidad:\n\nAumenta toda la amenaza que generas en actitud defensiva un 10% más y aumenta todo el daño que infliges en actitud de gladiador un 4%."},
[1219755] = {name = "Alma del deflector", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del deflector:\n\nObtienes 10 p. de ira cada vez que paras un ataque o que alguien para uno de los tuyos."},
[1219756] = {name = "Alma de revancha", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de revancha:\n\nRevancha también te otorga Aluvión, lo que aumenta tu velocidad de ataque un 30% durante los siguientes 3 golpes."},
[1219757] = {name = "Alma del incesante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del incesante:\n\nCuando tu objetivo para un ataque, tomas Represalia de forma inmediata e infliges un 200% de daño con arma al objetivo. Represalia no se puede esquivar, bloquear ni parar, pero solo puede ocurrir una vez cada 30 s por objetivo."},
[1219758] = {name = "Alma del portatruenos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del portatruenos:\n\nReduce un 100% el tiempo de reutilización de Atronar."},
[1219760] = {name = "Alma del centinela", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del centinela:\n\nTu Embate con escudo genera un 100% más de amenaza y su tiempo de reutilización se restablece si se esquiva, para o bloquea."},
[1219762] = {name = "Alma del zurdo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del zurdo:\n\nReduce 2 s el tiempo de reutilización de tu habilidad Embate con escudo."},
[1219763] = {name = "Alma del gladiador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del gladiador:\n\nReduce 30 s el tiempo de reutilización de tu habilidad Ira sangrienta mientras estás en Actitud de gladiador."},
[1219764] = {name = "Alma de la réplica", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la réplica:\n\nReduce un 25% el tiempo de reutilización de Ola de choque."},
[1219766] = {name = "Alma del evasivo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del evasivo:\n\nAmago también otorga Eludir durante 6 s, lo que reduce un 50% todo el daño recibido de ataques con área de efecto de enemigos que no sean jugadores."},
[1219767] = {name = "Alma del toxicólogo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del toxicólogo:\n\nAumenta un 100% la bonificación de daño por golpe crítico con tus venenos."},
[1219768] = {name = "Alma del verdugo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del verdugo:\n\nTus remates tienen una probabilidad del 5% por punto de combo de hacer que tu próxima habilidad no cueste energía."},
[1219769] = {name = "Alma del oportunista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del oportunista:\n\nTus ataques iniciales tienen un 100% de probabilidad de hacer que tu siguiente habilidad no cueste energía."},
[1219770] = {name = "Alma del carnicero", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del carnicero:\n\nAumenta un 20% el daño que inflige el arma de tu mano derecha con habilidades que generan puntos de combo."},
[1219771] = {name = "Alma del fantasma", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del fantasma:\n\nReduce el tiempo de reutilización de Esfumar a 1 min. No se puede combinar con Elusión."},
[1219772] = {name = "Alma del ladronzuelo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del ladronzuelo:\n\nAumenta un 20% el daño de Mutilar y Sablazo."},
[1219773] = {name = "Alma del amante de la adrenalina", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del amante de la adrenalina:\n\nReduce el tiempo de reutilización de Subidón de adrenalina 4 min."},
[1219774] = {name = "Alma del experto en puyazos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del experto en puyazos:\n\nAumenta un 5% tu probabilidad de conseguir un golpe crítico con dagas."},
[1219775] = {name = "Alma del acechador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del acechador:\n\nAumenta un 30% la probabilidad de golpe crítico de tu habilidad Emboscada."},
[1219776] = {name = "Alma del eficiente", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del eficiente:\n\nTus remates cuestan un 50% menos de energía."},
[1219777] = {name = "Alma del malabarista de cuchillos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del malabarista de cuchillos:\n\nMientras Heridas superficiales y Danza de hojas están activos, Tempestad carmesí, Trabuco y Abanico de cuchillos cuesta 20 p. menos de energía y genera un 100% más de amenaza."},
[1219778] = {name = "Alma del maestro de las sombras", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del maestro de las sombras:\n\nEsfumarse ahora reduce todo el daño mágico que recibes un 50% durante su efecto, pero ya no otorga sigilo ni elimina los efectos de reducción de movimiento."},
[1219779] = {name = "Alma del equilibrista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del equilibrista:\n\nTus remates tienen una probabilidad del 20% por punto de combo de que recibas un 20% menos de daño físico del próximo ataque cuerpo a cuerpo que recibas dentro de 10 s."},
[1219780] = {name = "Alma del camorrista fogueado", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del camorrista fogueado:\n\nTu Bravura ante los golpes ahora también se activa cada vez que obtienes un punto de combo."},
[1219781] = {name = "Alma del cinturón negro", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del cinturón negro:\n\nTu Bravura ante los golpes también aumenta un 20% la armadura que te otorgan los objetos por cada acumulación (hasta un máximo de 100%)."},
[1219782] = {name = "Alma del esgrimista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del esgrimista:\n\nEl tiempo de reutilización de tu Daga de guardamano se restablece cada vez que tu objetivo esquiva o para un ataque."},
[1219783] = {name = "Alma del espadachín", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del espadachín:\n\nTu Daga de guardamano ahora golpea a 1 objetivo cercano más y también hace que tu Golpe siniestro golpee a 1 objetivo cercano más durante 10 s. Estos golpes adicionales no se duplican con Aluvión de acero."},
[1219784] = {name = "Alma del sanguinario", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sanguinario:\n\nMientras el efecto está activo, tu Daga de guardamano hace que te sanes por un 15% de todo el daño que inflige Golpe siniestro. La sanación excedente se convierte en una Barrera de sangre que absorbe daño equivalente a un máximo del 20% de tu salud máxima."},
[1219785] = {name = "Alma del transfusionista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del transfusionista:\n\nTransfusión de vida genera un 50% más de maná y un 100% menos de amenaza."},
[1219786] = {name = "Alma del refinamiento", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del refinamiento:\n\nAumenta un 2% tu probabilidad de conseguir un golpe crítico con hechizos y ataques."},
[1219787] = {name = "Alma del exterminador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del exterminador:\n\nTu talento Ocaso tiene un 4% más de probabilidad de activarse. Tu Incinerar tiene un 4% de probabilidad de activar tu Exterminación sin importar la salud del objetivo."},
[1219788] = {name = "Alma del putrefaccionista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del putrefaccionista:\n\nAumenta el daño de tus hechizos periódicos y de tu mascota Guardia vil un 10 + (5 * ComboPoints)%."},
[1219789] = {name = "Alma del malévolo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del malévolo:\n\nEl daño periódico de tus hechizos Llama de las Sombras, Aflicción inestable y Maldición de agonía, y el daño infligido por tu Guardia vil tienen una probabilidad del 4% de otorgar el efecto Trance de las Sombras."},
[1219790] = {name = "Alma del sombramante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sombramante:\n\nDescarga de las Sombras inflige un 10 + (5 * ComboPoints)% más de daño por cada uno de tus efectos sobre el objetivo, hasta un máximo de 30 + (5 * ComboPoints)%."},
[1219791] = {name = "Alma del heraldo del caos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del heraldo del caos:\n\nReduce un 50% el tiempo de reutilización de tu Descarga de caos y aumenta un 10% el daño infligido con Descarga de caos y Descarga de las sombras. Además, Descarga de caos ahora puede activar tu talento Descarga de las sombras mejorada y hace que tenga 26 cargas más (no se acumulan con las cargas adicionales de Llama de las Sombras)."},
[1219792] = {name = "Alma del incendiario", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del incendiario:\n\nCada vez que golpeas a un objetivo con Conflagrar, obtienes un 5% más de daño de Fuego durante 20 s. Se acumula hasta 2 veces."},
[1219793] = {name = "Alma del pastor infernal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del pastor infernal:\n\nAumenta un 20% el poder de ataque y el daño con hechizos que tu mascota demoníaca obtiene de tus atributos."},
[1219794] = {name = "Alma del señor demoníaco", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del señor demoníaco:\n\nAumenta un 50% los beneficios de tu talento Maestro demonólogo."},
[1219795] = {name = "Alma del exorcista demoníaco", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del exorcista demoníaco:\n\nDesterrar ahora se lanza al instante y se puede lanzar sobre ti mismo mientras seas un demonio. No puedes Desterrarte a ti mismo mientras tienes Abstinencia, y si lo haces recibirás Abstinencia durante 1 min."},
[1219796] = {name = "Alma del adolorido", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del adolorido:\n\nCada vez que recibes daño, tú y tu mascota obtienen una cantidad de maná equivalente al daño recibido, hasta un máximo de 420 p. de maná por evento. Solo puede ocurrir una vez cada pocos segundos."},
[1219797] = {name = "Alma del ánima flamígera", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del ánima flamígera:\n\nTus golpes de Cuchilla de las Sombras tienen un 20% de probabilidad de otorgarte un fragmento de alma, restablecer el tiempo de reutilización de Fuego de alma y hacer que tu siguiente Fuego de alma en los próximos 10 s sea instantáneo."},
[1219798] = {name = "Alma del devoracarnes", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del devoracarnes:\n\nMientras marcas como objetivo a un enemigo que esté en un radio de 30 m, Transfusión de vida te otorga maná a costa de la salud de tu objetivo, pero le inflige un 50 + (5 * ComboPoints)% menos de daño. No afecta el maná obtenido."},
[1219799] = {name = "Alma del abisal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del abisal:\n\nMientras Metamorfosis está activa, tus habilidades ofensivas e invocaciones demoníacas no cuestan fragmentos de alma. Además, sanas un 15% de tu salud máxima cuando dañas a un objetivo con Quemadura de las Sombras."},
[1219800] = {name = "Alma del natovacío", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del natovacío:\n\nToda la sanación adicional que te infliges se convierte en un escudo que absorbe daño. Este escudo puede absorber hasta un 30 + (5 * ComboPoints)% de tu salud máxima y acumula múltiples sanaciones."},
[1219801] = {name = "Alma de la hoja umbría", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la hoja umbría:\n\nReduce 1.5 s el tiempo de reutilización de tu Cuchilla de las Sombras."},
[1219802] = {name = "Alma del ritualista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del ritualista:\n\nLos efectos de tu Sacrificio demoníaco ahora persisten mientras tengas una mascota demoníaca activa, siempre y cuando no reinvoques a la mascota sacrificada. Solo puedes contar con un efecto de Sacrificio demoníaco activo a la vez."},
[1219803] = {name = "Alma del propagador de dolor", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del propagador de dolor:\n\nDurante 6 s después de usar Cuchilla de las Sombras, tu Dolor abrasador golpea a 1 objetivo más que esté en un radio cuerpo a cuerpo."},
[1219804] = {name = "Alma del líder del engaño", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del líder del engaño:\n\nGeneras un 100% más de amenaza durante 8 s después de usar Disparo de distracción."},
[1219805] = {name = "Alma del buscapresas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del buscapresas:\n\nMientras rastreas un tipo de criatura, infliges un 3% más de daño a ese tipo de criatura."},
[1219806] = {name = "Alma del tirador certero", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del tirador certero:\n\nLa siguiente habilidad de Disparo que utilices en los próximos 12 s después de utilizar Disparo de puntería inflige un 20% más de daño."},
[1219807] = {name = "Alma del asaltante agresivo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del asaltante agresivo:\n\nTu Disparo de puntería inflige un 20% más de daño a los objetivos bajo los efectos de una de tus trampas."},
[1219808] = {name = "Alma del alternador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del alternador:\n\nTus habilidades de daño de Disparo infligen un 10% más de daño si el último Disparo de daño usado fue distinto al anterior."},
[1219809] = {name = "Alma del toxinólogo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del toxinólogo:\n\nEl daño de tu Picadura de serpiente aumenta un 25% de tu poder de ataque durante su duración normal."},
[1219810] = {name = "Alma del cazarrecompensas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del cazarrecompensas:\n\nAumenta un 10% el daño de Disparo mortal contra objetivos que no están controlados por jugadores."},
[1219811] = {name = "Alma del as del gatillo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del as del gatillo:\n\nReduce el tiempo de reutilización de Disparo mortal un 50%. Mientras Fuego rápido está activo con la runa Matanza rápida grabada, Disparo mortal no tiene tiempo de reutilización y, cuando se usa contra un objetivo que no está controlado por un jugador, hace 3 Disparos mortales más con un 30% del daño y con un alcance mínimo."},
[1219812] = {name = "Alma del protector de bestias", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del protector de bestias:\n\nAumenta un 20% el poder de ataque que tu mascota bestia obtiene de tus atributos."},
[1219813] = {name = "Alma del maestro de canes", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del maestro de canes:\n\nAumenta un 20% la regeneración de enfoque de tu mascota bestia."},
[1219814] = {name = "Espíritus atrapantes", additional_info = nil},
[1219815] = {name = "Alma del domador alfa", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del domador alfa:\n\nAumenta un 100% la regeneración de enfoque de tus mascotas."},
[1219816] = {name = "Alma del montero", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del montero:\n\nTu Mordedura de mangosta también reduce un 1% la probabilidad de esquivar de su objetivo y aumenta un 1% tu probabilidad de golpear durante 30 s."},
[1219818] = {name = "Alma del retaliador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del retaliador:\n\nMordedura de mangosta también se activa durante 5 s cuando tu objetivo para o bloquea, o cuando tus ataques cuerpo a cuerpo fallan."},
[1219819] = {name = "Alma de ecos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de ecos:\n\nGolpe de raptor aumenta un 20% el daño que inflige tu próxima habilidad cuerpo a cuerpo diferente (excepto Cortar alas) en un período de 5 s."},
[1219820] = {name = "Alma del azotador letal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del azotador letal:\n\nAumenta un 20% el daño que inflige el arma de tu mano derecha con Golpe de raptor y Golpe de dracoleón."},
[1219821] = {name = "Alma del cinético", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del cinético:\n\nTu daño periódico tiene un 5% de probabilidad de restablecer el tiempo de reutilización de una de tus habilidades de Golpe. Siempre se selecciona el Golpe con el mayor tiempo de reutilización restante."},
[1219822] = {name = "Alma del estratega", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del estratega:\n\nAumenta el daño con el tiempo de Golpe de dracoleón un 50% y aumenta el enfoque máximo de tu mascota 50 p."},
[1219823] = {name = "Alma del golpeador mortal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del golpeador mortal:\n\nAumenta un 20% el daño de impacto de Mordedura de mangosta y todos los Golpes."},
[1219824] = {name = "Alma del sanador súbito", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sanador súbito:\n\n-0.1 s de tiempo de lanzamiento de Sanación relámpago y -0.2 s de tiempo de lanzamiento de Sanación superior."},
[1219825] = {name = "Alma del refinamiento", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del refinamiento:\n\nAumenta un 2% tu probabilidad de conseguir un golpe crítico con hechizos y ataques."},
[1219826] = {name = "Alma del oficiante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del oficiante:\n\nAumenta un 25% tu probabilidad de golpe crítico con Rezo de sanación y Círculo de sanación."},
[1219827] = {name = "Alma del fiel", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del fiel:\n\nPermite que un 15% de tu regeneración de maná continúe mientras lanzas hechizos."},
[1219828] = {name = "Alma de serendipia", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de serendipia:\n\nTu sanación periódica tiene un 2% de probabilidad de hacer que tu próximo hechizo con un tiempo de lanzamiento inferior a 10 segundos sea un hechizo de lanzamiento instantáneo."},
[1219829] = {name = "Alma del resonante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del resonante:\n\nCírculo de sanación y Penitencia también aplican un efecto de sanación con el tiempo a sus objetivos que sana un 25% del total durante 15 s."},
[1219830] = {name = "Alma del devoto", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del devoto:\n\nTu Rezo de alivio obtiene 2 cargas más."},
[1219831] = {name = "Alma del arzobispo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del arzobispo:\n\nTu Círculo de sanación ahora sana al miembro más herido del grupo objetivo por un 100% más."},
[1219832] = {name = "Alma del penitente", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del penitente:\n\nReduce 6 s el tiempo de reutilización de tu hechizo Penitencia."},
[1219833] = {name = "Alma del guardián del alma", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del guardián del alma:\n\nAumenta un 10% la absorción de daño de tu Palabra de poder: escudo."},
[1219834] = {name = "Alma del errante crepuscular", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del errante crepuscular:\n\nPuedes lanzar Sanación relámpago mientras estás en Forma de las Sombras."},
[1219835] = {name = "Alma del rompementes", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del rompementes:\n\nLos golpes críticos de Explosión mental reducen la duración de tu próximo Tortura mental un 50%, si bien aumentan su daño total un 25%."},
[1219836] = {name = "Alma del mortífero", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del mortífero:\n\nReduce 6 s el tiempo de reutilización de tu hechizo Palabra de las Sombras: muerte."},
[1219837] = {name = "Alma de la fuente espiritual", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la fuente espiritual:\n\nTu Palabra de las Sombras: dolor tiene un 2.0% de probabilidad por cada punto de talento en Transfusión de espíritu de activar tu talento Transfusión de espíritu cuando inflige daño, o un 20% de probabilidad por cada punto de talento cuando un objetivo muere con tu Palabra de las Sombras: dolor activa. Enfoque interno también tiene un 20% de probabilidad por cada punto de talento de activar Transfusión de espíritu."},
[1219838] = {name = "Alma del zelote", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del zelote:\n\nMientras Transfusión de espíritu está activo, infliges un 25% más de daño de las Sombras."},
[1219839] = {name = "Alma del profanador implacable", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del profanador implacable:\n\nYa no se reduce la duración de tu Tortura mental cuando recibes daño, y el lanzamiento activa una Púa mental gratis sobre el objetivo."},
[1219840] = {name = "Alma del desdeñoso", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del desdeñoso:\n\nEl efecto de tu Púa mental ahora es instantáneo, inflige un 10% más de daño y se puede lanzar mientras canalizas otro hechizo."},
[1219841] = {name = "Alma del pesteador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del pesteador:\n\nTu runa Dolor y sufrimiento ahora puede restablecer la duración de Peste devoradora."},
[1219842] = {name = "Alma del reverberante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del reverberante:\n\nTus Faros temporales duran un 20% más."},
[1219843] = {name = "Alma del cronosanador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del cronosanador:\n\nAumenta un 10% toda la sanación cronomántica que realizas."},
[1219844] = {name = "Alma del anhelo temporal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del anhelo temporal:\n\nCada vez que sanas a un objetivo con Regeneración, el tiempo de reutilización restante de Retroceder en el tiempo se reduce 1 s."},
[1219845] = {name = "Alma del precognoscente", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del precognoscente:\n\nTu Misiles arcanos restituye un 10% de su costo de maná básico cada vez que inflige daño."},
[1219846] = {name = "Alma del arcanista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del arcanista:\n\nExplosión Arcana obtiene un 10% más de probabilidad de activar Tromba de misiles, y Tromba de misiles ahora afecta a Regeneración de la misma forma que a Misiles arcanos."},
[1219847] = {name = "Alma del cuidador eterno", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del cuidador eterno:\n\nTus Faros temporales causados por Regeneración en masa ahora duran 21 s."},
[1219848] = {name = "Alma del conjurante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del conjurante:\n\nTu Explosión Arcana aumenta el daño realizado un 10% más por acumulación."},
[1219849] = {name = "Alma del resguardador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del resguardador:\n\nTu Escudo de maná, Resguardo contra el Fuego y Resguardo contra la Escarcha absorben un 50% más de daño y también colocan un Faro temporal sobre el objetivo durante 30 s."},
[1219850] = {name = "Alma del abrazo invernal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del abrazo invernal:\n\nAumenta un 15% más la probabilidad de activar tu runa Dedos de Escarcha."},
[1219851] = {name = "Alma del criomante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del criomante:\n\nAumenta un 75% el daño que infligen tus hechizos Descarga de Escarcha y Descarga de fríoarcano."},
[1219852] = {name = "Alma del evocador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del evocador:\n\nEres inmune a todo el daño mientras canalizas Evocación."},
[1219853] = {name = "Alma del elementalista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del elementalista:\n\nObtienes un 1% más de daño durante 15 s cada vez que lanzas un hechizo de una escuela de magia diferente."},
[1219854] = {name = "Alma del armero mágico", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del armero mágico:\n\nArmadura de mago aumenta tu regeneración de maná un 15% más mientras lanzas hechizos. Armadura de arrabio aumenta 18 p. tu daño con hechizos y tu sanación. Armadura de hielo aumenta un 20% la probabilidad de activar Dedos de Escarcha."},
[1219855] = {name = "Alma del reavivador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del reavivador:\n\nReduce un 20% la amenaza que generan tus hechizos de Fuego."},
[1219856] = {name = "Alma de la convergencia ardiente", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la convergencia ardiente:\n\nTu Piroexplosión inflige un 20% más de daño a los objetivos bajo los efectos del efecto periódico de tu Bola de fuego."},
[1219857] = {name = "Alma de la llamarada perpetua", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la llamarada perpetua:\n\nEl efecto periódico de tu Bola de fuego obtiene más daño para su duración, igual al 100% de su daño de impacto."},
[1219858] = {name = "Alma del pirómano", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del pirómano:\n\nTu Explosión de Fuego ahora hace que tu próximo hechizo de Fuego obtenga un 50% más de probabilidad de golpe crítico durante 10 s."},
[1219859] = {name = "Alma del encendedor", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del encendedor:\n\nAumenta un 10% el daño que inflige tu talento Ignición."},
[1219860] = {name = "Alma de la antorcha", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la antorcha:\n\nTus hechizos Bola de fuego, Descarga de Pirofrío y Descarga de fuego fardo obtienen un 4% más de daño por cada uno de tus efectos de Fuego sobre tu objetivo, hasta un máximo de un 12% más."},
[1219861] = {name = "Alma del bloqueador prístino", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del bloqueador prístino:\n\nAumenta 30 p. el valor de bloqueo de tu escudo."},
[1219862] = {name = "Alma del guardián de luz", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del guardián de luz:\n\nSana 189 to 211 p. cuando bloqueas. Solo puede sanar una vez cada pocos segundos."},
[1219863] = {name = "Alma del defensor radiante", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del defensor radiante:\n\nEn vez de tener cargas, Escudo Sagrado siempre alcanza su duración máxima. Además, el daño aumenta un 80% de tu valor de bloqueo con escudo."},
[1219864] = {name = "Alma del portaescudos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del portaescudos:\n\nAumenta un 10% la probabilidad de bloqueo adicional de Escudo Sagrado."},
[1219865] = {name = "Alma del bastión", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del bastión:\n\nRecibes un 10% menos de daño mientras Escudo Sagrado está activo."},
[1219866] = {name = "Alma del expiador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del expiador:\n\nTu talento Expiación ahora tiene un 20% de probabilidad por punto de talento de activarse cuando bloqueas."},
[1219867] = {name = "Alma del acorazado", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del acorazado:\n\nTu Bendición de salvaguardia también aumenta un 10% todas las estadísticas cuando la lanzas sobre ti."},
[1219868] = {name = "Alma del guardián", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del guardián:\n\nEscudo del honrado hace que el lanzamiento de tu próxima Luz Sagrada sea instantáneo. Si la lanzas sobre ti, restaurará un 100% de su costo de maná y no será afectada por Custodiado por la Luz."},
[1219869] = {name = "Alma del pacificador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del pacificador:\n\nAumenta un 70% la probabilidad de que tus aliados activen tu Sentencia de Luz o Sentencia de sabiduría."},
[1219870] = {name = "Alma del refinamiento", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del refinamiento:\n\nAumenta tu probabilidad de golpe crítico con hechizos y ataques un 2%."},
[1219871] = {name = "Alma del ejemplar", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del ejemplar:\n\nCuando tu Destello de luz, Luz Sagrada o Señal de la Luz restauran la salud de un objetivo por completo, también restauras 189 to 211 p. de salud a todos los miembros de su grupo."},
[1219872] = {name = "Alma del inquisidor", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del inquisidor:\n\nAumenta un 5% la probabilidad de golpe crítico de Choque sagrado."},
[1219873] = {name = "Alma de soberanía", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de soberanía:\n\nAumenta un 50% el daño infligido con tu hechizo de Consagración."},
[1219874] = {name = "Alma del investido", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del investido:\n\nMientras no seas objetivo de Señal de la Luz, tu objetivo de Señal de la Luz también sana un 75% del daño que infliges con Consagración, Exorcismo, Choque sagrado, Cólera sagrada y Martillo de cólera."},
[1219875] = {name = "Alma del vindicador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del vindicador:\n\nReduce un 25% el tiempo de reutilización de Luz divina."},
[1219876] = {name = "Alma del altruista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del altruista:\n\nTus sanaciones sobre el objetivo de tu Señal de la Luz también sanan al objetivo aliado más cercano por un 90%."},
[1219877] = {name = "Alma del árbitro", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del árbitro:\n\nTu Sentencia de Luz y Sentencia de sabiduría también otorgan los efectos de Sentencia del cruzado."},
[1219878] = {name = "Alma del portador de sellos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del portador de sellos:\n\nTu Sello de orden, Sello de rectitud y Sello de martirio infligen un 35% menos de daño, pero ahora persisten durante 6 s después de que lanzas otro Sello, o hasta que lances un tercer Sello. Tus Sentencias ahora pueden activar varios Sellos si están activas."},
[1219879] = {name = "Alma del justicar", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del justicar:\n\nAumenta un 5% el daño infligido por tus Sentencias, y tus Sentencias ya no consumen tus Sellos en el objetivo. Tus Sentencias ahora pueden activar varios Sellos al estar activas."},
[1219880] = {name = "Alma del juez", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del juez:\n\nReduce 5 s el tiempo de reutilización de tu habilidad Sentencia, pero también reduce un 45% su daño."},
[1219881] = {name = "Alma del ascendiente", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del ascendiente:\n\nTu Sentencia otorga un 1% más de daño Sagrado durante 8 s, y se acumula hasta 5 veces."},
[1219882] = {name = "Alma del desquite", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del desquite:\n\nAumenta un 150% el daño de Golpe de cruzado."},
[1219883] = {name = "Alma del excomulgador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del excomulgador:\n\nTus ataques básicos con armas cuerpo a cuerpo de dos manos aumentan un 35% el daño de tu siguiente lanzamiento de Exorcismo en los próximos 20 s. Se acumula hasta 3 veces."},
[1219884] = {name = "Alma del iluminado", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del iluminado:\n\nAumenta un 50% el daño infligido por tu hechizo Choque sagrado."},
[1219885] = {name = "Alma del exilio", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del exilio:\n\nReduce 3 s el tiempo de reutilización de tu hechizo Exorcismo y aumenta un 75% el daño que inflige."},
[1219886] = {name = "Alma del templario", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del templario:\n\nCon un arma de una mano equipada, Golpe de cruzado ahora libera el efecto de Sentencia de tus Sellos, pero no consume el Sello."},
[1219887] = {name = "Alma del viajero del viento", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del viajero del viento:\n\nAumenta tu velocidad de ataque un 30% en tus 3 próximos golpes después de parar, esquivar o bloquear."},
[1219888] = {name = "Alma del amo del escudo", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del amo del escudo:\n\nTus paradas y evasiones también activan tu habilidad de runa Maestría con escudos."},
[1219889] = {name = "Alma del protector totémico", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del protector totémico:\n\nTus Tótems Piel de piedra también reducen el daño físico recibido un 5% y tu Tótem Muro de viento también reduce el daño mágico recibido un 5%."},
[1219890] = {name = "Alma del aplacachoques", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del aplacachoques:\n\nTu Choque de llamas también aumenta un 30% la probabilidad de bloqueo durante 5 s o hasta que bloquees un ataque."},
[1219891] = {name = "Alma del baluarte espiritual", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del baluarte espiritual:\n\nCada vez que bloqueas, la cantidad de bloqueo aumenta un 10% de tu daño con hechizos durante 6 s, y se acumula hasta 3 veces."},
[1219892] = {name = "Alma del empuñavorágine", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del empuñavorágine:\n\nCada vez que bloqueas un ataque, tienes una probabilidad del 50% de activar tu runa Arma vorágine."},
[1219893] = {name = "Alma del zancalavas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del zancalavas:\n\nDañar a un objetivo con Golpe de tormenta, Ráfaga de lava o Explosión de arrabio también reduce un 10% todo el daño que recibes durante 10 s."},
[1219894] = {name = "Alma del alfa verdadero", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del alfa verdadero:\n\nCuando lanzas Espíritu del alfa sobre ti mismo, también aumenta tu salud un 5%, tu amenaza generada un 25%, y todo el daño que inflijas un 5%."},
[1219895] = {name = "Alma del guardián de tótems", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del guardián de tótems:\n\nEl radio de tus tótems que afectan a los objetivos aliados aumenta a 40 m."},
[1219896] = {name = "Alma de los ancestros", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de los ancestros:\n\nTras haber lanzado Ola de sanación, Ola de sanación inferior o Mareas vivas, te otorga un 25% de probabilidad de obtener maná por un monto equivalente al 35% del costo básico del hechizo."},
[1219897] = {name = "Alma del tejespíritus", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del tejespíritus:\n\nTu Ola de sanación saltará a otros objetivos cercanos. Cada salto reduce la eficacia de la sanación un 60%. El hechizo saltará a un máximo de 2 objetivos más."},
[1219898] = {name = "Alma del zancaaguas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del zancaaguas:\n\nTus golpes críticos que infligen daño y sanación no periódicos ahora tienen un 100% de probabilidad de activar tu Escudo de agua, pero no consumen una carga ni activan su tiempo de reutilización."},
[1219899] = {name = "Alma del velatormentas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del velatormentas:\n\nAhora tu Cadena de relámpagos también sana al objetivo de tu Escudo de tierra más reciente un 100% del daño infligido."},
[1219900] = {name = "Alma del vidente elemental", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del vidente elemental:\n\nAumenta la sanación de Sanación en cadena y el daño de Cadena de relámpagos un 20%."},
[1219901] = {name = "Alma del vitalista", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del vitalista:\n\nTu Mareas Vivas aumenta la cantidad de sanación de Sanación en cadena un 25% más."},
[1219902] = {name = "Alma del sanador espiritual", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sanador espiritual:\n\nReduce el tiempo de lanzamiento de Sanación en cadena 0.5 s."},
[1219903] = {name = "Alma del refinamiento", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del refinamiento:\n\nAumenta tu probabilidad de golpe crítico con hechizos y ataques un 2%."},
[1219904] = {name = "Alma del jefe", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del jefe:\n\nTu talento Aluvión aumenta un 10% más tu velocidad de ataque."},
[1219905] = {name = "Alma de carga furiosa", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de carga furiosa:\n\nTu probabilidad de activar Choque estático aumenta un 12% (6% mientras portas dos armas)."},
[1219906] = {name = "Alma del rompetormentas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del rompetormentas:\n\nAumenta un 50% el daño de mano derecha de tu Golpe de tormenta."},
[1219907] = {name = "Alma de la tempestad", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la tempestad:\n\nMientras Choque estático está grabado, tu Escudo de relámpagos obtiene una carga cada vez que golpeas a un objetivo con Descarga de relámpagos o Cadena de relámpagos, hasta un máximo de 9 cargas. Además, mientras Choque estático está grabado, tu Escudo de relámpagos puede infligir daño crítico."},
[1219908] = {name = "Alma del destructor sísmico", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del destructor sísmico:\n\nAumenta el daño de Golpe de tormenta y Latigazo de lava un 50%. Este efecto aumenta un 100% si se utiliza un arma de dos manos."},
[1219909] = {name = "Alma del clamallamas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del clamallamas:\n\nTus golpes críticos de Golpe de tormenta, Latigazo de lava y Ráfaga de lava hacen que tu objetivo arda y reciba un 30% del daño infligido durante 4 s."},
[1219910] = {name = "Alma del volcán", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del volcán:\n\nLos golpes críticos de tu Descarga de relámpagos tienen un 35% de probabilidad de restablecer el tiempo de reutilización de Ráfaga de lava y Cadena de relámpagos y de hacer que el próximo lanzamiento de Ráfaga de lava o Cadena de relámpagos en 10 s sea instantáneo."},
[1219911] = {name = "Alma de la llama furibunda", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la llama furibunda:\n\nRáfaga de lava ahora también restablece la duración de Choque de llamas para tu objetivo en 12 s."},
[1219912] = {name = "Alma del maestro elemental", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del maestro elemental:\n\nAhora tus golpes críticos con hechizos tienen una probabilidad del 100% de activar tu talento Enfoque elemental."},
[1219913] = {name = "Alma del tribal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del tribal:\n\nBeta leal, de tu habilidad Espíritu del alfa, ahora también aumenta un 5 + (5 * ComboPoints)% el daño de Fuego, Escarcha y Naturaleza."},
[1219914] = {name = "Alma del guía espiritual", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del guía espiritual:\n\nMientras Lanzamiento libre está activo, infliges un 15 + (5 * ComboPoints)% más de daño no físico."},
[1219915] = {name = "Alma del ancestro", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del ancestro:\n\nTienes una probabilidad del 70% de evitar las interrupciones por daño mientras lanzas Descarga de relámpagos, Cadena de relámpagos o Ráfaga de lava, y aumenta un 10% la probabilidad de activar tu talento Enfoque elemental."},
[1219916] = {name = "Alma de los elementos", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de los elementos:\n\nAumenta un 60% la bonificación de daño por golpe crítico con tus hechizos de Fuego, Escarcha y Naturaleza."},
[1219917] = {name = "Alma del sabio de lava", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sabio de lava:\n\nEl daño de tu Ráfaga de lava aumenta un porcentaje equivalente a tu probabilidad de golpe crítico con hechizos."},
[1219918] = {name = "Alma del guardián ancestral", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del guardián ancestral:\n\nAumenta un 10% tu probabilidad de bloquear ataques con un escudo."},
[1219919] = {name = "Alma del corrupto", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del corrupto:\n\nAumenta un 5% más la probabilidad de activar tu runa Oleada de poder."},
[1219920] = {name = "Alma de pata suave", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de pata suave:\n\nPuedes lanzar Renacer y Estimular mientras estás en Forma de oso o Forma de oso temible."},
[1219921] = {name = "Alma del feroz", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del feroz:\n\nReduce 30 s el tiempo de reutilización de Enfurecer y ya no reduce tu armadura."},
[1219922] = {name = "Alma del cambiaformas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del cambiaformas:\n\nForma de oso y Forma de oso temible aumentan un 20% más toda la amenaza que generas, y Agazapar ahora elimina toda la amenaza generada contra el objetivo, pero tiene 20 s más de tiempo de reutilización."},
[1219923] = {name = "Alma del territorial", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del territorial:\n\nFlagelo (oso) también hace que tu Magullar golpee a 1 objetivo más durante los próximos 6 s."},
[1219924] = {name = "Alma de la bestia", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la bestia:\n\nTus habilidades Destrozar (oso), Flagelo (oso), Magullar y Lacerar obtienen un 5% más de probabilidad de golpe crítico contra los objetivos bajo los efectos de tu Lacerar."},
[1219925] = {name = "Alma del lacerador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del lacerador:\n\nTu Flagelo ahora propaga el Lacerar de tu objetivo principal a otros de los objetivos que golpea."},
[1219926] = {name = "Alma del furioso", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del furioso:\n\nCada vez que esquivas en Forma de oso temible, obtienes un 10% más de daño para el próximo Destrozar o Flagelo. Se acumula un máximo de 5 veces."},
[1219927] = {name = "Alma del destrozador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del destrozador:\n\nReduce 1.5 s el tiempo de reutilización de Destrozar (oso)."},
[1219928] = {name = "Alma del estimulador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del estimulador:\n\nCuando lanzas Estimular sobre otro jugador, también se lanzará sobre ti."},
[1219929] = {name = "Alma de la fuente de nutrición", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de fuente de nutrición:\n\nCuando lanzas tus hechizos de Toque de sanación o Nutrir, tienes un 25% de probabilidad de obtener una cantidad de maná equivalente al 35% del costo base del hechizo."},
[1219930] = {name = "Alma del sosiego", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sosiego:\n\nReduce un 100% el tiempo de reutilización de Tranquilidad y aumenta un 100% su sanación."},
[1219931] = {name = "Alma del caminasueños", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del caminasueños:\n\nLos golpes críticos de tus hechizos de sanación activan el efecto Estado onírico, lo que te otorga un 50% de tu regeneración de maná al lanzar hechizos durante 8 s."},
[1219932] = {name = "Alma del cuidador de arboleda", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del cuidador de arboleda:\n\nTus golpes críticos con hechizos que no son periódicos reducen 0.5 s el tiempo de lanzamiento de tu siguiente Toque de sanación, Recrecimiento o Nutrir."},
[1219933] = {name = "Alma del sabio emplumado", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del sabio emplumado:\n\nAumenta un 10% la sanación de Crecimiento salvaje. Además, Crecimiento salvaje se puede usar en forma de lechúcico lunar, y su sanación aumenta un 50% en esa forma."},
[1219934] = {name = "Alma del vidente benevolente", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del vidente benevolente:\n\nReduce un 65% el tiempo de reutilización de tus hechizos Renacer e Estimular."},
[1219935] = {name = "Alma del tejevidas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del tejevidas:\n\nTus sanaciones críticas con Toque de sanación, Recrecimiento y Nutrir sanan al objetivo inmediatamente por otro 50% de la sanación realizada."},
[1219936] = {name = "Alma del iluminador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del iluminador:\n\nTu Fuego feérico (Feral) también aumenta un 1% la probabilidad de que todos los ataques golpeen a ese objetivo durante 40 s."},
[1219937] = {name = "Alma de instintos depredadores", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de instintos depredadores:\n\nEl daño periódico de tu Arañazo y tu Destripar ahora puede ser golpes críticos."},
[1219938] = {name = "Alma del destripador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del destripador:\n\nTu Destripar y tu Mordedura feroz tienen una probabilidad de 20% por p. de combo gastado de restablecer la duración de Rugido salvaje a su valor inicial."},
[1219939] = {name = "Alma de la zarpa", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la zarpa:\n\nAumenta 3 s la duración de Arañazo y un 10% su daño periódico."},
[1219940] = {name = "Alma de la manada imponente", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la manada imponente:\n\nTu probabilidad de golpe crítico aumenta un 15% cuando Furia del tigre está activa."},
[1219941] = {name = "Alma del barbárico", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del barbárico:\n\nTus habilidades Triturar, Mordedura feroz y Destrozar (felino) infligen un 10% más de daño por efecto de sangrado tuyo sobre el objetivo, hasta un máximo de un 20% más."},
[1219942] = {name = "Alma del frenético", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del frenético:\n\nTu Triturar ya no tiene un requisito de posición, pero inflige un 5% más de daño si estás detrás del objetivo."},
[1219943] = {name = "Alma del desangrador", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del desangrador:\n\nLos golpes críticos de tu Destrozar, Triturar y Mordedura feroz hacen que tu objetivo sangre y sufra un 30% del daño infligido durante los próximos 4 s s."},
[1219944] = {name = "Alma del guardián de espinas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del guardián de espinas:\n\nEl daño infligido por Espinas aumenta 100 p. y su duración, un 200%."},
[1219945] = {name = "Alma del lunático", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del lunático:\n\nAumenta un 3% tu probabilidad de golpear con hechizos y ataques."},
[1219946] = {name = "Alma del llamaestrellas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del llamaestrellas:\n\nReduce un 50% el tiempo de reutilización de Lluvia de estrellas."},
[1219947] = {name = "Alma de la noche", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de la noche:\n\nAumenta un 25% el daño y el radio de daño de las estrellas de Lluvia de estrellas y Huracán."},
[1219948] = {name = "Alma de los protectores", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de los protectores:\n\nTus lanzamientos de Cólera tienen un 10% de probabilidad de invocar a un grupo de 3 antárboles para que ataquen a tu objetivo durante 15 s."},
[1219949] = {name = "Alma del colérico", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del colérico:\n\nTus golpes críticos de Cólera tienen un 50% de probabilidad de hacer que tu próximo Fuego estelar inflija un 10% más de daño. Se acumula hasta 3 veces."},
[1219950] = {name = "Alma de gracia salvaje", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de gracia salvaje:\n\nTu talento Gracia de la Naturaleza obtiene 1 carga más cada vez que se activa."},
[1219951] = {name = "Alma del ascendiente astral", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del ascendiente astral:\n\nAumenta un 60% la bonificación de daño crítico de tus Fuego estelar, Oleada de estrellas y Cólera."},
[1219952] = {name = "Alma del llamacometas", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del llamacometas:\n\nReduce 0.5 s el tiempo de lanzamiento y el tiempo de reutilización global de Fuego estelar."},
[1219953] = {name = "Alma del bosque", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma del bosque:\n\nAumenta un 10% la probabilidad de golpe crítico de Cólera."},
[1219954] = {name = "Alma de pericia animal", additional_info = "Hechizo de 3 seg\nRequiere Sobrehombros\n[q]Infunde tus hombreras permanentemente con el Alma de pericia animal:\n\nTus ataques cuerpo a cuerpo tienen un 5% menos de probabilidad de ser esquivados o parados."},
[1219955] = {name = "Grabado de almas", additional_info = "Instante\n[q]Se puede grabar el alma de un guerrero caído en esta ranura."},
[1219956] = {name = "Alma del táctico", additional_info = nil},
[1219957] = {name = "Alma del táctico", additional_info = "[q]Después de cargar actitudes, el costo de ira de tu próxima habilidad ofensiva se reduce 10 p."},
[1219958] = {name = "Alma del veterano de guerra", additional_info = "[q]Durante 15 s después de cambiar de actitud, puedes usar habilidades que requieren la actitud anterior como si aún la tuvieras."},
[1219959] = {name = "Alma del veterano de guerra", additional_info = nil},
[1219960] = {name = "Alma del augur de batalla", additional_info = "[q]Durante los primeros 15 s después de activar una actitud, puedes obtener un beneficio adicional:\n\n Actitud de batalla/Actitud de gladiador: aumenta un 5% el daño infligido.\n\n Actitud rabiosa: aumenta un 5% la probabilidad de golpe crítico.\n\n Actitud defensiva: reduce un 5% el daño físico recibido."},
[1219961] = {name = "Alma del augur de batalla", additional_info = nil},
[1219962] = {name = "Alma del buscasangre", additional_info = "[q]Los golpes críticos de Abrumar restablecen la duración máxima de Desgarrar en tu objetivo."},
[1219963] = {name = "Alma del buscasangre", additional_info = nil},
[1219964] = {name = "Alma del titán", additional_info = "[q]Tus habilidades Golpe heroico, Embate y Abrumar infligen un 10 + (5 * ComboPoints)% más de daño."},
[1219965] = {name = "Alma del titán", additional_info = nil},
[1219966] = {name = "Alma del destructor", additional_info = "[q]Tus golpes de Embate restablecen el tiempo de reutilización de tus habilidades Golpe mortal, Sed de sangre y Embate con escudo."},
[1219967] = {name = "Alma del destructor", additional_info = nil},
[1219968] = {name = "Alma del lazomortal", additional_info = "[q]Reduce un 50% el tiempo de reutilización de tu Deseo de muerte."},
[1219969] = {name = "Alma del lazomortal", additional_info = nil},
[1219970] = {name = "Alma del sanguinista", additional_info = "[q]Infliges un 15% más de daño mientras un enemigo cercano esté afectado por tu Desgarrar y tus Heridas profundas."},
[1219971] = {name = "Alma del sanguinista", additional_info = nil},
[1219972] = {name = "Alma del bloqueador prístino", additional_info = "[q]Aumenta 30 p. el valor de bloqueo de tu escudo."},
[1219973] = {name = "Alma del bloqueador prístino", additional_info = nil},
[1219974] = {name = "Alma del salvaje", additional_info = "[q]Obtienes 1 p. más de ira cada vez que recibes o infliges daño con ataques automáticos."},
[1219975] = {name = "Alma del salvaje", additional_info = nil},
[1219976] = {name = "Alma de animosidad", additional_info = "[q]Aumenta toda la amenaza que generas en actitud defensiva un 10% más y aumenta todo el daño que infliges en actitud de gladiador un 4%."},
[1219977] = {name = "Alma de animosidad", additional_info = nil},
[1219978] = {name = "Alma del deflector", additional_info = "[q]Obtienes 10 p. de ira cada vez que paras un ataque o que alguien para uno de los tuyos."},
[1219979] = {name = "Alma del deflector", additional_info = nil},
[1219980] = {name = "Alma de revancha", additional_info = "[q]Revancha también te otorga Aluvión, lo que aumenta tu velocidad de ataque un 30% durante los siguientes 3 golpes."},
[1219981] = {name = "Alma de revancha", additional_info = nil},
[1219982] = {name = "Alma del incesante", additional_info = "[q]Cuando tu objetivo para un ataque, tomas Represalia de forma inmediata e infliges un 200% de daño con arma al objetivo. Represalia no se puede esquivar, bloquear ni parar, pero solo puede ocurrir una vez cada 30 s por objetivo."},
[1219983] = {name = "Alma del incesante", additional_info = nil},
[1219984] = {name = "Alma del portatruenos", additional_info = "[q]Reduce un 100% el tiempo de reutilización de Atronar."},
[1219985] = {name = "Alma del portatruenos", additional_info = nil},
[1219986] = {name = "Alma del centinela", additional_info = "[q]Tu Embate con escudo genera un 100% más de amenaza y su tiempo de reutilización se restablece si se esquiva, para o bloquea."},
[1219987] = {name = "Alma del centinela", additional_info = nil},
[1219988] = {name = "Alma del zurdo", additional_info = "[q]Reduce 2 s el tiempo de reutilización de tu habilidad Embate con escudo."},
[1219989] = {name = "Alma del zurdo", additional_info = nil},
[1219990] = {name = "Alma del gladiador", additional_info = "[q]Reduce 30 s el tiempo de reutilización de tu habilidad Ira sangrienta mientras estás en Actitud de gladiador."},
[1219991] = {name = "Alma del gladiador", additional_info = nil},
[1219992] = {name = "Alma de la réplica", additional_info = "[q]Reduce un 25% el tiempo de reutilización de Ola de choque."},
[1219993] = {name = "Alma de la réplica", additional_info = nil},
[1219994] = {name = "Alma del evasivo", additional_info = "[q]Amago también otorga Eludir durante 6 s, lo que reduce un 50% todo el daño recibido de ataques con área de efecto de enemigos que no sean jugadores."},
[1219995] = {name = "Alma del evasivo", additional_info = nil},
[1219996] = {name = "Alma del toxicólogo", additional_info = "[q]Aumenta un 100% la bonificación de daño por golpe crítico con tus venenos."},
[1219997] = {name = "Alma del toxicólogo", additional_info = nil},
[1219998] = {name = "Alma del verdugo", additional_info = "[q]Tus remates tienen una probabilidad del 5% por punto de combo de hacer que tu próxima habilidad no cueste energía."},
[1219999] = {name = "Alma del verdugo", additional_info = nil},
[1220000] = {name = "Alma del oportunista", additional_info = "[q]Tus ataques iniciales tienen un 100% de probabilidad de hacer que tu siguiente habilidad no cueste energía."},
[1220001] = {name = "Alma del oportunista", additional_info = nil},
[1220002] = {name = "Alma del carnicero", additional_info = "[q]Aumenta un 20% el daño que inflige el arma de tu mano derecha con habilidades que generan puntos de combo."},
[1220003] = {name = "Alma del carnicero", additional_info = nil},
[1220004] = {name = "Alma del fantasma", additional_info = "[q]Reduce el tiempo de reutilización de Esfumar a 1 min. No se puede combinar con Elusión."},
[1220005] = {name = "Alma del fantasma", additional_info = nil},
[1220006] = {name = "Alma del ladronzuelo", additional_info = "[q]Aumenta un 20% el daño de Mutilar y Sablazo."},
[1220007] = {name = "Alma del ladronzuelo", additional_info = nil},
[1220008] = {name = "Alma del amante de la adrenalina", additional_info = "[q]Reduce el tiempo de reutilización de Subidón de adrenalina 4 min."},
[1220009] = {name = "Alma del amante de la adrenalina", additional_info = nil},
[1220010] = {name = "Alma del experto en puyazos", additional_info = "[q]Aumenta un 5% tu probabilidad de conseguir un golpe crítico con dagas."},
[1220011] = {name = "Alma del experto en puyazos", additional_info = nil},
[1220012] = {name = "Alma del acechador", additional_info = "[q]Aumenta un 30% la probabilidad de golpe crítico de tu habilidad Emboscada."},
[1220013] = {name = "Alma del acechador", additional_info = nil},
[1220014] = {name = "Alma del eficiente", additional_info = "[q]Tus remates cuestan un 50% menos de energía."},
[1220015] = {name = "Alma del eficiente", additional_info = nil},
[1220016] = {name = "Alma del malabarista de cuchillos", additional_info = "[q]Mientras Heridas superficiales y Danza de hojas están activos, Tempestad carmesí, Trabuco y Abanico de cuchillos cuesta 20 p. menos de energía y genera un 100% más de amenaza."},
[1220017] = {name = "Alma del malabarista de cuchillos", additional_info = nil},
[1220018] = {name = "Alma del maestro de las sombras", additional_info = "[q]Esfumarse ahora reduce todo el daño mágico que recibes un 50% durante su efecto, pero ya no otorga sigilo ni elimina los efectos de reducción de movimiento."},
[1220019] = {name = "Alma del maestro de las sombras", additional_info = nil},
[1220020] = {name = "Alma del equilibrista", additional_info = "[q]Tus remates tienen una probabilidad del 20% por punto de combo de que recibas un 20% menos de daño físico del próximo ataque cuerpo a cuerpo que recibas dentro de 10 s."},
[1220021] = {name = "Alma del equilibrista", additional_info = nil},
[1220022] = {name = "Alma del camorrista fogueado", additional_info = "[q]Tu Bravura ante los golpes ahora también se activa cada vez que obtienes un punto de combo."},
[1220023] = {name = "Alma del cinturón negro", additional_info = "[q]Tu Bravura ante los golpes también aumenta un 20% la armadura que te otorgan los objetos por cada acumulación (hasta un máximo de 100%)."},
[1220024] = {name = "Alma del camorrista fogueado", additional_info = nil},
[1220025] = {name = "Alma del cinturón negro", additional_info = nil},
[1220026] = {name = "Alma del esgrimista", additional_info = "[q]El tiempo de reutilización de tu Daga de guardamano se restablece cada vez que tu objetivo esquiva o para un ataque."},
[1220027] = {name = "Alma del esgrimista", additional_info = nil},
[1220028] = {name = "Alma del espadachín", additional_info = "[q]Tu Daga de guardamano ahora golpea a 1 objetivo cercano más y también hace que tu Golpe siniestro golpee a 1 objetivo cercano más durante 10 s. Estos golpes adicionales no se duplican con Aluvión de acero."},
[1220029] = {name = "Alma del espadachín", additional_info = nil},
[1220030] = {name = "Alma del sanguinario", additional_info = "[q]Mientras el efecto está activo, tu Daga de guardamano hace que te sanes por un 15% de todo el daño que inflige Golpe siniestro. La sanación excedente se convierte en una Barrera de sangre que absorbe daño equivalente a un máximo del 20% de tu salud máxima."},
[1220031] = {name = "Alma del sanguinario", additional_info = nil},
[1220032] = {name = "Alma del transfusionista", additional_info = "[q]Transfusión de vida genera un 50% más de maná y un 100% menos de amenaza."},
[1220033] = {name = "Alma del transfusionista", additional_info = nil},
[1220034] = {name = "Alma del refinamiento", additional_info = "[q]Aumenta un 2% tu probabilidad de conseguir un golpe crítico con hechizos y ataques."},
[1220035] = {name = "Alma del exterminador", additional_info = "[q]Tu talento Ocaso tiene un 4% más de probabilidad de activarse. Tu Incinerar tiene un 4% de probabilidad de activar tu Exterminación sin importar la salud del objetivo."},
[1220036] = {name = "Alma del refinamiento", additional_info = nil},
[1220037] = {name = "Alma del exterminador", additional_info = nil},
[1220038] = {name = "Alma del putrefaccionista", additional_info = "[q]Aumenta el daño de tus hechizos periódicos y de tu mascota Guardia vil un 10 + (5 * ComboPoints)%."},
[1220039] = {name = "Alma del putrefaccionista", additional_info = nil},
[1220040] = {name = "Alma del malévolo", additional_info = "[q]El daño periódico de tus hechizos Llama de las Sombras, Aflicción inestable y Maldición de agonía, y el daño infligido por tu Guardia vil tienen una probabilidad del 4% de otorgar el efecto Trance de las Sombras."},
[1220041] = {name = "Alma del malévolo", additional_info = nil},
[1220042] = {name = "Alma del sombramante", additional_info = "[q]Descarga de las Sombras inflige un 10 + (5 * ComboPoints)% más de daño por cada uno de tus efectos sobre el objetivo, hasta un máximo de 30 + (5 * ComboPoints)%."},
[1220043] = {name = "Alma del sombramante", additional_info = nil},
[1220044] = {name = "Alma del heraldo del caos", additional_info = "[q]Reduce un 50% el tiempo de reutilización de tu Descarga de caos y aumenta un 10% el daño infligido con Descarga de caos y Descarga de las sombras. Además, Descarga de caos ahora puede activar tu talento Descarga de las sombras mejorada y hace que tenga 26 cargas más (no se acumulan con las cargas adicionales de Llama de las Sombras)."},
[1220045] = {name = "Alma del heraldo del caos", additional_info = nil},
[1220046] = {name = "Alma del incendiario", additional_info = "[q]Cada vez que golpeas a un objetivo con Conflagrar, obtienes un 5% más de daño de Fuego durante 20 s. Se acumula hasta 2 veces."},
[1220047] = {name = "Alma del incendiario", additional_info = nil},
[1220048] = {name = "Alma del pastor infernal", additional_info = "[q]Aumenta un 20% el poder de ataque y el daño con hechizos que tu mascota demoníaca obtiene de tus atributos."},
[1220049] = {name = "Alma del pastor infernal", additional_info = nil},
[1220050] = {name = "Alma del señor demoníaco", additional_info = "[q]Aumenta un 50% los beneficios de tu talento Maestro demonólogo."},
[1220051] = {name = "Alma del señor demoníaco", additional_info = nil},
[1220052] = {name = "Alma del exorcista demoníaco", additional_info = "[q]Desterrar ahora se lanza al instante y se puede lanzar sobre ti mismo mientras seas un demonio. No puedes Desterrarte a ti mismo mientras tienes Abstinencia, y si lo haces recibirás Abstinencia durante 1 min."},
[1220053] = {name = "Alma del exorcista demoníaco", additional_info = nil},
[1220054] = {name = "Alma del adolorido", additional_info = "[q]Cada vez que recibes daño, tú y tu mascota obtienen una cantidad de maná equivalente al daño recibido, hasta un máximo de 420 p. de maná por evento. Solo puede ocurrir una vez cada pocos segundos."},
[1220055] = {name = "Alma del adolorido", additional_info = nil},
[1220056] = {name = "Alma del ánima flamígera", additional_info = "[q]Tus golpes de Cuchilla de las Sombras tienen un 20% de probabilidad de otorgarte un fragmento de alma, restablecer el tiempo de reutilización de Fuego de alma y hacer que tu siguiente Fuego de alma en los próximos 10 s sea instantáneo."},
[1220057] = {name = "Alma del ánima flamígera", additional_info = nil},
[1220058] = {name = "Alma del devoracarnes", additional_info = "[q]Mientras marcas como objetivo a un enemigo que esté en un radio de 30 m, Transfusión de vida te otorga maná a costa de la salud de tu objetivo, pero le inflige un 50 + (5 * ComboPoints)% menos de daño. No afecta el maná obtenido."},
[1220059] = {name = "Alma del devoracarnes", additional_info = nil},
[1220060] = {name = "Alma del abisal", additional_info = "[q]Mientras Metamorfosis está activa, tus habilidades ofensivas e invocaciones demoníacas no cuestan fragmentos de alma. Además, sanas un 15% de tu salud máxima cuando dañas a un objetivo con Quemadura de las Sombras."},
[1220061] = {name = "Alma del abisal", additional_info = nil},
[1220062] = {name = "Alma del natovacío", additional_info = "[q]Toda la sanación adicional que te infliges se convierte en un escudo que absorbe daño. Este escudo puede absorber hasta un 30 + (5 * ComboPoints)% de tu salud máxima y acumula múltiples sanaciones."},
[1220063] = {name = "Alma del natovacío", additional_info = nil},
[1220064] = {name = "Alma de la hoja umbría", additional_info = "[q]Reduce 1.5 s el tiempo de reutilización de tu Cuchilla de las Sombras."},
[1220065] = {name = "Alma de la hoja umbría", additional_info = nil},
[1220066] = {name = "Alma del ritualista", additional_info = "[q]Los efectos de tu Sacrificio demoníaco ahora persisten mientras tengas una mascota demoníaca activa, siempre y cuando no reinvoques a la mascota sacrificada. Solo puedes contar con un efecto de Sacrificio demoníaco activo a la vez."},
[1220067] = {name = "Alma del ritualista", additional_info = nil},
[1220068] = {name = "Alma del propagador de dolor", additional_info = "[q]Durante 6 s después de usar Cuchilla de las Sombras, tu Dolor abrasador golpea a 1 objetivo más que esté en un radio cuerpo a cuerpo."},
[1220069] = {name = "Alma del propagador de dolor", additional_info = nil},
[1220070] = {name = "Alma del líder del engaño", additional_info = "[q]Generas un 100% más de amenaza durante 8 s después de usar Disparo de distracción."},
[1220071] = {name = "Alma del líder del engaño", additional_info = nil},
[1220072] = {name = "Alma del buscapresas", additional_info = "[q]Mientras rastreas un tipo de criatura, infliges un 3% más de daño a ese tipo de criatura."},
[1220073] = {name = "Alma del buscapresas", additional_info = nil},
[1220074] = {name = "Alma del tirador certero", additional_info = "[q]La siguiente habilidad de Disparo que utilices en los próximos 12 s después de utilizar Disparo de puntería inflige un 20% más de daño."},
[1220075] = {name = "Alma del tirador certero", additional_info = nil},
[1220076] = {name = "Alma del asaltante agresivo", additional_info = "[q]Tu Disparo de puntería inflige un 20% más de daño a los objetivos bajo los efectos de una de tus trampas."},
[1220077] = {name = "Alma del asaltante agresivo", additional_info = nil},
[1220078] = {name = "Alma del alternador", additional_info = "[q]Tus habilidades de daño de Disparo infligen un 10% más de daño si el último Disparo de daño usado fue distinto al anterior."},
[1220079] = {name = "Alma del alternador", additional_info = nil},
[1220080] = {name = "Alma del toxinólogo", additional_info = "[q]El daño de tu Picadura de serpiente aumenta un 25% de tu poder de ataque durante su duración normal."},
[1220081] = {name = "Alma del toxinólogo", additional_info = nil},
[1220082] = {name = "Alma del cazarrecompensas", additional_info = "[q]Aumenta un 10% el daño de Disparo mortal contra objetivos que no están controlados por jugadores."},
[1220083] = {name = "Alma del cazarrecompensas", additional_info = nil},
[1220084] = {name = "Alma del as del gatillo", additional_info = "[q]Reduce el tiempo de reutilización de Disparo mortal un 50%. Mientras Fuego rápido está activo con la runa Matanza rápida grabada, Disparo mortal no tiene tiempo de reutilización y, cuando se usa contra un objetivo que no está controlado por un jugador, hace 3 Disparos mortales más con un 30% del daño y con un alcance mínimo."},
[1220085] = {name = "Alma del as del gatillo", additional_info = nil},
[1220086] = {name = "Alma del protector de bestias", additional_info = "[q]Aumenta un 20% el poder de ataque que tu mascota bestia obtiene de tus atributos."},
[1220087] = {name = "Alma del protector de bestias", additional_info = nil},
[1220088] = {name = "Alma del maestro de canes", additional_info = "[q]Aumenta un 20% la regeneración de enfoque de tu mascota bestia."},
[1220089] = {name = "Alma del maestro de canes", additional_info = nil},
[1220090] = {name = "Alma del domador alfa", additional_info = "[q]Aumenta un 100% la regeneración de enfoque de tus mascotas."},
[1220091] = {name = "Alma del domador alfa", additional_info = nil},
[1220092] = {name = "Alma del montero", additional_info = "[q]Tu Mordedura de mangosta también reduce un 1% la probabilidad de esquivar de su objetivo y aumenta un 1% tu probabilidad de golpear durante 30 s."},
[1220093] = {name = "Alma del montero", additional_info = nil},
[1220094] = {name = "Alma del retaliador", additional_info = "[q]Mordedura de mangosta también se activa durante 5 s cuando tu objetivo para o bloquea, o cuando tus ataques cuerpo a cuerpo fallan."},
[1220095] = {name = "Alma del retaliador", additional_info = nil},
[1220096] = {name = "Alma de los ecos", additional_info = "[q]Golpe de raptor aumenta un 20% el daño que inflige tu próxima habilidad cuerpo a cuerpo diferente (excepto Cortar alas) en un período de 5 s."},
[1220097] = {name = "Alma de los ecos", additional_info = nil},
[1220098] = {name = "Alma del azotador letal", additional_info = "[q]Aumenta un 20% el daño que inflige el arma de tu mano derecha con Golpe de raptor y Golpe de dracoleón."},
[1220099] = {name = "Alma del azotador letal", additional_info = nil},
[1220100] = {name = "Alma del cinético", additional_info = "[q]Tu daño periódico tiene un 5% de probabilidad de restablecer el tiempo de reutilización de una de tus habilidades de Golpe. Siempre se selecciona el Golpe con el mayor tiempo de reutilización restante."},
[1220101] = {name = "Alma del cinético", additional_info = nil},
[1220102] = {name = "Alma del estratega", additional_info = "[q]Aumenta el daño con el tiempo de Golpe de dracoleón un 50% y aumenta el enfoque máximo de tu mascota 50 p."},
[1220103] = {name = "Alma del estratega", additional_info = nil},
[1220104] = {name = "Alma del golpeador mortal", additional_info = "[q]Aumenta un 20% el daño de impacto de Mordedura de mangosta y todos los Golpes."},
[1220105] = {name = "Alma del golpeador mortal", additional_info = nil},
[1220106] = {name = "Alma del sanador súbito", additional_info = "[q]-0.1 s de tiempo de lanzamiento de Sanación relámpago y -0.2 s de tiempo de lanzamiento de Sanación superior."},
[1220107] = {name = "Alma del sanador súbito", additional_info = nil},
[1220108] = {name = "Alma del refinamiento", additional_info = "[q]Aumenta un 2% tu probabilidad de conseguir un golpe crítico con hechizos y ataques."},
[1220109] = {name = "Alma del refinamiento", additional_info = nil},
[1220110] = {name = "Alma del oficiante", additional_info = "[q]Aumenta un 25% tu probabilidad de golpe crítico con Rezo de sanación y Círculo de sanación."},
[1220111] = {name = "Alma del oficiante", additional_info = nil},
[1220112] = {name = "Alma del fiel", additional_info = "[q]Permite que un 15% de tu regeneración de maná continúe mientras lanzas hechizos."},
[1220113] = {name = "Alma del fiel", additional_info = nil},
[1220114] = {name = "Alma de serendipia", additional_info = "[q]Tu sanación periódica tiene un 2% de probabilidad de hacer que tu próximo hechizo con un tiempo de lanzamiento inferior a 10 segundos sea un hechizo de lanzamiento instantáneo."},
[1220115] = {name = "Alma de serendipia", additional_info = nil},
[1220116] = {name = "Alma del resonante", additional_info = "[q]Círculo de sanación y Penitencia también aplican un efecto de sanación con el tiempo a sus objetivos que sana un 25% del total durante 15 s."},
[1220117] = {name = "Alma del resonante", additional_info = nil},
[1220118] = {name = "Alma del devoto", additional_info = "[q]Tu Rezo de alivio obtiene 2 cargas más."},
[1220119] = {name = "Alma del devoto", additional_info = nil},
[1220120] = {name = "Alma del arzobispo", additional_info = "[q]Tu Círculo de sanación ahora sana al miembro más herido del grupo objetivo por un 100% más."},
[1220121] = {name = "Alma del arzobispo", additional_info = nil},
[1220122] = {name = "Alma del penitente", additional_info = "[q]Reduce 6 s el tiempo de reutilización de tu hechizo Penitencia."},
[1220123] = {name = "Alma del penitente", additional_info = nil},
[1220124] = {name = "Alma del guardián del alma", additional_info = "[q]Aumenta un 10% la absorción de daño de tu Palabra de poder: escudo."},
[1220125] = {name = "Alma del guardián del alma", additional_info = nil},
[1220126] = {name = "Alma del errante crepuscular", additional_info = "[q]Puedes lanzar Sanación relámpago mientras estás en Forma de las Sombras."},
[1220127] = {name = "Alma del errante crepuscular", additional_info = nil},
[1220128] = {name = "Alma del rompementes", additional_info = "[q]Los golpes críticos de Explosión mental reducen la duración de tu próximo Tortura mental un 50%, si bien aumentan su daño total un 25%."},
[1220129] = {name = "Alma del rompementes", additional_info = nil},
[1220130] = {name = "Alma del mortífero", additional_info = "[q]Reduce 6 s el tiempo de reutilización de tu hechizo Palabra de las Sombras: muerte."},
[1220131] = {name = "Alma del mortífero", additional_info = nil},
[1220132] = {name = "Alma de la fuente espiritual", additional_info = "[q]Tu Palabra de las Sombras: dolor tiene un 2.0% de probabilidad por cada punto de talento en Transfusión de espíritu de activar tu talento Transfusión de espíritu cuando inflige daño, o un 20% de probabilidad por cada punto de talento cuando un objetivo muere con tu Palabra de las Sombras: dolor activa. Enfoque interno también tiene un 20% de probabilidad por cada punto de talento de activar Transfusión de espíritu."},
[1220133] = {name = "Alma de la fuente espiritual", additional_info = nil},
[1220134] = {name = "Alma del zelote", additional_info = "[q]Mientras Transfusión de espíritu está activo, infliges un 25% más de daño de las Sombras."},
[1220135] = {name = "Alma del zelote", additional_info = nil},
[1220136] = {name = "Alma del profanador implacable", additional_info = "[q]Ya no se reduce la duración de tu Tortura mental cuando recibes daño, y el lanzamiento activa una Púa mental gratis sobre el objetivo."},
[1220137] = {name = "Alma del profanador implacable", additional_info = nil},
[1220138] = {name = "Alma del desdeñoso", additional_info = "[q]El efecto de tu Púa mental ahora es instantáneo, inflige un 10% más de daño y se puede lanzar mientras canalizas otro hechizo."},
[1220139] = {name = "Alma del desdeñoso", additional_info = nil},
[1220140] = {name = "Alma del pesteador", additional_info = "[q]Tu runa Dolor y sufrimiento ahora puede restablecer la duración de Peste devoradora."},
[1220141] = {name = "Alma del pesteador", additional_info = nil},
[1220142] = {name = "Alma del reverberante", additional_info = "[q]Tus Faros temporales duran un 20% más."},
[1220143] = {name = "Alma del reverberante", additional_info = nil},
[1220144] = {name = "Alma del cronosanador", additional_info = "[q]Aumenta un 10% toda la sanación cronomántica que realizas."},
[1220145] = {name = "Alma del cronosanador", additional_info = nil},
