[1220147] = {name = "Alma del anhelo temporal", additional_info = nil},
[1220148] = {name = "Alma del precognoscente", additional_info = "[q]Tu Misiles arcanos restituye un 10% de su costo de maná básico cada vez que inflige daño."},
[1220149] = {name = "Alma del precognoscente", additional_info = nil},
[1220150] = {name = "Alma del arcanista", additional_info = "[q]Explosión Arcana obtiene un 10% más de probabilidad de activar Tromba de misiles, y Tromba de misiles ahora afecta a Regeneración de la misma forma que a Misiles arcanos."},
[1220151] = {name = "Alma del arcanista", additional_info = nil},
[1220152] = {name = "Alma del cuidador eterno", additional_info = "[q]Tus Faros temporales causados por Regeneración en masa ahora duran 21 s."},
[1220153] = {name = "Alma del cuidador eterno", additional_info = nil},
[1220154] = {name = "Alma del conjurante", additional_info = "[q]Tu Explosión Arcana aumenta el daño realizado un 10% más por acumulación."},
[1220155] = {name = "Alma del conjurante", additional_info = nil},
[1220156] = {name = "Alma del resguardador", additional_info = "[q]Tu Escudo de maná, Resguardo contra el Fuego y Resguardo contra la Escarcha absorben un 50% más de daño y también colocan un Faro temporal sobre el objetivo durante 30 s."},
[1220157] = {name = "Alma del resguardador", additional_info = nil},
[1220158] = {name = "Alma del abrazo invernal", additional_info = "[q]Aumenta un 15% más la probabilidad de activar tu runa Dedos de Escarcha."},
[1220159] = {name = "Alma del abrazo invernal", additional_info = nil},
[1220160] = {name = "Alma del criomante", additional_info = "[q]Aumenta un 75% el daño que infligen tus hechizos Descarga de Escarcha y Descarga de fríoarcano."},
[1220161] = {name = "Alma del criomante", additional_info = nil},
[1220162] = {name = "Alma del evocador", additional_info = "[q]Eres inmune a todo el daño mientras canalizas Evocación."},
[1220163] = {name = "Alma del evocador", additional_info = nil},
[1220164] = {name = "Alma del elementalista", additional_info = "[q]Obtienes un 1% más de daño durante 15 s cada vez que lanzas un hechizo de una escuela de magia diferente."},
[1220165] = {name = "Alma del elementalista", additional_info = nil},
