[1220167] = {name = "Alma del armero mágico", additional_info = nil},
[1220168] = {name = "Alma del reavivador", additional_info = "[q]Reduce un 20% la amenaza que generan tus hechizos de Fuego."},
[1220169] = {name = "Alma del reavivador", additional_info = nil},
[1220170] = {name = "Alma de la convergencia ardiente", additional_info = "[q]Tu Piroexplosión inflige un 20% más de daño a los objetivos bajo los efectos del efecto periódico de tu Bola de fuego."},
[1220171] = {name = "Alma de la convergencia ardiente", additional_info = nil},
[1220172] = {name = "Alma de la llamarada perpetua", additional_info = "[q]El efecto periódico de tu Bola de fuego obtiene más daño para su duración, igual al 100% de su daño de impacto."},
[1220173] = {name = "Alma de la llamarada perpetua", additional_info = nil},
[1220174] = {name = "Alma del pirómano", additional_info = "[q]Tu Explosión de Fuego ahora hace que tu próximo hechizo de Fuego obtenga un 50% más de probabilidad de golpe crítico durante 10 s."},
[1220175] = {name = "Alma del pirómano", additional_info = nil},
[1220176] = {name = "Alma del encendedor", additional_info = "[q]Aumenta un 10% el daño que inflige tu talento Ignición."},
[1220177] = {name = "Alma del encendedor", additional_info = nil},
[1220178] = {name = "Alma de la antorcha", additional_info = "[q]Tus hechizos Bola de fuego, Descarga de Pirofrío y Descarga de fuego fardo obtienen un 4% más de daño por cada uno de tus efectos de Fuego sobre tu objetivo, hasta un máximo de un 12% más."},
[1220179] = {name = "Alma de la antorcha", additional_info = nil},
[1220180] = {name = "Alma del bloqueador prístino", additional_info = "[q]Aumenta 30 p. el valor de bloqueo de tu escudo."},
[1220181] = {name = "Alma del bloqueador prístino", additional_info = nil},
[1220182] = {name = "Alma del guardián de luz", additional_info = "[q]Sana 189 to 211 p. cuando bloqueas. Solo puede sanar una vez cada pocos segundos."},
[1220183] = {name = "Alma del guardián de luz", additional_info = nil},
[1220184] = {name = "Alma del defensor radiante", additional_info = "[q]En vez de tener cargas, Escudo Sagrado siempre alcanza su duración máxima. Además, el daño aumenta un 80% de tu valor de bloqueo con escudo."},
[1220185] = {name = "Alma del defensor radiante", additional_info = nil},
[1220186] = {name = "Alma del portaescudos", additional_info = "[q]Aumenta un 10% la probabilidad de bloqueo adicional de Escudo Sagrado."},
[1220187] = {name = "Alma del portaescudos", additional_info = nil},
[1220188] = {name = "Alma del bastión", additional_info = "[q]Recibes un 10% menos de daño mientras Escudo Sagrado está activo."},
[1220189] = {name = "Alma del bastión", additional_info = nil},
[1220190] = {name = "Alma del expiador", additional_info = "[q]Tu talento Expiación ahora tiene un 20% de probabilidad por punto de talento de activarse cuando bloqueas."},
[1220191] = {name = "Alma del expiador", additional_info = nil},
[1220192] = {name = "Alma del acorazado", additional_info = "[q]Tu Bendición de salvaguardia también aumenta un 10% todas las estadísticas cuando la lanzas sobre ti."},
[1220193] = {name = "Alma del acorazado", additional_info = nil},
[1220194] = {name = "Alma del guardián", additional_info = "[q]Escudo del honrado hace que el lanzamiento de tu próxima Luz Sagrada sea instantáneo. Si la lanzas sobre ti, restaurará un 100% de su costo de maná y no será afectada por Custodiado por la Luz."},
[1220195] = {name = "Alma del guardián", additional_info = nil},
[1220196] = {name = "Alma del pacificador", additional_info = "[q]Aumenta un 70% la probabilidad de que tus aliados activen tu Sentencia de Luz o Sentencia de sabiduría."},
[1220197] = {name = "Alma del pacificador", additional_info = nil},
[1220198] = {name = "Alma del refinamiento", additional_info = "[q]Aumenta tu probabilidad de golpe crítico con hechizos y ataques un 2%."},
[1220199] = {name = "Alma del refinamiento", additional_info = nil},
[1220200] = {name = "Alma del ejemplar", additional_info = "[q]Cuando tu Destello de luz, Luz Sagrada o Señal de la Luz restauran la salud de un objetivo por completo, también restauras 189 to 211 p. de salud a todos los miembros de su grupo."},
[1220201] = {name = "Alma del ejemplar", additional_info = nil},
[1220202] = {name = "Alma del inquisidor", additional_info = "[q]Aumenta un 5% la probabilidad de golpe crítico de Choque sagrado."},
[1220203] = {name = "Alma del inquisidor", additional_info = nil},
[1220204] = {name = "Alma de soberanía", additional_info = "[q]Aumenta un 50% el daño infligido con tu hechizo de Consagración."},
[1220205] = {name = "Alma de soberanía", additional_info = nil},
[1220206] = {name = "Alma del investido", additional_info = "[q]Mientras no seas objetivo de Señal de la Luz, tu objetivo de Señal de la Luz también sana un 75% del daño que infliges con Consagración, Exorcismo, Choque sagrado, Cólera sagrada y Martillo de cólera."},
[1220207] = {name = "Alma del investido", additional_info = nil},
[1220208] = {name = "Alma del vindicador", additional_info = "[q]Reduce un 25% el tiempo de reutilización de Luz divina."},
[1220209] = {name = "Alma del vindicador", additional_info = nil},
[1220210] = {name = "Alma del altruista", additional_info = "[q]Tus sanaciones sobre el objetivo de tu Señal de la Luz también sanan al objetivo aliado más cercano por un 90%."},
[1220211] = {name = "Alma del altruista", additional_info = nil},
