[1220219] = {name = "Alma del juez", additional_info = nil},
[1220220] = {name = "Alma del ascendiente", additional_info = "[q]Tu Sentencia otorga un 1% más de daño Sagrado durante 8 s, y se acumula hasta 5 veces."},
[1220221] = {name = "Alma del ascendiente", additional_info = nil},
[1220222] = {name = "Alma del desquite", additional_info = "[q]Aumenta un 150% el daño de Golpe de cruzado."},
[1220223] = {name = "Alma del desquite", additional_info = nil},
[1220224] = {name = "Alma del excomulgador", additional_info = "[q]Tus ataques básicos con armas cuerpo a cuerpo de dos manos aumentan un 35% el daño de tu siguiente lanzamiento de Exorcismo en los próximos 20 s. Se acumula hasta 3 veces."},
[1220225] = {name = "Alma del excomulgador", additional_info = nil},
[1220226] = {name = "Alma del iluminado", additional_info = "[q]Aumenta un 50% el daño infligido por tu hechizo Choque sagrado."},
[1220227] = {name = "Alma del iluminado", additional_info = nil},
[1220228] = {name = "Alma del exilio", additional_info = "[q]Reduce 3 s el tiempo de reutilización de tu hechizo Exorcismo y aumenta un 75% el daño que inflige."},
[1220229] = {name = "Alma del exilio", additional_info = nil},
[1220230] = {name = "Alma del templario", additional_info = "[q]Con un arma de una mano equipada, Golpe de cruzado ahora libera el efecto de Sentencia de tus Sellos, pero no consume el Sello."},
[1220231] = {name = "Alma del templario", additional_info = nil},
[1220232] = {name = "Alma del viajero del viento", additional_info = "[q]Aumenta tu velocidad de ataque un 30% en tus 3 próximos golpes después de parar, esquivar o bloquear."},
[1220233] = {name = "Alma del viajero del viento", additional_info = nil},
[1220234] = {name = "Alma del amo del escudo", additional_info = "[q]Tus paradas y evasiones también activan tu habilidad de runa Maestría con escudos."},
[1220235] = {name = "Alma del amo del escudo", additional_info = nil},
