[1220242] = {name = "Alma del empuñavorágine", additional_info = "[q]Cada vez que bloqueas un ataque, tienes una probabilidad del 50% de activar tu runa Arma vorágine."},
[1220243] = {name = "Alma del empuñavorágine", additional_info = nil},
