[1220245] = {name = "Alma del zancalavas", additional_info = nil},
[1220246] = {name = "Alma del alfa verdadero", additional_info = "[q]Cuando lanzas Espíritu del alfa sobre ti mismo, también aumenta tu salud un 5%, tu amenaza generada un 25%, y todo el daño que inflijas un 5%."},
