[1220249] = {name = "Alma del guardián de tótems", additional_info = nil},
[1220250] = {name = "Alma de los ancestros", additional_info = "[q]Tras haber lanzado Ola de sanación, Ola de sanación inferior o Mareas vivas, te otorga un 25% de probabilidad de obtener maná por un monto equivalente al 35% del costo básico del hechizo."},
