[1220256] = {name = "Alma del velatormentas", additional_info = "[q]Ahora tu Cadena de relámpagos también sana al objetivo de tu Escudo de tierra más reciente un 100% del daño infligido."},
[1220257] = {name = "Alma del velatormentas", additional_info = nil},
[1220258] = {name = "Alma del vidente elemental", additional_info = "[q]Aumenta la sanación de Sanación en cadena y el daño de Cadena de relámpagos un 20%."},
[1220259] = {name = "Alma del vidente elemental", additional_info = nil},
[1220260] = {name = "Alma del vitalista", additional_info = "[q]Tu Mareas Vivas aumenta la cantidad de sanación de Sanación en cadena un 25% más."},
[1220261] = {name = "Alma del vitalista", additional_info = nil},
[1220262] = {name = "Alma del sanador espiritual", additional_info = "[q]Reduce el tiempo de lanzamiento de Sanación en cadena 0.5 s."},
[1220263] = {name = "Alma del sanador espiritual", additional_info = nil},
[1220264] = {name = "Alma del refinamiento", additional_info = "[q]Aumenta tu probabilidad de golpe crítico con hechizos y ataques un 2%."},
[1220265] = {name = "Alma del refinamiento", additional_info = nil},
[1220266] = {name = "Alma del jefe", additional_info = "[q]Tu talento Aluvión aumenta un 10% más tu velocidad de ataque."},
[1220267] = {name = "Alma del jefe", additional_info = nil},
