[1220279] = {name = "Alma de la llama furibunda", additional_info = "[q]Ráfaga de lava ahora también restablece la duración de Choque de llamas para tu objetivo en 12 s."},
[1220280] = {name = "Alma del volcán", additional_info = nil},
