[1220282] = {name = "Alma del maestro elemental", additional_info = "[q]Ahora tus golpes críticos con hechizos tienen una probabilidad del 100% de activar tu talento Enfoque elemental."},
[1220283] = {name = "Alma del maestro elemental", additional_info = nil},
[1220284] = {name = "Alma del tribal", additional_info = "[q]Beta leal, de tu habilidad Espíritu del alfa, ahora también aumenta un 5 + (5 * ComboPoints)% el daño de Fuego, Escarcha y Naturaleza."},
[1220285] = {name = "Alma del tribal", additional_info = nil},
