[1220287] = {name = "Alma del guía espiritual", additional_info = nil},
[1220288] = {name = "Alma del ancestro", additional_info = "[q]Tienes una probabilidad del 70% de evitar las interrupciones por daño mientras lanzas Descarga de relámpagos, Cadena de relámpagos o Ráfaga de lava, y aumenta un 10% la probabilidad de activar tu talento Enfoque elemental."},
[1220289] = {name = "Alma del ancestro", additional_info = nil},
[1220291] = {name = "Alma de los elementos", additional_info = "[q]Aumenta un 60% la bonificación de daño por golpe crítico con tus hechizos de Fuego, Escarcha y Naturaleza."},
[1220292] = {name = "Alma de los elementos", additional_info = nil},
[1220293] = {name = "Alma del sabio de lava", additional_info = "[q]El daño de tu Ráfaga de lava aumenta un porcentaje equivalente a tu probabilidad de golpe crítico con hechizos."},
[1220294] = {name = "Alma del sabio de lava", additional_info = nil},
[1220295] = {name = "Alma del guardián ancestral", additional_info = "[q]Aumenta un 10% tu probabilidad de bloquear ataques con un escudo."},
[1220296] = {name = "Alma del guardián ancestral", additional_info = nil},
[1220297] = {name = "Alma del corrupto", additional_info = "[q]Aumenta un 5% más la probabilidad de activar tu runa Oleada de poder."},
[1220298] = {name = "Alma del corrupto", additional_info = nil},
[1220299] = {name = "Alma de pata suave", additional_info = "[q]Puedes lanzar Renacer y Estimular mientras estás en Forma de oso o Forma de oso temible."},
[1220300] = {name = "Alma de pata suave", additional_info = nil},
[1220301] = {name = "Alma del feroz", additional_info = "[q]Reduce 30 s el tiempo de reutilización de Enfurecer y ya no reduce tu armadura."},
[1220302] = {name = "Alma del feroz", additional_info = nil},
[1220303] = {name = "Alma del cambiaformas", additional_info = "[q]Forma de oso y Forma de oso temible aumentan un 20% más toda la amenaza que generas, y Agazapar ahora elimina toda la amenaza generada contra el objetivo, pero tiene 20 s más de tiempo de reutilización."},
[1220304] = {name = "Alma del cambiaformas", additional_info = nil},
[1220305] = {name = "Alma del territorial", additional_info = "[q]Flagelo (oso) también hace que tu Magullar golpee a 1 objetivo más durante los próximos 6 s."},
[1220306] = {name = "Alma del territorial", additional_info = nil},
[1220307] = {name = "Alma de la bestia", additional_info = "[q]Tus habilidades Destrozar (oso), Flagelo (oso), Magullar y Lacerar obtienen un 5% más de probabilidad de golpe crítico contra los objetivos bajo los efectos de tu Lacerar."},
