[1220310] = {name = "Alma del lacerador", additional_info = "[q]Tu Flagelo ahora propaga el Lacerar de tu objetivo principal a otros de los objetivos que golpea."},
[1220311] = {name = "Alma del lacerador", additional_info = nil},
[1220312] = {name = "Alma del furioso", additional_info = "[q]Cada vez que esquivas en Forma de oso temible, obtienes un 10% más de daño para el próximo Destrozar o Flagelo. Se acumula un máximo de 5 veces."},
[1220313] = {name = "Alma del furioso", additional_info = nil},
[1220314] = {name = "Alma del destrozador", additional_info = "[q]Reduce 1.5 s el tiempo de reutilización de Destrozar (oso)."},
[1220315] = {name = "Alma del destrozador", additional_info = nil},
[1220316] = {name = "Alma del estimulador", additional_info = "[q]Cuando lanzas Estimular sobre otro jugador, también se lanzará sobre ti."},
[1220317] = {name = "Alma del estimulador", additional_info = nil},
[1220318] = {name = "Alma de la fuente de nutrición", additional_info = "[q]Cuando lanzas tus hechizos de Toque de sanación o Nutrir, tienes un 25% de probabilidad de obtener una cantidad de maná equivalente al 35% del costo base del hechizo."},
[1220319] = {name = "Alma de la fuente de nutrición", additional_info = nil},
[1220320] = {name = "Alma del sosiego", additional_info = "[q]Reduce un 100% el tiempo de reutilización de Tranquilidad y aumenta un 100% su sanación."},
[1220321] = {name = "Alma del sosiego", additional_info = nil},
