[1226032] = {name = "S03 - Item - Scarlet Enclave - Druid - Restoration 2P Bonus", additional_info = "[q]Cada vez que tu Flor de vida sana a un objetivo, tiene un 5% de probabilidad de hacer tu siguiente lanzamiento de Toque de sanación, Nutrir o Recrecimiento en los próximos 15 s sea instantáneo.\n(Probabilidad de que accione: 5%)"},
[1226035] = {name = "Floración presta", additional_info = "Instante\n[q]Reduce un 100% el tiempo de lanzamiento de tu siguiente Toque de sanación, Recrecimiento o Nutrir."},
[1226038] = {name = "Rejuveneciendo", additional_info = "Alcance de 100 m\nInstante\n[q]Reduce un 20% el tiempo de lanzamiento de tu siguiente Toque de sanación, Recrecimiento o Nutrir."},
[1226040] = {name = "S03 - Item - Scarlet Enclave - Druid - Restoration 4P Bonus", additional_info = "[q]Los objetivos con tu Rejuvenecimiento de rango 10 u 11 activo reciben un 20% más de sanación de tus hechizos."},
[1226044] = {name = "S03 - Item - Scarlet Enclave - Druid - Restoration 6P Bonus", additional_info = "[q]Tus sanaciones no periódicas de Recrecimiento de rango 8 o 9 tienen un 50% de probabilidad de propagar tu Rejuvenecimiento a todos los miembros del grupo del objetivo en un radio de 43.5 m que no se encuentren ya bajo los efectos de tu Rejuvenecimiento.\n(Probabilidad de que accione: 50%)"},
[1226045] = {name = "Desmagnetizado", additional_info = "Rango ilimitado\nInstante\n[q]Altera un campo magnético que se encuentra entre un objetivo enemigo cercano y tú y los repele.\n\n Solo puede afectar a objetivos de hasta 2 niveles por encima de ti. Algunos objetivos no pueden ser desplazados. Los objetivos solo pueden sufrir este efecto una vez cada 2 min."},
[1226046] = {name = "Rejuvenecimiento salvaje", additional_info = "Instante"},
[1226092] = {name = "S03 - Item - Scarlet Enclave - Druid - Balance 2P Bonus", additional_info = "[q]Tu Fuego estelar inflige un 20% más de daño a los objetivos con tu Fuego lunar, y tu Cólera inflige un 40% más de daño a los objetivos con tu Fuego solar."},
[1226103] = {name = "S03 - Item - Scarlet Enclave - Druid - Balance 4P Bonus", additional_info = "[q]Tu Oleada de estrellas ahora aumenta el daño de tus próximos 2 Fuegos estelares."},
[1226105] = {name = "Oleada solar", additional_info = "Instante\n[q]Modifies Damage/Healing Done +41%:\nCólera , Cólera , Cólera , Cólera , Cólera , Cólera , Cólera , Cólera"},
[1226106] = {name = "Oleada lunar", additional_info = "Instante\n[q]Modifies Damage/Healing Done +21%:\nFuego estelar , Fuego estelar , Fuego estelar , Fuego estelar , Fuego estelar , Fuego estelar , Fuego estelar"},
[1226108] = {name = "S03 - Item - Scarlet Enclave - Druid - Balance 6P Bonus", additional_info = "[q]Cada vez que tu Fuego solar inflige daño periódico, obtienes un 40% más de daño en tu próxima Cólera, que se acumula un máximo de 5 veces. Cada vez que tu Fuego lunar inflige daño periódico, obtienes un 20% más de daño en tu próximo Fuego estelar, que se acumula un máximo de 5 veces. Estas bonificaciones no se aplican en Oleada de estrellas."},
[1226109] = {name = "S03 - Item - Scarlet Enclave - Druid - Feral 2P Bonus", additional_info = "[q]Obtienes 2 p. de energía cada vez que Arañazo o Destripar infligen daño periódico."},
