[1226206] = {name = "Caja de artilugios", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nEnvoltura de mitril , Núcleo de poder de oro (2)\n(2)\nMaterial de profesión\n[q]\"Un módulo de control simple que utilizan los ingenieros para fabricar artilugios.\""},
[1226207] = {name = "[q2]Caja de artilugios: Teletransporte", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nCaja de artilugios , Activador inestable , Trasto de torio\n[q2]Caja de artilugios: Teletransporte\nNecesitas ser de nivel 45\n[q2]Uso: Te teletransportas 20 m más adelante."},
