[1226402] = {name = "Recoger manzana", additional_info = "Rango ilimitado\nHechizo de 1.5 seg\n[q]Roba una manzana desde una distancia segura."},
[1226406] = {name = "Tunelado arcano", additional_info = nil},
[1226407] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 2P Bonus", additional_info = "[q]Tu Explosión Arcana tiene un 10% de probabilidad de provocar Túnel arcano. Túnel arcano impide que tu efecto de Explosión Arcana sea consumido por tu siguiente lanzamiento de un hechizo de daño Arcano. Además, activar Poder arcano restablece el tiempo de reutilización de tu Regeneración en masa.\n(Probabilidad de que accione: 20%)"},
[1226414] = {name = "Anclaje temporal", additional_info = nil},
[1226415] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 4P Bonus", additional_info = "[q]Retroceder en el tiempo también reduce un 20% todo el daño que recibe tu objetivo durante 8 s."},
[1226423] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 2P Bonus", additional_info = "[q]Tu Bomba viva ahora inflige daño cada 1 s y se detona si el objetivo muere. Además, el efecto de Helar de tu runa de Lanza de hielo ahora se acumula hasta 10 veces, y Descarga de fríoarcano otorga 2 acumulaciones cada vez que golpea."},
[1226432] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 6P Bonus", additional_info = "[q]Reduce 25 s el tiempo de reutilización de tu hechizo Orbe congelado. Cada vez que se consume Helar, el tiempo de reutilización de tu Congelación profunda se reduce 1.0 s por acumulación consumida. Reduce 5 s el tiempo de reutilización de Explosión de Fuego, que ahora además restablece la duración de tu Bomba viva en el objetivo."},
[1226446] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 4P Bonus", additional_info = "[q]Lanzar Congelación profunda aumenta la duración restante de tu Venas heladas 10 s. Lanzar Piroexplosión cancela 2 acumulaciones del efecto de tu Descarga de fuego fardo."},
