[1226595] = {name = "S03 - Item - Scarlet Enclave - Priest - Shadow 6P Bonus", additional_info = "[q]El daño que inflige tu Tortura mental ahora aumenta cuanto más tiempo canalices el hechizo. Cada vez que inflige daño, el daño siguiente aumenta un 70%. Este efecto se restablece con una nueva canalización."},
[1226689] = {name = "[q4]Carcaj escarlata", additional_info = "Hechizo de 3 seg\nComponentes:\nOrbe recto , Cuero basto (24), Pellejo basto curtido (2)\n[q4]Carcaj escarlata\n(2)\nSe liga al equiparlo\nCarcaj de 30 casillas\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la velocidad de ataque en un 15%."},
