[1226808] = {name = "Comida", additional_info = "{Instante} {1 seg de reutilización}\nComponentes:\nGalleta enriquecida con maná\n[q]Restaura un 5% de tu salud y maná por segundo durante 20 s. Debes permanecer sentado mientras comes."},
