[1226814] = {name = "Galleta enriquecida con maná", additional_info = "{Instante} {1 min de reutilización}\n[q]Restaura 2148 p. de salud y 4410 p. de maná durante 30 s. Debes permanecer sentado mientras comes."},
[1226843] = {name = "S03 - Item - Scarlet Enclave - Rogue - Damage 2P Bonus", additional_info = "[q]Mientras Heridas superficiales no está activa, tu Puñalada, Golpe siniestro, Sablazo y Mutilar infligen un 20% más de daño por cada uno de tus efectos activos de veneno o sangrado sobre el objetivo, hasta un aumento máximo del 60%."},
[1226868] = {name = "¡Combo!", additional_info = nil},
