[1226961] = {name = "S03 - Item - Scarlet Enclave - Shaman - Elemental 2P Bonus", additional_info = "[q]Cuando tu Ráfaga de lava, Cadena de relámpagos o Descarga de relámpagos golpea a un objetivo bajo los efectos de un Choque de llamas de rango 5 o 6, también inflige un pulso del daño de Choque de llamas."},
[1226963] = {name = "Choque de llamas", additional_info = "Alcance de 20 m\nInstante\n[q]"},
[1226972] = {name = "Choque de llamas", additional_info = "Alcance de 20 m\nInstante\n[q]"},
[1226977] = {name = "S03 - Item - Scarlet Enclave - Shaman - Elemental 4P Bonus", additional_info = "[q]Aumenta la probabilidad de activar Sobrecarga un 10% y aumenta el daño de Ráfaga de lava un porcentaje equivalente a tu probabilidad de golpe crítico con hechizos. Cuando Descarga de relámpagos o Cadena de relámpagos inflige daño, aumenta un 10% el daño de tu siguiente Ráfaga de lava en un período de 15 s. Este efecto se acumula hasta 5 veces."},
[1226978] = {name = "S03 - Item - Scarlet Enclave - Shaman - Elemental 6P Bonus", additional_info = "[q]Cuando tu Cadena de relámpagos daña a menos de 3 objetivos, inflige un 35% más de daño por cada objetivo por debajo de 3."},
[1226981] = {name = "Grimorio de sinergia", additional_info = "Alcance de 100 m\n[q]El daño que infligen tú o tu demonio invocado tiene una probabilidad del 10% de aumentar el daño que inflige el otro un 10% durante 15 s."},
[1226984] = {name = "S03 - Item - Scarlet Enclave - Shaman - Enhancement 2P Bonus", additional_info = "[q]Cuando Choque estático está activo, Latigazo de lava, Ráfaga de lava y Golpe de tormenta tienen un 100% de probabilidad de agregar una carga a tu Escudo de relámpagos. Si tienes más de 9 cargas, Escudo de relámpagos infligirá daño a tu objetivo inmediatamente, en lugar de acumular cargas."},
[1226986] = {name = "S03 - Item - Scarlet Enclave - Shaman - Enhancement 4P Bonus", additional_info = "[q]Reduce un 60% el tiempo de reutilización de tu Tótem Nova de Fuego, aumenta un 200% su daño y reduce un 60% su costo de maná. Además, tu Tótem Nova de Fuego ahora se activa de forma instantánea al lanzarlo."},
[1226997] = {name = "S03 - Item - Scarlet Enclave - Shaman - Enhancement 6P Bonus", additional_info = "[q]Arma vorágine puede acumular hasta 10 cargas. Al usar un arma de dos manos, obtienes 2 cargas a la vez. Lanzar con más de 5 cargas aumenta el daño y la sanación del hechizo un 20% por cada carga sobrante. Lanzar con 10 cargas consume todas las cargas y lanza el hechizo dos veces."},
[1227080] = {name = "Leer libro de cocina", additional_info = "Hechizo de 5 seg\n[q]Te enseña a cocinar las recetas de festín más deseadas de Carrie Fogata."},
[1227088] = {name = "Tierra presta", additional_info = "Instante\n[q]Reduce un 100% el tiempo de lanzamiento de tu siguiente Ola de sanación inferior, Ola de sanación o Sanación en cadena."},
[1227093] = {name = "S03 - Item - Scarlet Enclave - Shaman - Restoration 2P Bonus", additional_info = "[q]Las sanaciones de tu Escudo de tierra tienen un 25% de probabilidad de hacer que el tiempo de lanzamiento de tu próxima sanación sea instantáneo."},
[1227099] = {name = "S03 - Item - Scarlet Enclave - Shaman - Restoration 4P Bonus", additional_info = "[q]Tu Ola de sanación y tu Ola de sanación inferior también sanan al objetivo de tu Escudo de tierra por un 50% de sus montos, si no es el objetivo principal."},
