[1236154] = {name = "Palabra de poder: escudo", additional_info = "Alcance de 40 m\n{Instante} {4 seg de reutilización}\n[q]Refuerza con un escudo el alma de un miembro del grupo, amortiguando 16650 to 19350 p. de daño. Dura 30 s. Mientras dura el escudo, el lanzamiento de hechizos no se verá interrumpido por el daño. Una vez protegido, el objetivo no puede recibir protección de nuevo hasta pasados 15 s."},
[1236156] = {name = "Disipar magia", additional_info = "Alcance de 30 m\nHechizo de 2.5 seg\n[q]Elimina la magia del objetivo, suprimiendo 2 efectos dañinos de un amigo o 2 hechizos beneficiosos de un enemigo."},
