[1236162] = {name = "Fuego sagrado", additional_info = "Alcance de 30 m\nHechizo de 1 seg\n[q]Envuelve al objetivo en llamas sagradas que infligen 950 to 1050 p. de daño Sagrado y 250 p. más de daño Sagrado cada 2 s durante 10 s."},
[1236172] = {name = "Bola de Fuego", additional_info = "Alcance de 40 m\nHechizo de 3 seg\n[q]Inflige daño de Fuego a un enemigo."},
