[1236174] = {name = "Polimorfia", additional_info = "{10% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Transforma al enemigo en oveja y la obliga a deambular durante hasta 20 s. Mientras deambula, la oveja no puede atacar ni lanzar hechizos, pero se regenera muy rápidamente. Si recibe daño, volverá a su forma normal. Solo se puede aplicar polimorfia a un objetivo a la vez. Solo funciona en bestias, dragones, gigantes, humanoides y alimañas."},
[1236175] = {name = "Traslación", additional_info = "75 p. de maná\nInstante\n[q]Teletransporta al taumaturgo 20 m hacia delante salvo si hay algún obstáculo y lo libera de sus ataduras."},
[1236176] = {name = "Desarmar", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {1 min de reutilización}\n[q]Desarma el arma del enemigo durante 10 s."},
