[1236181] = {name = "Luz Sagrada", additional_info = "Alcance de 40 m\nHechizo de 2.5 seg\n[q]Invoca la magia Sagrada para sanar a un aliado."},
[1236182] = {name = "Golpe de cruzado", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Inflige 693 to 807 p. de daño a un enemigo y aumenta el daño Sagrado que recibe 10 p. por cada Golpe de cruzado. Puede aplicarse hasta 5 veces. Dura 30 s."},
[1236183] = {name = "Cuchilla Sagrada", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Siguiente cuerpo a cuerpo} {6 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Inflige daño con arma más 740 to 860 p. a un enemigo y a sus aliados cercanos. Afecta hasta a 3 objetivos."},
[1236188] = {name = "Disparo de puntería", additional_info = "Alcance de 100 mHechizo de 3 seg 6 seg de reutilización\nRequiere Arma a distancia\n[q]Un disparo de puntería que aumenta el daño a distancia 1387 to 1613 p."},
[1236190] = {name = "Multidisparo", additional_info = "Alcance de 100 m\nHechizo de 2.5 seg\nRequiere Arma a distancia\n[q]Dispara una descarga de misiles contra el enemigo y sus aliados cercanos que alcanza a un máximo de 3 objetivos y aumenta 462 to 538 p el daño normal."},
[1236191] = {name = "Disparo de conmoción", additional_info = "Alcance de 100 m\nHechizo de 2.5 seg\nRequiere Arma a distancia\n[q]Deja atontado a un enemigo, lo que reduce su velocidad de movimiento un 50% durante 3 s.\n(Probabilidad de que accione: 40%)"},
